def _path_arg_kind(v):
    """一个文字参数的值是不是「只写了个文件路径」⇒ (种类, 展开后的路径) 或 None。纯函数(只看文件在不在)。
    at-file = @ + 存在的普通文件 · at-dir = @ + 存在但不是普通文件 · at-missing = @ + 不带空白、像路径、不存在 · bare = 以 / 或 ~/ 开头、是存在的普通文件。"""
    s = str(v if v is not None else "").strip()
    if not s:
        return None
    if s.startswith("@"):
        p = os.path.expanduser(s[1:])
        if os.path.isfile(p):
            return ("at-file", p)
        if re.search(r"\s", s) or not _AT_PATHLIKE_RE.search(s[1:]):
            return None
        return ("at-dir", p) if os.path.exists(p) else ("at-missing", p)
    if (s.startswith("/") or s.startswith("~/")) and os.path.isfile(os.path.expanduser(s)):
        return ("bare", os.path.expanduser(s))
    return None


def _text_at_read(v):
    """`ask --text` 的一段 ⇒ (要上卡的原文, 要报的话, @ 的那个文件)。@文件 ⇒ 读 UTF-8 内容(去掉末尾换行,同 "$(cat 文件)");
    不是路径 ⇒ 原样;写成路径却读不成 ⇒ (None, 一句要报的话, 路径)。只读文件、不写。"""
    k = _path_arg_kind(v)
    if not k:
        return v, None, None
    kind, p = k
    q = __import__("shlex").quote(p)
    if kind == "bare":
        return None, ("--text 写的是文件路径不是内容(%s),他在板上只会看到一行路径。\n"
                      "   ⇒ 要放这份文件的原文就写 --text \"$(cat %s)\",或 --text @%s(读文件内容)" % (str(v).strip()[:100], q, q)), p
    if kind == "at-missing":
        return None, '--text 写的是 @路径,可这个文件不存在;要放原文就写 --text "$(cat 文件)" 或给对路径(现在写的是 %s)' % p, p
    if kind == "at-dir":
        return None, '--text 写的是 @路径,可 %s 不是普通文件(是目录或别的);要放原文就写 --text "$(cat 文件)" 或给对路径' % p, p
    try:
        if os.path.getsize(p) > ASK_TEXT_FILE_MAX * 4:      # UTF-8 一个字最多 4 字节:超过这么多字节一定超过上限,不用整份读进来
            return None, "--text @%s 太大了(%d 字节),原文最多 %d 字 —— 要他过目的是一段话,不是一份文件" % (p, os.path.getsize(p), ASK_TEXT_FILE_MAX), p
        with open(p, "rb") as fh:
            t = fh.read().decode("utf-8-sig")
    except OSError as e:
        return None, "--text @%s 读不了:%s ⇒ 改好权限,或写 --text \"$(cat 文件)\"" % (p, e.strerror or e), p
    except UnicodeDecodeError:
        return None, "--text @%s 不是 UTF-8 文本,读出来会是乱码 ⇒ 先转成 UTF-8(iconv -f GBK -t UTF-8)再给" % p, p
    t = t.rstrip("\r\n")
    if not t.strip():
        return None, "--text @%s 是空的 —— 卡上「请你过目的原文」会是空白一块 ⇒ 先把要他过目的话写进去" % p, p
    if len(t) > ASK_TEXT_FILE_MAX:
        return None, "--text @%s 有 %d 字,超过 %d 字 —— 要他过目的是一段话,不是一份文件;长文出方案页挂 --deep" % (p, len(t), ASK_TEXT_FILE_MAX), p
    return t, None, p


def _prose_path_problem(fields, report=None, *, value_prefix=""):
    """fields = [(参数名, 值或值列表)…];哪一个整串(或用 | 分开的一段)就是一个文件路径 ⇒ 一句要报的话;都不是 ⇒ None。只看文件在不在。"""
    for name, val in fields:
        for one in (val if isinstance(val, (list, tuple)) else [val]):
            if one is None:
                continue
            s = str(one)
            for piece in [s] + (s.split("|") if "|" in s else []):
                k = _path_arg_kind(piece)
                if k:
                    problem = ("%s 写的是文件路径不是内容(%s),他在板上只会看到一行路径。\n"
                            "   ⇒ 要放这份文件里的话就写 %s \"%s$(cat %s)\";本来要写一句话 ⇒ 直接写那句话"
                            % (name, piece.strip()[:100], name, value_prefix, __import__("shlex").quote(k[1])))
                    if report is None:
                        return problem
                    report('prose-file-path', problem)
    return None


def _prose_args_problem(cmd, a, report=None, *, skip=()):
    """cmd = ask / row / answer / head / dir / deep-ok:BOARD_PROSE_ARGS 里列的参数有写成文件路径的 ⇒ 一句要报的话;没有 ⇒ None。"""
    return _prose_path_problem([(f, getattr(a, dest, None)) for f, dest in BOARD_PROSE_ARGS[cmd].items()
                                if dest not in skip], report=report)


def _copy_path_problem(copies, report=None):
    """ask --copy 的原文写成 @路径 ⇒ 一句要报的话;裸路径放过(要他复制一条路径是正经用法);没有 ⇒ None。"""
    for c in copies or []:
        body = str(c).partition("|")[2] if "|" in str(c) else str(c)
        k = _path_arg_kind(body)
        if k and k[0] != "bare":
            problem = ("--copy 的原文写的是 @路径(%s)—— --copy 不读文件,卡上只会印这一串,他照着粘也没用。\n"
                    "   ⇒ 要他粘的是文件内容就写 --copy \"<短标题>|$(cat %s)\";要他粘的就是这条路径 ⇒ 去掉 @"
                    % (body.strip()[:100], __import__("shlex").quote(k[1])))
            if report is None:
                return problem
            report('copy-file-path', problem)
    return None


# ⭐ 1117 晚 B(状态板线转负责人 14:25 截图):「去哪看」写「「要你的」该重上卡 ask-87980d38;本行说明写了每件怎么读」—— 他:「我能看得懂任何事情吗?」
#   ⇒ 卡标题 / 去哪看 / 结果 / 还要你做 / 入口旁的说明、ask 的标题 / 前因后果 / 批了以后怎么做 里写卡号、行号、「本行 / 该行 / 那张卡」⇒ 拒写。
#   否过什么:⛔ --covered-by / --ack / --row / --wait-for / --dup-of 不查(本来就该写编号,ask-… 写进 --wait-for 还是「等别的板上的卡」的入口);
#     ⛔ 「本行业 / 该行为」不算(后面跟业 / 为放过);编号前后紧挨着英文字母数字的不算(Task-12345678)。
_BOARD_REF_RE = re.compile(r"(?<![A-Za-z0-9_-])(?:ask-[0-9a-f]{8}|r\d{4}-[0-9a-f]{4}|ntc-[A-Za-z0-9][\w-]*)(?![A-Za-z0-9_])"
                           r"|本行(?![业为])|该行(?![业为])|上面那张卡|那张卡")


def _board_ref_problem(fields, report=None):
    """fields = [(参数名, 值或值列表)…];有卡号 / 行号 / 本行 / 那张卡 ⇒ 一句要报的话;没有 ⇒ None。纯函数。"""
    for name, val in fields:
        for one in (val if isinstance(val, (list, tuple)) else [val]):
            m = _BOARD_REF_RE.search(str(one or ""))
            if m:
                problem = ("%s 里写着「%s」—— 他不认卡号和行号 —— 写他在页面上看得到的名字(哪一块、标题叫什么)。\n"
                        "   例:--see \"出单看板 → 来源一栏显示主站渠道名\";验收卡本来就自动链着那一行,不用再指" % (name, m.group(0)))
                if report is None:
                    return problem
                report('board-reference', problem)
    return None


# 1021(AI平台 v1.9 交来,负责人原话:「你现在需要我粘贴的东西……全部夹杂在这个对话里,我根本没有办法去粘贴。我也不知道粘什么,
#   我还是容易粘错……要么加个专门的代码块」)⇒ 要他粘进终端的命令必须走 --copy(单独一块、等宽、带「复制」)。
#   判据实测(全机 14 天 674 次 ask):命中 8 次,全是真要他粘的命令(read -rs …&&…、sudo killall、gh secret set、aliyun configure);
#   ⛔ 别加 `~/.`(那 2 次是在说明里提文件路径)、别认 `|`(那是 --steps 的分隔符)、命令词后面只认 ASCII(「git 提交号」「ssh 到服务器」不算)。
ASK_PASTE_RE = re.compile(r"&&|\$\(|\$\{?[A-Z_]{3,}\}?|(?:^|[\s|:：「(])(?:sudo|export|curl|npx|python3|ssh|gh|git|node|brew|npm|pnpm|"
                          r"launchctl|chmod|read|printf|echo|cat|cd|open|lark-cli|aliyun|bl|ve)\s+-{0,2}[a-zA-Z~/.\"'][\w./~:=-]*")


def _ask_paste_problem(q, rec, why, steps):
    """卡的说明文字里夹着要他粘贴的命令 ⇒ 返回一句要报的话;没有 ⇒ None。纯函数。⛔ --text / --copy 里的不查(那本来就是原文块)。"""
    for flag, v in (("--steps", steps), ("--rec", rec), ("--q", q), ("--why", why)):
        m = ASK_PASTE_RE.search(str(v or ""))
        if m:
            return ("%s 里夹着一段要他粘贴的命令(「%s」)—— 夹在说明里,他分不清从哪粘到哪,还容易粘错(负责人 10-21)。\n"
                    "   ⇒ 命令放进 --copy \"<一个短标题>|<命令原文,一个字不改>\"(卡上单独一块、等宽、带「复制」按钮,可给多块);\n"
                    "     说明里只写「粘贴下面『<短标题>』那一块,回车」。" % (flag, m.group(0).strip()[:40]))
    return None


ASK_RELAY_RE = re.compile(r"转告|转发给|帮我问|替我问|帮我告诉|替我告诉")


def _ask_relay_problem(q, rec, steps, texts):
    """要他把话转给别人(转告 / 转发给 / 帮我问…)却没给 --text 原话 ⇒ 返回一句要报的话;不是转告卡、或给了原文 ⇒ None。纯函数。
    ⭐ 1020(AI平台 v1.9 报,负责人原话:「你如果要我转告同事辛,你就应该给我一段你想让我转告同事辛的一段原话」):
      卡写「请转告同事辛:型号名要写成 X」,步骤只有「把这三个名字发给他」—— 他得自己组织措辞。
    实测(全机 14 天 1057 次 ask):这六个词命中的都是真转告卡,0 误伤;「告诉我一声」「发给豆包」「发给你」这类宽词误伤多,⛔ 别加进来。
    ⛔ 只查有没有原文:原文写得对不对机器判不了。"""
    if [x for x in (texts or []) if str(x or "").strip()]:
        return None
    m = ASK_RELAY_RE.search(" ".join(str(x or "") for x in (q, rec, steps)))
    if not m:
        return None
    return ("卡里写着「%s」(要他把话转给别人),却没给 --text —— 他得自己想怎么说,还可能转错。\n"
            "   ⇒ 加 --text \"<他直接复制发出去的那段原话>\":卡上单独一块,换行照留,他点一下就能复制。\n"
            "   ⇒ 原话写在 --rec / --q 里也不行:那里会被收成「第一句 + 展开」,复制不全。" % m.group(0))


def _ask_row_problem(src, row):
    """`ask --row <ack>` 指的那一行在不在「你交代的」里;不在 / 不止一行 ⇒ 返回一句为什么(调用方报错、什么都不写),在 ⇒ None。"""
    if row is None:
        return None
    if not str(row).strip():
        return "--row 要给那一行的 data-ack,现在是空的"
    try:
        _row_span(src, str(row).strip())
    except ValueError as e:
        return ("--row 指的那一行找不到:%s —— 卡上那个「那一行」的链接会是死的,机器卡也照样会把它重复列一次。"
                "先看「你交代的」里那一行的 data-ack 是什么(没有这一行就先加上),或者不给 --row。" % e)
    return None


# ──────────────── 1006 挂卡 / 改行时拦相对日期
#   板是挂着给他隔天、隔几天看的:写「明天给你」的那张卡,过一夜「明天」就指错了一天,而板上没有任何东西会变红。
#   ⚠ 引号里的不拦:他的原话常带这些词(「今天先别发」),那是引用,不是板在说时间。
#   ⚠ 「明」前面是 说 / 证 / 表 / 声 / 注 / 标 / 阐 / 写 的不算(「说明天数」「注明早期」是 说明 + 天数、注明 + 早期;字面子串当闸本机栽过多次)。
_REL_DATE_RE = re.compile(r"今天|今晚|昨天|今早|(?<![说证表声注标阐写])明天|(?<![说证表声注标阐写])明早")
_REL_QUOTED_RE = re.compile(r"「[^」]*」|“[^”]*”|\"[^\"]*\"")


def _relative_date_words(text):
    """text 里写在引号外面的相对日期词(今天 / 今晚 / 明天 / 昨天 / 今早 / 明早),按出现顺序、去重。纯函数。"""
    bare = _REL_QUOTED_RE.sub(lambda m: " " * len(m.group(0)), str(text or ""))
    out = []
    for m in _REL_DATE_RE.finditer(bare):
        if m.group(0) not in out:
            out.append(m.group(0))
    return out


def _relative_date_fix(text, today=None):
    """⭐ 1020(负责人:AI 用板的成本要降):引号外的 今天 / 今晚 / 今早 / 明天 / 明早 / 昨天 直接换成日期,不再拒写让 AI 重写一轮
    (10-13→10-20 全机碰板的轮里 4% 是被拒后重写)。返回 (新文字, [(原词, 换成)…]);没有 ⇒ 原样、[]。纯函数。
    ⚠ 判哪些算(引号里不算、「说明天数」不算)与 _relative_date_words 同一套正则。"""
    if not text:
        return text, []
    today = today or datetime.date.today()
    fmt = lambda d: "%02d-%02d" % (d.month, d.day)
    t0, t1, tm = fmt(today), fmt(today + datetime.timedelta(days=1)), fmt(today - datetime.timedelta(days=1))
    rep = {"今天": t0, "今晚": t0 + " 晚上", "今早": t0 + " 早上", "明天": t1, "明早": t1 + " 早上", "昨天": tm}
    src = str(text)
    bare = _REL_QUOTED_RE.sub(lambda m: "\0" * len(m.group(0)), src)
    out, done, last = [], [], 0
    for m in _REL_DATE_RE.finditer(bare):
        w = m.group(0)
        out.append(src[last:m.start()]); out.append(rep[w]); last = m.end()
        if (w, rep[w]) not in done:
            done.append((w, rep[w]))
    out.append(src[last:])
    return "".join(out), done


def _relative_date_fix_args(a, names, today=None):
    """对 a 上这几个参数(字符串或字符串列表)逐个换掉相对日期;返回给作者看的一句(没换 ⇒ "")。"""
    seen = []
    for nm in names:
        v = getattr(a, nm, None)
        if isinstance(v, (list, tuple)):
            nv = []
            for x in v:
                y, d = _relative_date_fix(x, today)
                nv.append(y); seen += [z for z in d if z not in seen]
            setattr(a, nm, type(v)(nv) if isinstance(v, tuple) else nv)
        elif isinstance(v, str):
            y, d = _relative_date_fix(v, today)
            setattr(a, nm, y); seen += [z for z in d if z not in seen]
    return ("  ↳ 相对日期已换成日期(板隔天还挂着):%s" % "、".join("「%s」→ %s" % z for z in seen)) if seen else ""


def _owner_pattern():
    return "|".join(re.escape(name) for name in BP.owner_names())


def _name_pattern(names, word_boundary=False):
    def pattern(name):
        escaped = re.escape(name)
        return r"\b" + escaped + r"\b" if word_boundary and name.isascii() and name.isalnum() else escaped
    return "".join(pattern(name) + "|" for name in names)


_SAY_WAIT_RE = re.compile(rf"(?<!不用)(?<!不再)(?<!不必)(?<!没在)(?<!别)(?:等你|还差你|你点头|等(?:{_owner_pattern()})|(?<!让)(?<!叫)(?<!推给)你去(?![过了])|请你|麻烦你|(?<!不)需要你|你需要|你得(?!到)|你要去|你(?:和|跟)[^,，。;；]{{1,12}}(?:谈|说|聊|对))")


def _say_wait_words(text):
    """text 里写在引号外面的「在等他 / 要他去做」说法(等你 / 还差你 / 你点头 / 等负责人 / 你去 / 请你 / 需要你 / 你和 X 谈;否定不算),按出现顺序、去重。纯函数。
    ⭐ 1109 投流转:r1109-2a8d 写「卡包投流佣金你去和 同事丑 谈」,标着盯着,板上 0 张卡。全机 140 行回放这组词零误咬。
    1119 状态板线误咬:「这张卡让你去催 AI,方向反了」—— 前面是 让 / 叫 / 推给 的「你去」是在转述别人叫他去,不算(引号里的本来就蒙掉)。"""
    bare = _REL_QUOTED_RE.sub(lambda m: " " * len(m.group(0)), str(text or ""))
    out = []
    for m in _SAY_WAIT_RE.finditer(bare):
        if m.group(0) not in out:
            out.append(m.group(0))
    return out


def _say_wait_problem(say, fact, linked, you_arg, path="<板>"):
    """`row --say` 的新文字说「在等他」,而这一行既没标着要他、也没有卡在讲它、这次也没表态 ⇒ 返回要报的话;否则 None。纯函数。
    fact = 改完之后这一行的事实(_yours_zone_rows 的一项);linked = 「要你的」里是否已有卡链到这一行;you_arg = 这次命令给的 --you。
    ⭐ 1013(负责人对电商-投流:「状态板怎么又腐烂了…这个问题很大」):那条线三轮在聊天里以「要你定的一件」收尾,只把这句话写进了行的现状,
      「要你的」里没有卡;它自己说:「row --say 成功 + lint PASS 给了我『已经上板』的感觉,而『行里提到在等你』和『要你的里有卡』是两回事」。
      ⛔ 只在命令行这条路、只看这次新写的文字;不进 lint(全机 112 行没做完的行里有「等你」字样的约 10 行,多数是他已搁置 / 在别的板上等,进 lint 就是误咬)。"""
    ws = _say_wait_words(say)
    if not ws or not fact or not fact.get("open"):
        return None
    if you_arg or linked or fact.get("you") in ROW_YOU_MINE:
        return None
    import shlex as _shx
    q, k = _shx.quote(path), fact.get("ack") or "<这一行的编号>"
    return ("--say 里写着「%s」,但这一行没标着要他、「要你的」里也没有它的卡 —— 写进行的现状 ≠ 摆到他面前:他开板先看「要你的」,"
            "那里没有,这件事对他就不存在(负责人 10-13 对电商-投流:「状态板怎么又腐烂了」)。三选一:\n"
            "   ① 要他判断 ⇒ 这条命令加 `--you decide --act \"要他定的一句\"`,紧接着挂展开卡:\n"
            "        python3 ~/.claude/scripts/board.py ask %s --row %s --q \"他能直接回答的一个问题\" --why \"前因后果\" --rec \"我的建议\" --opt \"选项|说明\"\n"
            "   ② 要他动手(一句话讲得清的动作)⇒ 加 `--you do --act \"他要做的一句\"`\n"
            "   ③ 现在并不需要他做什么(他自己说了先搁着 / 是在别的线的板上等他)⇒ 加 `--you wait`,并把话写准(比如「你 10-07 说先搁着」)"
            % ("」「".join(ws), q, k))


# ⭐ 1117 J2(电商-基建 #b8d4③):--wait-for 写的是等他(「你在…那张卡上的回答」「你拍…」「等负责人」「他自己验」),他面前却没有这件事的卡 ⇒ 拒写,
#   同 --say 里「等你」那条(_say_wait_problem,负责人 10-13「状态板怎么又腐烂了」)。11-17 全机只读扫:没做完、在等他、同板没卡链着的行 17 行。
#   放过:等日子(「日子:…」开头)/ 这一行有卡链着 / 这一行或这次命令标着要他拍 / 动手 / 去催 / 写了卡号(ask-xxxxxxxx,卡挂在别的线板上)。
#   否过什么:⛔ 不放过 --you wait —— 「不用你做」和「在等你」自相矛盾(--say 那条放过它,是因为 --say 里常写「你 10-07 说先搁着」这类记事);
#     ⛔ 「给你 / 帮你 / 跟你…」后面的不算(「等同事甲给你确认」是在等同事甲);⛔ 不进 lint(只看这次新写的,老行不翻)。
_WAIT_HIM_RE = re.compile(rf"(?<!不用)(?<!不再)(?<!不必)(?<!没在)(?<!别)(?<!不)(?:^\s*(?:等)?你(?!们)|等你(?!们)|还差你|{_owner_pattern()}|他自己|(?<![给帮替向跟和问对让])你(?:拍|定|答|验|试|点头|确认|在|把|哪天|说|决定))")
_WAIT_HIM_CARD_RE = re.compile(r"\bask-[0-9a-f]{8}\b")


def _wait_for_him_words(text):
    """--wait-for 里写在引号外面的「在等他」说法,按出现顺序、去重。纯函数。"""
    bare = _REL_QUOTED_RE.sub(lambda m: " " * len(m.group(0)), str(text or ""))
    out = []
    for m in _WAIT_HIM_RE.finditer(bare):
        w = m.group(0).strip()
        if w and w not in out:
            out.append(w)
    return out


def _wait_for_him_problem(wait_for, fact, linked, you_arg, path="<板>"):
    """`row --wait-for` 这次写的是等他,而他面前没有这件事的卡 ⇒ 返回要报的话;否则 None。纯函数。fact = 改完之后这一行的事实;linked = 「要你的」里有没有卡链到这一行。"""
    wf = str(wait_for or "")
    if _WAIT_DATE_PREFIX.match(wf) or _WAIT_HIM_CARD_RE.search(wf):
        return None
    ws = _wait_for_him_words(wf)
    if not ws or not fact or not fact.get("open"):
        return None
    if linked or you_arg in ROW_YOU_MINE or fact.get("you") in ROW_YOU_MINE:
        return None
    import shlex as _shx
    q, k = _shx.quote(path), fact.get("ack") or "<这一行的编号>"
    return ("--wait-for 写的是在等他(「%s」),可「要你的」里没有这件事的卡 —— 写进「在等」≠ 摆到他面前:他开板先看「要你的」,"
            "那里没有,这件事对他就不存在(同 --say 里写「等你」那条,负责人 10-13:「状态板怎么又腐烂了」)。三选一:\n"
            "   ① 真要他判断 / 动手 ⇒ 挂卡(挂上这一行自动改标「要你拍」):\n"
            "        python3 ~/.claude/scripts/board.py ask %s --row %s --q \"他能直接回答的一个问题\" --rec \"我的建议\"\n"
            "   ② 卡已经挂在别的线板上 ⇒ 把那张卡的卡号写进 --wait-for,例「等你答记忆助手线板上 ask-1a2b3c4d」\n"
            "   ③ 他说过先搁着、现在不用他做什么 ⇒ 写成等日子:--wait-for \"日子:MM-DD 再问他(他 MM-DD 说先搁着)\" --eta MM-DD --not-waiting none"
            % ("」「".join(ws), q, k))


def _relative_date_problem(pairs, today=None):
    """pairs = [(参数名, 文字或文字列表)…];哪个参数里有引号外的相对日期 ⇒ 返回一句要报的话,都没有 ⇒ None。纯函数。"""
    today = today or datetime.date.today()
    hits = []
    for name, val in pairs:
        ws = []
        for one in (val if isinstance(val, (list, tuple)) else [val]):
            for w in _relative_date_words(one):
                if w not in ws:
                    ws.append(w)
        if ws:
            hits.append("%s 里的「%s」" % (name, "」「".join(ws)))
    if not hits:
        return None
    return ("写了相对日期:%s —— 过一夜就错,写成日期(如 %02d-%02d)。板是挂着给他隔天看的,「明天」到了明天指的就是后天。\n"
            "  引号里的原话不拦:确实是在引他 / 别人的话,就用「…」或 \"…\" 括起来。"
            % (";".join(hits), today.month, today.day))


# ──────────────── 1006 他在板上直接点的回答:读出来、没消化就拦
#   负责人 10-06:「点了当场记到板上,这个我觉得是 OK 的」。周检头号毛病是「他答了,板还挂着」(398 条里 13 条),
#   0930 把改板降成一行命令(answer / row)之后比例没变 ⇒ 缺的不是门槛,是 AI 根本没回来看。
#   看板服务(boards-server.py 的 _ans_post)今天起把他在卡 / 方案页上点的回答记成文件:
#     <state_dir>/board-server/answers/<quote(页面文件名, safe="")>.json = {题 id: {q, choice, note, ts[, copied]}}
#   状态板:题 id = 卡的 data-ack,页面文件名 = 板文件名;方案页(web_root/proposals/ 下):页面文件名 = 那一页,题 id 页面自己定。
#   三处接上:① lint 报错「他答了,板还挂着」(touch 顺带跑 lint ⇒ 每次刷板都撞上);② `board.py answers <板>` 把没消化的印给 AI 读;
#   ③ `answer` 拿掉卡的同时清掉那条记录。
#   ⚠ 「消化了」的判据(两种,别混):
#     · 作者手写的卡 ⇒ 卡不在「要你的」里了(`answer` 拿掉);看不看 copied 都一样 —— 他复制去粘给别的线,不等于这块板跟上了。
#     · 方案页的题、机器卡(每次落板现算,`answer` 拿不掉)⇒ 记录上有 copied(他自己点了复制,或 AI 消化完跑 `answers --mark`)。
#       他改答一次,服务会整条覆盖、copied 没了 ⇒ 重新算没消化。
#   ⛔ 读不到答案目录 / 文件坏了 ⇒ 当成没有记录:lint 是每条线每次刷板的必经动作,不能因为一份状态文件坏了把所有人拦住。


def _answers_file(page, adir=None):
    """页面文件名 → 它的答案文件。⭐ 1115 大扫除 C4:算法只在 board_paths.answers_file_name 一份(boards-server.py _ans_file 用同一个)。
    伺服拒收的怪名字(不是 .html / 以点开头 / 超长)伺服本来写不出文件 ⇒ 这里只取文件名转义一下兜底,只为不抛。"""
    return os.path.join(adir or BP.state("board-server", "answers"),
                        BP.answers_file_name(page) or (_urlparse.quote(os.path.basename(str(page)), safe="") + ".json"))


def _answers_load(page, adir=None):
    """读一页的答案 {题 id: 记录};没有文件 / 读不了 / 不是 JSON / 不是字典 ⇒ {}(⛔ 不抛)。
    条目本身不是字典的不在这里筛 —— _answers_pending 只认字典。"""
    try:
        with open(_answers_file(page, adir), encoding="utf-8") as fh:
            d = json.load(fh)
    except (OSError, ValueError):
        return {}
    if not isinstance(d, dict):
        return {}
    return d


def _answers_save(page, data, adir=None):
    """原子写回一页的答案(临时文件 + os.replace;临时名带进程号,不和服务自己的 `.tmp` 撞)。"""
    f = _answers_file(page, adir)
    tmp = "%s.%d.tmp" % (f, os.getpid())
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(data, fh, ensure_ascii=False)
    os.replace(tmp, f)


def _answers_raw(page, adir=None):
    """要改写时用:原样读出整份(保住不认识的条目)。没有文件 ⇒ None;坏了 ⇒ ValueError / OSError 往上抛。"""
    f = _answers_file(page, adir)
    if not os.path.exists(f):
        return None
    with open(f, encoding="utf-8") as fh:
        d = json.load(fh)
    if not isinstance(d, dict):
        raise ValueError("答案文件不是一个 JSON 对象")
    return d


def _answers_consumed_file(adir=None):
    """1020:清掉的回答另存在这里(一行一条 JSON,只增)—— 答案目录的上一层,不进答案目录(那里一页一个文件)。"""
    return os.path.join(os.path.dirname(adir or BP.state("board-server", "answers")), "answers-consumed.jsonl")


def _answers_drop(page, key, adir=None):
    """把一页答案里 key 那条删掉。删了 ⇒ 返回那条记录(先另存进 _answers_consumed_file);没有文件 / 没有那条 ⇒ None;
    删不成 ⇒ 出一声、None(⛔ 不抛:answer 已经成了)。
    ⚠ 1020(AI平台 v1.9 报):收卡时他前一分钟刚提交的回答被一起清掉,板上、磁盘上都没留原文 ⇒ 清之前先另存,原文交回给调用方印出来。"""
    try:
        d = _answers_raw(page, adir)
        if d is None or key not in d:
            return None
        rec = d[key]
        try:
            with open(_answers_consumed_file(adir), "a", encoding="utf-8") as fh:
                fh.write(json.dumps({"page": str(page), "id": key, "rec": rec,
                                     "dropped": datetime.datetime.now().strftime("%Y-%m-%dT%H:%M:%S")}, ensure_ascii=False) + "\n")
        except OSError as e:
            print("  ⚠ 那条回答没能另存(%s: %s)—— 原文见下一行,要留就抄走。" % (type(e).__name__, e))
        d.pop(key)
        _answers_save(page, d, adir)
        return rec if isinstance(rec, dict) else {"choice": str(rec)}
    except (OSError, ValueError) as e:
        print("  ⚠ 他在板上答的那条记录没清掉(%s: %s)—— 卡已经拿掉了,不影响结果;那条记录留在 %s 里。"
              % (type(e).__name__, e, _answers_file(page, adir)))
        return None


def _ans_when(ts):
    """记录里的 ISO 时间 → 「MM-DD HH:MM」(带时区的换成本机时间);读不懂就原样印前 40 字,空的说没记下。"""
    t = str(ts or "").strip()
    if not t:
        return "时间没记下"
    try:
        d = datetime.datetime.fromisoformat((t[:-1] + "+00:00") if t.endswith(("Z", "z")) else t)
    except ValueError:
        return t[:40]
    if d.tzinfo is not None:
        d = d.astimezone()
    return d.strftime("%m-%d %H:%M")


def _answers_proposal_pages(src):
    """这块板上方案板入口(`<a class="deep" href="…/proposals/<页名>">`)指向的方案页文件名,去重保序。纯函数。
    注释 / 脚本 / 样式里的不算。"""
    out = []
    for a in re.finditer(r'<a class="deep"[^>]*>', _mask_noncontent(src)):
        h = re.search(r'\bhref\s*=\s*"([^"]*)"', a.group(0))
        if not h:
            continue
        pth = _urlparse.unquote(_urlparse.urlparse(h.group(1).strip()).path)
        m = re.search(r'/proposals/([^/]+\.html?)$', pth)
        if m and m.group(1) not in out:
            out.append(m.group(1))
    return out


# 依据: 11-25 vhdp-review 返工意见未被线接住，任务定超过 60 分钟沿用收答报错。
_PAGE_ANSWER_LINT_AGE_S = 60 * 60
# 依据: 11-25 页面回答 lint 只贴原话前 80 字，重挂拒写贴全文。
_PAGE_ANSWER_PREVIEW = 80
# 依据: 卡收走后页面仍可收答，随板保留已移除的页面入口。
_PAGE_ANSWER_REFS = re.compile(r"<!-- board-page-refs ([^<>]+?) -->")


def _proposal_answer_page(url):
    """板服务的方案页地址 → 答案记录所用的页面文件名。"""
    from html import unescape
    try:
        u = _urlparse.urlsplit(unescape(url))
    except ValueError:
        return None
    if u.netloc and (u.hostname not in ("localhost", "127.0.0.1") or
                     u.scheme not in ("", "http", "https")):
        return None
    if not u.netloc and u.scheme:
        return None
    m = re.fullmatch(r"/?proposals/([^/]+)", _urlparse.unquote(u.path))
    page = m.group(1) if m else ""
    return page if BP.answers_file_name(page) else None


def _proposal_answer_refs(src):
    """板正文里的页面链接，含卡上 --see 印出的本机网址。"""
    visible = _mask_noncontent(src)
    hrefs = (m[1] for m in re.finditer(r"""\bhref\s*=\s*["']([^"']+)["']""", visible, re.I))
    urls = [*hrefs, *_local_urls(visible)]
    return dict.fromkeys(page for url in urls if (page := _proposal_answer_page(url)))


def _past_proposal_answer_refs(src):
    return dict.fromkeys(_urlparse.unquote(page) for m in _PAGE_ANSWER_REFS.finditer(src) for page in m[1].split())


def _keep_proposal_answer_refs(before, out):
    refs = dict.fromkeys([*_past_proposal_answer_refs(before), *_past_proposal_answer_refs(out),
                          *_proposal_answer_refs(before)])
    for page in _proposal_answer_refs(out):
        refs.pop(page, None)
    if refs.keys() == _past_proposal_answer_refs(out).keys():
        return out
    out = re.sub(_PAGE_ANSWER_REFS.pattern + r"\n?", "", out)
    if refs:
        out = out.rstrip("\n") + "\n<!-- board-page-refs %s -->\n" % " ".join(_urlparse.quote(pg, safe="") for pg in refs)
    return out


# ⭐ 1026 负责人:「我只有板上的回复写到一半，然后他就直接去读了……导致我的板上回复没写完，他直接读了这种片面的一半的回复」
#   18:43 批「先试一下吧，看看效果」⇒ 板上的回答分「交了」和「还在写」:点了「交给这条线」= 交;没点的,
#   只点了选项、1 分钟没再动 = 交(多半就是答完了);写了字、10 分钟没再改 = 交(走开了也不能永远不算)。
#   没交的 = 草稿:answers 不列内容、不记「看过」(⇒ answer 收不了这张卡),只说一句「他还在写」;钩子也不贴。
ANS_SUB_CHOICE_S, ANS_SUB_NOTE_S = BP.ANS_SUB_CHOICE_S, BP.ANS_SUB_NOTE_S   # 1115 大扫除 C3:与伺服共用 board_paths 那一份;kit.js 同名 ×1000 由自检比对


def _ans_ts_epoch(ts):
    t = str(ts or "").strip()
    if not t:
        return None
    try:
        d = datetime.datetime.fromisoformat((t[:-1] + "+00:00") if t.endswith(("Z", "z")) else t)
    except ValueError:
        return None
    return d.timestamp() if d.tzinfo is not None else time.mktime(d.timetuple())


def _ans_kept(rec):
    """⭐ 1027(电商-基建 v2.2 转,负责人:「为什么我也点了记下呀？为什么没有，你看不到呢？是因为我没有点交给这条线吗？」):
    他亲手点了卡上的「记下」(记录带 keep,且 keep ≥ ts)= 这一张他写完了 ⇒ answers / 注入钩子照常列给 AI 看;
    但不算「交给这条线」⇒ 不为它叫醒(他可能还在答别的卡,1026 晚他要「全部答完再一次交」)。自动存的半截字没有 keep,照旧藏着。"""
    t, k = _ans_ts_epoch(rec.get("ts")), _ans_ts_epoch(rec.get("keep"))
    return t is not None and k is not None and k >= t


def _ans_submitted(rec, now=None):
    """这条回答算不算他交了(见 ANS_SUB_* 上面那段)。读不懂时间的老记录算交了(宁可多列,别吞掉)。"""
    t = _ans_ts_epoch(rec.get("ts"))
    if t is None:
        return True
    sub = _ans_ts_epoch(rec.get("sub"))
    if sub is not None and sub >= t:
        return True
    now = time.time() if now is None else now
    return now - t >= (ANS_SUB_NOTE_S if str(rec.get("note") or "").strip() else ANS_SUB_CHOICE_S)


def _ans_on_old_page(page, ts, root=None):
    """1029 晚:方案页的这条回答早于页面最后一次改动(伺服同一判据,boards-server.py _ans_is_prev)⇒ 页面改动时间「MM-DD HH:MM」;否则 None。
    页面上它已经灰着算「上一版」,AI 照办前要先核:多半已经办过、页面就是照它改的。"""
    try:
        pm = os.path.getmtime(os.path.join(root or BP.web_root(), "proposals", os.path.basename(str(page or ""))))
        t = datetime.datetime.fromisoformat(str(ts or "").strip().replace("Z", "+00:00")).timestamp()
    except (OSError, ValueError):
        return None
    return datetime.datetime.fromtimestamp(pm).strftime("%m-%d %H:%M") if t < pm - 2 else None


def _answers_pending(src, board_page, ans_map, now=None):
    """这块板上【还没消化】的回答 —— 纯函数:吃板文本 + {页面文件名: 答案字典},吐列表(先板上的卡、按板上顺序;再各方案页)。
    每条 = dict(kind="card"|"page", page, id, title, choice, note, ts, machine, draft)。draft = 他还在写(见 _ans_submitted)。
      · card:答案里有记录、同 data-ack 的卡此刻还在「要你的」区里。卡已经不在板上的记录不算。
              作者手写的卡 ⇒ 只要还挂着就算(不看 copied);机器卡(`answer` 拿不掉)⇒ 没有 copied 才算。
      · page:这块板的方案板入口指向的方案页里,没有 copied 的记录。"""
    out = []
    mine = ans_map.get(board_page) or {}
    head, end = _yours_zone_span(src)
    if head and mine:
        body = src[head.end():end]
        gen = [(m.start(), m.end()) for _nm, b_, e_ in _gen_block_pairs()
               for m in re.finditer(re.escape(b_) + r".*?" + re.escape(e_), body, re.S)]
        for c in re.finditer(r'<article\b([^>]*)>.*?</article>', body, re.S):
            if "card" not in _class_set(c.group(1)):
                continue
            am = re.search(r'\bdata-ack\s*=\s*"([^"]*)"', c.group(1))
            ack = am.group(1) if am else None
            rec = mine.get(ack) if ack else None
            if not isinstance(rec, dict):
                continue
            machine = ack in YOURS_MACHINE_ACKS or any(g0 <= c.start() < g1 for g0, g1 in gen)
            if machine and rec.get("copied"):
                continue
            q = re.search(r'<h2 class="q">(.*?)</h2>', c.group(0), re.S)
            title = re.sub(r"\s+", " ", re.sub(r"<[^>]+>", "", q.group(1))).strip() if q else ""
            out.append({"kind": "card", "page": board_page, "id": ack, "title": title or str(rec.get("q") or ack),
                        "choice": str(rec.get("choice") or ""), "note": str(rec.get("note") or ""), "except": _ans_except(rec),
                        "ts": str(rec.get("ts") or ""), "machine": machine, "draft": not (_ans_submitted(rec, now) or _ans_kept(rec)),
                        "unsent": not _ans_submitted(rec, now)})
    deep_pages = _answers_proposal_pages(src)
    page_refs = {**_proposal_answer_refs(src), **_past_proposal_answer_refs(src)}
    for pg in dict.fromkeys([*deep_pages, *page_refs]):
        out.extend(it for it in _proposal_answer_items(pg, ans_map.get(pg), now)
                   if pg in deep_pages or it["page_wide"])
    return out


def _proposal_answer_items(pg, records, now=None):
    """复用方案题的消化判定；页面级回答由伺服写成 page / _overall。"""
    out = []
    for k, rec in (records or {}).items():
        if not isinstance(rec, dict) or rec.get("copied"):
            continue
        choice, note = str(rec.get("choice") or ""), str(rec.get("note") or "")
        page_wide = k == "_overall" or (k == "page" and rec.get("q") == "这一页")
        if page_wide and not (choice.strip() or note.strip()):
            continue
        submitted = _ans_submitted(rec, now)
        out.append({"kind": "page", "page": pg, "id": str(k), "title": str(rec.get("q") or k),
                    "choice": choice, "note": note, "except": _ans_except(rec), "ts": str(rec.get("ts") or ""),
                    "machine": False, "page_wide": page_wide,
                    "draft": not (submitted or _ans_kept(rec)), "unsent": not submitted})
    return out


def _answers_map(path, src, adir=None):
    """从磁盘读出这块板用得到的答案:{板文件名: …, 各方案页文件名: …}(读不到的都是 {})。"""
    pages = dict.fromkeys([os.path.basename(path), *_answers_proposal_pages(src),
                           *_proposal_answer_refs(src), *_past_proposal_answer_refs(src)])
    return {pg: _answers_load(pg, adir) for pg in pages}


def _submitted_page_answers(pages, now=None):
    for pg in pages:
        for it in _proposal_answer_items(pg, _answers_load(pg), now):
            if it["page_wide"] and not it["unsent"]:
                yield it


def _page_answer_mark_command(board, it):
    import shlex
    args = shlex.join(["answers", str(board), "--page", it["page"], "--mark", it["id"]])
    return "python3 ~/.claude/scripts/board.py " + args


def _page_answer_said(it):
    return "\n".join(text for text in (it["choice"], it["note"]) if text.strip())


def _page_answer_lint_errors(src, path):
    now = time.time()
    pages = dict.fromkeys([*_proposal_answer_refs(src), *_past_proposal_answer_refs(src)])
    errors = []
    for it in _submitted_page_answers(pages, now):
        ts = _ans_ts_epoch(it["ts"])
        if ts is None or now - ts <= _PAGE_ANSWER_LINT_AGE_S:
            continue
        said = _page_answer_said(it)
        preview = said[:_PAGE_ANSWER_PREVIEW] + ("…" if len(said) > _PAGE_ANSWER_PREVIEW else "")
        errors.append("**他答了,板还挂着**: 页面回答没消化 · %s · %s · 「%s」\n"
                      "    ⇒ 照他的回答办，再跑 `%s`。"
                      % (it["page"], _ans_when(it["ts"]), preview, _page_answer_mark_command(path, it)))
    return errors


def _page_answer_write_problem(board, *entries):
    pages = dict.fromkeys(page for url in _local_urls(*entries) if (page := _proposal_answer_page(url)))
    for entry in entries:
        if entry and (page := _proposal_answer_page(entry.strip())):
            pages[page] = None
    return "\n".join("页面回答没消化 · %s · %s\n%s\n"
                     "    ⇒ 先处理这条回答，跑 `%s` 标为已消化，再挂卡。"
                     % (it["page"], _ans_when(it["ts"]), _page_answer_said(it), _page_answer_mark_command(board, it))
                     for it in _submitted_page_answers(pages))


def _ans_except(rec):
    """按组批量定(plan.py ```batch,1113)那一题的例外条目名;不是按组题(记录里没有 except)⇒ None,整组没例外 ⇒ []。"""
    ex = rec.get("except") if isinstance(rec, dict) else None
    return [str(x).strip() for x in ex if str(x).strip()] if isinstance(ex, list) else None


def _ans_batch_said(choice, exc):
    """「整组选了「X」,例外:条目 a、b」—— 叫醒文本 / answers 印给 AI 看的那一句(1113 负责人:「我不可能点105次」)。"""
    return "整组选了「%s」,%s" % (choice or "(没选)", ("例外:条目 " + "、".join(exc)) if exc else "没有例外(整组照办)")


def _ans_said(it, note_limit=None):
    """一条回答说了什么:选项 + 补充(note_limit 给了就只取补充的前 N 个字)。"""
    choice = re.sub(r"\s+", " ", it.get("choice") or "").strip()
    note = re.sub(r"\s+", " ", it.get("note") or "").strip()
    if note_limit is not None and len(note) > note_limit:
        note = note[:note_limit] + "…"
    bits = []
    if it.get("except") is not None:
        bits.append(_ans_batch_said(choice, it["except"]))
    elif choice:
        bits.append("选了「%s」" % choice)
    if note:
        bits.append("补充:「%s」" % note)
    return ",".join(bits) or "(没选也没写字 —— 记录是空的)"


def _answered_lint_errors(src, board_page, ans, board_arg=None, now=None):
    """lint 那道闸的判定 —— 纯函数:板上还挂着、而他已经在板上答了的卡,每张一条错。ans = 这块板自己那份答案字典。now 缺省 = 此刻(自检给定)。
    ⭐ 1117 抢收(11-17 16:04 AI Harness 板 4 张回答卡,他点「看过了」77–82 秒后被那条线照这条报错手收,机器本来会收):
      机器会自己收的(验收卡 / 回答卡纯通过、没补充、不满 WAKE_FRESH_S)不报 —— 与 cmd_answers 同一个判断 _answers_auto_accept,不另写判据;
      超过 WAKE_FRESH_S 机器还没收 ⇒ 照报(机器漏收时仍要有人管)。"""
    arg = board_arg or board_page
    errs = []
    items = [it for it in _answers_pending(src, board_page, {board_page: ans or {}}, now=now)
             if it["kind"] == "card" and not it.get("draft")]                                                            # 1026:他还在写 ⇒ 不算「答了没收」
    auto = _answers_auto_accept(src, items, now)                                                # 1117 抢收:机器会自己收的
    items = [it for it in items if it not in auto]
    for it in items:
        if it["machine"]:
            nxt = ("这是机器卡(每次落板现算),`answer` 拿不掉 ⇒ 照他的回答改源头(「你交代的」那几行用 `board.py row`;"
                   "「卡在你身上」那张改 .queue.json),改完跑 `python3 ~/.claude/scripts/board.py answers %s --mark`。" % arg)
        else:
            nxt = ("照他的回答办,然后 `python3 ~/.claude/scripts/board.py answer %s --ack %s --res \"<他怎么答的,一句>\" "
                   "(--why \"这一行现在到哪了\" | --done)`"
                   "(拿掉卡、这条记录一起清掉;卡对应着「你交代的」里一行时,那一行的现状由你写:没做完给 --why,做完了给 --done)。" % (arg, it["id"]))
        errs.append("**他答了,板还挂着**:「%s」(data-ack=\"%s\")这张卡,他 %s 已经在板上答了 —— %s。可它还挂在「要你的」里:"
                    "他会以为白答了,下一次打开还得再答一遍(周检头号毛病,负责人 10-06 让板自己记下回答就是为了治它)。"
                    "⇒ %s 这块板全部没消化的回答:`board.py answers %s`。"
                    % (_clause(it["title"], 40), it["id"], _ans_when(it["ts"]), _ans_said(it, 40), nxt, arg))
    return errs


def _answers_draft_line(drafts, arg=None):
    if not drafts:
        return []
    return ["(另有 %d 条他还在写、没交:%s —— ⛔ 别照半截的办、别为它停下等;他在对话里叫你看板 ⇒ "
            "`board.py answers %s --take-drafts`)"
            % (len(drafts), "、".join("「%s」" % _clause(x["title"], 20) for x in drafts[:5]), arg or "<板>")]


def _answers_report(board_name, items, board_arg=None, drafts=None):
    """`board.py answers` 印的那几行 —— 纯函数,吃 _answers_pending 的结果(已去掉草稿;草稿另给 drafts,只印一句)。
    没有 ⇒ 第一行是「没有待处理的回答」(钩子认这几个字不出声)。"""
    arg = board_arg or board_name
    if not items:
        return ["没有待处理的回答(%s)" % board_name] + _answers_draft_line(drafts, arg)
    cards = [x for x in items if x["kind"] == "card"]
    pages = []
    for x in items:
        if x["kind"] == "page" and x["page"] not in pages:
            pages.append(x["page"])
    out = ["%s:他在板上 / 方案页上答了 %d 条,还没消化" % (board_name, len(items))]

    def one(x):
        tag = "(机器卡)" if x["machine"] else ""
        out.append("  · [%s]%s %s" % (x["id"], tag, x["title"]))
        if x.get("except") is not None:             # 1113 按组批量定:一句话说清整组选了什么、哪几条除外
            out.append("      选了:%s" % _ans_batch_said(re.sub(r"\s+", " ", x["choice"]).strip(), x["except"]))
        else:
            _ch = re.sub(r"\s+", " ", x["choice"]).strip()
            if x.get("asked"):                       # 1117 二轮:回答卡记的值是通过 / 不通过,转述照他点的按钮字(看过了 / 没答到点上)
                _ch = dict(zip(ANSWER_VALS, [o.split("|")[0] for o in ANSWER_OPTS])).get(_ch, _ch)
            out.append("      选了:%s" % (_ch or "(没选)"))
        if x["note"].strip():
            out.append("      补充:%s" % re.sub(r"\s*\n\s*", " ⏎ ", x["note"].strip()))
        _im = _ans_img_paths(x["note"])
        if _im:
            out.append("      他贴了 %d 张图(用 Read 打开看,回他时说看到了什么):%s"
                       % (len(_im), " · ".join(f if ok else "%s(本机找不到)" % f for f, ok in _im)))
        out.append("      答于:%s" % _ans_when(x["ts"]))
        _old = _ans_on_old_page(x["page"], x["ts"]) if x["kind"] == "page" else None
        if _old:
            out.append("      ⚠ 答在这一页的上一版(页面 %s 又改过,页上已灰着算旧回答):多半已经照它改过页了 ⇒ 先核办没办过,别重办" % _old)
        if x.get("unsent"):
            out.append("      (他点了「记下」= 这张写完了,还没点「交给这条线」:照办即可,他可能还在答别的卡)")

    if cards:
        out.append("■ 板上的卡(%d 张,还挂在「要你的」里)" % len(cards))
        for x in cards:
            one(x)
    for pg in pages:
        qs = [x for x in items if x["kind"] == "page" and x["page"] == pg]
        out.append("■ 方案页 %s(%d 题)" % (pg, len(qs)))
        for x in qs:
            one(x)
    # 1027(AI Harness v2.8 审计:answers 注入 245 次共 330KB,每次重复整段命令教学)⇒ 收成一行固定动作,细节 `board.py answers --help`
    acts = []
    if any(not x["machine"] for x in cards):
        acts.append("卡 → 照办后 `board.py answer %s --ack <卡> --res \"他怎么答的\" (--why \"这一行现在到哪了\" | --done)`" % arg)
    acts.extend("页面级回答 → 照办后 `%s`" % _page_answer_mark_command(arg, x)
                for x in items if x.get("page_wide"))
    if any(x["kind"] == "page" and not x.get("page_wide") or x["machine"] for x in items):
        acts.append("方案页的题 / 机器卡 → 办完哪题标哪题 `board.py answers %s --mark <题号…>`(机器卡先改源头的行;不写题号 = 全标)" % arg)
    out.append("下一步(board.py = python3 ~/.claude/scripts/board.py):" + ";".join(acts) + "。不收 lint 会一直报错;细节 `board.py answers --help`")
    return out + _answers_draft_line(drafts, arg)


def _answers_auto_accept(src, items, now=None):
    """⭐ 1115 大扫除 D5:items 里机器会自己收的那几条 —— 验收卡上点了通过 / 同意不做、没写补充、点完不满 WAKE_FRESH_S、机器收卡开着。"""
    if BP._load().get('accept_autoclose', True) is False:
        return []
    now = time.time() if now is None else now
    out = []
    for x in items or []:
        if x.get("kind") != "card" or str(x.get("choice") or "") not in _ACCEPT_YES or str(x.get("note") or "").strip():
            continue
        t = _ans_ts_epoch(x.get("ts"))
        if t is None or now - t > WAKE_FRESH_S or not _accept_card(src, x["id"]):
            continue
        out.append(x)
    return out


def _answers_mark(items, now_iso, adir=None, marked=None):
    """把 items 里【方案页的题】和【机器卡】对应的记录写上 copied = now_iso;作者手写的卡不标(它们靠 `answer` 拿卡来消化)。
    读进来之后他又改答了(ts 变了)的不标。返回 (标了几条, [没标成的说明])。"""
    by_page, n, bad = {}, 0, []
    for it in items:
        if it["kind"] == "page" or it["machine"]:
            by_page.setdefault(it["page"], []).append(it)
    for pg, its in by_page.items():
        try:
            d = _answers_raw(pg, adir)
            if d is None:
                continue
            k = 0
            for it in its:
                rec = d.get(it["id"])
                if isinstance(rec, dict) and str(rec.get("ts") or "") == it["ts"]:
                    rec["copied"] = now_iso
                    k += 1
                    if marked is not None:
                        marked.append(it)
            if k:
                _answers_save(pg, d, adir)
                n += k
        except (OSError, ValueError) as e:
            bad.append("%s 没标成(%s: %s)" % (pg, type(e).__name__, e))
    return n, bad


# ⭐ 1026 晚(电商-投流达人 v1.9 转,负责人让反馈):他在板上写完、回到对话说「看一下状态板上的回复」,
#   可写了字的要停手 10 分钟才算交 ⇒ AI 只读到「他还在写」,两次都晚了约 10 分钟。他在对话里点名叫看板 = 他认为交了。
#   ⇒ `answers --take-drafts` 把这块板(连方案页)上还没交的记成交了(记录上写 sub,与「交给这条线」按钮同一个字段);
#     注入钩子认出他这一轮的话在叫看板时自动带上它。读进来之后他又改了(ts 变了)的不动。
def _mark_said(x):
    """--mark 列出的一条:[题号] 题干 —— 选了:…(补充:…)。"""
    ch = re.sub(r"\s+", " ", str(x.get("choice") or "")).strip()
    said = _ans_batch_said(ch, x["except"]) if x.get("except") is not None else (ch or "(没选)")
    nt = re.sub(r"\s+", " ", str(x.get("note") or "")).strip()
    return "[%s] %s —— 选了:%s%s" % (x["id"], _clause(x.get("title") or "", 30), said, (";补充:" + _clause(nt, 40)) if nt else "")


def _answers_take_drafts(drafts, adir=None):
    now = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z"
    by_page, n, bad = {}, 0, []
    for it in drafts:
        by_page.setdefault(it["page"], []).append(it)
    for pg, its in by_page.items():
        try:
            d = _answers_raw(pg, adir)
            if d is None:
                continue
            k = 0
            for it in its:
                rec = d.get(it["id"])
                if isinstance(rec, dict) and str(rec.get("ts") or "") == it["ts"]:
                    rec["sub"] = now
                    k += 1
            if k:
                _answers_save(pg, d, adir)
                n += k
        except (OSError, ValueError) as e:
            bad.append("%s 没记成交了(%s: %s)" % (pg, type(e).__name__, e))
    return n, bad


def _answers_shown_file():
    return BP.state("board-server", "answers-shown.json")


def _answers_shown_mark(items):
    """1020 晚:记下哪几条回答已经印给 AI 看过了 {页: {卡: 那条回答的 ts}}。answer 收卡时拿它判「你看过他这条回答没有」。
    ⚠ 存的是那条回答的 ts:他看过之后又改了回答 ⇒ ts 变了 ⇒ 又算没看过。"""
    if not items:
        return
    f = _answers_shown_file()
    try:
        d = json.load(open(f, encoding="utf-8"))
        d = d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        d = {}
    for x in items:
        d.setdefault(x["page"], {})[x["id"]] = x["ts"]
    try:
        os.makedirs(os.path.dirname(f), exist_ok=True)
        tmp = "%s.%d.tmp" % (f, os.getpid())
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(d, fh, ensure_ascii=False)
        os.replace(tmp, f)
    except OSError:
        pass


def _answer_unseen(page, ack):
    """他在板上答了这张卡、而这条回答还没被 `answers`(或叫醒时贴进来的那段)印出来过 ⇒ 返回那条记录;否则 None。"""
    rec = _answers_load(page).get(ack)
    if not isinstance(rec, dict):
        return None
    try:
        seen = (json.load(open(_answers_shown_file(), encoding="utf-8")) or {}).get(page, {}).get(ack)
    except (OSError, ValueError, AttributeError):
        seen = None
    return None if seen is not None and seen == str(rec.get("ts") or "") else rec


ANS_IMG_RE = re.compile(r"\u3014\u56fe:([\w.-]+)\u3015")   # 〔图:文件名〕—— 8777 伺服在回复框里插的标记(boards-server.py ANS_IMG_JS)


def _ans_img_paths(note):
    """他在板上 / 方案页回复里贴的图 → [(本机完整路径, 在不在)]。1026 负责人:「让那个状态板也支持……把图片复制进去做回复」。
    图存在 state_dir/board-server/answer-media/(BOARD_ANSWER_MEDIA 可改),回复里只留标记 ⇒ AI 拿路径用 Read 看。"""
    d = os.path.expanduser(os.environ.get("BOARD_ANSWER_MEDIA") or BP.state("board-server", "answer-media"))
    return [(os.path.join(d, n), os.path.isfile(os.path.join(d, n))) for n in ANS_IMG_RE.findall(str(note or ""))]


def cmd_answers(a):
    """⭐ 1006:打印这块板上还没消化的回答(他在卡 / 方案页上直接点的)。`--mark` 才改答案记录(只标方案页的题和机器卡)。
    1020 晚:印出来的那几条记成「AI 看过了」(answer 收卡时要用)。"""
    p = assert_canonical(a.path)
    s = open(p, encoding="utf-8").read()
    name = os.path.basename(p)
    page = getattr(a, "page", None)
    if page is not None and (os.path.basename(page) != page or not BP.answers_file_name(page)):
        die("--page 要给方案页文件名，例如 vhdp-review.html。")

    def pending():
        if page is not None:
            return _proposal_answer_items(page, _answers_load(page))
        return _answers_pending(s, name, _answers_map(p, s))

    allit = pending()
    if getattr(a, "take_drafts", False) and any(x["draft"] for x in allit):
        n, bad = _answers_take_drafts([x for x in allit if x["draft"]])
        if n:
            print("✓ --take-drafts:他在对话里叫你看板上的回复 ⇒ %d 条还没点交的当作他交了(下面照常列出)。" % n)
        for b in bad:
            print("  ⚠ " + b)
        allit = pending()
    items = [x for x in allit if not x["draft"]]
    auto = _answers_auto_accept(s, items)                 # 1115 大扫除 D5:验收卡的单纯通过机器约 90 秒内自己收 ⇒ 不贴给线,免得和机器抢
    items = [x for x in items if x not in auto]
    for ln in _answers_report(page or name, items, board_arg=p, drafts=[x for x in allit if x["draft"]]):
        print(ln)
    if auto:
        print("  (另:验收卡 %s 他点了通过,没写补充 —— 机器约 %d 秒内自动收行、投知会,别手收)"
              % (" ".join(x["id"] for x in auto), ACCEPT_GRACE_S))
    _answers_shown_mark(items)
    mk = getattr(a, "mark", None)
    if mk is None or mk is False:
        return 0
    # 1113 电商-选品 #3b90:--mark 原来一把全标、只回「2 条标成已消化」,不说是哪两题 ⇒ 它漏办了一题(他选了「全部下」)。
    #   ⇒ 可写题号只标办完的那几题;标完逐题列出题干和他选了什么;写了题号还剩没标的也列出来。
    can = [x for x in items if x["kind"] == "page" or x["machine"]]
    ids = [] if mk is True else [str(i).strip() for i in mk if str(i).strip()]
    if ids:
        unk = [i for i in ids if i not in {x["id"] for x in can}]
        if unk:
            print("✗ --mark:%s 不是这块板上待标的题号 —— 什么都没标。能标的:%s"
                  % (" ".join(unk), " ".join("[%s] %s" % (x["id"], _clause(x["title"], 20)) for x in can) or "(没有)"))
            return 1
        pick = [x for x in can if x["id"] in ids]
    else:
        pick = can
    done_l = []
    n, bad = _answers_mark(pick, datetime.datetime.now().astimezone().isoformat(timespec="seconds"), marked=done_l)
    if n:
        print("✓ --mark:%d 条标成已消化(方案页的题 / 机器卡),每条核一眼你照办了没有:" % n)
        for x in done_l:
            print("  · " + _mark_said(x))
        rest = [x for x in can if x not in done_l]
        if rest:
            print("  还没标的 %d 条(办完再 `answers <板> --mark <题号>`):" % len(rest))
            for x in rest:
                print("  · " + _mark_said(x))
        print("  板上作者写的卡没动 —— 它们用 `answer` 拿掉。")
    elif not bad:
        print("--mark:没有要标的(方案页的题 / 机器卡上没有待处理的回答;板上作者写的卡不标,用 `answer` 拿掉)。")
    for b in bad:
        print("  ⚠ " + b)
    return 1 if bad else 0


