#   ⛔ 板上已落的 data-tier 等属性不清:不进指纹、kit 不读,留着无害。


def _lint_key(msg):
    """一条 lint 报错 → 归一化的开头:去掉强调符、数字换成 N、引号里的具体名字拿掉,取前 28 个字。同一类错在不同时刻、不同行上得到同一个键。"""
    t = re.sub(r"\*\*|`", "", str(msg))
    t = re.sub(r"「[^」]*」|\([^)]*\)|（[^）]*）", "", t)
    t = re.sub(r"\d+", "N", t)
    return re.sub(r"\s+", "", t)[:28]


def _lint_log(path, errors, log_path=None):
    """每次 lint 记一行到 state_dir/board-lint.log(只记,不拦,不印)。

    1110 负责人(方案页 fable-audit-plan-1110 最后一题选「照做」,审计清单第 9 条):近 7 天 lint 的报错行 893 行,
    「他答了,板还挂着」三张卡合计被报 19 次 —— 但分不清是同一个错连报了很久,还是修了又犯。当场修掉的不是问题,连报很久的才是。
    ⇒ 绿的也记(靠它判「这条错消失了」)。算数在 `scripts/board-review/lint_lifetime.py`。
    ⛔ 临时目录里的测试板不记(同 `_registrable_board`);写不进去不影响 lint 本身。"""
    if not _registrable_board(path):
        return False
    try:
        f = log_path or BP.state("board-lint.log")
        os.makedirs(os.path.dirname(f), exist_ok=True)
        rec = {"ts": int(time.time()), "board": os.path.basename(path), "n": len(errors), "keys": sorted(set(_lint_key(e) for e in errors))}
        with open(f, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(rec, ensure_ascii=False) + "\n")
        return True
    except OSError:
        return False


def _wake_log(line):
    try:
        f = BP.state("board-wake.log")
        os.makedirs(os.path.dirname(f), exist_ok=True)
        with open(f, "a", encoding="utf-8") as fh:
            fh.write("%s %s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), line))
    except OSError:
        pass


def _wake_due(ans_dir, shown, woken, now):
    """该叫的回答 —— {页面文件名: {题 id: 记录}}:答案文件 WAKE_FRESH_S 内动过、记录 WAKE_MAX_AGE_S 内写的、他交了、
    还没印给 AI 看过(shown 同 ts)、没叫过(woken 同 ts)。纯读,不抛。"""
    out = {}
    try:
        names = os.listdir(ans_dir)
    except OSError:
        return out
    for fn in names:
        f = os.path.join(ans_dir, fn)
        if not fn.endswith(".json"):
            continue
        try:
            if now - os.path.getmtime(f) > WAKE_FRESH_S:
                continue
            d = json.load(open(f, encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if not isinstance(d, dict):
            continue
        page = _urlparse.unquote(fn[:-len(".json")])
        for k, rec in d.items():
            if not isinstance(rec, dict) or rec.get("copied"):
                continue
            t, ts = _ans_ts_epoch(rec.get("ts")), str(rec.get("ts") or "")
            if t is None or now - t > WAKE_MAX_AGE_S or not _ans_submitted(rec, now):
                continue
            if (shown.get(page) or {}).get(k) == ts or (woken.get(page) or {}).get(k) == ts:
                continue
            out.setdefault(page, {})[k] = rec
    return out


def _wake_live_sessions(sess_dir):
    """开着的 CLI 会话 {cliSessionId: (socket 路径, peerToken, status)}:进程活着、有收件口、钥匙读得到;status = idle / busy(读不到为空)。
    ⚠ inbox.js 的到点叫醒也在调(它的 python 小入口 import board 后按 `sock, tok, st = live[sid]` 取三项),改名 / 改参数 / 改返回值前先告诉 AI Harness(自检「1110 叫醒入口」守着)。"""
    out = {}
    try:
        names = os.listdir(sess_dir)
    except OSError:
        return out
    for fn in names:
        m = re.fullmatch(r"(\d+)\.json", fn)
        if not m:
            continue
        pid = int(m.group(1))
        try:
            os.kill(pid, 0)
        except (OSError, ValueError):
            continue
        try:
            d = json.load(open(os.path.join(sess_dir, fn), encoding="utf-8"))
            sock = d.get("messagingSocketPath")
            sid = d.get("sessionId")
            keys = [k for k in names if k.startswith("%d." % pid) and k.endswith(".key")]
            tok = json.load(open(os.path.join(sess_dir, keys[0]), encoding="utf-8")).get("peerToken") if keys else None
        except (OSError, ValueError, AttributeError):
            continue
        if sid and sock and tok:
            out[sid] = (sock, tok, str(d.get("status") or ""))
    return out


def _wake_pick_sid(board, state, writes, live):
    """这块板归哪条开着的会话:先看 touch 记的(writes,最后一条最准),再看收尾钩子学到的 own;都开着的取最近的那条。"""
    best, best_t = None, -1
    for e in writes:
        if isinstance(e, dict) and e.get("board") == board and e.get("sid") in live and int(e.get("ts") or 0) >= best_t:
            best, best_t = e["sid"], int(e.get("ts") or 0)
    if best:
        return best
    for k, v in (state or {}).items():
        sid = k.split("::", 1)[0]
        if isinstance(v, dict) and v.get("own") == board and sid in live:
            t = int(v.get("since") or 0)
            if t >= best_t:
                best, best_t = sid, t
    return best


def _wake_send(sock_path, token, text, timeout=3.0):
    """往一条会话的收件口塞一条用户消息。成了回 "";没成回原因(⛔ 不抛)。
    ⚠ inbox.js 的到点叫醒也在调(`B._wake_send(sock, tok, text)`,按回的字符串空不空判 sent / error),改名 / 改参数 / 改返回值前先告诉 AI Harness(自检「1110 叫醒入口」守着)。"""
    import socket
    if not hasattr(socket, "AF_UNIX"):
        return "这台机器没有 unix socket"
    s = None
    try:
        s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        s.settimeout(timeout)
        s.connect(sock_path)
        s.sendall((json.dumps({"type": "auth", "token": token}) + "\n").encode("utf-8"))
        s.sendall((json.dumps({"type": "user", "message": {"role": "user", "content": text}}, ensure_ascii=False) + "\n").encode("utf-8"))
        return ""
    except OSError as e:
        return "%s: %s" % (type(e).__name__, e)
    finally:
        if s is not None:
            try:
                s.close()
            except OSError:
                pass


def _wake_hold(pend):
    """这块板上他还在写、没交的条数(_answers_pending 的 draft)—— 非 0 ⇒ 这一轮先不叫这块板(1026 晚,见 cmd_wake_lines)。"""
    return sum(1 for x in pend or () if x.get("unsent", x.get("draft")))   # 1027:点了记下但没交的也算他还在答


def _wake_live_titles(sess_dir, live):
    """开着的会话 {sessionId: 标题};标题在会话文件的 name 字段(桌面版写的)。读不到 ⇒ 空串。"""
    out = {}
    try:
        names = os.listdir(sess_dir)
    except OSError:
        return out
    for fn in names:
        if not re.fullmatch(r"\d+\.json", fn):
            continue
        try:
            d = json.load(open(os.path.join(sess_dir, fn), encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if isinstance(d, dict) and d.get("sessionId") in live:
            out[d["sessionId"]] = str(d.get("name") or d.get("title") or "")
    return out


def _wake_pick_child(child, parent, state, writes, live, titles):
    """⭐ 1110 子线投影:子板上的回答(他多半是在父板上答的投影卡)叫谁 → (sid, "child" | "parent") / (None, None)。
    ① 标题对得上的活子线会话(几条都对得上取最近写过子板的)② 子板的其它写入者(排除父板主人 —— 常驻线代写过子板也会登记成写入者,
    它不该抢在子线前面)③ 都不在 ⇒ 父板主人,消息里写明是谁的卡 ④ 都没有 ⇒ (None, None)。"""
    m = _ONEOFF_BOARD_RE.match(child)
    want = _title_norm(m.group(1)) if m else None
    owner = _wake_pick_sid(parent, state, writes, live)
    if want:
        hit = []
        for s in sorted(live):
            tm = _ONEOFF_TITLE_RE.match(str(titles.get(s) or "").strip())
            if tm and _title_norm(tm.group(1)) == want:
                hit.append(s)
        if hit:
            best = _wake_pick_sid(child, {}, writes, {s: live[s] for s in hit}) if len(hit) > 1 else None
            return (best or hit[0]), "child"
    others = {s: v for s, v in live.items() if s != owner}
    sid = _wake_pick_sid(child, state, [e for e in writes if isinstance(e, dict) and e.get("sid") != owner], others)
    if sid:
        return sid, "child"
    if owner:
        return owner, "parent"
    return None, None


def _wake_text(board_path, items, via=None):
    rp = _wake_repo_path(board_path)
    body = "\n".join(_answers_report(os.path.basename(rp), items, board_arg=rp))
    for item in items:
        if item.get('acceptance') and item.get('choice') == '同意不做':
            body += "\n他同意这件不做了,用 answer --done 收,结论写「不做了」+ 他的话。"
        elif item.get('acceptance') and item.get('choice') == '接着做':
            body += "\n他不同意不做:用 answer --why 回到在做,接着做下去,他补充的放进现状。"
        elif item.get('acceptance') and item.get('asked') and item.get('choice') in ('通过', '不通过'):   # 1117 二轮:提问行的回答卡不是验收
            _nt = re.sub(r'\s+', ' ', str(item.get('note') or '')).strip()
            body += (("\n他看过了回答" + (",补了一句:" + _nt if _nt else "") + "。用 answer --done 收,他的话当结论。") if item.get('choice') == '通过' else
                     ("\n他说没答到点上" + (":" + _nt if _nt else "(没写还想知道什么,回他时先问一句)")
                      + "。用 answer --why 回到在做,照他说的补答,补完再挂一次回答卡(row --review)。"))
        elif item.get('acceptance') and item.get('choice') == '通过':
            body += "\n这是验收通过,用 answer --done 收,他的话当结论。"
        elif item.get('acceptance') and item.get('choice') == '不通过':
            body += "\n验收没通过,用 answer --why 回到在做,把他写的差什么放进现状。"
    if via:                                   # 1110 子线投影:子线不在,叫的是父板主人 ⇒ 写明是谁的卡
        return ("【子线的卡】这是%s的卡(子板 %s),请带给它或代它处理。\n" % (_child_title(os.path.basename(rp)), rp)
                + "【板上回答】负责人在状态板上交了 %d 条回答(最后改于 %s;本机看板服务代他转,原文就在下面,不用再跑 answers;一条回答只转一次)。"
                "照办,办完按「下一步」收卡:\n%s" % (len(items), _ans_when(max(x["ts"] for x in items)), body))
    return ("【板上回答】负责人在你的状态板上交了 %d 条回答(最后改于 %s;本机看板服务代他转,原文就在下面,不用再跑 answers;一条回答只转一次)。"
            "照办,办完按「下一步」收卡:\n%s" % (len(items), _ans_when(max(x["ts"] for x in items)), body))


def _wake_repo_path(web_path):
    """伺服目录里那份是仓里板的硬链 ⇒ 叫醒消息给仓里的路径(与注入钩子给的同一个,1026 投流达人:同一轮两个路径让人起疑)。找不到就原样。"""
    try:
        for q in all_boards():
            if os.path.basename(q) == os.path.basename(web_path) and os.path.samefile(q, web_path):
                return q
    except (OSError, ValueError, TypeError):
        pass
    return web_path


def _accept_card(src, ack):
    head, end = _yours_zone_span(src)
    if not head:
        return None
    for c in _yours_cards(src[head.end():end]):
        card = c.group(0)
        tag = card.split('>', 1)[0]
        if re.search(r'\bdata-ack="%s"' % re.escape(ack), tag) and re.search(r'\bdata-accept="1"', tag):
            return card
    return None


# 依据: 负责人 11-13 14:40 卡 ask-1845f4d9 要求通过后只知会、不叫醒;给本地 inbox 命令 10 秒防止卡住伺服。
ACCEPT_NOTIFY_TIMEOUT = 10


def _accept_log(line):
    """验收自动收行的每个结果:印出来(命令行 / 自检看得到)且记进叫醒日志(伺服起的子进程输出没人留)。"""
    print(line)
    _wake_log(line)


def _node_bin():
    """node 的绝对路径。⚠ 1113 AI Harness 实测:伺服由 launchd 起,PATH 只有 /usr/bin:/bin:/usr/sbin:/sbin,没有 /opt/homebrew/bin ⇒
    裸写 'node' 起不来,验收通过的知会一条没投(失败又只 print,伺服不留)。PATH 里找不到就按 brew / 官方安装位置找。"""
    import shutil
    for c in (shutil.which("node"), "/opt/homebrew/bin/node", "/usr/local/bin/node"):
        if c and os.path.exists(c):
            return c
    return "node"


def _accept_notify(line, text):
    """调用现有 inbox.js 的 --to / --tag / --text / --fyi 接口;返回失败原因,成功为空。"""
    import subprocess
    try:
        r = subprocess.run([_node_bin(), os.path.expanduser('~/.claude/scripts/inbox.js'), 'send', '--to', line,
                            '--tag', '知会', '--text', text, '--fyi', '--from', '状态板(机器:你点了验收通过)'], capture_output=True, text=True, timeout=ACCEPT_NOTIFY_TIMEOUT)   # 1113:伺服没有会话号,不带 --from 信箱写成「(未知线)」
        return '' if r.returncode == 0 else (r.stderr.strip() or r.stdout.strip() or '退出码 %s' % r.returncode)
    except (OSError, subprocess.TimeoutExpired) as e:
        return '%s: %s' % (type(e).__name__, e)


def _accept_owner(board_path, src):
    """沿用 _board_claim 的板与未归档会话归属;多个版本属同一线才算认得出。"""
    try:
        claim = _board_claim(_web_twin(board_path) or board_path, src)
    except (OSError, ValueError):
        return None
    lines = {re.sub(_TITLE_VER_RE, '', part).strip() for part in str(claim or '').split('、') if part.strip()}
    return next(iter(lines)) if len(lines) == 1 else None


def _accept_owner_fallback(bname, state, writes, live, sess_dir):
    """_accept_owner 认不出时:用叫醒同一套认法(_wake_pick_sid)找这块板最近的开着的会话,取它标题去掉版本号当线名。还认不出 ⇒ None。"""
    try:
        sid = _wake_pick_sid(bname, state if isinstance(state, dict) else {}, writes, live)
        title = _wake_live_titles(sess_dir, live).get(sid) if sid else None
    except Exception:
        return None
    line = re.sub(_TITLE_VER_RE, '', str(title or '')).strip()
    return line or None


# ⭐ 1117 tail-3(状态板 v2.2 派):他点了验收通过 ⇒ 机器收卡、往那条线信箱投一句【知会】;认不出板的主人线时原来只记一行日志就丢了。
#   实例:state_dir/board-wake.log 2026-11-16 17:02:46 board=示例项目-工具优化.html(那条线当时在换棒,几分钟后就认得出了)。
#   ⇒ 认不出 ⇒ 记进待投(state_dir/board-server/accept-pending.json,键 = 板文件名::卡号,同一张卡只记一次);
#     wake-lines 每轮(伺服 30 秒那一路和每 CHASE_TICK_S 那一路都进 cmd_wake_lines)先重试:认出了就投、从待投里删;
#     满 ACCEPT_PENDING_MAX_S 还认不出 ⇒ 并进到点该追「认不出主人线」那一条投状态板信箱(同一条,不另起一种),投成就删 —— 每张卡只报这一次。
#     会话清单读不到 = 判不了、不算认不出(_registry_unsure,1115 大扫除 C10 的口径)⇒ 那一轮不报、留着。
#   cmd_wake_lines 里两处认主人(先单独收的通过 / 普通回答里的通过)原来是同一段抄了两遍 ⇒ 合成 _accept_owner_for_pass。
#   否过什么:⛔ 认不出就立刻投状态板 —— 换棒那几分钟最常见,几分钟后就认得出;⛔ 叫醒哪条线 —— 这句知会本来就只进信箱、不叫醒。
ACCEPT_PENDING_MAX_S = 86400   # 依据: 现有「认不出主人每天报一次」的周期(_wake_chase 认不出主人线:一块板一天一条)
# ⭐ 1117 late(状态板 v2.2 派):同一类漏网 —— 验收收掉后他又在卡上补了字(_accept_late_forward),认不出主人线时原来也只记一行日志就丢了
#   (调用方随后记 woken,这一版补的字再也不扫)。⇒ 接进上面同一个待投、同一套重试(_accept_pending_retry)、满一天并进「认不出主人线」那条;
#   键 = late::板文件名::卡号::这次补字的时间(_accept_late_key):和通过知会的「板::卡」分开(同一张卡两条都留),同一次补字只记一次,
#   又补了一次 = 新的一条(不吞);记录带 kind=late,报状态板时那一行写「收卡后他又补了字」(仍不写原话)。
#   否过什么:⛔ 补投成功后像直接投成那样把这条清进 answers-consumed —— 重试在扫补字之前跑,他在等的这段时间又补了一次的话,
#     清掉的是新的那条、投出去的是旧的那句,新补的字就没了;不清只是 answers 里留着这一条(woken 记了同一个时间,不会重投)。


def _accept_late_key(page, cid, rec):
    """收卡后补的字记进待投用的键(1117 late)。"""
    return "late::%s::%s::%s" % (page, cid, str(rec.get("ts") or ""))


def _accept_pending_file():
    return BP.state("board-server", "accept-pending.json")


def _accept_pending_load():
    try:
        d = json.load(open(_accept_pending_file(), encoding="utf-8"))
    except (OSError, ValueError):
        return {}
    return d if isinstance(d, dict) else {}


def _accept_pending_save(d):
    f = _accept_pending_file()
    try:
        if not d:
            if os.path.exists(f):
                os.remove(f)
            return
        os.makedirs(os.path.dirname(f), exist_ok=True)
        tmp = "%s.%d.tmp" % (f, os.getpid())
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(d, fh, ensure_ascii=False)
        os.replace(tmp, f)
    except OSError:
        pass


def _accept_pending_add(board_path, card, tail, now=None, key=None, kind=None):
    """认不出主人线时把给那条线的知会(「【知会】发给 X:」后面那半句)记进待投。同一个键只记一次 ⇒ 返回这次记没记。
    kind:1117 late 起收卡后补的字记 "late"(报状态板时那一行写「收卡后他又补了字」);通过知会不带。"""
    k = key or "%s::%s" % (os.path.basename(board_path), card)
    d = _accept_pending_load()
    if k in d:
        return False
    d[k] = dict(board=os.path.basename(board_path), path=board_path, card=card, tail=tail, at=time.time() if now is None else now)
    if kind:
        d[k]["kind"] = kind
    _accept_pending_save(d)
    return True


def _accept_pending_drop(keys):
    d = _accept_pending_load()
    hit = [k for k in keys if d.pop(k, None) is not None]
    if hit:
        _accept_pending_save(d)
    return hit


def _accept_pending_age(e, now):
    try:
        return now - float(e.get("at") or 0)
    except (TypeError, ValueError):
        return now


def _accept_pending_expired(now=None):
    """待投里满 ACCEPT_PENDING_MAX_S 还在的 ⇒ [(键, 记录)](按键排序)。"""
    now = time.time() if now is None else now
    return [(k, e) for k, e in sorted(_accept_pending_load().items()) if isinstance(e, dict) and _accept_pending_age(e, now) >= ACCEPT_PENDING_MAX_S]


def _accept_owner_for_pass(bname, bpath, src, state, writes, live, sdir, quiet=False):
    """验收通过要投知会的那条线:先按板认(_accept_owner),认不出退回叫醒那套认法(_accept_owner_fallback,1113 AI Harness 实测)。还认不出 ⇒ None。
    1117 tail-3:cmd_wake_lines 两处和待投重试共用这一个;认不出时记一行日志(重试那路 quiet,不每轮记)。"""
    owner = (_accept_owner(bpath, src) if src is not None else None) or _accept_owner_fallback(bname, state, writes, live, sdir)
    if owner is None and not quiet:
        _wake_log("✗ 验收通过认不出主人线,知会记进待投(之后每轮重试,满一天还认不出报状态板) board=%s" % bname)
    return owner


def _accept_pending_retry(now=None, sess_dir=None, dry=False):
    """wake-lines 每轮先跑:待投里认得出主人线了 ⇒ 投、从待投里删。返回投成几条。认不出的留着(满一天由 _wake_chase 并进认不出主人那条)。"""
    d = _accept_pending_load()
    if not d:
        return 0
    now = time.time() if now is None else now
    sdir, live, state, writes = _wake_ctx(sess_dir)
    done, n = [], 0
    for k, e in sorted(d.items()):
        if not isinstance(e, dict) or not e.get("tail"):
            _wake_log("✗ 待投的验收知会记录坏了,删掉:%s" % k)
            done.append(k)
            continue
        try:
            src = open(e.get("path") or "", encoding="utf-8").read()
        except OSError:
            src = None
        owner = _accept_owner_for_pass(e.get("board") or "", e.get("path") or "", src, state, writes, live, sdir, quiet=True)
        if not owner:
            continue
        if dry:
            print("待投的验收知会 %s → 会投给 %s" % (k, owner))
            continue
        try:
            err = _accept_notify(owner, "【知会】发给 %s:%s" % (owner, e["tail"]))
        except Exception as ex:
            err = "%s: %s" % (type(ex).__name__, ex)
        if err:
            _accept_log("✗ 待投的验收知会又没投成 board=%s 卡=%s 线=%s:%s" % (e.get("board"), e.get("card"), owner, str(err)[:300]))
            continue
        done.append(k)
        n += 1
        _accept_log("✓ 待投的验收知会补投了 board=%s 卡=%s 线=%s(认不出主人后 %d 分钟)" % (e.get("board"), e.get("card"), owner, int(_accept_pending_age(e, now) // 60)))
    if done:
        _accept_pending_drop(done)
    return n


ACCEPT_GRACE_S = 90   # 依据: 11-13 23:31:01 点通过 → 23:31:39 写补充(38 秒),卡 17 秒后已被收;留到一分半
#   ⚠ kit.js 验收卡上的提示字写的是「一分半」(ansAcceptHint 等);改这个数要改那几句字,selftest「1115 大扫除 C3」比对


def _accept_settled(x, now):
    """验收卡上这条回答最后一次改动(ts)已满 ACCEPT_GRACE_S 秒(他补字的窗口过了)。读不懂时间 ⇒ 算满(宁可办,别憋着)。
    1114 第 2 步:验收卡一点就交、补的字并进同一条(kit 每次存都带 sub)⇒ 叫醒 / 机器收都按这一条等他停手。"""
    try:
        t = datetime.datetime.fromisoformat(str(x.get('ts') or '').replace('Z', '+00:00')).timestamp()
    except ValueError:
        return True
    return now - t >= ACCEPT_GRACE_S


def _accept_quiet(x, now):
    """纯「通过」(没写补充)且点完已满 ACCEPT_GRACE_S 秒 ⇒ 可以机器收。带补充的、刚点的都不收。"""
    if str(x.get('note') or '').strip():
        return False
    return _accept_settled(x, now)


def _answers_consumed_tail(adir=None, n=4000):
    """answers-consumed.jsonl 最后 n 行(收卡时另存的原文)⇒ [dict]。读不到 ⇒ []。"""
    try:
        with open(_answers_consumed_file(adir), encoding="utf-8") as fh:
            lines = fh.read().splitlines()[-n:]
    except OSError:
        return []
    out = []
    for ln in lines:
        try:
            e = json.loads(ln)
        except ValueError:
            continue
        if isinstance(e, dict):
            out.append(e)
    return out


def _accept_late_notes(page, src, recs, consumed, now):
    """⭐ 1115 大扫除 C7:验收通过被收掉之后他又在那张卡上补的字。纯函数。
    recs = 这块板该看的回答 {卡号: 记录};consumed = _answers_consumed_tail。返回 [(卡号, 现在这条, 收掉那条)]:
    收掉时(同页同卡号最后一次)选的是通过 / 同意不做、卡已不在板上、现在这条有补充且和收掉那份不同、最后一次改动已满 ACCEPT_GRACE_S。"""
    last = {}
    for e in consumed or []:
        if e.get("page") == page and isinstance(e.get("rec"), dict):
            last[str(e.get("id"))] = e["rec"]
    out = []
    for cid, rec in (recs or {}).items():
        old = last.get(cid)
        if not isinstance(rec, dict) or old is None or str(old.get("choice") or "") not in _ACCEPT_YES:
            continue
        note = str(rec.get("note") or "").strip()
        if not note or note == str(old.get("note") or "").strip():
            continue
        if _accept_card(src, cid) or not _accept_settled(rec, now):
            continue
        out.append((cid, rec, old))
    return out


# ⭐ 1115 大扫除 D4(AI Harness 11-15 验收):C7 只看 _wake_due 给的回答 —— 答案文件 15 分钟内动过、记录 30 分钟内写的(WAKE_MAX_AGE_S)⇒
#   11-13 23:03 / 23:31 补的两条(选品 ask-24155518、投流达人 ask-45b66e9f)永远进不去。补的字卡已收、只投知会不叫醒 ⇒ 不用新鲜度那道门。
#   ⇒ 单独一路扫答案目录:记录 ACCEPT_LATE_MAX_S 内写的、有补充、没投过(woken 同 ts),交给 _accept_late_notes 判(规则不变)。
# 依据: 任务书 sweep-1115/D-brief.md 第 4 条「上限放到 7 天」(那两条到 11-15 已约 40 小时)
ACCEPT_LATE_MAX_S = 7 * 86400


def _accept_late_due(adir, woken, now):
    """该看的「收卡后补的字」候选 → {页面文件名: {题 id: 记录}}:ACCEPT_LATE_MAX_S 内写的、有补充、没 copied、没投过(woken 同 ts)。纯读,不抛。"""
    out = {}
    try:
        names = os.listdir(adir)
    except OSError:
        return out
    for fn in names:
        if not fn.endswith(".json"):
            continue
        f = os.path.join(adir, fn)
        try:
            if now - os.path.getmtime(f) > ACCEPT_LATE_MAX_S:
                continue
            d = json.load(open(f, encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if not isinstance(d, dict):
            continue
        page = _urlparse.unquote(fn[:-len(".json")])
        for k, rec in d.items():
            if not isinstance(rec, dict) or rec.get("copied") or not str(rec.get("note") or "").strip():
                continue
            t, ts = _ans_ts_epoch(rec.get("ts")), str(rec.get("ts") or "")
            if t is None or now - t > ACCEPT_LATE_MAX_S or (woken.get(page) or {}).get(k) == ts:
                continue
            out.setdefault(page, {})[k] = rec
    return out


def _accept_late_sweep(adir, woken, now, dry=False, sess_dir=None):
    """收卡后补的字投【知会】(不叫醒)。返回 (投了几条, woken 改没改)。dry ⇒ 只印会投什么。"""
    due = _accept_late_due(adir, woken, now)
    if not due:
        return 0, False
    cons = _answers_consumed_tail(adir)
    web = BP.web_root()
    n, dirty, ctx = 0, False, None
    for page, recs in sorted(due.items()):
        bpath = os.path.join(web, page)
        if not os.path.isfile(bpath):            # 方案页的题不归这里(验收卡只在板上)
            continue
        try:
            src = open(bpath, encoding="utf-8").read()
        except OSError:
            continue
        for cid, rec, old in _accept_late_notes(page, src, recs, cons, now):
            if dry:
                print("验收已收后他补的字 %s/%s → 会投知会给那条线:「%s」" % (page, cid, _clause(str(rec.get("note") or ""), 60)))
                n += 1
                continue
            if ctx is None:
                ctx = _wake_ctx(sess_dir)
            sdir, live, state, writes = ctx
            own = _accept_owner_for_pass(page, bpath, src, state, writes, live, sdir, quiet=True)   # 1117 late:和通过知会同一个认法;认不出的日志由 _accept_late_forward 记
            if _accept_late_forward(page, cid, rec, old, own, adir):
                n += 1
            else:                                # 没投成:这一版不再试(同 C7)
                woken.setdefault(page, {})[cid] = rec.get("ts")
                dirty = True
    return n, dirty


def _wake_state_save(woken):
    try:
        f = _wake_state_file()
        os.makedirs(os.path.dirname(f), exist_ok=True)
        tmp = "%s.%d.tmp" % (f, os.getpid())
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(woken, fh, ensure_ascii=False)
        os.replace(tmp, f)
    except OSError:
        pass


def _accept_late_forward(page, cid, rec, old, owner, adir=None):
    """补的字投【知会】给那条线(同单纯通过的知会路径 _accept_notify,不叫醒);投成 ⇒ 这条记录清进 answers-consumed(再补再投)。返回投没投成。
    1117 late:认不出主人线 ⇒ 记进待投(_accept_pending_add,键 _accept_late_key),返回 False(调用方记 woken,这一版不再扫;之后由待投重试)。"""
    note = str(rec.get("note") or "").strip()
    q = re.sub(r"\s+", " ", str(rec.get("q") or old.get("q") or "")).strip() or cid
    tail = "%s 已经验收收掉了,他 %s 又在那张卡上补了:「%s」" % (_accept_title(q), _ans_when(rec.get("ts")), note)   # 1117 late:直接投和待投补投用同一句
    if not owner:                            # 1117 late:认不出 ⇒ 记进同一个待投,之后每轮重试(原来只记一行日志就丢了)
        _accept_pending_add(os.path.join(BP.web_root(), page), cid, tail, key=_accept_late_key(page, cid, rec), kind="late")
        _accept_log("✗ 验收已收后他又补了字:认不出板主人线,知会记进待投(认出了就补投) board=%s 卡=%s" % (page, cid))
        return False
    msg = "【知会】发给 %s:%s" % (owner, tail)
    try:
        err = _accept_notify(owner, msg)
    except Exception as e:
        err = "%s: %s" % (type(e).__name__, e)
    if err:
        _accept_log("✗ 验收已收后补的字没投成 board=%s 线=%s 卡=%s:%s" % (page, owner, cid, str(err)[:300]))
        return False
    _answers_drop(page, cid, adir)
    _accept_log("✓ 验收已收后补的字已投知会 board=%s 线=%s 卡=%s" % (page, owner, cid))
    return True


def _accept_pass(board_path, card_ack, choice, note, owner=None):
    """他选通过时走与 answer --done 相同的收卡写行路径;失败则让叫醒入口照常通知。
    1115 sw-drop:「不做了,同意吗」卡上点「同意不做」走同一条路,只是结论写成「不做了」并引用他那次点击。"""
    if choice not in _ACCEPT_YES:
        return False
    src = open(board_path, encoding='utf-8').read()
    card = _accept_card(src, card_ack)
    try:
        rec = (_answers_raw(os.path.basename(board_path)) or {}).get(card_ack) or {}
    except (OSError, ValueError):
        return False
    if not card or rec.get('choice') != choice or str(rec.get('note') or '') != str(note or ''):
        return False
    _drop = bool(re.search(r'\bdata-drop="1"', card.split('>', 1)[0]))
    if _drop != (choice == '同意不做'):          # 选项和卡对不上(通过点在不做卡上 / 反过来)⇒ 不收,照普通回答叫醒
        return False
    _asked = bool(re.search(r'\bdata-asked="1"', card.split('>', 1)[0]))      # 1117 提问行的回答卡:收法同验收通过,结论 / 知会写「看过了」
    _small = bool(re.search(r'\bdata-small="', card.split('>', 1)[0]))      # 1116 小修卡:只认「都通过」;普通卡不认「都通过」
    if _small != (choice == '都通过'):
        return False
    if _small:
        _bk = _small_backs(rec, _accept_batch_rows(src, card_ack))
        if _bk:                                  # 打回了几件 ⇒ 没打回的收,打回的照单张不通过转给那条线
            return _small_split(board_path, card_ack, src, card, rec, _bk, owner)
    link = re.search(r'href="#row-([^"]+)"', card)
    if not link:
        return False
    row = link.group(1)
    a, b, z = _row_span(src, row)
    import html as _html
    title = _html.unescape(_row_facts(src[a:b], src[b:z]).get('title') or '交代的事项')
    summary = (('不做了: ' if _drop else '看过了回答: ' if _asked else '验收通过: ') + re.sub(r'[^\u4e00-\u9fff\w ]', ' ', title)).strip()[:60]
    if _sum_problem(summary):
        summary = '交代的这件事项商定不做了' if _drop else '看过了回答: 你问的这件事' if _asked else '验收通过: 你交代的这件事'
    if _drop:
        _cq = re.search(r'<h2 class="q">(.*?)</h2>', card, re.S)
        result = '不做了:你 %s 在「%s」点了「同意不做」' % (_ans_when(rec.get('ts')), _html.unescape(_cq.group(1)).strip() if _cq else title)
    else:
        result = ('你 %s 看过了回答' if _asked else '你 %s 验收通过') % _ans_when(rec.get('ts'))
    if note:
        result += '；' + str(note).strip()
    args = argparse.Namespace(path=board_path, ack=card_ack, res=result, row=row, done=True, why=None,
                              no_row=False, no_touch=True, sum=summary, force=True, _answer_page=os.path.basename(board_path), _auto_accept=True)
    try:
        rc = cmd_answer(args)
    except (SystemExit, OSError, ValueError):
        return False
    # 写入和消费已成功时,即使随后 touch 或通知报错也不能再次叫醒或重收。
    if _accept_card(open(board_path, encoding='utf-8').read(), card_ack) is not None:
        return False
    tail = '%s 他 %s %s' % (_accept_title(title), _ans_when(rec.get('ts')), '同意不做,已收成不做了' if _drop else '看过了' if _asked else '验收通过')   # 1113:原来按 30 字硬截,截出「(你 11-」半截括号
    if _small:                               # 1116 小修卡:一张卡几件 ⇒ 知会里列全
        _si = _small_items(card)
        tail = '他 %s 在今天的小修卡上点了「都通过」,%d 件都收了:%s' % (_ans_when(rec.get('ts')), len(_si), '、'.join(_clause(n, 20) for _k, n, _g, _s in _si))
    if note:
        tail += ';他补充:「%s」' % str(note).strip()
    if not owner:                            # 1117 tail-3:认不出 ⇒ 记进待投,之后每轮重试(原来只记一行日志就丢了)
        _accept_pending_add(board_path, card_ack, tail)
        _accept_log('✗ 验收已收:认不出板主人线,知会记进待投(认出了就补投) board=%s' % os.path.basename(board_path))   # 1113:原来只 print,伺服不留
    else:
        msg = '【知会】发给 %s:%s' % (owner, tail)
        try:
            err = _accept_notify(owner, msg)
        except Exception as e:
            err = '%s: %s' % (type(e).__name__, e)
        if err:
            _accept_log('✗ 验收已收:投知会失败 board=%s 线=%s:%s' % (os.path.basename(board_path), owner, str(err)[:300]))
        else:
            _accept_log('✓ 验收已收,知会已投 board=%s 线=%s' % (os.path.basename(board_path), owner))
    # 知会先于可能慢的 touch:伺服有总超时,不能因刷新慢漏掉已收事项的知会。
    try:
        _touch_child(board_path, '验收收行')
    except Exception as e:
        _accept_log('✗ 验收已收:刷新板失败: %s: %s' % (type(e).__name__, e))
    return True


# ⭐ 1113 等外部计时 ④ 到点叫醒(负责人 11-13 18:17 卡 ask-ee1ae1b3,规则见 _wait_kind 那一节)。
#   入口:cmd_wake_lines 每次一进来先跑这里;boards-server 的 _wake_loop 另外每 CHASE_TICK_S 无条件起一次 wake-lines
#   (原来只在答案目录 15 分钟内有动静才起 —— 到点叫醒不能靠他刚在板上答过题)。
#   一条线一天最多叫一次(记 state_dir/board-server/chase-woken.json:{线名: 叫过那天});到点的几件合成一条。
#   选人与转回答同一套(_wake_pick_sid / _wake_pick_child / _wake_live_sessions / _wake_send,⛔ 签名不改:inbox.js 也在调);
#   那条线正在跑(busy)⇒ 这一轮不叫、不记,下一轮再试;没有开着的会话 ⇒ 投它信箱【要你做#xxxx】--by today(到点没读看门会叫醒)。
#   送到之后给到点的行记 data-chase-due=<那天>(已有的不盖:「叫过那天」只记第一次);次日起它没被处理(计时没重置、没交验收、没挂卡)
#   ⇒ kit 在他板顶首屏「卡着的」标红「等了 N 天没人追」(_chase_overdue / kit chaseOverdue)。关掉:board-config 写 "wake_chase": false。
# 依据: 负责人 11-13 18:17 卡 ask-ee1ae1b3(伺服另加的无条件入口每 10 分钟一次;8777 循环本身 30 秒一轮)
CHASE_TICK_S = BP.CHASE_TICK_S   # 1115 大扫除 C3:与伺服 _wake_loop 共用 board_paths 那一份
# 依据: 信箱看门同样按 10 秒给 node 子进程留时限(ACCEPT_NOTIFY_TIMEOUT 那条实测)
CHASE_INBOX_TIMEOUT = 10


def _stuck_wake_key(path, ack):
    return _STUCK_WAKE_PREFIX + os.path.abspath(path) + "#" + ack


def _chase_state_file():
    return BP.state("board-server", "chase-woken.json")


def _chase_inbox(line, tag, text):
    """没有开着的会话 ⇒ 投那条线的信箱【要你做#xxxx】--by today。成了回 "",没成回原因(⛔ 不抛)。"""
    import subprocess
    try:
        r = subprocess.run([_node_bin(), os.path.expanduser('~/.claude/scripts/inbox.js'), 'send', '--to', line, '--tag', tag, '--by', 'today',
                            '--text', text, '--from', '状态板(机器:到点该追)'], capture_output=True, text=True, timeout=CHASE_INBOX_TIMEOUT)
        return '' if r.returncode == 0 else (r.stderr.strip() or r.stdout.strip() or '退出码 %s' % r.returncode)
    except (OSError, subprocess.TimeoutExpired) as e:
        return '%s: %s' % (type(e).__name__, e)


def _wake_ctx(sess_dir=None):
    """叫醒要的三样:开着的会话、收尾钩子学到的归属、touch 记的写入者(与 cmd_wake_lines 同一份来源)。"""
    _sdir = sess_dir or os.path.join(os.path.expanduser("~"), ".claude", "sessions")
    live = _wake_live_sessions(_sdir)
    try:
        state = json.load(open(BP.state("board-stop-hook", "state.json"), encoding="utf-8"))
    except (OSError, ValueError):
        state = {}
    writes = []
    try:
        for ln in open(BP.state("board-stop-hook", "writes.jsonl"), encoding="utf-8").read().splitlines()[-3000:]:
            try:
                writes.append(json.loads(ln))
            except ValueError:
                pass
    except OSError:
        pass
    return _sdir, live, (state if isinstance(state, dict) else {}), writes


# 依据: 负责人 11-15 大扫除派活原句「认不出主人的板一天一次投进状态板本线信箱」
CHASE_UNOWNED_TO = "状态板"


def _chase_unowned_text(groups, accepts=()):
    """认不出主人的板汇总成一条【知会】(投状态板本线信箱,一天一次)。groups = [(key, g)]。纯函数。
    accepts = [(待投键, 记录)]:满一天还认不出主人线的验收知会(1117 tail-3,并进这同一条);只写板名、卡号、收的时间,不写他的原话。
      收卡后他又补的字(记录 kind=late,1117 late)同在这里,那一行写「收卡后他又补了字,<记下的时间> 记的」。
    ⚠ inbox.js 拒投「像在请对方做事」的【知会】(请你 / 帮我 / 需要你 / 讨论 / 给出 / 怎么改…)⇒ 这里的字避开那些词。"""
    per = {}
    for _k, g in groups:
        for bp, f, _w in g["items"]:
            per.setdefault(bp, []).append(f.get("ack") or "?")
    out = []
    if per:
        out.append("发给 %s:【到点该追 · 认不出主人】%d 块板上有到点该追的行,可认不出板归哪条线(板名 / <title> 去掉版本号后对不上任何没归档的会话,"
                   "launch-titles.json 也没记,也没有最近写过它的开着的会话)⇒ 今天谁都没叫(每块板一天只报一次):" % (CHASE_UNOWNED_TO, len(per)))
    for bp in sorted(per):
        out.append("· %s:%d 件到点(行 %s)· %s" % (os.path.basename(bp), len(per[bp]), "、".join(per[bp][:8]), bp))
    if accepts:
        out.append("%s【验收知会 · 认不出主人】%d 条:他点了验收通过、卡已收,可满一天还认不出板归哪条线,给那条线的知会没投出去(每张卡只报这一次):"
                   % (("另有 " if per else "发给 %s:" % CHASE_UNOWNED_TO), len(accepts)))
        for _k, e in accepts:
            try:
                _when = time.strftime("%m-%d %H:%M", time.localtime(float(e.get("at") or 0)))
            except (TypeError, ValueError):
                _when = "?"
            _how = ("收卡后他又补了字,%s 记的" if e.get("kind") == "late" else "%s 收的") % _when   # 1117 late
            out.append("· %s 卡 %s(%s)· %s" % (e.get("board") or "?", e.get("card") or "?", _how, e.get("path") or ""))
    out.append("认领办法:主人线在自己会话里跑一次 python3 ~/.claude/scripts/board.py touch <板>(记下这条线管它,下一轮就认得出);"
               "那条线已经结束 ⇒ board.py retire <板> --to \"去向\" 让板退场。")
    return "\n".join(out)


def _stuck_chase_reason(why):
    return why.startswith("预计日推了 ")


def _chase_text(line, items, code):
    """一条线的到点叫醒消息:items = [(板路径, fact, 说明)]。每件写明行号 + 标题与三选一的命令。"""
    import shlex as _shx
    _nl = sum(1 for _b, _f, w in items if str(w).startswith(LATE_WHY_HEAD))    # 1119 过了预计、球在你这边的(见 _late_row)
    _ny = sum(1 for _b, _f, w in items if str(w).startswith(YOU_IDLE_WHY))
    _ns = sum(1 for _, _, w in items if _stuck_chase_reason(w))
    _nn = sum(w == _NOTE_CHASE_WHY for _, _, w in items)
    _nw = len(items) - _nl - _ny - _ns - _nn
    _parts = (["%d 件在等外部 / 等日子的到点了" % _nw] if _nw else []) + (["%d 件过了预计还没做完、也没写在等谁" % _nl] if _nl else [])
    if _nn:
        _parts.append("%d 件有新结果待接" % _nn)
    if _ns:
        _parts.append("%d 件停在原处需要处理" % _ns)
    if _ny:
        _parts.append("%d 件只写在机器汇总卡里、满一天没人改" % _ny)
    head = "【要你做#%s】%s【到点该追】你的状态板上有 %s(机器每天只叫一次,几件合在这一条):" % (
        code, ("发给 %s:" % line) if line else "", ",".join(_parts))
    out = [head]
    for i, (bp, f, why) in enumerate(items, 1):
        q, ack = _shx.quote(bp), f.get("ack") or "?"
        sub = ("(%s 的行)" % _child_title(os.path.basename(bp))) if _ONEOFF_BOARD_RE.match(os.path.basename(bp)) else ""
        if why == _NOTE_CHASE_WHY:
            out.append("%d. %s 行 %s「%s」—— %s。用 row --say / --review / --checked 接住。" %
                       (i, os.path.basename(bp), ack, _clause(f["title"], 30), "；".join(
                           ("处理失败，" if r.get("fail") else "") + r["text"] + ("（产物 " + r["path"] + "）" if r.get("path") else "")
                           for r in f["machine_notes"].values())))
            continue
        if _wait_kind(f.get("st"), f.get("you"), f.get("wait_for")) == "ext":
            why += "。等的东西还需要吗？不需要了就改这一行（row --say / 交验收 / 挂不做了卡）"
        if _stuck_chase_reason(why):
            out.append("%d. %s 行 %s「%s」%s—— %s。查清卡点，更新现状或交验收。" %
                       (i, os.path.basename(bp), ack, _clause(f.get("title") or "", 30), sub, why))
            continue
        if why.startswith(YOU_IDLE_WHY):
            b = "python3 ~/.claude/scripts/board.py"
            out.append("%d. %s 行 %s「%s」%s—— %s。二选一:" % (i, os.path.basename(bp), ack, _clause(f.get("title") or "", 30), sub, why))
            out.append('   ① 还要他动 ⇒ 挂成正经卡,写清要他干什么:%s ask %s --row %s --q "哪件事 + 要他干什么" …' % (b, q, ack))
            out.append('   ② 不用他了 ⇒ 去掉要他、写清在等谁:%s row %s --ack %s --you wait --wait-for "等谁 / 等什么"' % (b, q, ack))
            continue
        if why.startswith(LATE_WHY_HEAD):             # 1119:球在你这边 ⇒ 三个出口,没有「去问他」
            b = "python3 ~/.claude/scripts/board.py"
            out.append("%d. %s 行 %s「%s」%s—— %s。三选一:" % (i, os.path.basename(bp), ack, _clause(f.get("title") or "", 30), sub, why))
            out.append("   ① 做完了 ⇒ 交验收:%s row %s --ack %s --review --q \"…\" --got \"…\"" % (b, q, ack))
            out.append("   ② 其实在等别人 ⇒ 写清等谁:%s row %s --ack %s --status blocked --you wait --wait-for \"等谁 / 等什么\"" % (b, q, ack))
            out.append("   ③ 还要做、得改日子 ⇒ 挪预计并写新出现了什么:%s row %s --ack %s --eta MM-DD --why \"新出现了什么\" --not-waiting \"现在就能做的事（没有写 none）\"" % (b, q, ack))
            continue
        if why.startswith(STALL_WHY_HEAD):            # 1116 等外部总时长:这一轮只 --chase 不收
            b = "python3 ~/.claude/scripts/board.py"
            out.append("%d. %s 行 %s「%s」%s—— %s。这一次只 --chase 不收,四选一:" % (i, os.path.basename(bp), ack, _clause(f.get("title") or "", 30), sub, why))
            out.append("   ① 换一条路再追:%s row %s --ack %s --chase \"追了谁、怎么问的\" --escalate \"换了什么路(升级 / 换渠道 / 换人)\"" % (b, q, ack))
            out.append("   ② 让他定继续等还是放弃 ⇒ 挂卡:%s ask %s --row %s --q \"…\" …" % (b, q, ack))
            out.append("   ③ 有结果交验收:%s row %s --ack %s --review --q \"…\" --got \"…\" --see \"…\"" % (b, q, ack))
            out.append("   ④ 不做了:%s row %s --ack %s --drop \"为什么不做\"" % (b, q, ack))
            continue
        out.append("%d. %s 行 %s「%s」%s—— %s。三选一:" % (i, os.path.basename(bp), ack, _clause(f.get("title") or "", 30), sub, why))
        out.append("   ① 追问外部:python3 ~/.claude/scripts/board.py row %s --ack %s --chase \"追了谁、怎么问的\"" % (q, ack))
        out.append("   ② 有结果交验收:python3 ~/.claude/scripts/board.py row %s --ack %s --review --q \"…\" --got \"…\"(有专门页面再加 --url … --check …)" % (q, ack))
        out.append("   ③ 只有他能动 ⇒ 挂卡:python3 ~/.claude/scripts/board.py ask %s --row %s --q \"…\" …" % (q, ack))
    if _ny:
        out.append("只写在机器汇总卡里的几件今天不处理,明天起他首屏「卡着的」标红「在等你:<行标题> · 挂了 N 天没人挂卡」。")
    if _nw:
        out.append("今天不处理,明天起这几件在他板顶首屏「卡着的」标红「等了 N 天没人追」。")
    if _nl:
        out.append("过了预计那几件今天不处理,明天起他首屏「卡着的」各标一行红「卡在 <这条线> · 过了预计 N 天」;光 --checked 不算处理。")
    if any(str(w).startswith(STALL_WHY_HEAD) for _b, _f, w in items):
        out.append("「换一条路」那几件这一轮只叫这一次;今天不处理,明天起他首屏「卡着的」标红「等了 N 个工作日没结果」。")
    return "\n".join(out)


def _chase_mark(src, acks, day):
    """给这几行记 data-chase-due=day(已有的不盖)。纯函数 → 新 src。"""
    for ack in acks:
        try:
            a, b, _z = _row_span(src, ack)
        except ValueError:
            continue
        if re.search(r'\bdata-chase-due\s*=', src[a:b]):
            continue
        src = src[:a] + _attr_set(src[a:b], "data-chase-due", day) + src[b:]
    return src


# 依据: 11-24 任务，10 点和 18 点只记一周，11-30 复盘。
_DOING_TODAY_HOURS = (10, 18)
_DOING_TODAY_END = datetime.date(2026, 11, 30)  # 依据: 11-30 复盘。
_DOING_TODAY_EVENT = "doing-today-idle"  # 依据: 一周观察写进 board-hints.log。


def _doing_today_idle(facts, today):
    idle = []
    for f in facts:
        if not f["ack"] or f["st"] != "doing" or f["eta"] != today or f["wait_for"]:
            continue
        moved, _ = _row_moved_at(f)
        if moved and moved.date() < today and (not f["txt"] or f["txt"] == f["txt_now"]):
            idle.append(f["ack"])
    return idle


def _log_doing_today(groups, now, woken):
    # 否过真叫醒：只采一周数据，11-30 按观测再决定。 否过在做行数硬上限：回放没有证据表明并发导致沉底。
    day = now.date().isoformat()
    hour = _DOING_TODAY_HOURS[1 if now.hour >= _DOING_TODAY_HOURS[1] else 0]
    dirty = False
    for line, items in sorted(groups.items()):
        key = "%s:%s:%s" % (_DOING_TODAY_EVENT, hour, line)
        if woken.get(key) == day:
            continue
        _board_write_event(items[0]["board"], "wake-lines", [], log_path=BP.state("board-hints.log"),
                           event=_DOING_TODAY_EVENT, line=line, hour=hour, day=day, rows=items)
        woken[key] = day
        dirty = True
    return dirty


def _wake_chase(dry=False, sess_dir=None, now=None, boards=None):
    """到点该追的行叫醒各自板的主人线(见上面那段)。返回这一轮叫了 / 投了几条线。"""
    if BP._load().get("wake_chase", True) is False:
        return 0
    now = time.time() if now is None else now
    now_dt = datetime.datetime.fromtimestamp(now)
    today, day = now_dt.date(), now_dt.date().isoformat()
    boards = all_boards() if boards is None else list(boards)
    groups, idle_groups = {}, {}
    log_idle = not dry and today <= _DOING_TODAY_END and now_dt.hour >= _DOING_TODAY_HOURS[0]
    ctx = None
    try:                                           # 1115 大扫除 A6:「暂停跳过」「认不出主人」一天只记一次 ⇒ 记号和叫醒记录同一个文件,先读
        woken = json.load(open(_chase_state_file(), encoding="utf-8"))
    except (OSError, ValueError):
        woken = {}
    woken = woken if isinstance(woken, dict) else {}
    dirty = False
    for bp in boards:
        try:
            src = open(bp, encoding="utf-8").read()
        except OSError:
            continue
        facts = (_yours_zone_rows(src, today=today) or {}).get("facts", [])
        if log_idle and (idle := _doing_today_idle(facts, today)):
            line = _accept_owner(bp, src) or os.path.splitext(os.path.basename(bp))[0]
            idle_groups.setdefault(line, []).extend(dict(board=os.path.basename(bp), row=ack) for ack in idle)
        due = []
        for f in facts:
            if not f.get("ack"):
                continue
            escalation = _stuck_escalation(f, today, now_dt) if f.get("st") == "watch" else None
            if escalation:
                if _stuck_wake_key(bp, f["ack"]) not in woken:
                    due.append((f, escalation))
                continue
            _sl = _wait_stall(f, today)                # 1116 等外部总时长:满 7 个工作日 ⇒ 这一件换成「换一条路」那句
            if _sl and f.get("stall_due"):
                continue                               # 这一轮已经叫过 ⇒ 不再天天叫(次日没处理他首屏标红);换了路 / 了结 / 换了对象才清
            d = (None, _stall_why(_sl)) if _sl else _chase_due(f, today, now_dt)
            if d:
                due.append((f, d[1]))
        # 否过全量执行者登记叫醒：终态回填已覆盖同一批回放案例。
        aged_notes = [(f, _NOTE_CHASE_WHY) for f in facts if f["ack"] and any(
            r.get("fail") or _note_hours(r, now) >= _NOTE_CHASE_HOURS for r in f["machine_notes"].values())]
        if not (due or aged_notes):
            continue
        _pz = _board_paused(facts, now_dt, src=src)   # 1115 D3b:明示标的暂停也认
        if _pz:                                    # 1114(AI Harness #bc40):暂停的线叫不醒、退信没人读 ⇒ 跳过;重开那条线时 recheck 逐条拉回来
            if not dry and woken.get("paused:" + os.path.basename(bp)) != day:   # 1115 A6:原来每 10 分钟记一行(7 天 780 行)⇒ 一块板一天一行
                _wake_log("到点该追 跳过 %s:这条线暂停了(%s;今天不再记)" % (os.path.basename(bp), _paused_label(_pz)))
                woken["paused:" + os.path.basename(bp)] = day
                dirty = True
            continue
        if ctx is None:
            ctx = _wake_ctx(sess_dir)
        sdir, live, state, writes = ctx
        bname = os.path.basename(bp)
        if _child_parent_of(bp):                   # 子线的行:子线在叫子线,不在叫父板主人(同转回答)
            sid, _m = _wake_pick_child(bname, _child_parent_of(bp), state, writes, live, _wake_live_titles(sdir, live))
            line = None if _m == "parent" else (_accept_owner(bp, src) or None)
            if _m == "parent":
                pp = _child_parent_path(bp, _child_parent_of(bp), boards)
                try:
                    line = _accept_owner(pp, open(pp, encoding="utf-8").read()) if pp else None
                except OSError:
                    line = None
        else:
            sid = _wake_pick_sid(bname, state, writes, live)
            line = _accept_owner(bp, src)
        if not line and sid:
            line = re.sub(_TITLE_VER_RE, '', str(_wake_live_titles(sdir, live).get(sid) or '')).strip() or None
        key = line or ("sid:%s" % sid if sid else "board:%s" % bname)
        g = groups.setdefault(key, dict(line=line, sid=None, items=[], notes=[]))
        g["sid"] = g["sid"] or sid
        g["items"] += [(bp, f, why) for f, why in due]
        g["notes"] += [(bp, f, why) for f, why in aged_notes]
    dirty = _log_doing_today(idle_groups, now_dt, woken) or dirty
    live = ctx[1] if ctx else {}
    n = 0
    unowned = []
    for key, g in sorted(groups.items()):
        if not g["items"]:
            continue
        g["items"].extend(g["notes"])
        if woken.get(key) == day:                  # 一条线一天最多一次(CHASE_WAKE_PER_DAY)
            continue
        sid = g["sid"]
        what = " ".join("%s/%s" % (os.path.basename(bp), f.get("ack")) for bp, f, _w in g["items"])
        if sid and live.get(sid, ("", "", ""))[2] == "busy":
            if dry:
                print("到点该追 %s → 先不叫:那条线正在跑(下一轮再试)" % key)
            continue
        code = hashlib.sha1(("%s|%s" % (key, day)).encode("utf-8")).hexdigest()[:4]
        text = _chase_text(g["line"], g["items"], code)
        if dry:
            print("到点该追 %s → %s:%s" % (key, sid or ("信箱" if g["line"] else "认不出主人线"), what))
            continue
        if sid and sid in live:
            err, how = _wake_send(live[sid][0], live[sid][1], text), "叫了"
        elif g["line"]:
            err, how = _chase_inbox(g["line"], "要你做#%s" % code, text), "投了信箱"
        else:                                      # 1115 A6:认不出主人 ⇒ 原来每 10 分钟重试一次、记一行、从不上报(7 天 1267 次);改成一天一次汇总投状态板本线信箱
            if woken.get("unowned:" + key) != day:
                unowned.append((key, g))
            continue
        _wake_log("%s 到点该追 线=%s sid=%s %s" % (("✓ " + how) if not err else "✗ 没叫(%s;下一轮再试)" % str(err)[:200], key, (sid or "-")[:8], what))
        if err:
            continue
        woken[key] = day
        n += 1
        per = {}
        for bp, f, why in g["items"]:
            if _stuck_chase_reason(why):
                woken[_stuck_wake_key(bp, f["ack"])] = day
            else:
                per.setdefault(bp, []).append((f, why))
        for bp, its in per.items():
            try:
                before = open(bp, encoding="utf-8").read()
                eligible = [f["ack"] for f, why in its if not why.startswith((STALL_WHY_HEAD, YOU_IDLE_WHY, _NOTE_CHASE_WHY))]
                if any(why.startswith(YOU_IDLE_WHY) for _, why in its):
                    fresh = {f["ack"]: f for f in (_yours_zone_rows(before, today=today) or {}).get("facts", [])}
                    for f, why in its:
                        current = fresh.get(f["ack"], {})
                        if why.startswith(YOU_IDLE_WHY) and _chase_due(current, today, now_dt) == ("you-idle", YOU_IDLE_WHY):
                            eligible.append(f["ack"])
                after = _chase_mark(before, eligible, day)
                after = _stall_mark(after, [f for f, _w in its if _w.startswith(STALL_WHY_HEAD)], day)   # 1116 等外部总时长
                if after != before:
                    with open(bp, encoding="utf-8") as fh:
                        if fh.read() != before:
                            continue          # 读进来之后被人改了 ⇒ 这一轮不记,明天照样按 wait-since 判
                    with open(bp, "r+b") as fh:
                        b = after.encode("utf-8"); fh.write(b); fh.truncate()
            except OSError:
                pass
    # 1117 tail-3:满一天还认不出主人线的验收知会,并进下面这同一条(不另起一种);没投成的今天不再试
    _ax = [] if dry else [(k, e) for k, e in _accept_pending_expired(now) if woken.get("accept-unowned:" + k) != day]
    if (unowned or _ax) and not dry:           # 1115 大扫除 C10:会话清单读不全 / 读空(桌面版重启时常见)⇒ 判不了,本轮不投「认不出主人」,下一轮再判
        _ru = _registry_unsure(sess_dir=ctx[0] if ctx else None, now=now)
        if _ru:
            if woken.get("unowned-unsure") != day:
                _wake_log("到点该追 判不了主人(%s),本轮不投「认不出主人」:%s(下一轮再判;今天不再记)" % (
                    _ru, " ".join(sorted({os.path.basename(bp) for _k, _g in unowned for bp, _f, _w in _g["items"]} | {e.get("board") or "?" for _k, e in _ax}))))
                woken["unowned-unsure"] = day
                dirty = True
            unowned = []
            _ax = []
    if unowned:                                # 1115 大扫除 C5:Codex 桌面线程转录里提到的板算有主,不进「认不出主人」那条知会
        unowned, _cxo = _unowned_minus_codex(unowned, _codex_board_owners(
            sorted({os.path.basename(bp) for _k, _g in unowned for bp, _f, _w in _g["items"]}), now=now))
        if _cxo and not dry:
            _cx1 = _codex_board_owners(sorted({os.path.basename(bp) for _k, _g in _cxo for bp, _f, _w in _g["items"]}), now=now)
            for _k, _g in _cxo:
                _nm = sorted({os.path.basename(bp) for bp, _f, _w in _g["items"]})
                _wake_log("到点该追 %s 归 Codex 线程(cwd %s),本机叫不醒它,等那条线回来处理(今天不再记)"
                          % (" ".join(_nm), "、".join(sorted({(_cx1.get(n) or {}).get("cwd") or "没记" for n in _nm}))))
                woken["unowned:" + _k] = day
            dirty = True
    if (unowned or _ax) and not dry:
        names = sorted({os.path.basename(bp) for _k, _g in unowned for bp, _f, _w in _g["items"]})
        err = _chase_inbox(CHASE_UNOWNED_TO, "知会", _chase_unowned_text(unowned, accepts=_ax))
        _wake_log("%s 到点该追 认不出主人线:%s%s(今天不再记)" % (("✓ 投了%s信箱" % CHASE_UNOWNED_TO) if not err else "✗ 投%s信箱没成(%s)" % (CHASE_UNOWNED_TO, str(err)[:200]), " ".join(names),
                                                     ("%s验收知会 %d 条(%s)" % (" · " if names else "", len(_ax), " ".join(k for k, _e in _ax))) if _ax else ""))
        for _k, _g in unowned:
            woken["unowned:" + _k] = day
        if _ax and not err:                        # 1117 tail-3:投成 ⇒ 从待投里删(每张卡只报这一次);没投成 ⇒ 今天不再试,明天再报
            _accept_pending_drop([k for k, _e in _ax])
        for _k, _e in (_ax if err else []):
            woken["accept-unowned:" + _k] = day
        dirty = True                               # 1115 A6 认不出主人的记号也要落盘
    if not dry and (n or dirty):
        cut = (today - datetime.timedelta(days=14)).isoformat()
        woken = {k: v for k, v in woken.items() if k.startswith(_STUCK_WAKE_PREFIX) or str(v) >= cut}
        try:
            f = _chase_state_file()
            os.makedirs(os.path.dirname(f), exist_ok=True)
            tmp = "%s.%d.tmp" % (f, os.getpid())
            with open(tmp, "w", encoding="utf-8") as fh:
                json.dump(woken, fh, ensure_ascii=False)
            os.replace(tmp, f)
        except OSError:
            pass
    return n


def cmd_wake_lines(dry=False, sess_dir=None, now=None):
    """8777 伺服每 30 秒叫一次(只在答案目录 15 分钟内有动静时)。见上面那段。"""
    if BP._load().get("wake_lines", True) is False or os.environ.get("BOARD_WAKE") == "0":
        return 0
    now = time.time() if now is None else now
    try:                                              # 1117 tail-3:认不出主人线时记下的验收知会先重试(认出了就投;出错不挡下面)
        _accept_pending_retry(now=now, sess_dir=sess_dir, dry=dry)
    except Exception as e:
        _wake_log("✗ 待投的验收知会没重试成(%s: %s)" % (type(e).__name__, str(e)[:300]))
    try:                                              # 1113 等外部计时:到点该追的先叫(一条线一天一次;出错不挡下面转回答)
        _wake_chase(dry=dry, sess_dir=sess_dir, now=now)
    except Exception as e:
        _wake_log("✗ 到点该追没跑成(%s: %s)" % (type(e).__name__, str(e)[:300]))
    if not dry and os.environ.get("BOARD_PRUNE_SWEEP") != "0":   # 1116 周修:每天一次全机收做完超过 7 天的行(没人 touch 的板也收;出错不挡下面转回答)
        try:
            _ps = _prune_sweep_daily(now)
            if _ps and (_ps["moved"] or _ps["failed"]):
                _wake_log("%s 每天收做完行:%s%s" % ("✗" if _ps["failed"] else "✓",
                                                 "、".join("%s %d 行" % x for x in _ps["moved"]) or "没有要搬的",
                                                 ("· 没收成:" + "、".join("%s(%s)" % x for x in _ps["failed"])) if _ps["failed"] else ""))
        except Exception as e:
            _wake_log("✗ 每天收做完行没跑成(%s: %s)" % (type(e).__name__, str(e)[:300]))
    if not dry and os.environ.get("BOARD_KIT_GC") != "0":   # 1115 sw-gc:每周一次挪开没人引用的旧 kit(出错不挡下面转回答)
        try:
            _kg = _kit_gc_weekly(now)
            if _kg and (_kg["moved"] or _kg["trashed"]):
                _wake_log("✓ kit 清理:挪开 %d 个没人引用的旧文件,%d 批进废纸篓,留 %d 个" % (len(_kg["moved"]), len(_kg["trashed"]), _kg["kept"]))
            _rg = _replaced_gc(now)                    # 1116:publish --replace 挪开的旧版放满 7 天进废纸篓
            if _rg:
                _wake_log("✓ 盖掉的旧页清理:%d 个放满 %d 天,进废纸篓" % (len(_rg), PUBLISH_REPLACED_DAYS))
        except Exception as e:
            _wake_log("✗ kit 清理没跑成(%s: %s)" % (type(e).__name__, str(e)[:300]))
    adir = BP.state("board-server", "answers")
    try:
        shown = json.load(open(_answers_shown_file(), encoding="utf-8"))
    except (OSError, ValueError):
        shown = {}
    try:
        woken = json.load(open(_wake_state_file(), encoding="utf-8"))
    except (OSError, ValueError):
        woken = {}
    shown = shown if isinstance(shown, dict) else {}
    woken = woken if isinstance(woken, dict) else {}
    retry = woken.get("__retry__") if isinstance(woken.get("__retry__"), dict) else {}
    woken["__retry__"] = retry = {k: v for k, v in retry.items() if now - float(v or 0) < WAKE_MAX_AGE_S}
    try:                                              # 1115 大扫除 D4:收卡后补的字单独一路扫(不受 WAKE_MAX_AGE_S 限制,上限 7 天;出错不挡下面转回答)
        _late_n, _late_dirty = _accept_late_sweep(adir, woken, now, dry=dry, sess_dir=sess_dir)
    except Exception as e:
        _late_dirty = False
        _wake_log("✗ 收卡后补的字没扫成(%s: %s)" % (type(e).__name__, str(e)[:300]))
    due = _wake_due(adir, shown, woken, now)
    # 1113 AI Harness 报:他点了验收通过、紧接着在那条线对话里发话 ⇒ 钩子先把回答贴给了那条线(answers-shown),
    #   _wake_due 按「已经印给 AI 看过」跳过 ⇒ 自动收也跟着没了。验收通过的收行不看 shown(只看 woken),其余回答照旧。
    due_pass = {pg: {k: r for k, r in recs.items() if str(r.get("choice") or "") in _ACCEPT_YES}
                for pg, recs in _wake_due(adir, {}, woken, now).items()}
    due_pass = {pg: v for pg, v in due_pass.items() if v}
    if not due and not due_pass:
        if _late_dirty and not dry:
            _wake_state_save(woken)
        return 0
    due_any = sorted(set(due) | set(due_pass))
    web = BP.web_root()
    boards = {}                                       # 板文件名 → 板路径(boards-web 里的硬链)
    for pg in due_any:
        if os.path.isfile(os.path.join(web, pg)):
            boards[pg] = os.path.join(web, pg)
    if any(pg not in boards for pg in due_any):       # 方案页 ⇒ 找挂着它的板(只在有方案页的回答时才扫全部板)
        for f in glob.glob(os.path.join(web, "*.html")):
            try:
                src = open(f, encoding="utf-8").read()
            except OSError:
                continue
            if any(pg in _answers_proposal_pages(src) for pg in due_any if pg not in boards):
                boards[os.path.basename(f)] = f
    _sdir = sess_dir or os.path.join(os.path.expanduser("~"), ".claude", "sessions")
    live = _wake_live_sessions(_sdir)
    try:
        state = json.load(open(BP.state("board-stop-hook", "state.json"), encoding="utf-8"))
    except (OSError, ValueError):
        state = {}
    writes = []
    try:
        for ln in open(BP.state("board-stop-hook", "writes.jsonl"), encoding="utf-8").read().splitlines()[-3000:]:
            try:
                writes.append(json.loads(ln))
            except ValueError:
                pass
    except OSError:
        pass
    for bname, bpath in sorted(boards.items()):
        try:
            src = open(bpath, encoding="utf-8").read()
        except OSError:
            continue
        pend = _answers_pending(src, bname, _answers_map(bpath, src), now=now)
        # 1113 负责人第一次真点(AI Harness 报):验收卡点「通过」他就认了 ⇒ 不等他点「交给这条线」、也不被同板别的草稿 / 刚交等满压住,先单独收掉。
        if BP._load().get('accept_autoclose', True) is not False and not dry:
            # 1113 夜(电商-投流达人【急】):点完通过 17 秒就收,38 秒后写的补充没人收 ⇒ 只收没写补充、点完满一分半的;带补充的照普通回答叫醒那条线
            passes = [x for x in pend if x.get('kind') == 'card' and x.get('choice') in _ACCEPT_YES and _accept_quiet(x, now)
                      and (x["id"] in (due.get(x["page"]) or {}) or x["id"] in (due_pass.get(x["page"]) or {}))
                      and _accept_card(src, x['id'])]
            if passes:
                owner = _accept_owner_for_pass(bname, bpath, src, state, writes, live, _sdir)   # 1117 tail-3:认不出 ⇒ _accept_pass 把知会记进待投
                done_ids = set()
                for x in passes:
                    if _accept_pass(bpath, x['id'], x['choice'], x.get('note', ''), owner=owner):
                        woken.setdefault(x['page'], {})[x['id']] = x['ts']; done_ids.add((x['page'], x['id']))
                if done_ids:
                    try:
                        src = open(bpath, encoding="utf-8").read()
                    except OSError:
                        continue
                    pend = [x for x in pend if (x['page'], x['id']) not in done_ids]
        # 1115 大扫除 D4:C7 原来在这里只看 due(30 分钟内的回答)⇒ 挪到上面 _accept_late_sweep 单独一路(7 天内都看)
        items = [x for x in pend if not x.get("unsent", x["draft"]) and x["id"] in (due.get(x["page"]) or {})]
        if not items:
            continue
        # ⭐ 1026 晚负责人(个人助理板 21:46:16 / 21:46:26 两张卡各叫醒一次):「你应该等我所有的回复完啊」
        #   ⇒ 这块板上还有他在写、没交的 ⇒ 这一轮不叫(不记 woken),等他点右下角「交给这条线」或那几条停手到点算交,再一起叫。
        #   草稿最多 10 分钟就算交(ANS_SUB_NOTE_S),所以最多晚 10 分钟,不会一直憋着。
        held = _wake_hold(pend)
        if held:
            if dry:
                print("%s → 先不叫:还有 %d 条他在写、没交" % (bname, held))
            continue
        newest = max([os.path.getmtime(_answers_file(pg, adir)) for pg in {x["page"] for x in items}
                      if os.path.exists(_answers_file(pg, adir))] or [0])
        if now - newest < WAKE_SETTLE_S:
            if dry:
                print("%s → 先不叫:%d 秒前刚交,等满 %d 秒把连着交的并成一条" % (bname, int(now - newest), WAKE_SETTLE_S))
            continue
        for x in items:
            _acard = _accept_card(src, x['id']) if x.get('kind') == 'card' else None
            x['acceptance'] = bool(_acard)
            x['asked'] = bool(_acard and re.search(r'\bdata-asked="1"', _acard.split('>', 1)[0]))   # 1117 二轮:回答卡叫醒不写「验收」(见 _wake_text)
            if x['acceptance'] and not x.get('choice') and str(x.get('note') or '').strip():
                x['choice'] = '接着做' if _accept_is_drop(src, x['id']) else '不通过'    # 1113 负责人在验收卡上只写了补充没选 ⇒ 按不通过叫醒那条线,话进现状(不做卡 ⇒ 接着做)
        # ⭐ 1114 第 2 步(验收答题合一):验收卡点「不通过」/ 带补充的(含通过后再补字)一点就交,但等最后一次改动满 ACCEPT_GRACE_S 秒再叫 ——
        #   他可能还在补(同 11-13 23:31 点完通过 38 秒才写补充、补充被吞那次)。纯通过不在这里等:下面照旧机器收、不叫醒。这一轮整块板先不叫、不记。
        _young = [x for x in items if x['acceptance'] and not (x.get('choice') in _ACCEPT_YES and not str(x.get('note') or '').strip())
                  and not _accept_settled(x, now)]
        if _young:
            if dry:
                print("%s → 先不叫:验收卡上的回答刚改过,等满 %d 秒(他可能还在补)" % (bname, ACCEPT_GRACE_S))
            continue
        if BP._load().get('accept_autoclose', True) is not False and not dry:
            remaining = []
            owner = (_accept_owner_for_pass(bname, bpath, src, state, writes, live, _sdir)   # 1113 AI Harness:认不出退回叫醒那套认法;1117 tail-3 两处合成一个函数
                     if any(x['acceptance'] and x.get('choice') in _ACCEPT_YES for x in items) else None)
            for x in items:
                _pq = x['acceptance'] and x.get('choice') in _ACCEPT_YES and not str(x.get('note') or '').strip()
                if _pq and not _accept_quiet(x, now):
                    continue                                 # 刚点通过:等满一分半(他可能还要写补充),这一轮不收也不叫
                if _pq and _accept_pass(bpath, x['id'], x['choice'], x.get('note', ''), owner=owner):
                    woken.setdefault(x['page'], {})[x['id']] = x['ts']
                else:
                    remaining.append(x)
            items = remaining
            if not items:
                continue
        sid = _wake_pick_sid(bname, state if isinstance(state, dict) else {}, writes, live)
        via = None
        if _child_parent_of(bpath):           # 1110 子线投影:子板的回答 —— 子线在叫子线,不在叫父板主人(写明是谁的卡)
            sid, _cmode = _wake_pick_child(bname, _child_parent_of(bpath), state if isinstance(state, dict) else {}, writes, live,
                                           _wake_live_titles(_sdir, live))
            via = bname if _cmode == "parent" else None
        if sid and live[sid][2] == "busy":
            if dry:
                print("%s → 先不叫:那条线正在跑(它这一轮收尾前自己会再查板)" % bname)
            continue
        what = " ".join("%s/%s" % (x["page"], x["id"]) for x in items)
        keys = ["%s::%s::%s" % (x["page"], x["id"], x["ts"]) for x in items]
        if not dry and all(now - float(retry.get(k) or 0) < WAKE_RETRY_S for k in keys):
            continue                                  # 刚试过没送到 ⇒ 等 WAKE_RETRY_S 再试
        if dry:
            print("%s → %s:%s" % (bname, sid or "没有开着的会话", what))
            continue
        err = _wake_send(live[sid][0], live[sid][1], _wake_text(bpath, items, via=via)) if sid else "没有开着的会话"
        _wake_log("%s board=%s sid=%s %s" % ("✓ 叫了" if not err else "✗ 没叫(%s;%d 分钟后再试)" % (err, WAKE_RETRY_S // 60),
                                             bname, (sid or "-")[:8], what))
        if err:
            for k in keys:
                retry[k] = now
            continue
        for x in items:
            woken.setdefault(x["page"], {})[x["id"]] = x["ts"]
        for k in keys:
            retry.pop(k, None)
        _answers_shown_mark(items)                    # 原文已经送进那条线 = 它看过了(answer 收卡要用)
    if not dry:
        _wake_state_save(woken)
    return 0


# ──────────────── 0930 #5516:改卡 / 改行也降到一行命令
#   与 `ask` 同一个道理(0916 cc控制:「闸挡的是懒,降门槛是消除懒的理由」):建卡已经是一行,
#   可他答完之后「拿掉那张卡、把那一行改成不再等他」、在做的活「更新一句进展」,仍要手改 HTML(写脚本找锚点、原地写、touch)
#   ⇒ 赶时间就不改,板停在旧结论。09-28 周检里「板没跟上他的回复」8 条、「在做的活看不出到哪了」8 条就是这个形状;
#   09-30 复量又查到 7 件请求只写进了行的文字、没标 data-you。⇒ answer / row 两条命令,都是可选的,不加闸。
#   ⛔ 两条都是【先全算完、再一次写】:任何一步做不到就报错、什么都不写 —— 不留半截的卡和行。


def _span_block(html, cls, start=0, end=None):
    """html[start:end] 里第一个 class 含 cls 的 <span> 的 (起, 止),按 span 深度找它自己的 </span>;没有返回 None。
    ⚠ 不能用非贪婪 `(.*?)</span>`:.why 里常带 <b>、偶尔带 <span>,那样会在里面那个 </span> 就收口,把半个 span 留在行里。
    ⚠ 0930 总控报:v6.4 时期的行,正文容器是 `<div class="txt">`;lint 认它(crow 的直接子元素带 txt 就算),这里原来只认 span ⇒ 拒改。
      span / div 两种都认,按**同名标签**数深度。"""
    end = len(html) if end is None else end
    m = re.compile(r'<(span|div)\b[^>]*class\s*=\s*"[^"]*\b%s\b[^"]*"[^>]*>' % re.escape(cls)).search(html, start, end)
    if not m:
        return None
    depth = 1
    for t in re.compile(r'<%s\b[^>]*>|</%s>' % (m.group(1), m.group(1))).finditer(html, m.end(), end):
        depth += -1 if t.group(0).startswith("</") else 1
        if depth == 0:
            return m.start(), t.end()
    return None


def _attr_set(tag, name, value):
    """开标签里设 / 改 / 删一个属性(value=None 删)。"""
    pat = re.compile(r'\s%s\s*=\s*"[^"]*"' % re.escape(name))
    if value is None:
        return pat.sub("", tag, count=1)
    v = ' %s="%s"' % (name, _esc(value).replace('"', "&quot;"))
    if pat.search(tag):
        return pat.sub(lambda _m: v, tag, count=1)
    return tag[:-1].rstrip() + v + ">"


def _row_span(src, ack):
    """「你交代的」区里 data-ack=ack 的那一行:(开标签起, 开标签止, 行止 —— 含它自己的 </div>)。
    找不到 / 不止一行 ⇒ ValueError。⚠ 先蒙注释和机器块再找(kit 里的示例、机器卡里的行都不算)。"""
    masked = _mask_noncontent(_machine_blank(src))
    m = re.search(r'<h2[^>]*>[^<]{0,12}你交代的[^<]{0,12}</h2>', masked)
    if not m:
        raise ValueError("这块板找不到「你交代的」区")
    iz = m.start()
    nz = _next_zone_start(src, iz)
    end = nz if nz > iz else len(src)
    hits = [t for t in re.compile(r'<div\b([^>]*)>').finditer(masked, iz, end)
            if "crow" in _class_set(t.group(1)) and re.search(r'\bdata-ack\s*=\s*"%s"' % re.escape(ack), t.group(1))]
    if not hits:
        raise ValueError("「你交代的」里没有 data-ack=\"%s\" 的行 —— 看有哪些行:`board.py rows <板>`(⛔ 别 grep 板 HTML)" % ack)
    if len(hits) > 1:
        raise ValueError("「你交代的」里有 %d 行都是 data-ack=\"%s\"(板内应唯一 —— 先手改掉重复的)" % (len(hits), ack))
    t = hits[0]
    close = _crow_body_end(masked, t.end())
    if close >= len(masked):
        raise ValueError("data-ack=\"%s\" 那一行没有收口的 </div>" % ack)
    return t.start(), t.end(), close + len("</div>")


# ⭐⭐ 1020 负责人:「单独看这个标题,其实我也看不懂到底是什么情况…能不能…简单的说一下这个事情是什么,然后以及做了什么…
#   或者说让那个AI去写板的时候,就把这个事做了?」⇒ 标成做完时必须带一句人话总结(data-sum),板上拿它当大字:
#   结论(.res)是给查细节用的,常常一开口就是术语;他的原话只有需求、没有结果。⛔ 不让机器另跑一遍总结 —— 写板那一刻作者手上就有,多写一句几乎不花钱。
# 未验证: 9fe385f29 要求一句人话总结但未说明70字上限，下次总结验收时回放完整性与长度。
SUM_MIN, SUM_MAX = 8, 70
SUM_HELP = ("一句人话:这件事是什么、做成了什么 —— 他不看别的、只看这一句也要懂。"
            "⛔ 别写文件名 / 命令 / 哈希 / 行号,别用只有你懂的词。"
            "例:--sum \"板文件太大、AI 每读一次都费钱 ⇒ 把每块板里重复的公共代码拆出去共用,板小了九成\"")


def _sum_problem(t):
    t = re.sub(r"\s+", " ", str(t or "")).strip()
    if not (SUM_MIN <= len(t) <= SUM_MAX):
        return "--sum 要 %d–%d 字(现在 %d 字)。%s" % (SUM_MIN, SUM_MAX, len(t), SUM_HELP)
    m = (re.search(r"`", t) or re.search(r"[\w-]+\.(?:py|js|mjs|css|html|json|md|sh|swift|kt|ts)\b", t)
         or re.search(r"\b[0-9a-f]{7,40}\b", t) or re.search(r"(?<![\w-])--[a-z][\w-]*", t) or re.search(r"\br\d{4}-[0-9a-f]{4}\b", t))
    if m:
        return "--sum 里有「%s」—— 这一句是给他看的人话,%s" % (m.group(0), SUM_HELP)
    return None


ETA_PUSH_N = 3


def _eta_pushed(old, new):
    """MM-DD 的预计日是不是往后推了(跨年:12 月 → 1 月算往后)。写不成 MM-DD 的不算。纯函数。"""
    m0, m1 = re.fullmatch(r"(\d{1,2})-(\d{1,2})", str(old or "").strip()), re.fullmatch(r"(\d{1,2})-(\d{1,2})", str(new or "").strip())
    if not m0 or not m1:
        return False
    a, b = (int(m0.group(1)), int(m0.group(2))), (int(m1.group(1)), int(m1.group(2)))
    if a[0] >= 11 and b[0] <= 2:
        return True
    return b > a and not (a[0] <= 2 and b[0] >= 11)


# ⭐⭐ 1113 等外部计时(负责人 11-13 18:17 卡 ask-ee1ae1b3 批「行,照这样做」;原话:「任何我交代给你的事项……一定不能沉底……肯定是你解决完了你要来找我」)。
#   实测全机:没做完的 34 件 ≥3 天没实质变化、预计日已过的只有 3 件 —— 各线每天改一句、挪日子躲过「过期」检查;
#   盯着 / 卡着的 59 件里 37 件没写在等谁。⇒ 五条:
#   ① `row` 写盯着(watch)/ 卡着不用他(blocked + wait)的行必须写 --wait-for(等外部:「等谁 / 等什么」;等日子:「日子:<为什么是这天>」),
#      没有 ⇒ 拒写、板一个字不变(只拦这次命令写到的那一行;现存的由 lint 报 —— 先只报不拦);
#   ② 行第一次进入等待记 data-wait-since;改 --say、挪 --eta 不重置;只有 --chase(追了一次)/ --review(交验收)/ 挂卡给他(--you decide、ask --row)重置;
#      离开等待(改在做 / 做完 / 标要他)清掉;
#   ③ 等日子的行:预计日第二次往后挪起必须带 --why(新出现了什么),挪过几次记 data-eta-pushed;
#   ④ 到点(等外部满 N 个工作日 / 等的日子到了)当天叫醒那块板的主人线一次(_wake_chase,一条线一天最多一次),叫过的行记 data-chase-due;
#   ⑤ 叫过次日还没处理 ⇒ 他板顶首屏「卡着的」那一块标红「等了 N 天没人追」(kit `chaseOverdue`,与 _chase_overdue 同一规则)。
#   否过什么、为什么:⛔ 不靠「预计日过了」—— 34 件里只抓到 3 件,挪日子就躲过去;⛔ 不另造「试跑 / 先试 X」的机制 —— 按「等日子」写进来,③④ 照常生效;
#   ⛔ blocked + decide / do / nudge / stuck 不归这里管 —— 那是在等他,走「要你的」卡。
# 依据: 负责人 11-13 18:17 卡 ask-ee1ae1b3(等外部满 3 个工作日叫醒;行上 --chase-after N 可改)
CHASE_WORKDAYS = 3
# 依据: 负责人 11-13 18:17 卡 ask-ee1ae1b3(一条线一天最多叫一次,到点的几件合成一条)
CHASE_WAKE_PER_DAY = 1
_WAIT_DATE_PREFIX = re.compile(r"^\s*日子\s*[:：]")   # 1120:原来写成两个半角冒号,全角「日子：」认不出,而 kit 全半角都认 ⇒ 两端判「等日子」不一致
# 1113 AI Harness 报:老行在等的其实是日子(「11-15 满一周数据」),没写「日子:」前缀 ⇒ 被当等外部、到点叫醒。
#   wait-for 像在等日子(写着日期 / 满一周 / 到期 / 试跑)却没前缀 ⇒ 不叫醒,lint 提示主人线补「日子:」。
_WAIT_DATEISH = re.compile(r"\d{1,2}\s*[-/月]\s*\d{1,2}|满\s*(一|两|\d+)\s*(周|天|个?月)|到期|试跑|跑一周|跑满")


def _wait_kind(st, you, wait_for):
    """这一行此刻是不是「在等」:watch 或 blocked + wait,且写了 data-wait-for ⇒ "date"(等日子:写成「日子:…」)/ "ext"(等外部);否则 None。纯函数。"""
    wf = str(wait_for or "").strip()
    if not wf or st not in ("watch", "blocked"):
        return None
    if st == "blocked" and you not in (None, "wait"):
        return None
    if st == "watch" and you in ("decide", "do", "nudge", "stuck"):
        return None
    return "date" if _WAIT_DATE_PREFIX.match(wf) else "ext"


def _workdays_between(start, today):
    """start(不算)之后到 today(算)之间有几个工作日(周一到周五;不算节假日)。纯函数。周五开始等 ⇒ 下周三 = 3。"""
    if start is None or today <= start:
        return 0
    days = (today - start).days
    full, rem = divmod(days, 7)
    n = full * 5
    d = start + datetime.timedelta(days=full * 7)
    for _ in range(rem):
        d += datetime.timedelta(days=1)
        if d.weekday() < 5:
            n += 1
    return n


def _wait_since_dt(f):
    """行的「开始等」时间:data-wait-since;老行没有 ⇒ 这一行最早可得的时间(_wait_first_dt:data-wait-first / data-fp0 / data-txt-at / data-upd 里最早的)。都没有 ⇒ None。
    ⭐ 1117 J1(电商-基建 #b8d4①):原来退回「上次动的时间」(_row_moved_at 先取 data-txt-at)—— 每次 --say 改字都把它推到今天,
      有 --wait-for 却没记开始等的老行「到点该追」永远不触发。⇒ 读行时缺起算就用最早可得的时间,不靠作者补。
      否过什么:⛔ 不在 touch 里给老行补写 data-wait-since —— 那是 --chase 的语义(最近一次追),补了会把「追过」和「开始等」搅在一起。"""
    return _parse_stamp(f.get("wait_since")) or _wait_first_dt(f)


def _chase_after_n(f):
    v = str(f.get("chase_after") or "").strip()
    return int(v) if v.isdigit() and int(v) > 0 else CHASE_WORKDAYS


# ⭐⭐ 1119 过了预计、球在 AI 这边(负责人 11-19 看电商-基建「要你的」里「这 N 件还没做完:过了预计,或挂了 3 天以上」那张卡:bad case,「可读性为0」)。
#   那张卡四个毛病:挤字被白块切开 · 每件贴几百字现状 · 「你要做:问我为什么拖了 / 问我预计哪天能完」叫他去催 AI(方向反了)·
#   kit 还给它挂「这张卡没写要你答什么」。根上:过了预计、AI 自己该动的事,不是他要做的,不该进「要你的」。
#   ⇒ 提醒卡撤掉(_stale_apply 和 kit paintStale 只撤旧卡);这类行并进「到点该追」:
#     _late_row = 没做完(todo / doing / blocked)、不标着要他(decide / do / nudge)、不在等(_wait_kind 为空:等外部 / 等日子归 1113 那套)、预计日早于今天。
#     到点当天叫醒本线一次(_chase_due 给 kind "late",三个出口:做完交验收 / 写清在等谁 / 挪预计并写新出现了什么);
#     次日还没处理(现状没改字、预计没挪过叫醒那天、没交验收)⇒ 他首屏「卡着的」标一行红:行名 + 卡在哪条线 + 过了预计 N 天(kit lateRow / chaseOverdue)。
#   否过什么、为什么:⛔ 不把提醒卡改短留在「要你的」—— 再短也是叫他去催 AI;⛔ 不另造提醒类型 / 信箱标签 —— 到点该追那条路现成(一天一条、合并、次日标红);
#     ⛔ 挂满 3 天但没过预计的不叫醒 —— 预计日是 AI 自己写的承诺,没到期就不算拖;挂太久归「N 天没核」那套(首屏照标)。
#   ⚠ 与 kit `lateRow` 同一规则,改一边必须改另一边(selftest 逐条核)。
LATE_WHY_HEAD = "过了预计 "


def _late_row(f, today):
    """过了预计、球在 AI 这边、不在等 ⇒ True(见上面那段)。纯函数。"""
    return bool(f.get("open") and f.get("st") in ("todo", "doing", "blocked") and f.get("you") not in ROW_YOU_MINE
                and not _wait_kind(f.get("st"), f.get("you"), f.get("wait_for")) and f.get("eta") and f["eta"] < today)


# 依据: 负责人 11-20 #0663，机器汇总卡里的行满 24 小时还没人改或挂卡，沿用「到点该追」。
YOU_IDLE_WHY = "只写在机器汇总卡里,满一天没人改或挂卡"


def _you_idle_since(f):
    """从标上要他的时刻算。旧行取可查时间里最近的一笔。与 kit chaseOverdue 同一规则。"""
    if (since := _parse_stamp(f.get("you_since"))) is not None:
        return since
    return max(filter(None, (_parse_stamp(f.get(k)) for k in ("txt_at", "upd", "fp0", "card_at"))), default=None)


def _you_idle_last(f, since):
    """最近一次动过行或收过卡的时刻。与 kit chaseOverdue 同一规则。"""
    return max([since] + [t for k in ("txt_at", "upd", "card_at") if (t := _parse_stamp(f.get(k))) is not None])


def _chase_due(f, today, now=None):
    """到点该追 ⇒ (kind, 说明);没到 ⇒ None。机器汇总卡按满 24 小时，其余沿用等外部 / 等日子 / 超预计的规则。纯函数。"""
    if not f.get("open"):
        return None
    if f.get("you") in ROW_YOU_MINE:
        if f.get("you_linked") or (f.get("fp") and f.get("fp_now") and f["fp"] != f["fp_now"]):
            return None
        since = _you_idle_since(f)
        now = now or datetime.datetime.combine(today, datetime.time())
        if since is not None and now.timestamp() - _you_idle_last(f, since).timestamp() >= 24 * 3600:
            return "you-idle", YOU_IDLE_WHY
        return None
    kind = _wait_kind(f.get("st"), f.get("you"), f.get("wait_for"))
    if kind == "date":
        if f.get("eta") and f["eta"] <= today:
            return kind, "等的日子 %s 到了" % f["eta"].strftime("%m-%d")
        return None
    if kind == "ext" and _WAIT_DATEISH.search(str(f.get("wait_for") or "")):
        return None                                  # 像在等日子却没写「日子:」⇒ 不叫醒,lint 让主人补前缀(见 _WAIT_DATEISH)
    if kind == "ext":
        t = _wait_since_dt(f)
        if t is None:
            return None
        n = _workdays_between(t.date(), today)
        if n >= _chase_after_n(f):
            return kind, "等「%s」已 %d 个工作日" % (_clause(f.get("wait_for") or "", 24), n)
        return None
    if not kind and _late_row(f, today):                # 1119:过了预计、球在 AI 这边(见 _late_row)
        return "late", "%s%d 天(预计 %s),没做完、也没写在等谁" % (LATE_WHY_HEAD, (today - f["eta"]).days, f["eta"].strftime("%m-%d"))
    return None


def _chase_overdue(f, today):
    """叫过之后没人处理:行上 data-chase-due 早于今天、还在等、开始等的时间没被重置(早于叫醒那天)⇒ 等了几天(按日历日);否则 None。
    1119 过了预计、球在 AI 这边(_late_row)也算:叫过之后现状没改字(data-txt-at 早于叫醒那天)、预计日没挪过叫醒那天、没交验收 ⇒ 过了预计几天。
    机器汇总卡:无手写卡链接、标上要他及最近改行或收卡均早于叫醒日 ⇒ 从标记日起算日历天数。
    与 kit.js `chaseOverdue` 同一规则(⚠ 改一边必须改另一边)。纯函数。"""
    if not f.get("open"):
        return None
    try:
        due = datetime.datetime.strptime(str(f.get("chase_due") or "")[:10], "%Y-%m-%d").date()
    except ValueError:
        return None
    if due >= today:
        return None
    if f.get("you") in ROW_YOU_MINE:
        since = _you_idle_since(f)
        if f.get("you_linked") or since is None or _you_idle_last(f, since).date() >= due:
            return None
        return max(1, (today - since.date()).days)
    kind = _wait_kind(f.get("st"), f.get("you"), f.get("wait_for"))
    if not kind and not _late_row(f, today):
        return None
    if not kind:                                     # 1119 late:交验收会把它标成要他拍(不再是 late);改了字 / 挪了预计 = 有人处理了
        eta = f.get("eta")
        if not eta or eta > due:
            return None
        t = _parse_stamp(f.get("txt_at"))
        if t is not None and t.date() >= due:
            return None
        return max(1, (today - eta).days)
    if _wait_kind(f.get("st"), f.get("you"), f.get("wait_for")) == "date":
        # 1113 AI Harness 报:等日子的只按预计日判,不看 wait-since —— 叫醒之后预计日挪到叫醒那天之后(带 --why)= 有人处理了
        eta = f.get("eta")
        if not eta or eta > due:
            return None
        return max(1, (today - eta).days)
    t = _parse_stamp(f.get("wait_since"))
    if t is not None and t.date() >= due:            # 叫醒那天及之后 --chase 过 = 有人追了
        return None
    start = t.date() if t is not None else due
    return max(1, (today - start).days)


# ⭐⭐ 1116 等外部被套话重置计时(AI Harness #9b59;负责人 11-16 在电商-基建线问「是不是腐烂了」)。
#   实例:电商-基建 某店乙 换绑手机号工单 11-05 提交,11 天一直「处理中」,平台隔几天回一句套话;每次 --chase(或改现状)都把 data-wait-since 重置,
#   「等了几天」永远到不了 3 个工作日,事情一直停着却从不暴露。⇒ 三条:
#   ① 行上另记 data-wait-first = 第一次开始等(--chase / 改字 / 挪日子都不动它);只有这件事了结(做完 / --review / --drop / 挂卡给他)
#      或 --wait-for 换成另一个对象(_same_wait_obj:去掉空白标点后互不包含)才清。--chase 次数记 data-chase-n。
#      老行没有 ⇒ 用行上最早可得的时间补(_wait_first_dt:data-wait-since / data-fp0 / data-txt-at / data-upd 里最早的)。
#   ② 等外部(不是等日子)从第一次开始等满 STALL_WORKDAYS 个工作日还没了结 ⇒ 到点该追那条路(_wake_chase)叫醒一次,行记 data-stall-due;
#      这一轮只 --chase 拒写(_row_apply),要 --chase … --escalate "换了什么路" / ask --row / --review / --drop;--escalate 记 data-stall-ok=<第几轮>。
#      之后每再满 STALL_WORKDAYS 个工作日再来一轮。这一轮叫过就不再天天叫(次日没处理靠 ③)。
#   ③ 叫过次日还没处理 ⇒ 他首屏「卡着的」标红「等了 N 个工作日没结果」(kit stallOverdue,与 _stall_overdue 同一规则)。
#   否过什么、为什么:⛔ 不改 data-wait-since 的语义 —— 「3 个工作日追一次」照旧按最近一次追算,这里另起一条总时长;
#     ⛔ 老行不只用 data-wait-since 补 —— --chase 会把它和 data-chase-due 一起重置,某店乙 那种行永远补不出真起点;
#        代价:老行若先在做了几天才转成等,会早几天叫(一轮只叫一次,换路或挂卡就了);
#     ⛔ 改在做(--status doing)会清 —— 那一行从此归「在做超过 24 小时没动」那道闸管(DOING_STALE_HOURS),不是没人管;
#     ⛔ 不靠关键词判「对方回的是不是套话」—— 机器判不了,只看总时长:事情没了结就是没了结。
# 依据: 现有「等外部满 3 个工作日追一次」(CHASE_WORKDAYS)的两倍多一天 = 够追两轮还没结果
STALL_WORKDAYS = 7
STALL_WHY_HEAD = "这件等「"
_WAIT_OBJ_STRIP = re.compile(r"[\s,，。;；:：、()（）「」【】\"'·/—-]+")
_CHASED_RE = re.compile(r"\d{1,2}-\d{1,2} 追了[:：]")


def _sinking_norm(text):
    return "".join(c.lower() for c in _html_unescape_attr(text) if c.isalnum())


# 依据: 回放 #21，反复追问与平台套话都没有改变外部等待状态。
_WAIT_BOILERPLATE = re.compile(
    r"(?:已催(?:平台|客服|促)?|已追(?:问|了)?|再次催促|等(?:待)?(?:平台|客服)?(?:回复|处理|审核)|"
    r"已提交(?:工单|申请|材料)?|已收到(?:申请|反馈|工单)?|(?:正在|仍在|还在)处理(?:中)?|"
    r"处理中|请(?:您)?(?:耐心|稍后)?等待|请耐心等候|请以[^。]{1,12}为准|暂无(?:新)?(?:进展|回复)|"
    r"会尽快(?:处理|回复)|稍后(?:处理|回复)|感谢(?:您)?(?:的)?(?:耐心等待|理解|支持|反馈)|"
    r"给您带来不便|敬请谅解|平台回复|客服回复|平台说|客服说|您好)+")
_WAIT_PROGRESS_SIM = 0.85  # 依据: 任务给出的去空白标点后的相似度。


def _wait_no_progress(text, previous):
    new = _sinking_norm(text)
    old = _sinking_norm(re.sub(r"^\d{1,2}-\d{1,2} 追了[:：]", "", previous or ""))
    return bool(new and (_WAIT_BOILERPLATE.fullmatch(new) or (
        old and SequenceMatcher(None, old, new, autojunk=False).ratio() >= _WAIT_PROGRESS_SIM)))


def _same_wait_obj(a, b):
    """两句 --wait-for 说的是不是同一个对象:去掉空白标点和开头的「等」后相同,或一句包含另一句 ⇒ True。纯函数。"""
    x, y = [re.sub(r"^等", "", _WAIT_OBJ_STRIP.sub("", str(s or ""))) for s in (a, b)]
    return bool(x and y) and (x == y or x in y or y in x)


def _wait_first_dt(f):
    """行的「第一次开始等」:data-wait-first;老行没有 ⇒ data-wait-since / data-fp0 / data-txt-at / data-upd 里最早的;都没有 ⇒ None。"""
    t = _parse_stamp(f.get("wait_first"))
    if t is not None:
        return t
    ts = [x for x in (_parse_stamp(f.get(k)) for k in ("wait_since", "fp0", "txt_at", "upd")) if x is not None]
    return min(ts) if ts else None


def _chase_count(f):
    """追过几次:data-chase-n;老行没有 ⇒ 现状里「MM-DD 追了:」出现几次。"""
    v = str(f.get("chase_n") or "").strip()
    if v.isdigit():
        return int(v)
    return len(_CHASED_RE.findall(str(f.get("why") or "")))


def _stall_ok_n(f):
    v = str(f.get("stall_ok") or "").strip()
    return int(v) if v.isdigit() else 0


def _wait_stall(f, today):
    """等外部从第一次开始等满 STALL_WORKDAYS(的整数倍)个工作日、这一轮还没换过路 ⇒ {n 工作日, chases 追过几次, rnd 第几轮, who};否则 None。纯函数。"""
    if not f.get("open") or _wait_kind(f.get("st"), f.get("you"), f.get("wait_for")) != "ext":
        return None
    if _WAIT_DATEISH.search(str(f.get("wait_for") or "")):
        return None                                  # 像在等日子却没写「日子:」⇒ 同 _chase_due,不按等外部算
    t = _wait_first_dt(f)
    if t is None:
        return None
    n = _workdays_between(t.date(), today)
    rnd = n // STALL_WORKDAYS
    if rnd < 1 or rnd <= _stall_ok_n(f):
        return None
    return dict(n=n, chases=_chase_count(f), rnd=rnd, who=_clause(f.get("wait_for") or "", 24), first=t)


def _stall_why(s):
    """到点叫醒里的那一句(也是只 --chase 被拒时报错的第一句)。"""
    return ("%s%s」已经 %d 个工作日、追过 %d 次还没结果 —— 光再追一次不算处理:换一条路(升级 / 换渠道 / 换人),或挂卡让他定继续等还是放弃"
            % (STALL_WHY_HEAD, s["who"], s["n"], s["chases"]))


def _stall_chase_msg(ack, s, path=None):
    """这一轮只 --chase 时的报错:为什么 + 四条可照抄的路。"""
    import shlex as _shx
    q = _shx.quote(path) if path else "<板>"
    b = "python3 ~/.claude/scripts/board.py"
    return ("%s。\n   这一次只 --chase 不收:追问不重置总时长,对方回了话但事情没往前走不算回。四选一,照抄改引号里的字:\n"
            "   ① 换一条路再追:%s row %s --ack %s --chase \"追了谁、怎么问的\" --escalate \"换了什么路(升级 / 换渠道 / 换人)\"\n"
            "   ② 让他定继续等还是放弃 ⇒ 挂卡:%s ask %s --row %s --q \"…\" …\n"
            "   ③ 有结果了 ⇒ 交验收:%s row %s --ack %s --review --q \"…\" --got \"…\" --see \"…\"\n"
            "   ④ 不做了 ⇒ %s row %s --ack %s --drop \"为什么不做\""
            % (_stall_why(s), b, q, ack, b, q, ack, b, q, ack, b, q, ack))


def _stall_overdue(f, today):
    """叫过「换一条路」之后没人处理:行上 data-stall-due 早于今天、还在等外部 ⇒ 从第一次开始等(data-wait-first,没有退 data-wait-since,再没有退叫醒那天)
    到今天几个工作日;否则 None。换了路(--escalate)/ 了结 / 换了等的对象时 data-stall-due 已被清掉。
    与 kit.js `stallOverdue` 同一规则(⚠ 改一边必须改另一边)。纯函数。"""
    if not f.get("open") or _wait_kind(f.get("st"), f.get("you"), f.get("wait_for")) != "ext":
        return None
    try:
        due = datetime.datetime.strptime(str(f.get("stall_due") or "")[:10], "%Y-%m-%d").date()
    except ValueError:
        return None
    if due >= today:
        return None
    t = _parse_stamp(f.get("wait_first")) or _parse_stamp(f.get("wait_since"))
    return max(1, _workdays_between(t.date() if t is not None else due, today))


def _stall_mark(src, facts, day):
    """叫过「换一条路」的行记 data-stall-due=day(已有的不盖),顺手把老行补出来的 data-wait-first / data-chase-n 落下(以后不再漂)。纯函数 → 新 src。"""
    for f in facts:
        try:
            a, b, _z = _row_span(src, f["ack"])
        except (ValueError, KeyError):
            continue
        tag = src[a:b]
        if not re.search(r'\bdata-stall-due\s*=', tag):
            tag = _attr_set(tag, "data-stall-due", day)
        if not re.search(r'\bdata-wait-first\s*=', tag) and _wait_first_dt(f) is not None:
            tag = _attr_set(tag, "data-wait-first", _wait_first_dt(f).strftime("%Y-%m-%dT%H:%M"))
        if not re.search(r'\bdata-chase-n\s*=', tag) and _chase_count(f):
            tag = _attr_set(tag, "data-chase-n", str(_chase_count(f)))
        src = src[:a] + tag + src[b:]
    return src


def _wait_need_msg(ack, path=None, new=False):
    """`row` 写盯着 / 卡着的行却没写 --wait-for 时的报错:两条可照抄的命令。"""
    import shlex as _shx
    q = _shx.quote(path) if path else "<板>"
    who = "--new --title \"…\"" if new else "--ack %s" % ack
    return ("盯着 / 卡着的行必须写在等什么(1113 负责人卡 ask-ee1ae1b3:「任何我交代给你的事项……一定不能沉底」)—— 这条命令什么都没写。二选一,照抄改引号里的字:\n"
            "   ① 在等外部(别人 / 平台 / 别的线):\n"
            "      python3 ~/.claude/scripts/board.py row %s %s --wait-for \"等谁 / 等什么外部\" …(原命令其余参数照带)\n"
            "   ② 等的就是那个日子(到期、试跑满几天、只记不拦先跑一周、等某件事发生才开始):\n"
            "      python3 ~/.claude/scripts/board.py row %s %s --wait-for \"日子:<为什么是这天>\" --eta MM-DD …\n"
            "   都写不出 ⇒ 这件现在就该做:--status doing。等他拍板 / 动手 ⇒ 挂卡 `board.py ask %s --row <行>`。"
            % (q, who, q, who, q))


def _row_argument_problems(after, no_after, status, you, no_you, eta, say, act, wait_for, add):
    if after is not None and no_after:
        add("row-after-conflict", "--after 和 --no-after 只能给一个")
    if status is not None and status not in _OPEN_ST + ("done",):
        add("row-status", "--status 只能是 %s" % " / ".join(_OPEN_ST + ("done",)))
    if you is not None and you not in ROW_YOU:
        add("row-you", "--you 只能是 %s" % " / ".join(ROW_YOU))
    if you is not None and no_you:
        add("row-you-conflict", "--you 和 --no-you 只能给一个")
    if eta is not None and not re.fullmatch(r"\d{1,2}-\d{1,2}", str(eta).strip()):
        add("row-eta-format", "--eta 要写成 MM-DD(现在是「%s」)" % eta)
    _pu = [m.group(0) for t in (say, act, wait_for) for m in _PROPOSAL_URL_RE.finditer(str(t or ""))]
    if _pu:
        add("row-proposal-url", "行的文字里写着方案板网址(%s)—— 写进去是一串点不动的字,lint 也会报错。\n"
                         "  给他看方案板的入口只挂在「要你的」的卡上:`board.py ask <板> … --deep <网址> --deep-why \"点进去能看到什么\"`;"
                         "行里写卡号指过去就行。" % _pu[0][:100])


class _RowWhyAsSay(ValueError):
    """当前行没有在往后挪预计日，现状文字可改用 --say。"""


def _row_apply(src, ack, say=None, status=None, eta=None, you=None, act=None, wait_for=None, no_you=False,
               after=None, no_after=False, today=None, strict_you=False, summary=None, need_sum=False,
               need_wait=False, chase=None, push_why=None, chase_after=None, now_dt=None, path_hint=None, is_new=False, escalate=None):
    """原地改「你交代的」里一行 —— 纯函数:吃板文本,吐 (新文本, [改了什么])。别的行一个字不动。
    规则与 lint 同一套(_row_facts):没做完的行要 .why + data-eta;blocked 要 data-you;do / nudge / stuck 要 .act;
    blocked + wait 要 data-wait-for;做完的行要 .res。⛔ 做不到就 ValueError、什么都不改。
    --say 整段换掉 .why(没做完)或 .res(做完):「改不是追加」(R2),旧的进账本。
    1008:after = 排在哪一行后面(那一行的 data-ack)⇒ 写 data-after;no_after 拿掉。带 data-after 的没做完行可以不写预计日。
         指向不存在的行 / 自己 / 已做完的行 / 会成环 / 这一行已做完 ⇒ ValueError。标成做完时 data-after 一并拿掉。"""
    _row_argument_problems(after, no_after, status, you, no_you, eta, say, act, wait_for, _write_value_error)
    a, b, z = _row_span(src, ack)
    tag, body = src[a:b], src[b:z]

    def attr(name):
        m = re.search(r'\b%s\s*=\s*"([^"]*)"' % re.escape(name), tag)
        return m.group(1) if m else None

    # 1113 等外部计时:--chase(追了谁、怎么问的)/ --why(等日子的行往后挪,新出现了什么)都落进现状
    _now_dt = now_dt or datetime.datetime.now()
    _now_s = _now_dt.strftime("%Y-%m-%dT%H:%M")
    if chase is not None and not str(chase).strip():
        raise ValueError("--chase 要写追了谁、怎么问的(例:--chase \"群里 @同事乙 问样品到没到\")")
    if push_why is not None and not str(push_why).strip():
        raise ValueError("--why 要写新出现了什么(为什么这个日子又要往后挪)")
    # ⭐ 1116 等外部总时长(见 STALL_WORKDAYS):满 7 个工作日这一轮,只 --chase 不收
    if escalate is not None and not str(escalate).strip():
        raise ValueError("--escalate 要写换了什么路(例:--escalate \"改打平台客服电话、要了主管工单号\")")
    if escalate is not None and chase is None:
        raise ValueError("--escalate 要和 --chase 一起用:--chase 写这次追了谁、怎么问的,--escalate 写这次换了什么路(升级 / 换渠道 / 换人)")
    _f0 = _row_facts(tag, body, today=_now_dt.date())
    _stall0 = _wait_stall(_f0, _now_dt.date()) if chase is not None else None
    if _stall0 and escalate is None:
        raise ValueError(_stall_chase_msg(ack, _stall0, path_hint))
    if chase_after is not None and not (str(chase_after).strip().isdigit() and 1 <= int(str(chase_after).strip()) <= 30):
        raise ValueError("--chase-after 要写 1–30 的整数(等外部满几个工作日叫醒,缺省 %d)" % CHASE_WORKDAYS)
    if wait_for is not None and _WAIT_DATE_PREFIX.match(str(wait_for)) and not _WAIT_DATE_PREFIX.sub("", str(wait_for)).strip():
        raise ValueError("--wait-for \"日子:\" 后面要写为什么是这一天(例:--wait-for \"日子:试跑满一周 11-20 看命中\")")
    progress_text = say or chase
    if chase is not None:
        _cs = "%s 追了:%s" % (_now_dt.strftime("%m-%d"), str(chase).strip()) + ((";换了路:%s" % str(escalate).strip()) if escalate is not None else "")
        say = ("%s · %s" % (str(say).strip(), _cs)) if say else _cs
    if push_why is not None:
        _ps = "预计改到 %s:%s" % (str(eta or "").strip() or "?", str(push_why).strip())
        say = ("%s · %s" % (str(say).strip(), _ps)) if say else _ps

    old_st = attr("data-status")
    new_st = status or old_st
    old_after = (attr("data-after") or "").strip() or None
    if after is not None:
        after = str(after).strip()
        if new_st == "done":
            raise ValueError("这一行已经做完了(或这次要标成做完)—— 做完的事不用排在谁后面,去掉 --after")
        _yz = _yours_zone_rows(src, today=today)
        _ap = _after_problem(_yz["facts"] if _yz else [], ack, after)
        if _ap:
            raise ValueError(_ap)
    txt = _span_block(body, "txt")
    if not txt:
        raise ValueError("data-ack=\"%s\" 那一行没有 <span class=\"txt\">,不是标准行 —— 手改吧" % ack)
    i0 = body.index(">", txt[0]) + 1
    i1 = body.rindex("</", txt[0], txt[1])          # 收口是 </span> 还是 </div> 都对
    inner = body[i0:i1]

    def cut(h, cls):
        sp = _span_block(h, cls)
        return (h[:sp[0]] + h[sp[1]:], h[sp[0]:sp[1]]) if sp else (h, None)

    inner, why_old = cut(inner, "why")
    inner, act_old = cut(inner, "act")
    inner, res_old = cut(inner, "res")
    # 1009(负责人点名电商-投流的板又腐了):row 改了一行的状态和现状,没带 --no-you ⇒ 旧的「要你拍」标记和那句话原样留着,
    #   机器卡继续把他已经答过的问题摆在「要你的」里,lint 全程 PASS。指向他的标记是现在时(R2.7),改这一行时必须当场重判:
    #   行上标着要他(decide / do / nudge / stuck)、这次改了现状或状态、却对「还要不要他」只字没提 ⇒ 报错不写(只在命令行这条路上)。
    _oy = attr("data-you")
    if (strict_you and _oy in ("decide", "do", "nudge", "stuck") and new_st != "done" and not no_you and you is None and act is None
            and (say is not None or (status is not None and status != old_st))):
        _oa = re.sub(r"\s+", " ", re.sub(r"<[^>]+>", "", act_old or "")).strip()
        raise ValueError("这一行还标着**要他%s**%s。你改了它的现状 / 状态,却没说还要不要他 —— 不说的话,「要你的」里会继续摆着这句旧的。\n"
                         "  ⇒ 三选一,加在这条命令后面再跑:\n"
                         "     · 他答过了 / 不用他了:--no-you\n"
                         "     · 还要他,但要他做的事变了:--you %s --act \"现在要他做的一句\"\n"
                         "     · 还要他,那句也没变:--you %s(原样再给一遍 = 你看过了,确实还是这句)"
                         % ({"decide": "拍板", "do": "动手", "nudge": "去催", "stuck": "解卡"}[_oy],
                            (":「%s」" % _clause(_oa, 60)) if _oa else "", _oy, _oy))
    mt = re.match(r'\s*<b\b[^>]*>.*?</b>\s*(?:[（(][^）)<]{0,60}[）)])?', inner, re.S)
    ins = mt.end() if mt else 0
    notes = []
    # ⚠ 0930 总控报:老行把现状直接写成 `<b>…</b>` 自由文字、没放进 .why / .res ⇒ 原来只在最前面插一个新 span,新旧两句并排,
    #   说明里的「整段换掉」没发生。⇒ 给了 --say、而这一行本来既没有 .why 也没有 .res 时,标题(和日期)之后、
    #   第一个块元素(details / ul / ol / div / table)之前的那段自由文字就是旧的现状:整段拿掉,原文印出来让作者决定进不进账本。
    if say and not why_old and not res_old:
        _rest = inner[ins:]
        _bk = re.search(r'<(?:details|ul|ol|div|table)\b', _rest)
        _k = _bk.start() if _bk else len(_rest)
        _free = re.sub(r'\s+', ' ', re.sub(r'<[^>]+>', '', _rest[:_k])).strip()
        if _free:
            inner = inner[:ins] + _rest[_k:]
            notes.append("换掉了行里没放进 .why / .res 的旧文字「%s」—— 要留就进账本" % _clause(_free, 60))
    tag2 = tag
    if new_st != old_st:
        notes.append("状态 %s → %s" % (old_st or "无", new_st))
    if summary is not None:
        _sp = _sum_problem(summary)
        if _sp:
            raise ValueError(_sp)
        if new_st != "done":
            raise ValueError("--sum 只给做完的行(它是板上「做完的」那件事的大字);没做完的行写 --say")
    if new_st == "done":
        if need_sum and summary is None and not attr("data-sum") and (old_st != "done" or say):
            raise ValueError("标成做完 / 改做完的结论,要带一句给他看的总结(--sum)。%s" % SUM_HELP)
        if summary is not None:
            tag2 = _attr_set(tag2, "data-sum", re.sub(r"\s+", " ", summary).strip())
            notes.append("总结:%s" % _clause(summary, 40))
        if say:
            spans = '<span class="res">%s</span>' % _esc(say)
            notes.append("结论:%s" % _clause(say, 40))
        elif res_old:
            spans = res_old
        else:
            raise ValueError("做完的行要一句结论(--say「结果是什么」)—— 只剩他的原话 = 不合格的汇报(0907)")
        for n in ("data-you", "data-wait-for", "data-you-card", "data-wait-since", "data-chase-due", "data-eta-pushed", "data-chase-after",   # 1113:做完 = 不再等
                  "data-wait-first", "data-chase-n", "data-stall-ok", "data-stall-due"):                                                     # 1116 总时长一起清
            tag2 = _attr_set(tag2, n, None)
        if chase is not None or push_why is not None:
            raise ValueError("--chase / --why 只给还在等的行;这一行做完了")
        if old_after:                               # 1008:做完了就不再排在谁后面
            tag2 = _attr_set(tag2, "data-after", None)
            notes.append("不再排在 %s 后面" % old_after)
    else:
        # ⭐ 1028(电商-选品 v2.8):r1028-31f4 先标做完带了 --sum「已过审在售」,发现 某店乙 两条没做又改回在做 ⇒ 总结照留,rows 里新现状和旧总结自相矛盾
        if old_st == "done" and attr("data-sum"):
            tag2 = _attr_set(tag2, "data-sum", None)
            notes.append("拿掉了做完时的总结「%s」(它说的是做完)" % _clause(attr("data-sum"), 30))
        if say:
            why_html = '<span class="why">%s</span>' % _esc(say)
            notes.append("现状:%s" % _clause(say, 40))
        elif why_old:
            why_html = why_old
        else:
            raise ValueError("没做完的行要写为什么没做完 / 现在到哪了(--say)")
        new_you = None if no_you else (you if you is not None else attr("data-you"))
        # ⭐ 1027(电商-选品 v2.6 转):r1024-4163 从 blocked + wait「在等 同事乙」用 `row --status doing` 改成在做,
        #   data-you=wait / data-wait-for 照留 ⇒ 板上还写「在等 同事乙」,其实是 AI 在做。⇒ 改成在做 / 盯着时,旧的「在等」一起清(显式给 --you 不管)
        _wait_cleared = False
        if you is None and new_st in ("doing", "watch") and new_you == "wait":
            new_you = None
            # 1113 等外部计时:盯着(watch)= 在等,旧的「在等 X」照留(只拿掉 data-you);改成在做才清
            if new_st == "doing":
                _wait_cleared = True
                if attr("data-wait-for") and wait_for is None:
                    notes.append("不再标着在等「%s」(改成在做)" % _clause(attr("data-wait-for"), 20))
        if no_you:
            act_html = None
        elif act is not None:
            act_html = '<span class="act">%s</span>' % _esc(act)
        else:
            act_html = act_old
        # ⭐ 1110 往后拖(AI Harness #7e4b):--wait-for 放开到 todo / doing / watch(同一个 data-wait-for;这几种状态默认就是「不用你做」,不写 data-you)。
        #   blocked 照旧只认 wait;标着要他的(decide / do / nudge / stuck)不落;改成在做 / 盯着时上面 1027 那段清掉的旧「在等」不带回来,除非这次又给了 --wait-for。
        # 1116(电商-基建 11-15 报):--no-you 只拿掉「要你」,显式给的 --wait-for 照写;没给才连旧的「在等」一起清(收卡路径照旧)
        if (no_you and wait_for is None) or new_you not in (None, "wait") or (new_you is None and new_st not in ("todo", "doing", "watch")):
            new_wait = None
        elif wait_for is not None:
            new_wait = str(wait_for).strip() or None
        else:
            new_wait = None if _wait_cleared else attr("data-wait-for")
        new_eta = str(eta).strip() if eta is not None else attr("data-eta")
        if new_st == "blocked" and not new_you:
            raise ValueError("blocked 的行要写卡在谁(--you decide / do / nudge / wait / stuck)")
        if new_you in ("do", "nudge", "stuck") and not act_html:
            raise ValueError("--you %s 要写他要做的一句(--act)" % new_you)
        if new_st == "blocked" and new_you == "wait" and not new_wait:
            raise ValueError("blocked + wait 要写在等什么(--wait-for)")
        new_after = None if no_after else (after if after is not None else old_after)
        if not new_eta and not new_after:
            raise ValueError("没做完的行要写预计哪天(--eta MM-DD)%s"
                             % ("—— 拿掉了「排在 %s 后面」,这一行就得有自己的预计日" % old_after if (no_after and old_after) else
                                ";是排在别的事后面、现在定不了哪天的,写 --after <前面那一行的编号>"))
        spans = why_html + (act_html or "") + (res_old or "")
        tag2 = _attr_set(tag2, "data-after", new_after)
        if new_after != old_after:
            notes.append(("排在 %s 后面" % new_after) if new_after else ("不再排在 %s 后面" % old_after))
        # ⭐ 1109 投流转负责人查腐烂:r1029-bec7 行名五件事 10-29 就做完了,之后 11 天只在推预计日、写「继续等」,机器一条没抓到。
        #   ⇒ 记这一行的预计日被往后推过几次(ETA_PUSH_N 次起进 recheck 名单);现状里写了「还差 / 还剩…」就清零:推日子可以,但要讲清这件事还剩什么。
        _n0 = int(attr("data-eta-n") or 0) if str(attr("data-eta-n") or "0").isdigit() else 0
        _old_say = _html_unescape_attr(re.sub(r"<[^>]+>", "", why_old or ""))
        _old_left = _remaining_text(_old_say)
        _new_left = _remaining_text(say)
        _n1 = 0 if _new_left and _new_left != _old_left else (_n0 + 1 if _eta_pushed(attr("data-eta"), new_eta) else _n0)
        tag2 = _attr_set(tag2, "data-eta-n", str(_n1)) if _n1 else re.sub(r'\s+data-eta-n="[^"]*"', "", tag2)
        tag2 = _attr_set(tag2, "data-eta", new_eta)
        tag2 = _attr_set(tag2, "data-you", new_you)
        tag2 = _attr_set(tag2, "data-wait-for", new_wait)
        # ⭐ 1113 等外部计时(见 _wait_kind 那一节)
        _ok = _wait_kind(old_st, attr("data-you"), attr("data-wait-for"))
        _nk = _wait_kind(new_st, new_you, new_wait)
        if need_wait and not _nk and new_st in ("watch", "blocked") and new_you not in ("decide", "do", "nudge", "stuck"):
            raise ValueError(_wait_need_msg(ack, path_hint, new=is_new))
        if chase is not None and not _nk:
            raise ValueError("--chase 只给在等外部 / 等日子的行(盯着或卡着、写了 --wait-for);这一行此刻不在等 —— 改现状用 --say")
        _since0 = attr("data-wait-since")
        if not _nk:
            _since = None
        elif (chase is not None and (_nk != "ext" or not _wait_no_progress(progress_text, _f0["why"]))):
            _since = _now_s
        elif _ok and _since0:
            _since = _since0
        elif _ok:                                   # 老行(这套之前就在等):从上次动的时间算起,不当成刚开始等
            _lg = _parse_stamp(attr("data-txt-at")) or _parse_stamp(attr("data-upd")) or _parse_stamp(attr("data-fp0"))
            _since = _lg.strftime("%Y-%m-%dT%H:%M") if _lg else _now_s
        else:
            _since = _now_s
        tag2 = _attr_set(tag2, "data-wait-since", _since)
        # ⭐ 1116 等外部总时长(见 STALL_WORKDAYS):第一次开始等 —— 同一个对象一直留着;了结 / 换了对象 / 不再写在等什么才清
        _first0, _ow = attr("data-wait-first"), attr("data-wait-for")
        _same = bool(_ow and new_wait and _same_wait_obj(_ow, new_wait))
        if _first0 and _same:
            _first = _first0
        elif _nk and _ok and _same:                 # 老行(这套之前就在等):用最早可得的时间补
            _ft = _wait_first_dt(_f0)
            _first = _ft.strftime("%Y-%m-%dT%H:%M") if _ft else _now_s
        elif _nk:
            _first = _now_s
        else:
            _first = None
        _keep = bool(_first) and (_first == _first0 or (not _first0 and _ok and _same))
        _cn = (_chase_count(_f0) if _keep else 0) + (1 if (chase is not None and _first) else 0)
        _sok = attr("data-stall-ok") if _keep else None
        if escalate is not None and _stall0 and _first:
            _sok = str(_stall0["rnd"])
            notes.append("换了路,满 %d 个工作日这一轮算处理过了(总时长照算,再满 %d 个工作日再问)" % (_stall0["n"], STALL_WORKDAYS))
        tag2 = _attr_set(tag2, "data-wait-first", _first)
        tag2 = _attr_set(tag2, "data-chase-n", str(_cn) if _cn else None)
        tag2 = _attr_set(tag2, "data-stall-ok", _sok)
        if attr("data-stall-due") and (not _keep or _sok != attr("data-stall-ok")):
            tag2 = _attr_set(tag2, "data-stall-due", None)
        if _first0 and _first != _first0:
            notes.append("等的对象换了 / 不再等,总时长重新算" if _first else "不再在等,清掉总时长")
        if _since and _since != _since0 and chase is not None:
            notes.append("追了一次,等待重新计时")
        elif _since and not _since0:
            notes.append("开始计等待(%s)" % _since[5:].replace("T", " "))
        elif _since0 and not _since:
            notes.append("不再在等,清掉等待计时")
        # ③ 等日子的行:往后挪第二次起要 --why
        _pushed = bool(_nk == "date" and _ok == "date" and _eta_pushed(attr("data-eta"), new_eta))
        _pn0 = int(attr("data-eta-pushed")) if str(attr("data-eta-pushed") or "").isdigit() else 0
        _late_push = bool(not _nk and new_st in ("todo", "doing", "blocked") and _eta_pushed(attr("data-eta"), new_eta))   # 1119:过了预计的行到点该追的出口 ③
        if push_why is not None and not _pushed and not _late_push:
            raise _RowWhyAsSay("--why 只和「把预计日往后挪」一起用(等日子的行,或没做完、不在等的行 + 更晚的 --eta);别的现状写 --say")
        if _pushed and _pn0 >= 1 and push_why is None:
            raise ValueError("这一行等的是日子(「%s」),预计日已经往后挪过 %d 次 —— 再挪(%s → %s)要写新出现了什么:加 --why \"新出现了什么\"。\n"
                             "   写不出 ⇒ 这件现在就该做(--status doing),或日子到了就交验收(--review)/ 挂卡问他(ask --row)。"
                             % (_clause(new_wait or "", 24), _pn0, attr("data-eta"), new_eta))
        _pn1 = (_pn0 + 1 if _pushed else _pn0) if _nk == "date" else 0
        tag2 = _attr_set(tag2, "data-eta-pushed", str(_pn1) if _pn1 else None)
        if _pushed:
            notes.append("等日子的行第 %d 次往后挪" % _pn1)
        if chase_after is not None:
            tag2 = _attr_set(tag2, "data-chase-after", str(int(str(chase_after).strip())))
            notes.append("等满 %s 个工作日叫醒" % int(str(chase_after).strip()))
        elif not _nk:
            tag2 = _attr_set(tag2, "data-chase-after", None)
        # 叫过之后:重置了计时 / 不再等 / 等日子的行把日子挪了 ⇒ 不再算「叫过没人追」
        # 1119:过了预计、球在 AI 这边(不在等)的行,光 --checked / 只动别的属性不算处理 ⇒ 记号留着(次日首屏照标红);改字、挪预计、换状态 / 类别才清
        _late_same = bool(not _nk and not _ok and say is None and push_why is None and new_eta == attr("data-eta")
                          and new_st == old_st and new_you == attr("data-you"))
        if _late_push and push_why is not None:
            notes.append("预计挪到 %s,写了新出现了什么" % new_eta)
        if attr("data-chase-due") and (not _nk or _since != _since0 or _pushed) and not _late_same:
            tag2 = _attr_set(tag2, "data-chase-due", None)
        if eta is not None:
            notes.append("预计 %s" % new_eta)
        if wait_for is not None and new_wait and new_st != "blocked":
            notes.append("在等:%s" % _clause(new_wait, 30))
        if you is not None:
            notes.append("标要你:%s%s" % (YOU_LABEL.get(you, you), ("(%s)" % _clause(act, 30)) if act else ""))
        if no_you:
            notes.append("不再标着要你")
        if no_you or you is not None:
            tag2 = _attr_set(tag2, "data-you-card", None)          # 1027:挂卡时自动标的「要你拍」(_ask_row_mark),作者自己改过就不再归卡管
    tag2 = _attr_set(tag2, "data-status", new_st)
    new_body = body[:i0] + inner[:ins] + spans + inner[ins:] + body[i1:]
    if new_st == "done" or new_you not in ROW_YOU_MINE:
        tag2 = _attr_set(tag2, "data-you-since", None)
    elif new_you != _oy:
        tag2 = _attr_set(tag2, "data-you-since", _now_s)
    elif _row_fp(tag, body) != _row_fp(tag2, new_body):
        tag2 = _attr_set(tag2, "data-upd", _now_s)
        tag2 = _attr_set(tag2, "data-chase-due", None)
    return src[:a] + tag2 + new_body + src[z:], notes


# ──────────────── 1008 往「你交代的」里新增一行:`row --new`
#   之前没有命令能加行,各线只能手改 HTML ⇒「他说以后再做的事」常常就没落成一行(电商-基建:答完的卡收走,那件事从此不在板上)。
#   生成的行与 `_row_apply` 写出来的同一个形状(先放一个只有标题和日期的骨架,再交给 _row_apply 填 —— 规则只有一份)。
ROW_NEW_ST = ("todo", "doing", "blocked", "watch")
_ACK_OK_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,63}")


def _row_new_ack(taken, title, now):
    """自动取一个板上没用过的行编号:r<MMDD>-<4 位>(短,后面写 --after 时要手敲)。taken = 已经用掉的 data-ack 集合。"""
    seed = "%s|%s" % (title, time.strftime("%Y-%m-%dT%H:%M:%S", now))
    for i in range(1000):
        ack = "r%s-%s" % (time.strftime("%m%d", now), hashlib.sha1(("%s|%d" % (seed, i)).encode("utf-8")).hexdigest()[:4])
        if ack not in taken:
            return ack
    raise ValueError("取不出没用过的行编号 —— 用 --ack 自己给一个")


def _row_new_slot(src):
    """新行插在哪:「你交代的」区里第一个露在外面的 `.checks`(不在机器块 / 注释 / 任何 <details> 里)开标签之后的下标。
    认不出 ⇒ ValueError(说清是哪一样认不出)。⚠ 板上的顺序由 kit 现排,这里只保证落在区里、露在外面。"""
    masked = _mask_noncontent(_machine_blank(src))
    m = re.search(r'<h2[^>]*>[^<]{0,12}你交代的[^<]{0,12}</h2>', masked)
    if not m:
        raise ValueError("这块板找不到「你交代的」区(区头应形如 `<div class=\"zone\"><h2>你交代的</h2>…</div>`)—— 没地方放这一行")
    iz = m.start()
    nz = _next_zone_start(src, iz)
    end = nz if nz > iz else len(src)
    depth = 0
    for t in re.compile(r'<details\b[^>]*>|</details>|<div\b([^>]*)>').finditer(masked, iz, end):
        g = t.group(0)
        if g.startswith("</details"):
            depth = max(0, depth - 1)
        elif g.startswith("<details"):
            depth += 1
        elif depth == 0 and "checks" in _class_set(t.group(1)):
            return t.end()
    raise ValueError("「你交代的」区里找不到露在外面的行容器(`<div class=\"checks\">`,不在折叠 / 机器生成块里)—— 结构认不出,没敢写。"
                     "看一眼这一区:行应该放在 `<article class=\"card\"><div class=\"body\"><div class=\"checks\">` 里")


# 依据: 11-24 任务给出的标题相似度，以及相同引用至少八字。
_SINKING_TITLE_SIM = 0.8
_SINKING_QUOTE_MIN = 8  # 依据: 同一句原话至少八字。
# 依据: 该任务指定的书名号及引号。
_SINKING_QUOTE = re.compile(r'「([^」]+)」|《([^》]+)》|“([^”]+)”|"([^"]+)"|『([^』]+)』|‘([^’]+)’')


def _duplicate_quote(text):
    return {value.strip() for groups in _SINKING_QUOTE.findall(_html_unescape_attr(text))
            for value in groups if len(value.strip()) >= _SINKING_QUOTE_MIN}


def _sinking_duplicate(first, second):
    a, b = (_sinking_norm(f["title"]) for f in (first, second))
    if a and b and SequenceMatcher(None, a, b, autojunk=False).ratio() >= _SINKING_TITLE_SIM:
        return True
    return bool(_duplicate_quote((first["title"] or "") + "\n" + (first["why"] or "")) &
                _duplicate_quote((second["title"] or "") + "\n" + (second["why"] or "")))


def _sinking_duplicate_warnings(src, ack=None):
    facts = [f for f in (_yours_zone_rows(src) or {}).get("facts", []) if f["open"] and f["ack"]]
    pairs = ((a, b) for i, a in enumerate(facts) for b in facts[i + 1:]) if ack is None else (
        (a, b) for a in facts if a["ack"] == ack for b in facts if b is not a)
    return ["%s 可能和 %s「%s」是同一件，是就用 --merge-into" %
            (a["ack"], b["ack"], _html_unescape_attr(b["title"])[:20])
            for a, b in pairs if _sinking_duplicate(a, b)]


def _recent_row_duplicate(src, title, now, *, say, status, eta, wait_for):
    # 依据: 11-23 重跑案例，按任务规定只拦过去 10 分钟建的同标题未完成行。
    cutoff = now - datetime.timedelta(minutes=10)
    key = "".join(title.split())
    for fact in (_yours_zone_rows(src) or {}).get("facts", []):
        if not fact["open"] or not fact["ack"] or "".join(_html_unescape_attr(fact["title"]).split()) != key:
            continue
        # 同标题只出提示。备注、状态或等的内容不同，不能当成重跑。
        if (fact["st"] != status or fact["eta_raw"] != eta
                or _html_unescape_attr(fact["wait_for"]) != (wait_for or "")
                or _html_unescape_attr(fact["why"]) != " ".join(str(say or "").split())):
            continue
        try:
            created = datetime.datetime.fromisoformat(fact["created"] or "")
        except ValueError:
            created = _parse_stamp(fact["fp0"]) if fact["td"] == now.date() else None
        if created and cutoff <= created <= now:
            return fact["ack"]
    return None


def _row_new(src, title, status=None, say=None, eta=None, after=None, ack=None, you=None, act=None, wait_for=None,
             now=None, taken=(), summary=None, need_wait=False, path_hint=None, chase_after=None):
    """往「你交代的」里加一行 —— 纯函数:吃板文本,吐 (新文本, 这一行的 data-ack, [说明])。别的一个字不动。
    没做完的行照契约要「为什么没做完」(say)和「预计哪天」(eta;带 after 时可省),缺了 ValueError、什么都不改。
    taken = 板外也算用过的编号(留档页里的)。"""
    now = now or time.localtime()
    title = re.sub(r"\s+", " ", str(title or "")).strip()
    if not title:
        raise ValueError("--new 要给 --title \"一句话标题\"(他交代的那件事,用他的话)")
    status = status or "todo"
    duplicate = _recent_row_duplicate(src, title, datetime.datetime.fromtimestamp(time.mktime(now)),
                                      say=say, status=status, eta=eta, wait_for=wait_for)
    if duplicate:
        raise ValueError("已有未完成的同标题行 %s，刚建过；用 row --ack %s 改这一行。" % (duplicate, duplicate))
    # ⭐ 1028 电商-选品:每晚抽查同事乙的结论只能塞进长期行的第一句,负责人「是这个事项直接淹没在今天的事情里了吗?」⇒ 当时开了「新开一行直接标做完」。
    #   ⛔ 1114 起命令行上的 status done 一律拒(cmd_row「做完须经他验收」,--new 也不例外)⇒ 这一支只剩自检和内部调用;
    #   「只是告诉他一声」的结果现在照常开行再 `--review` 交他点。
    if status == "done":
        if not (summary and str(summary).strip()) or not (say and str(say).strip()):
            raise ValueError("--new --status done 只给「只是告诉他一声」的结果用(每天的验收 / 抽查):要 --say 结论 + --sum 一句人话;"
                             "顺手做的事不另开行(折进「顺手做的」)")
        k = _row_new_slot(src)
        used = set(re.findall(r'\bdata-ack\s*=\s*"([^"]*)"', src)) | set(taken or ())
        if ack is not None and (not _ACK_OK_RE.fullmatch(str(ack)) or ack in used):
            raise ValueError("--ack「%s」写法不对或已经用过 —— 不给就自动取一个" % ack)
        ack = ack or _row_new_ack(used, title, now)
        bone = ('\n<div class="crow" data-status="todo" data-ack="%s"><span class="mk"></span><span class="txt"><b>%s</b>（%s）</span></div>'
                % (ack, _esc(title), time.strftime("%m-%d", now)))
        out = src[:k] + bone + src[k:]
        out, notes = _row_apply(out, ack, say=say, status="done", summary=summary, need_sum=True)
        return out, ack, ["新加一行「%s」(做完,进「最近 24 小时做完的」)" % _clause(title, 30)]
    if status not in ROW_NEW_ST:
        raise ValueError("--new 的 --status 只能是 %s(现在是「%s」):做完的事不用新加一行;要他拍的用 "
                         "`board.py ask <板> … --row <行>` 挂卡,行本身照 todo / blocked 写" % (" / ".join(ROW_NEW_ST), status))
    if _PROPOSAL_URL_RE.search(title):
        raise ValueError("标题里写着方案板网址 —— 写进去是一串点不动的字,lint 也会报错;入口只挂在「要你的」的卡上(`ask --deep`)")
    used = set(re.findall(r'\bdata-ack\s*=\s*"([^"]*)"', src)) | set(taken or ())
    if ack is not None:
        ack = str(ack).strip()
        if not _ACK_OK_RE.fullmatch(ack):
            raise ValueError("--ack 只能用字母 / 数字 / - _ .(现在是「%s」);不给就自动取一个" % ack)
        if ack in used:
            raise ValueError("data-ack=\"%s\" 板上(或留档页里)已经有了 —— 换一个,或不给 --ack 让它自动取" % ack)
    else:
        ack = _row_new_ack(used, title, now)
    k = _row_new_slot(src)
    # 依据: --no-touch 新行也要在 10 分钟内挡重复，首次记账时间可能晚于创建。
    bone = ('\n<div class="crow" data-status="%s" data-ack="%s" data-created="%s"><span class="mk"></span><span class="txt"><b>%s</b>（%s）</span></div>'
            % (status, ack, time.strftime("%Y-%m-%dT%H:%M:%S", now), _esc(title), time.strftime("%m-%d", now)))
    out = src[:k] + bone + src[k:]
    today = datetime.date(now.tm_year, now.tm_mon, now.tm_mday)
    out, notes = _row_apply(out, ack, say=say, status=status, eta=eta, you=you, act=act, wait_for=wait_for, after=after, today=today,
                            need_wait=need_wait, path_hint=path_hint, is_new=True, chase_after=chase_after,
                            now_dt=datetime.datetime(now.tm_year, now.tm_mon, now.tm_mday, now.tm_hour, now.tm_min))
    return (out, ack, ["新加一行「%s」" % _clause(title, 30)]
            + [x for x in notes if not x.startswith("状态 ")] + _sinking_duplicate_warnings(out, ack))


class _AnswerNeedsWhy(Exception):
    """answer:卡对应着一行,而作者没说这一行现在到哪了(args = 行编号, 那一行的 _row_facts)。只在 _answer_apply 里用。"""


class _AnswerWhyDrops(Exception):
    """answer --why:新现状把原现状里提到的货号 / 编号丢了(args = 行编号, 原现状, [丢了的编号])。只在 _answer_apply 里用。"""


# ⭐ 1104(电商-选品 v3.2 转,负责人 11-04 21:3x 要各线报板上腐烂):r1103-92d9 一行装着 AAA / BBB1 / 某商品丙 / CCC1 几个品,
#   收 CCC1 那张卡写 --why,整行现状被换成只讲 CCC1 的一句 —— 其余几个品到哪了从板上没了,他看到的是残缺现状,工具一声不响。
#   ⇒ 新现状里漏了原现状提到的货号 / 编号(大写字母开头 3 位以上,同 _CODE_RE)⇒ 拒,摆出原文;
#     --why-add = 新这句放最前、原现状接在后面;--why-replace = 确认整段换掉。都没漏 ⇒ 照旧换,并印出被换掉的原文。
def _why_dropped_codes(old, new):
    keep = set(_CODE_RE.findall(str(new or "")))
    return [c for c in dict.fromkeys(_CODE_RE.findall(str(old or ""))) if c not in keep and c not in _CODE_SKIP]


# 1008 D:他的回答像是「以后再做」⇒ answer 成功后多提示一句(只提示,不拦、不改退出码)。
#   宁可少提示:只认明说往后放的几种说法;「先不关」「以后都用 A」这类不算。
_LATER_RE = re.compile(
    r"以后(?:再|做|弄|搞|处理|考虑)|再说|(?:之后|回头|晚点|过后|过阵子|过两天)再|先[^,。;,;!?!?]{1,30}再|"
    r"等[^,。;,;!?!?]{1,30}(?:做完|弄完|搞完|忙完|结束|之后|以后)|暂缓|先放一放|先放着|往后放|排(?:在|到)[^,。;,;]{0,20}后面")


def _answer_later_hint(res, path):
    """--res 里像是「以后再做」⇒ 要多印的几行;不像 ⇒ []。纯函数。"""
    if not _LATER_RE.search(str(res or "")):
        return []
    return ["  ⚠ 他像是说这件事**以后再做**。卡收了它就不在板上了 ⇒ 给它留一行(排在前面那件后面;前面那件一做完,板会把它推回来):",
            "     python3 ~/.claude/scripts/board.py row %s --new --title \"…\" --status todo --say \"…\" --after <前面那行>" % path,
            "     已经有这一行了 ⇒ `board.py row %s --ack <行> --after <前面那行>`。不是这个意思就不用管这段。" % path]


# 1023(电商-选品转,负责人原话:「我不是让你把某商品的那个1688链接给我吗？你这事怎么没做呢？你不应该放在状态板上吗？
#   为什么这个事情你只在对话里讲了，没有在那个状态板上讲？」):他在卡的补充里要一个链接,AI 用 answer --why 把链接写进行的现状、卡收了;
#   随后 row --you do 出的「等你的行」机器卡只印 --act 那句 ⇒ 链接只在行里(点不动、首屏只露第一句)和聊天里。
#   实测(10-23 全机 500 行):没做完、写着网址的行只有这 1 行;带外链的 30 行全是做完的(产物存档,照放)。
#   ⇒ 没做完的行里一写网址就拒,指到 `ask --row … --copy`(那张卡在「要你的」、网址单独一格带「复制」)。
_ROW_URL_RE = re.compile(r"https?://[^\s<>\"'」）)]+")


def _open_row_url_problem(texts, row_ack=None, board=None):
    """没做完的行要写进去的字里有网址 ⇒ 一句要报的话;没有 ⇒ None。纯函数。texts = [(参数名, 值)]。"""
    for flag, v in texts:
        m = _ROW_URL_RE.search(str(v or ""))
        if m:
            q = __import__("shlex").quote(board) if board else "<板>"
            return ("%s 里写着网址(%s)—— 没做完的行里的网址他点不动,首屏还只露第一句:他要拿去用的东西只写在行里,他就看不到"
                    "(1023 选品:他要的 1688 链接只进了行,「要你的」卡上没有)。\n"
                    "   ⇒ 要他点开 / 复制去用的 ⇒ 挂卡:`board.py ask %s --row %s --q \"…\" --rec \"…\" --copy \"<短标题>|<网址>\"`"
                    "(本机方案页用 --deep),行里只写「链接在『要你的』那张卡上」;\n"
                    "   ⇒ 只是你自己记的出处 ⇒ 写卡号 / PR 号,别写网址;这件已经做完 ⇒ 标做完(做完的行里放产物链接照常)。"
                    % (flag, m.group(0)[:80], q, row_ack or "<行>"))
    return None


def _answer_update_why(out, rk, why, why_mode, today, q, ack, require_open=False):
    ta, tb, _tz = _row_span(out, rk)
    ost = re.search(r'\bdata-status\s*=\s*"([^"]*)"', out[ta:tb])
    ost = ost.group(1) if ost else None
    nst = "doing" if ost in ("waiting-you", "blocked") else ost
    if not str(why or "").strip():
        raise _AnswerNeedsWhy(rk, _row_facts(out[ta:tb], out[tb:_tz], today))
    _of = _row_facts(out[ta:tb], out[tb:_tz], today)
    if require_open and not _of["open"]:
        raise ValueError("--why-row 只能改还在追的行 %s" % rk)
    problem = _open_row_url_problem([("--why-row", why)], row_ack=rk) if require_open else None
    if problem:
        raise ValueError(problem)
    _old = re.sub(r"\s+", " ", str(_of.get("why") or "")).strip()
    _say = why
    if why_mode == "add" and _old:
        # 1105 选品:原来用「;」连,首屏只露到第一个句号 / 分号(fsFirst)⇒ 看着像原文没了。用「 · 」连,首屏露新句 + 原文开头;全文在台账那一行
        _say = "%s · %s" % (str(why).strip().rstrip("。;；"), _old)
    elif why_mode != "replace":
        _drop = _why_dropped_codes(_old, why)
        if _drop:
            raise _AnswerWhyDrops(rk, _old, _drop)
    # ⭐ 1116 讲人话 ⑤(电商-基建 #b6c2):一行挂着几张卡,收其中一张时 --why 整段换掉现状 ⇒ 另几张卡问的那几件到哪了,板上就没了。
    #   ⇒ 行上还有别的没收的卡:不换现状、不改状态、不拿掉「要你」,只在末尾追加「<卡> 已收:…」;最后一张收时才按 --why 换。
    _others = _row_linked_cards(out, rk)
    if _others:
        import html as _h5
        _ct = _clause(re.sub(r"\s+", " ", _h5.unescape(re.sub(r"<[^>]+>", "", q.group(1)))).strip() if q else ack, 24)
        _add = "「%s」已收:%s" % (_ct, str(why).strip().rstrip("。;；"))
        out, ch = _row_apply(out, rk, say=("%s · %s" % (_old.rstrip("。;；"), _add)) if _old else _add, status=ost)
        ch = list(ch) + ["行上还挂着 %s 没收 ⇒ 现状没整段换,只在末尾追加了一句;最后一张收时再按 --why 换" % "、".join(_others)]
        return out, ch
    out, ch = _row_apply(out, rk, say=_say, status=nst, no_you=True)
    ch = list(ch) + _answer_why_check(_of, _say)
    if _old and why_mode != "add":
        ch.append("被换掉的原现状:「%s」" % _clause(_old, 120))
    return out, ch


def _answer_input_problems(res, why, done, row, report):
    if not str(res or "").strip():
        report("answer-result", "--res 要写他怎么答的 / 结果(一句)")
    if why and not done:                                          # 1023 选品:他要的链接写进了没做完的行的现状 ⇒ 拒
        _uw = _open_row_url_problem([("--why", why)], row_ack=row)
        if _uw:
            report("answer-why-url", _uw)


def _write_value_error(_key, message):
    raise ValueError(message)


def _card_attr(tag, attr):
    match = re.search(r'\s%s\s*=\s*"([^"]*)"' % re.escape(attr), tag.split(">", 1)[0])
    return _html_unescape_attr(match[1]) if match else None


def _card_answer_records(page, ack, card, load):
    """旧卡记录和与它同步的方案页记录。"""
    rec = (load(page) or {}).get(ack)
    deep_page = _card_attr(card, "data-deep-page")
    deep_q = _card_attr(card, "data-deep-q")
    linked = (load(deep_page) or {}).get(deep_q) if deep_page and deep_q else None
    return rec, linked


def _card_has_answer(page, ack, card, *, strict=False):
    load = _answers_raw if strict else _answers_load
    if isinstance((load(page) or {}).get(ack), dict):
        return True
    deep_page = _card_attr(card, "data-deep-page")
    deep_q = _card_attr(card, "data-deep-q")
    return bool(deep_page and deep_q and isinstance((load(deep_page) or {}).get(deep_q), dict))


def _card_marked_rows(src, ack, today=None):
    return [f["ack"] for f in (_yours_zone_rows(src, today=today) or {}).get("facts", [])
            if f["ack"] and f["you_card"] == ack]


def _clear_card_rows(src, card, ack, today=None, review_links=False):
    owned = set(_card_marked_rows(src, ack, today))
    linked = set()
    if review_links and _card_attr(card, "data-accept") == "1":
        linked.update((_card_attr(card, "data-accept-rows") or "").split())
        linked.update(re.findall(r'href="#row-([^"]+)"', card))
    notes = []
    for row in sorted(owned | linked):
        try:
            start, tag_end, end = _row_span(src, row)
        except ValueError:
            continue
        tag, body = src[start:tag_end], src[tag_end:end]
        others = _row_linked_cards(src, row)
        if others:
            if row in owned:
                src = src[:start] + _attr_set(tag, "data-you-card", others[0]) + src[tag_end:]
            continue
        if row not in owned and (_card_attr(tag, "data-you-card") or _card_attr(tag, "data-you") != "decide"):
            continue
        for attr in ("data-you", "data-you-card", "data-you-since"):
            tag = _attr_set(tag, attr, None)
        act = _span_block(body, "act") if review_links else None
        if act:
            body = body[:act[0]] + body[act[1]:]
        src = src[:start] + tag + body + src[end:]
        notes.append("那一行(%s)不再标「要你拍」(是挂这张卡时标的)" % row)
    return src, notes


def _answer_apply(src, ack, res, row=None, done=False, why=None, no_row=False, today=None, confirm_done=False, summary=None, need_sum=False,
                  why_mode=None, why_rows=None, report=None, withdraw_page=None, replacing=False):
    """他答了「要你的」里一张卡 ⇒ 拿掉卡(R3「拍完当轮拿掉」),对应的那一行一起改成不再等他 —— 纯函数,吐 (新文本, [说明])。
    对应的行:--row 指定 › 卡里链到的 #row-<ack> › 标着 data-you-card 的行 › 卡号与行的 data-ref 相同的行。
    撤卡模式会另外读取这张卡的回答记录，确认没人答过。
    ⭐ 1008(负责人,电商-基建:一行里写着几件事,他只答了其中一张卡,那一行的现状被整段换成「你 10-08 答了:…」,另外半件事的状态看不出来了):
       有对应的行、没给 done、也没给 why ⇒ ValueError、什么都不改 —— 他答完之后这一行到哪了只有作者知道,不再拿他的回答去盖。
    ⛔ 机器卡(每次落板现算)不能手拿:下一次 touch / queue 原样长回来 —— 报错并说改源头。"""
    today = today or datetime.date.today()
    if report is None and not (withdraw_page or replacing):
        _answer_input_problems(res, why, done, row, _write_value_error)
    head, end = _yours_zone_span(src)
    if not head:
        raise ValueError("这块板找不到「要你的」区")
    z0 = head.end()
    body = src[z0:end]
    gen = [(m.start(), m.end()) for _nm, b_, e_ in _gen_block_pairs()
           for m in re.finditer(re.escape(b_) + r".*?" + re.escape(e_), body, re.S)]
    hit = None
    for c in re.finditer(r'<article\b([^>]*)>.*?</article>', body, re.S):
        if "card" in _class_set(c.group(1)) and re.search(r'\bdata-ack\s*=\s*"%s"' % re.escape(ack), c.group(1)):
            hit = c
            break
    if not hit:
        raise ValueError("「要你的」里没有 data-ack=\"%s\" 的卡" % ack)
    if ack in YOURS_MACHINE_ACKS or any(g0 <= hit.start() < g1 for g0, g1 in gen):
        raise ValueError("data-ack=\"%s\" 是机器卡(每次落板现算),手拿掉下一次落板就长回来 —— 改它的源头:"
                         "「你交代的」那几行用 `board.py row --no-you` 或做完交验收 `--review`;「卡在你身上」那张改 .queue.json 的 you;"
                         "过期提醒改那一行的 data-eta" % ack)
    if _is_placeholder_card(hit.group(0)):
        raise ValueError("那是「此刻没有要你的」占位卡,不用拿")
    card = hit.group(0)
    if withdraw_page and _card_has_answer(withdraw_page, ack, card, strict=True):
        raise ValueError("他已在 %s 上填写过回答；先用 answer --ack %s --res … 处理回答。"
                         "换卡并保留补充或其他选项可用：board.py ask <板> … --replaces %s。"
                         "已点通过或不通过时先收卡。" % (ack, ack, ack))
    cs, ce = hit.start(), hit.end()
    if body[ce:ce + 1] == "\n":
        ce += 1
    new_body = body[:cs] + body[ce:]
    remaining = _yours_cards(new_body)
    if any(_card_attr(c.group(0), "data-ack") == ack for c in remaining):
        raise ValueError("板上有多张卡共用 %s；先修正重复卡号再收。" % ack)
    n = len(remaining)
    new_head = re.sub(r'(<span class="n">)[^<]*(</span>)', lambda m: m.group(1) + "%d 件" % n + m.group(2), head.group(0), count=1)
    out = src[:head.start()] + new_head + new_body + src[end:]
    q = re.search(r'<h2 class="q">(.*?)</h2>', card, re.S)
    notes = ["「要你的」−1 → 现在 %d 件(拿掉:%s)" % (n, _clause(re.sub(r"<[^>]+>", "", q.group(1)) if q else ack, 40))]
    if withdraw_page or replacing:
        out, cleared = _clear_card_rows(out, card, ack, today, review_links=True)
        return out, notes + cleared
    if no_row:
        out, _nn = _answer_norow_rows(out, card, ack, today)
        # 1105 选品:卡链着一行、--no-row 收 ⇒ 给那一行记收卡时间;之后没改字也没 --checked ⇒ 进要核名单、lint 提醒(见 _row_card_moved)
        _lk = re.search(r'href="#row-([^"]+)"', card)
        if _lk:
            try:
                _ca, _cb, _cz = _row_span(out, _lk.group(1))
                if _row_facts(out[_ca:_cb], out[_cb:_cz], today).get("open"):
                    out = out[:_ca] + _attr_set(out[_ca:_cb], "data-card-at", datetime.datetime.now().strftime("%Y-%m-%dT%H:%M")) + out[_cb:]
                    _nn = list(_nn) + ["⚠ 这张卡链着行 %s,现状没动 —— 变了 `row --ack %s --say …`,仍对 `--checked \"核了什么\"`,不然它进要核名单" % (_lk.group(1), _lk.group(1))]
            except ValueError:
                pass
        return out, notes + ["没动任何行(--no-row)"] + _nn
    rk = row
    if not rk:
        lk = re.search(r'href="#row-([^"]+)"', card)
        rk = lk.group(1) if lk else None
    if not rk:
        marked = _card_marked_rows(src, ack, today)
        if len(marked) > 1:
            raise ValueError("多行标着这张卡；用 --row 指定主行，或用 --no-row 只收卡并清理标记")
        if marked:
            rk = marked[0]
    if not rk:
        cn = re.search(r'<span class="chip id">\s*#(\d+)\s*</span>', card)
        if cn:
            y = _yours_zone_rows(out, today=today)
            refs = [f["ack"] for f in (y["facts"] if y else []) if f.get("ref") == cn.group(1) and f["ack"]]
            if len(refs) == 1:
                rk = refs[0]
            elif len(refs) > 1:
                notes.append("⚠ 「你交代的」里有 %d 行都挂着 #%s,没替你挑 —— 用 `board.py row` 改那一行" % (len(refs), cn.group(1)))
    batch_rows = _accept_batch_rows(src, ack)
    why_rows = why_rows or {}
    linked = set(re.findall(r'href="#row-([^"]+)"', card)) | set(batch_rows)
    unknown = why_rows.keys() - (linked | ({rk} if rk else set()))
    if unknown:
        raise ValueError("--why-row 指了卡 %s 没关联的行:%s" % (ack, "、".join(sorted(unknown))))
    if rk in why_rows and why:
        raise ValueError("行 %s 同时给了 --why 和 --why-row，只留一个" % rk)
    if not rk:
        return out, notes + ["这张卡没链到「你交代的」里的行 —— 他的答复只在聊天里;要留痕就写进它的卡号或账本"]
    try:
        if done:
            # 1008 晚(电商-基建 v1.7 实撞两次):`--done` 被读成「这张卡处理完了」,而它做的是「把对应那一整行标成做完」——
            #   一张「这张卡没讲清楚,重写」的卡 --done,把还没做完的 137 行标完成并搬进了留档页;另一张把已做完行的结论盖成了「不用答了」。
            #   ⇒ 已做完的行不许再被盖结论;命令行上 --done 必须同时用 --row 点名那一行(报错里把那一行的标题和现状摆出来)。
            _da, _db, _dz = _row_span(out, rk)
            _df = _row_facts(out[_da:_db], out[_db:_dz], today)
            _dl = "%s(%s)" % (_clause(_df.get("title") or "(没标题)", 30), rk)
            if not _df.get("open"):
                raise ValueError("--done 会把「你交代的」里那一行标成做完,而 **%s 已经是做完的**,它的结论会被 --res 这句盖掉。\n"
                                 "  ⇒ 只是收掉这张卡:把 --done 换成 --no-row;真要改那一行的结论:另跑 `board.py row … --ack %s --say \"新结论\"`。" % (_dl, rk))
            if confirm_done and not row:
                raise ValueError("--done 的意思是「**那一整行的事做完了**」,不是「这张卡处理完了」(卡本来就会被拿掉)。它会把这一行标成做完、--res 当结论:\n"
                                 "     %s —— 现在写的是:「%s」\n"
                                 "  ⇒ 二选一(1104 选品:原来只说了「是整行做完」,没说该怎么写,连撞两次)—— 照抄,改引号里的字:\n"
                                 "     · 这一整行的事都做完了:python3 ~/.claude/scripts/board.py answer <板> --ack %s --res \"…\" --done --row %s --sum \"一句人话:这件事是什么、做成了什么\"\n"
                                 "     · 只是这张卡那件了结了、这一行还有别的没做完:python3 ~/.claude/scripts/board.py answer <板> --ack %s --res \"…\" --why \"这张卡那件做完了\" --why-add\n"
                                 "       (那件要单独交验收:另跑 python3 ~/.claude/scripts/board.py row <板> --new --title \"那件的标题\" --say \"做完了,等你验\" --eta MM-DD 开一行,再 row <板> --ack <新行> --review --q \"…\" --got \"…\")\n"
                                 "     · 只是这张卡不用答了、和那一行无关:把 --done 换成 --no-row(只拿卡)"
                                 % (_dl, _clause(_df.get("why") or _df.get("res") or "(空)", 60), ack, rk, ack))
            out, ch = _row_apply(out, rk, say=res, status="done", summary=summary, need_sum=need_sum)
        else:
            changes = {rk: why} if why or not why_rows else {}
            changes.update(why_rows)
            for _rk, _why in changes.items():
                out, ch = _answer_update_why(out, _rk, _why, why_mode if _rk == rk and why else None,
                                             today, q, ack, require_open=_rk in why_rows)
                notes.append("那一行(%s):%s" % (_rk, ";".join(ch) or "没变"))
            for _rk in batch_rows:
                if _rk in changes or _row_linked_cards(out, _rk):
                    continue
                out, _ = _row_apply(out, _rk, status="doing", no_you=True)
                notes.append("同一张验收卡上的行 %s 一起回到在做" % _rk)
            out, cleared = _clear_card_rows(out, card, ack, today)
            return out, notes + cleared
    except _AnswerWhyDrops as e:
        _rk, _old, _drop = e.args
        raise ValueError(
            "--why 会把这一行(%s)的现状**整段换掉**,而新写的这句里没有原现状提到的 %s —— 换掉之后这几件到哪了,板上就没了。\n"
            "  原现状:「%s」\n"
            "  ⇒ 三选一(照抄,改引号里的字):\n"
            "     · 只补这张卡的进展、原现状留着:python3 ~/.claude/scripts/board.py answer <板> --ack %s --res \"…\" --why \"这张卡的进展\" --why-add\n"
            "     · 整段重写、把没变的几件也写进去:python3 ~/.claude/scripts/board.py answer <板> --ack %s --res \"…\" --why \"…(含 %s 到哪了)\"\n"
            "     · 那几件确实都了结了、就要整段换掉:原命令加 --why-replace"
            % (_rk, "、".join(_drop[:6]), _clause(_old, 160), ack, ack, "、".join(_drop[:6])))
    except _AnswerNeedsWhy as e:
        f = e.args[1]
        raise ValueError(
            "这张卡对应着「你交代的」里的一行(%s)。他答完之后**这一行现在到哪了,由你写一句** —— 不再拿他的回答去盖这一行的现状"
            "(一行里常不止一件事:盖掉之后,另外半件事到哪了就看不出来了)。\n"
            "  这一行现在写的是:「%s」\n"
            "  ⇒ 三选一,加在这条命令后面再跑:\n"
            "     · 这件事还没做完:--why \"这一行现在到哪了(整段换掉上面那句,所以没变的部分也要写进去)\"\n"
            "     · 这一整行的事做完了(不是「这张卡处理完了」):--done --row <那一行的编号>(--res 当结论)\n"
            "     · 这张卡和那一行其实无关:--no-row(只拿卡,那一行一个字不动)"
            % (_row_label(f), f.get("why") or "(这一行没写现状)"))
    except ValueError as e:
        raise ValueError("卡找到了,但对应那一行(%s)改不了:%s —— 先用 `board.py row` 把那一行补齐,或加 --no-row 只拿卡" % (rk, e))
    out, cleared = _clear_card_rows(out, card, ack, today)
    return out, notes + ["那一行(%s):%s" % (rk, ";".join(ch) or "没变")] + cleared


# ⭐ 1027(电商-选品 v2.6 转):收「床头充电站」那张卡(他选先不做)用了 --no-row,r1023-9711 就一直挂着「等同事乙找 S000」—— 没人回头改。
#   ⇒ --no-row 时:① 这张卡挂上时自动标「要你拍」的那一行(data-you-card = 这张卡)改回来;
#     ② 列出文字里提到这张卡上同一个货号 / 编号(大写字母开头 3 位以上)的没做完的行,提示重判(只提示,不改)。
_CODE_RE = re.compile(r"(?<![A-Za-z0-9])[A-Z][A-Z0-9]{2,}(?![A-Za-z0-9])")
_CODE_SKIP = {"AI", "API", "CEO", "GMV", "SKU", "TK", "某店甲", "某店乙", "USD", "PR", "CI", "OK", "URL", "PDF", "HTML", "CLI", "MCP", "TODO", "AND", "THE"}


def _answer_norow_rows(src, card, ack, today=None):
    """(新 src, [说明])。纯函数。"""
    src, notes = _clear_card_rows(src, card, ack, today)
    facts = (_yours_zone_rows(src, today=today) or {}).get("facts", [])
    text = re.sub(r"<[^>]+>", " ", card or "")
    codes = sorted({c for c in _CODE_RE.findall(text) if c not in _CODE_SKIP})
    if codes:
        hit = []
        for f in facts:
            if not f.get("open") or not f.get("ack"):
                continue
            blob = " ".join(str(f.get(k) or "") for k in ("title", "why", "act", "wait_for"))
            cs = [c for c in codes if re.search(r"(?<![A-Za-z0-9])%s(?![A-Za-z0-9])" % re.escape(c), blob)]
            if cs:
                hit.append("%s「%s」(提到 %s)" % (f["ack"], _clause(f.get("title") or "", 24), "/".join(cs)))
        if hit:
            notes.append("⚠ 这几行也提到卡上的 %s,他答完它们还对不对?过一遍(row --ack <行> --say …):%s" % ("/".join(codes[:6]), ";".join(hit[:8])))
    return src, notes


# ⭐ 1027(电商-选品 v2.6 转):`answer --why` 整段换掉那一行的现状,两次被写成了这一张卡的事(对标监控那行第一句成了「加了 AI 代发后重新挂卡」)。
#   ⇒ 印出旧 → 新第一句;新现状和行标题一个词都对不上 ⇒ 提醒(只提醒,不拦:机器分不清是不是换了说法)。
def _answer_why_check(f, why):
    old = re.split(r"[。;;\n]", str(f.get("why") or ""))[0].strip()
    new = re.split(r"[。;;\n]", str(why or ""))[0].strip()
    out = ["第一句「%s」→「%s」(一行讲的是整件事,不是这一张卡)" % (_clause(old or "(空)", 30), _clause(new, 30))]
    def grams(t):
        t = re.sub(r"[^\w\u4e00-\u9fff]+", " ", str(t or ""))
        g = set(w.lower() for w in re.findall(r"[A-Za-z0-9]{3,}", t))
        for seg in re.findall(r"[\u4e00-\u9fff]{2,}", t):
            g |= {seg[i:i + 2] for i in range(len(seg) - 1)}
        return g
    tg = grams(f.get("title"))
    if tg and not (tg & grams(why)):
        out.append("⚠ 新现状和这一行的标题「%s」一个词都对不上 —— 是不是写成了这张卡的事?不是就不用管" % _clause(f.get("title") or "", 24))
    return out


def _write_back(p, before, out, *, pending=True, validate=None):
    """原地写回(保 inode / 硬链;⛔ 不整份换文件);读进来之后板被别人改过 ⇒ 什么都不写。"""
    with open(p, "r+b") as fh:
        BP.lock_fd(fh.fileno())
        if fh.read().decode("utf-8").replace("\r\n", "\n").replace("\r", "\n") != before:
            die("板在读进来到写回之间被人改了 —— 什么都没写,重跑一次。")
        if validate:
            validate()
        out = _keep_proposal_answer_refs(before, out)
        fh.seek(0)
        fh.write(out.encode("utf-8"))
        fh.truncate()
    if pending:
        _print_pending_notes(out)


def _path_lookup(root, name):
    """`board.py path <线名>` 的查法:root 下 `.claude/boards/` 里先按文件名、再按 <title> 找;找到返回路径,找不到 None。
    ⚠ 文件名不一定等于线名(历史遗留:iOS 线那块叫 ios.html 不叫 示例项目-IOS.html)。
      推不中就按 <title> 找,⛔ 别给出一个不存在的路径 —— 那比报错更坏:调用者会照着它新建**第二份**板。"""
    bdir = os.path.join(root, ".claude", "boards")
    slug = name.replace(" 状态板", "")
    guess = os.path.join(bdir, slug + ".html")
    if os.path.exists(guess):
        return guess
    want = (slug + " 状态板").lower()
    for fn in sorted(os.listdir(bdir)) if os.path.isdir(bdir) else []:
        if not fn.endswith(".html") or fn == "_index.html":
            continue
        fp = os.path.join(bdir, fn)
        m = re.search(r"<title>(.*?)</title>", open(fp, encoding="utf-8", errors="ignore").read(), re.S)
        if m and m.group(1).strip().lower() == want:
            return fp
    return None


def _board_out_of_reach(path, dirs=None):
    """这块板所在的 `.claude/boards` 在不在「找板」走得到的地方。走不到 ⇒ 返回一句要报的话;走得到 ⇒ None。
    dirs = 找板走到的板目录(测试时传);缺省现走一遍(`board_paths.walk_boards`,与总览 / 伺服目录同一套)。

    ⭐ 1001(给同事装机、在干净环境里走安装步骤时撞到):仓放在 ~/Documents 下,`new` 照样说「建好」、
      `touch` 照样盖戳,可这块板进不了伺服目录 —— 8777 上是 404,总览里也没有,而没有任何一步出声。
      本机的仓全在 ~/work 下,所以这条在本机永远撞不到(0918 打包时那四处同一个形状)。
    ⛔ 不替他改配置:只说清为什么打不开、照抄哪一行能好。"""
    bd = os.path.realpath(os.path.dirname(path))
    found = dirs if dirs is not None else [dp for dp, _fns in _bounded_board_walk()]
    if any(os.path.realpath(d) == bd for d in found):
        return None
    home = os.path.expanduser("~")

    def _short(x):
        return ("~" + x[len(home):]) if (x == home or x.startswith(home + os.sep)) else x
    proj = _short(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(path)))))
    cfg = _short(BP.config_path())
    roots = [_short(r) for r in BP.roots()]
    want = ", ".join('"%s"' % r for r in roots + [proj])
    return ("这块板不在找板的范围里 ⇒ **%s 上打不开**(他点开是 404),总览里也没有。找板只走 `board_roots` 底下的仓(现在是 %s)。"
            "⇒ 把这个项目加进去:在 `%s` 里写 `{\"board_roots\": [%s]}`(文件已经有就只加最后这一项),再 touch 一次。"
            % (BP.origin(), "、".join(roots) or "空", cfg, want))


def _gen_stamp_text(t, now, human):
    """板顶的生成时间换成 now(秒)/ human(「YYYY-MM-DD HH:MM」)。板上没有 `data-gen="数字"` ⇒ None(外壳不对)。
    ⚠ 1001(给同事装机、在干净环境里走安装步骤时撞到):原来拿「替换前后一样」当「没找到」——
      同一秒里的第二次 touch(`touch` 完紧跟一条 `ask` / `row`,各盖一次戳;gh 没登录时一次 touch 不到一秒)
      时间戳本来就一样,却被报成「这块板的外壳不对,先跑 board.py sync」,新加的卡也没盖上戳。"""
    if not re.search(r'data-gen="\d+"', t):
        return None
    t2 = re.sub(r'data-gen="\d+"', 'data-gen="%d"' % now, t, count=1)
    return re.sub(r'生成于 <b>[^<]*</b>', '生成于 <b>%s</b>' % human, t2, count=1)


def _port_text(text):
    """给人看的文字里的本机地址按配置的端口印;缺省端口时一个字不变。
    ⚠ 1001:8777 被占的机器照 SKILL.md 改了端口,刷板提示里却还印着 `127.0.0.1:8777/<板文件名>.html` ——
      照着给出去的地址打不开。提示和 help 的正文是写死的长字符串,统一在打印那一步换。"""
    p = BP.port()
    return text if p == 8777 else text.replace("127.0.0.1:8777", "127.0.0.1:%d" % p)


# ⭐ 1109 负责人(经 单开#r1109-6aa5):「你这条线的状态板,你说挂到板上去,我根本可找不到。」
#   新线 `board.py new` 之后面板还停在 New tab;面板检查(board-pane-check.js)要等他下一条消息才响,那时他已经找了一圈。
#   ⇒ 写板命令的输出里当场说:这块板此刻没开在面板里 ⇒ 回复前先 navigate。判据同面板检查:STALE 秒没被拉过。
#   ⛔ 只在 Claude 会话里说(Codex 没有这个面板工具)。
PANE_STALE_S = 180


# ⭐ 1110 面板归属(状态板线;负责人 11-09 一天问了 4 次「我根本找不到」):上面那条判据只看「这块板 STALE 秒内被拉过」,
#   不分是哪个会话的面板拉的 ⇒ 别的会话的面板开着它,本会话也判成开着,AI 说「挂到板上了」,他在这个会话右边却找不到。
#   ⇒ navigate 的地址带 ?s=<本会话标记>(kit 记进 sessionStorage,之后的定时拉取都带上),伺服把「哪个标记的面板此刻在拉哪块板」
#   记进 pane-fetch.json;这里核到「本会话的面板此刻指向这块板」才算开着,核不到当场说并给打开方式。
#   标记 = sha1(cliSessionId) 前 10 位:本侧取 _cli_session_id()(writes.jsonl 的 sid 就是它);钩子 board-pane-check.js 取 hook 输入的
#   session_id —— 钩子拿 e.sid === sid 对 writes.jsonl,所以两边是同一个 id、算出同一个标记。取不到(不是桌面会话)⇒ 退回旧判法。
PANE_MARK_LEN = 10      # 依据: sha1 前 10 位十六进制 = 40 bit,本机同时活着的会话几十个,撞号可忽略;伺服 / kit / 钩子按同一长度校验


def _pane_mark(sid=None):
    """本会话的面板标记;拿不到会话 id ⇒ ''(调用方退回旧判法)。"""
    sid = _cli_session_id() if sid is None else sid
    if not sid:
        return ""
    import hashlib
    return hashlib.sha1(str(sid).encode("utf-8")).hexdigest()[:PANE_MARK_LEN]


def _pane_nav(fn, mark=""):
    """「⇒ 回复前先 navigate(…),再说挂到板上了」那半句;有标记就带 ?s=。"""
    import urllib.parse as _up
    return ("⇒ 回复前先 `mcp__Claude_Browser__navigate({ url: \"%s/%s%s\" })`,再说「挂到板上了」。"
            % (BP.origin(), _up.quote(fn), ("?s=" + mark) if mark else ""))


def _pane_tail_msg(fn, last, now, mark=""):
    """纯函数:这块板最近一次被面板拉取的时间 → 要印的一句;还在面板里 ⇒ None。(旧判法:不分会话)"""
    age = None if last is None else now - float(last)
    if age is not None and age < PANE_STALE_S:
        return None
    return ("  👉 这块板此刻没开在面板里(%s)—— 他在右边找不到。" % ("从没开过" if age is None else "%d 分钟没人看" % (age // 60))) + _pane_nav(fn, mark)


def _pane_verdict(fn, mark, pane, last, now):
    """纯函数(1110 面板归属):→ 要印的一句;本会话的面板此刻开着这块板 ⇒ None。
    pane = pane-fetch.json 的内容 {标记: {"board": 板文件名, "t": 秒}};last = last-fetch.json 里这块板的时间(不分会话)。
    a 本标记的记录在 STALE 秒内、指着这块板 ⇒ None · b 指着另一块 ⇒ 说开的是哪块 · c 没有 / 过期 ⇒ 说核不到(别的面板开着它就加半句)
    d 没有标记 ⇒ 完全照旧判法。"""
    if not mark:
        return _pane_tail_msg(fn, last, now)
    rec = pane.get(mark) if isinstance(pane, dict) else None
    cur = None
    if isinstance(rec, dict) and rec.get("board"):
        try:
            if now - float(rec.get("t")) < PANE_STALE_S:
                cur = str(rec.get("board"))
        except (TypeError, ValueError):
            cur = None
    if cur == fn:
        return None
    if cur:
        return ("  👉 本会话的面板此刻开的是〈%s〉,不是这块 —— 他在右边找不到。" % cur) + _pane_nav(fn, mark)
    other = ""
    try:
        if last is not None and now - float(last) < PANE_STALE_S:
            other = "(有别的面板开着它,但不是本会话的,或是没带标记打开的)"
    except (TypeError, ValueError):
        other = ""
    return ("  👉 核不到本会话的面板开着这块板%s —— 他在右边找不到。" % other) + _pane_nav(fn, mark)


def _pane_mark_for(path, mark, sess):
    """纯函数(1110 面板归属):这次写的板该不该按「本会话的面板」判 —— 该 ⇒ 原样回 mark;不该 ⇒ ""(退回只看这块板有没有面板开着)。
    子线往派它的线的板上写进度行:那块板该开在父线的面板里,不是子线自己的。⛔ 别催子线把父线的板送进自己的面板
    (负责人 11-09 截图那次就是子线的面板被翻成了父线的板;11-10 他定「子线留着,但对我隐身」)。"""
    if mark and sess and _subline_board_problem(path, sess):
        return ""
    return mark


def _pane_tail(p):
    if not os.environ.get("CLAUDECODE"):
        return
    par = _child_parent_of(p)               # 1110 子线投影:子板的卡投影在父板上 ⇒ 只看父板有没有哪个面板开着,⛔ 不催送子板进面板
    if par:
        try:
            lastmap = json.load(open(BP.state("board-server", "last-fetch.json"), encoding="utf-8"))
        except (OSError, ValueError):
            return
        m = _pane_parent_msg(par, lastmap, time.time())
        if m:
            print(m)
        return
    fn = os.path.basename(p)
    try:
        last = json.load(open(BP.state("board-server", "last-fetch.json"), encoding="utf-8")).get(fn)
    except (OSError, ValueError):
        return                  # 读不到就不说话:这是提示,错报比不报糟
    mark, pane = _pane_mark(), {}
    try:
        mark = _pane_mark_for(p, mark, _session_ident() if mark else None)
    except Exception:
        pass
    if mark:
        try:
            pane = json.load(open(BP.state("board-server", "pane-fetch.json"), encoding="utf-8"))
        except (OSError, ValueError):
            pane = {}           # 伺服还没记过任何带标记的面板 ⇒ 当作核不到(c),照样给打开方式
    m = _pane_verdict(fn, mark, pane, last, time.time())
    if m:
        print(m)


def _touch_child(p, what="改动"):
    """改动写入之后顺手 touch 一次。成功返回 0，后续 touch 失败返回 3。
    ⭐ 1021 晚(示例-运维 转):原来只印「⛔ touch 报错了(上面)」—— 原因印在子进程的 stderr 里,
      和这句不挨着,被截断或分流时就成了「报了错却看不到是什么错」;而它最常见的原因是「内容和上次盖戳时一样」,
      那对改板命令来说根本不是错(运维线随后单跑 touch 也说内容未变、lint PASS)。
    ⇒ 收下子进程的输出原样印出,失败时把原因摘进同一句;「内容一模一样」不算失败。"""
    _brief("touch")              # 1020:摘要由父进程打一次(同目录一天一次全文),子进程不再打
    try:
        r = subprocess.run([sys.executable, os.path.abspath(__file__), "touch", p],
                           env=dict(os.environ, BOARD_NO_BRIEF="1", BOARD_NOTE_ALREADY_PRINTED="1"), capture_output=True, text=True)
    except (OSError, subprocess.SubprocessError) as e:
        print("  ⛔ 改动已写进板，但 touch 没跑完(退出码 3):%s" % e)
        return 3
    out, err = r.stdout or "", r.stderr or ""
    if r.returncode and "一模一样" in err and not re.search(r"^\s*✗", out, re.M):
        print("  ✓ 板的内容和上次盖戳时一样(这次%s没让板变)—— 不用再 touch。" % what)
        return 0
    # touch 的子步骤可能打印拒写尾巴，那句话只描述子步骤。
    out, err = (re.sub(r"^([ \t]*)⇒ 什么都没写。$", r"\1⇒ 这个 touch 步骤没有写入。", part, flags=re.M)
                for part in (out, err))
    sys.stdout.write(out)
    sys.stdout.write(err)
    if r.returncode:
        why = next((line.strip() for part in (out, err) for line in part.splitlines()
                    if re.match(r"\s*(✗|⛔)", line)), "")
        print("  ⛔ touch 没过(子进程退出码 %d):%s\n     这次改动已写进板(退出码 3 = 已写、板上有别的错要修)。修好后再 touch 一次。"
              % (r.returncode, why[:200] or "子进程没印出原因 —— 报给状态板线"))
    _pane_tail(p)
    return 3 if r.returncode else 0


def _touch_after_edit(p, no_touch):
    if no_touch:
        print("  ⚠ 没盖戳(--no-touch)⇒ 记得 `board.py touch` 一次,否则面板上还是旧的。")
        return 0
    return _touch_child(p)


# ⭐ 1028(电商-选品 v2.8 转,负责人 10-28 17:1x「你这个是个很严重的bad case啊」):卡 ask-f9bdb099 问「插排重量的私信能不能发给同事乙」,
#   他答「我直接问掉好了」;AI 照常 `answer --why` 把卡收了 ⇒ 他问完供应商回来,板上没有地方填:「我现在都不知道在哪个版,在哪个哪个地方回复你了」。
#   他的回答是「这一步我来」时,卡其实没完结,只是从「要他拍」变成「要他动手」;「要你的」里的机器小卡没有回答框,标 --you do 也接不住。
#   ⇒ 他的回答 / --res / --why 里有「我去问 / 我自己来 / 我直接…」⇒ 不让直接收(--done 除外):先挂一张给他填结果的卡再收(--followup <新卡>),
#     或写明他不用再回的理由(--no-followup)。实测:10-22~10-28 消化掉的 374 条回答里 12 条这么说,几乎都是他接下了一步。
_SELF_DO_RE = re.compile(r"我(?:已经)?(?:自己(?:去|来|先|直接)?|来|去|直接|先|在)(?:问|找|联系|弄|做|处理|搞|发|查|跟|和|试|改|下单|付|买|对接)"
                         r"|我自己来|我来吧|我去吧|我会(?:问|去|跟|联系|处理)|我问一下|我去问|我问问|我直接"
                         rf"|(?:他|{_owner_pattern()})(?:说)?自己(?:在|去|来)?(?:问|联系|找|处理|发)")


# ⭐ 1029(电商-选品 v2.9 转,负责人 10-29 14:5x:「我还没讨论完,怎么就已经没了?……很多事情感觉就我还没有讨论完,那个事情就已经直接从板上消失了」):
#   他在卡上没选选项、写的是追问 / 讨论(「购买理由表是什么」「先拿几个 case 试、调研、算收益和成本」),线照「答了当轮收」把卡收了、没续一张 ⇒ 这件从「要你的」消失。
#   ⇒ 他没选选项(空 / 「其他」)、补充里在问或说还要再讨论 ⇒ 同「这一步我来」:要 --followup <续的那张卡> 或 --no-followup「他其实拍了什么」。--done 不放行(他的问题还没回)。
#   依据:10-20~10-29 消化掉的 457 条卡上回答,212 条只写补充,其中 120 条命中下面的词(抽 15 条看,都是他在问 / 推回去);「好吧? / 对吧?」这类反问不算。
_DISCUSS_RE = re.compile(r"(?<![吧啊呀嘛])[?？]|你觉得|是不是|为什么|是什么|什么情况|怎么回事|没搞懂|没看懂|没懂|讲清楚|说清楚|吗[。，,!！\s]|吗$"
                         r"|再(?:进一步)?(?:想想|想一下|讨论|设计|优化|研究|调研|聊)|先(?:拿|试|调研|看看|跑)|还没(?:讨论|想好|定|聊)|我再想|商量")


# 依据: 11-20 投流达人，选项明确把申请交给 AI，补充里「你能帮我…」也是请 AI 做。
_SELF_DO_DELEGATE_RE = re.compile(r"替你|帮我|你来|你自动")
# 依据: 同一条回答中的「你能帮我直接申请」「你每周自动帮我申请」。
_SELF_DO_REQUEST_RE = re.compile(r"(你[^，。！？；\r\n,.!?;]*?帮)我")


def _answer_selfdo_problem(src, a, answers):
    """answer 要收的这张卡,他的回答像是「这一步我来」、或他没选选项在追问 / 讨论,而作者没给他留接着回的地方 ⇒ 一句要报的话;否则 None。纯函数(answers = 这块板的回答记录)。"""
    rec = answers.get(a.ack) if isinstance(answers, dict) else None
    m = dm = None
    choice = str((rec or {}).get("choice") or "")
    if not getattr(a, "done", False) and not _SELF_DO_DELEGATE_RE.search(choice):
        note = _SELF_DO_REQUEST_RE.sub(r"\1", str((rec or {}).get("note") or ""))
        texts = [choice, note, str(a.res or ""), str(getattr(a, "why", None) or "")]
        m = next((x for x in (_SELF_DO_RE.search(t) for t in texts) if x), None)
    if not m and rec and str(rec.get("choice") or "").strip() in ("", "其他(我自己写)"):
        dm = _DISCUSS_RE.search(str(rec.get("note") or ""))
    if not m and not dm:
        return None
    fu, nf = getattr(a, "followup", None), getattr(a, "no_followup", None)
    if nf is not None:
        if len(str(nf).strip()) < 6:
            return "--no-followup 要写他为什么不用再回你(例:「他只是说自己发,发完就完,不用告诉我」)"
        return None
    if fu:
        cards = {c["id"] for c in _yours_report(src, "")["cards"]}
        if fu == a.ack or fu not in cards:
            return "--followup %s 不是「要你的」里另一张卡 —— 先 `board.py ask … --do` 挂出来,再拿它的卡号" % fu
        return None
    if dm:
        t = dm.string
        clip = t[max(0, dm.start() - 16):dm.end() + 12].replace("\n", " ")
        return ("✗ 他没选选项,补充里在问 / 说还要再讨论(「…%s…」)—— 现在收卡,这件就从「要你的」消失了"
                "(10-29 电商-选品:他问「购买理由表是什么」、又说「先拿几个 case 试」,卡收了没续,他:「我还没讨论完,怎么就已经没了」)。\n"
                "   ⇒ 还要他接着回 / 接着拍 ⇒ 先挂续的那张:`board.py ask <板> --row <行> --q \"<他问的那句的答案 + 现在要他定的>\" --rec …`,"
                "再 `board.py answer … --followup <新卡号>`;\n"
                "   ⇒ 他其实已经拍了、问的只是顺口一句 ⇒ `--no-followup \"他拍的是:…;问的那句已在 <哪里> 答了\"`。" % clip)
    t = m.string
    clip = t[max(0, m.start() - 12):m.end() + 16].replace("\n", " ")
    return ("✗ 他的回答里说这一步他自己来(「…%s…」)—— 收了卡,他做完回来就没地方填结果"
            "(10-28 电商-选品:他说自己问供应商,卡被收了,问完「都不知道在哪个版,在哪个地方回复你了」)。\n"
            "   ⇒ 先给他留个填结果的地方:`board.py ask <板> --do --row <行> --q \"问完供应商,把结果填这里\" --rec … --steps …`,"
            "再 `board.py answer … --followup <新卡号>`;\n"
            "   ⇒ 他确实不用再回你(只是说自己发、发完就完)⇒ `--no-followup \"为什么不用他再回\"`;他做完了、结果也给了 ⇒ `--done`。" % clip)


# 1104(负责人在方案页 board-rot-plan-20261103 拍「照这套改」):他一次答了 13 张卡,AI 得一张张跑 answer(选品 v3.2 嫌「讨论中收卡要续卡」那道闸费轮次)
#   ⇒ `--ack a,b,c` 一条命令收多张,共用 --res / --why / --followup / --no-followup;逐张照单张的规矩判(没看过的、讨论中的照样拦),最后只盖一次戳。
#   ⛔ 不能和 --row 一起用(几张卡对应几行,点名一行说不清);先逐张核对；有卡被拦，整组都留在板上。
def _answer_acks(v):
    return [x for x in dict.fromkeys(re.split(r"[,，\s]+", str(v or "").strip())) if x]


# ⭐ 1105(电商-选品 v3.2 转):批量改时每条都 touch + lint,改到一半他已经在看了 ⇒ `board.py batch <板>`:
#   从标准输入(或 --file)读,一行一条 `row …` / `answer …`(写法和命令行一样,不写板路径),全部写完只盖一次戳。
#   ⛔ 一条被拦不影响别的:照跑完,最后说清哪几条没成、原因;退出码非 0。每条只印一行结果,不重印那一大段提示。
def cmd_batch(a, ap):
    import contextlib as _cx, shlex as _shx
    try:
        text = open(a.file, encoding="utf-8").read() if a.file else sys.stdin.read()
    except OSError as e:
        die("读不到 %s:%s" % (a.file, e))
    lines = [l.strip() for l in text.splitlines() if l.strip() and not l.strip().startswith("#")]
    if not lines:
        die("没有要做的:一行一条 `row --ack <行> --say \"…\"` 或 `answer --ack <卡> --res \"…\" --why \"…\"`")
    ok, bad = 0, []
    for i, l in enumerate(lines, 1):
        buf = io.StringIO()
        rc = 0
        try:
            parts = _shx.split(l)
            if not parts or parts[0] not in ("row", "answer"):
                raise ValueError("只认 row / answer 开头")
            with _cx.redirect_stdout(buf), _cx.redirect_stderr(buf):
                b = ap.parse_args([parts[0], a.path] + parts[1:] + ["--no-touch"])
                if parts[0] == "row":
                    rc = cmd_row(b)
                else:
                    rc = cmd_answer_multi(b) if len(_answer_acks(b.ack)) > 1 else cmd_answer(b)
        except SystemExit as e:
            rc = e.code if e.code not in (None, 0) else 0
        except ValueError as e:
            rc = 2
            buf.write("✗ %s\n" % e)
        out = [x for x in buf.getvalue().splitlines() if x.strip()]
        if rc:
            bad.append((i, l, out))
            print("✗ 第 %d 条没成:%s" % (i, _clause(l, 60)))
        else:
            ok += 1
            print("✓ 第 %d 条:%s" % (i, _clause(out[0].lstrip("✓ ") if out else l, 90)))
    print("批量:%d 条成了,%d 条没成%s" % (ok, len(bad), ";全部写完只盖一次戳" if ok else ""))
    for i, l, out in bad:
        print("── 第 %d 条:%s" % (i, l[:160]))
        for x in [y for y in out if "✗" in y or "⇒" in y or "error" in y][:6] or out[:6]:
            print("   " + x[:300])
    rc = _touch_after_edit(assert_canonical(a.path), a.no_touch) if ok else 0
    return 2 if bad else rc


@_board_write_command("answer")
def cmd_answer_multi(a):
    checks = _CURRENT_WRITE.get()
    acks = _answer_acks(a.ack)
    if getattr(a, "withdraw", None) is not None:
        die("--withdraw 一次撤一张卡，请只给一个 --ack")
    if getattr(a, "why_row", None):
        checks.add("answer-batch-why-row", "一次收多张卡时请逐张用 --why-row")
    if getattr(a, "row", None):
        checks.add("answer-batch-row", "一次收多张卡(--ack %s)时不能用 --row —— 每张卡按它自己链着的行改;要点名行就一张张收" % ",".join(acks))
    why_rows = _answer_arguments(a, checks)
    if getattr(a, "why_row", None) or getattr(a, "row", None):
        checks.defer("逐张核对卡与关联行")
        checks.finish()
    p = checks.board(a.path)
    src = out = checks.read_board(p)
    planned = []
    for ack in acks:
        b = argparse.Namespace(**(vars(a) | {"ack": ack, "no_touch": True}))
        card_checks = _WriteChecks("answer", b, preview=True)
        page, after, notes = _answer_plan(b, p, out, why_rows, card_checks)
        if card_checks.items:
            for key, problem in card_checks.items:
                checks.add(key, "%s：%s" % (ack, problem))
        else:
            planned.append((b, page, out, notes))
            out = after
    if checks.items:
        checks.defer("重验整组卡一起收掉后的关联行")
        try:
            checks.finish()
        except SystemExit as e:
            return e.code
    checks.before_write()
    checks.restore()
    _write_back(p, src, out, pending=False)
    checks.commit("✓ 已收卡:%s" % ",".join(acks), out)
    for b, page, before, notes in planned:
        _answer_clear_queue(b, p, before)
    rc = _touch_after_edit(p, a.no_touch)
    for b, page, before, notes in planned:
        if _answer_left_on_board(p, b.ack, src, out):
            rc = 3
            continue
        _answer_after_write(b, p, page, before, notes)
        _answer_finish_hints(b, p, notes)
    return rc



@_board_write_command("answer")
def cmd_answer(a):
    """⭐ 0930 #5516:他答了「要你的」里一张卡 ⇒ 一行拿掉卡、对应的行改成不再等他(见 _answer_apply)。"""
    checks = _CURRENT_WRITE.get()
    if getattr(a, "withdraw", None) is not None:
        return _answer_withdraw(a, checks)
    why_rows = _answer_arguments(a, checks)
    p = checks.board(a.path)
    s = checks.read_board(p)
    page, out, notes = _answer_plan(a, p, s, why_rows, checks)
    checks.before_write()
    checks.restore()
    _write_back(p, s, out, pending=False)
    checks.commit("✓ 已收卡:%s" % a.ack, out)
    _answer_clear_queue(a, p, s)
    rc = _touch_after_edit(p, a.no_touch)
    if _answer_left_on_board(p, a.ack, s, out):
        return 3
    _answer_after_write(a, p, page, s, notes)
    _answer_finish_hints(a, p, notes)
    return rc


def _answer_withdraw(a, checks):
    allowed = {"cmd", "command", "path", "ack", "withdraw", "no_touch"}
    if any(key not in allowed and value for key, value in vars(a).items()):
        die("--withdraw 只和 --ack / --no-touch 同用")
    reason = " ".join(a.withdraw.split())
    if not reason:
        die("--withdraw 要写为什么撤")
    p = checks.board(a.path)
    src = checks.read_board(p)
    try:
        out, notes = _answer_apply(src, a.ack, None, withdraw_page=os.path.basename(p))
    except (OSError, ValueError) as e:
        if not checks.preview:
            print("✗ 没撤掉:%s" % e, file=sys.stderr)
            checks.show_path_messages()
            _board_write_event(p, "answer", ["withdraw"], detail={"withdraw": str(e).splitlines()[0][:60]})
        raise SystemExit(2)
    checks.before_write()
    checks.restore()
    _write_back(p, src, out, pending=False)
    checks.commit("✓ 已收卡:%s" % a.ack, out)
    print("  已撤卡，原因:%s" % reason)
    for note in notes:
        print("  " + note)
    rc = _touch_after_edit(p, a.no_touch)
    return 3 if _answer_left_on_board(p, a.ack, src, out) else rc


def _answer_arguments(a, checks):
    _prose_args_problem("answer", a, report=checks.add)
    if isinstance(getattr(a, "why_add", None), str):     # 1105 选品:`--why-add "句子"` 也认(= --why "句子" --why-add);放最前:后面的闸要读 --why
        if a.why:
            checks.add("why-add-conflict", "--why 和 --why-add \"句子\" 给了两句 —— 只留一个\n  ⇒ 什么都没写。")
        else:
            a.why, a.why_add = a.why_add, True
    why_rows = {}
    for arg in getattr(a, "why_row", None) or []:
        row_ack, sep, why = arg.partition("=")
        if not sep or not _ACK_OK_RE.fullmatch(row_ack) or not why.strip() or row_ack in why_rows:
            checks.add("why-row-format", '--why-row 要写成 行号="一句现状"，每个行号只写一次\n  ⇒ 什么都没写。')
            continue
        why_rows[row_ack] = why
    if why_rows and (a.done or a.no_row):
        checks.add("why-row-mode", "--why-row 不和 --done / --no-row 同用\n  ⇒ 什么都没写。")
    _prose_path_problem([("--why-row", list(why_rows.values()))], report=checks.add)
    if getattr(a, "why_add", False) and getattr(a, "why_replace", False):
        checks.add("answer-why-mode", "--why-add 和 --why-replace 只能给一个")
    if (getattr(a, "why_add", False) or getattr(a, "why_replace", False)) and not a.why:
        checks.add("answer-why-missing", "--why-add / --why-replace 要和 --why 一起用")
    _answer_input_problems(a.res, a.why, a.done, a.row, checks.add)
    return why_rows


# 依据: 11-23 核实报告 ①；交验收时显式交代对方那半。
_OTHER_HALF_RE = re.compile(r"通知|让[^，。！？；;\n]*?也|另一半|那半|那份|交给(?:他|她|某人)|也做|也搞")
# 依据: 11-23 核实报告 ① 与现有 _ASK_OTHER_RE 里的人名；等待行也提供本板的人名。
# 依据: 本机真板写真名,对外包由 pack 脚本豁免。
_OTHER_HALF_NAMES = re.compile(_name_pattern(BP.other_names(), word_boundary=True) + r"@[\w-]+")
# 未验证: 未在板上出现过的人名，用紧邻状态词的常见姓氏、称呼或英文名识别。
_OTHER_NAME_TOKEN = r"(?:[小老阿][一-龥]{1,2}|[李王张刘陈杨黄赵周吴徐孙马朱胡林何高郭郑梁谢宋唐许韩邓冯于董程曹袁赖汪蔡罗苏叶卢方蒋沈杜][一-龥]{1,2}|[A-Z][a-z]+)"
# 依据: 11-23 核实报告 ①，提问行回答点了人名并说没做、还没或过期。
_OTHER_NAMED_STATUS_RE = re.compile(r"(?<![一-龥A-Za-z])" + _OTHER_NAME_TOKEN + r"\s*(?=还没|没做|(?:已)?过期)")
# 依据: 11-23 核实报告 ① 的收卡关键词。
_OTHER_CHASE_RE = re.compile(r"照卡追|一起追了|让他|等\s*([一-龥]{2,4}|[A-Za-z][A-Za-z._-]*)\s*回(?=$|[\s，。！？；、,.!?;]|复|话|来|信|消息|答|结果)")
# 依据: 11-23 核实报告 ① 的提问行回答判词。
_OTHER_UNDONE_RE = re.compile(r"没做|还没|过期")


def _unquoted_review_text(value):
    return re.sub(r"「[^」]*」|《[^》]*》", " ", _html_unescape_attr(str(value or "")))


# 依据: #f4c4；会话内的定时和排队需要交验收的人主动登记。
_OTHER_HALF_SCHEDULES = "定时 / 排队 / 首跑 / 等换上 也算另一半。"


def _codex_run_json(path):
    try:
        with open(path, encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return {}
    return data if isinstance(data, dict) else {}


def _running_codex_rows(board, rows):
    """返回这些板行还在跑的运行目录。只认 codex-run.sh --row 的显式关联。"""
    targets = set(rows)
    root = BP.state("codex-runs")
    matches = {}
    for folder in sorted(glob.glob(os.path.join(root, "*"))):
        meta = (_codex_run_json(os.path.join(folder, "meta.json"))
                or _codex_run_json(os.path.join(folder, "meta.pending.json")))
        ref = meta.get("board_row")
        if not isinstance(ref, dict):
            continue
        row, path = ref.get("row"), ref.get("board")
        if not isinstance(row, str) or row not in targets or not isinstance(path, str) or not path:
            continue
        if os.path.isabs(path):
            if os.path.realpath(path) != os.path.realpath(board):
                try:
                    if not os.path.samefile(path, board):
                        continue
                except OSError:
                    continue
        elif path != os.path.basename(board):
            continue
        if _codex_run_json(os.path.join(folder, "summary.json")).get("outcome"):
            continue
        matches.setdefault(row, []).append(folder)
    return matches


def _split_running_codex_rows(src, out, board, rows):
    active = _running_codex_rows(board, rows)
    if not active:
        return out
    archive = _archive_path(board)
    taken = []
    try:
        with open(archive, encoding="utf-8") as fh:
            taken = re.findall(r'\bdata-ack="([^"]*)"', fh.read())
    except FileNotFoundError:
        pass
    for row, folders in active.items():
        a, b, z = _row_span(src, row)
        title = _html_unescape_attr(_row_facts(src[a:b], src[b:z])["title"]) + " 剩下的:等后台跑完"
        waiting = "、".join(folders)
        if any(f["st"] == "watch" and _html_unescape_attr(f["title"]) == title
               and _html_unescape_attr(f["wait_for"]) == waiting
               for f in (_yours_zone_rows(out) or {}).get("facts", [])):
            continue
        out, _, _ = _row_new(
            out, title, status="watch", say="后台任务还在跑，结束后核结果。", eta=time.strftime("%m-%d"),
            wait_for=waiting, taken=taken, need_wait=True, path_hint=board)
    return out


def _review_other_half_problem(value, texts, answer, wait_names):
    named = (_OTHER_HALF_NAMES.search(answer) or _OTHER_NAMED_STATUS_RE.search(answer)
             or any(name and name in answer for name in wait_names))
    required = any(_OTHER_HALF_RE.search(_unquoted_review_text(t)) for t in texts) or (
        _OTHER_UNDONE_RE.search(answer) and named)
    if value is None and not required:
        return None
    choice = re.fullmatch(r"(row|done|none):([^\r\n]*\S[^\r\n]*)", value or "")
    if choice:
        return _review_other_half_ref_problem(choice[2].strip()) if choice[1] == "row" else None
    return ('交验收要写对方那半去哪了，三选一:--other-half "row:<跟进行号或卡号>" / '
            '--other-half "done:<对方做完的证据>" / --other-half "none:<为什么不用跟>"。'
            + _OTHER_HALF_SCHEDULES)


def _review_other_half_ref_problem(value):
    ref = value.removeprefix("#")
    if _ROT_ACK_RE.fullmatch(ref) or MACHINE_ROW_ACK_RE.fullmatch(ref) or _WAIT_HIM_CARD_RE.fullmatch(ref):
        return None
    try:
        _ask_card_chip(value)
    except ValueError:
        return ('--other-half 的 row: 只填跟进行号或卡号，例如 \'row:r1123-abcd\'、'
                '\'row:ask-1234abcd\' 或 \'row:#4122\'。')
    return None


def _review_other_half_done_problem(evidence, report=None):
    """done: 后的证据会显示在卡上，按 --got 的文字规则检查。"""
    if not evidence.strip():
        return None
    field = "--other-half done:"
    fields = [(field, evidence)]
    problem = _prose_path_problem([("--other-half", evidence)], report=report, value_prefix="done:")
    if problem:
        return problem
    for check in (_plain_problem, _board_ref_problem):
        problem = check(fields, report=report)
        if problem:
            return problem
    return _review_got_problem([evidence], 1, report=report, field=field)


def _answer_other_chase_problem(src, a, path):
    no_followup = getattr(a, "no_followup", None)
    if no_followup is None and not a.why:
        return None
    text = " ".join(str(v or "") for v in (no_followup, a.why, a.res if a.why else ""))
    hits = list(_OTHER_CHASE_RE.finditer(text))
    if not hits:
        return None
    facts = (_yours_zone_rows(src) or {}).get("facts", [])
    candidates = {f["ack"]: _stuck_who(f.get("wait_for")) for f in facts if f.get("open")}
    names = {m[1] for m in hits if m[1] and not re.fullmatch(r"周[一二三四五六日天]", m[1])}
    if not names and all(m[1] for m in hits):
        return None
    followup = getattr(a, "followup", None)
    if followup and any(c["id"] == followup and not c["machine"] for c in _yours_report(src, "")["cards"]) and followup not in _answer_acks(a.ack):
        return None
    card = next((m.group(0) for m in _yours_cards(src) if _card_attr(m.group(0), "data-ack") == a.ack), "")
    own_rows = set(re.findall(r'href="#row-([^"]+)"', card))
    own_rows.update((_card_attr(card, "data-accept-rows") or "").split())
    own_rows.add(a.row)
    context = _html_unescape_attr(re.sub(r"<[^>]+>", " ", card)) + " " + text
    from pathlib import Path
    try:
        said = Path(BP.web_root(), "_said", Path(path).stem + ".json")
        since = _parse_stamp(json.loads(said.read_text(encoding="utf-8")).get("t"))
    except (OSError, ValueError, AttributeError):
        since = None
    waiting = set()
    for f in facts:
        if not f.get("open") or f["ack"] in own_rows:
            continue
        at = _parse_stamp(f.get("wait_since")) or _parse_stamp(f.get("created")) or _parse_stamp(f.get("fp0"))
        who = candidates[f["ack"]]
        if who and since and at and at >= since:
            waiting.add(who)
    if names:
        covered = all(any(name == who or name.endswith(who) or who.endswith(name) for who in waiting) for name in names)
    else:
        mentioned = [m[0] for m in _OTHER_HALF_NAMES.finditer(context)]
        covered = any(who in context or any(who.endswith(name) for name in mentioned) for who in waiting)
    if covered:
        return None
    return ('收卡后还要追对方，先用 --followup <续卡号>，或本轮另开 '
            'row --new --wait-for "等谁 / 等什么" 的跟进行，再收卡。')


def _answer_plan(a, p, s, why_rows, checks):
    _answer_page = getattr(a, '_answer_page', None) or os.path.basename(p)
    if a.done:
        _head, _end = _yours_zone_span(s)
        _cards = _yours_cards(s[_head.end():_end]) if _head else []
        _card = next((c.group(0) for c in _cards if re.search(r'\bdata-ack="%s"' % re.escape(a.ack), c.group(0).split('>', 1)[0])), '')
        if not re.search(r'\bdata-accept="1"', _card.split('>', 1)[0]) and not getattr(a, '_selftest_done', False):
            checks.add("answer-done-card", '普通卡不能直接标做完。' + _REVIEW_EXIT + '\n  ⇒ 什么都没写。')
    # 1020 晚(Harness 扫 + AI平台 19:49 实撞):他一分钟前刚在这张卡上答了、你还没看过,就把卡收了 ⇒ 他的回答没人照办。
    #   ⇒ 先看过再收:`board.py answers <板>`(他每次发话时钩子也会贴进来)印过这一条才放行;确定不用看加 --force。
    _uv = None if getattr(a, "force", False) else _answer_unseen(_answer_page, a.ack)
    if _uv is not None and not (_ans_submitted(_uv) or _ans_kept(_uv)):
        checks.add("answer-in-progress", "✗ 他在这张卡上还在写、没交(上次改于 %s)—— 半截的回答别照办,也别收卡。\n"
            "   ⇒ 他点「交给这条线」或停手(只点选项 1 分钟 / 写了字 10 分钟)后,`board.py answers %s` 会列出来,那时再办再收。\n"
            "   ⇒ 确定这张卡跟他写的无关、现在就要收 ⇒ 加 --force。\n   ⇒ 什么都没写。"
            % (_ans_when(_uv.get("ts")), __import__("shlex").quote(p)))
    elif _uv is not None:
        _un = re.sub(r"\s*\n\s*", " ⏎ ", str(_uv.get("note") or "").strip())
        checks.add("answer-unseen", "✗ 他在这张卡上答过、你还没看过(答于 %s):选了「%s」%s\n"
            "   ⇒ 先照他这条办(他要的可能和你 --res 写的不一样),再收卡。\n"
            "   ⇒ 「看过」= 跑一次 `board.py answers %s`(印出来的那几条就记成看过,之后这条 answer 原样再跑就收得掉);\n"
            "     这条已经照办了、只是没经过 answers ⇒ 加 --force。\n   ⇒ 什么都没写。"
            % (_ans_when(_uv.get("ts")), re.sub(r"\s+", " ", str(_uv.get("choice") or "")).strip() or "没选",
               ";补充:" + _un if _un else "", __import__("shlex").quote(p)))
    try:
        _ar = _answers_raw(_answer_page) or {}
    except (OSError, ValueError):              # 答案文件坏了 / 读不了 ⇒ 只按 --res / --why 判(坏文件由后面 _answers_drop 照旧出声)
        _ar = {}
    checks.add("answer-other-chase", _answer_other_chase_problem(s, a, p))
    _sd = _answer_selfdo_problem(s, a, _ar)
    if _sd:
        checks.add("answer-followup", "%s\n  ⇒ 什么都没写。" % _sd)
    out, notes = s, []
    try:
        out, notes = _answer_apply(s, a.ack, a.res, row=a.row, done=a.done, why=a.why, no_row=a.no_row, confirm_done=True,
                                   summary=getattr(a, "sum", None), need_sum=True, why_rows=why_rows,
                                   why_mode="add" if getattr(a, "why_add", False) else "replace" if getattr(a, "why_replace", False) else None,
                                   report=checks.add)
        if a.done and not a.no_row:
            import html as _hb
            _bdrop = _accept_is_drop(s, a.ack)
            for _bx in _accept_batch_rows(s, a.ack):
                if _bx == a.row:
                    continue
                _ra, _rb, _rz = _row_span(out, _bx)
                _bt = _hb.unescape(_row_facts(out[_ra:_rb], out[_rb:_rz]).get('title') or '')
                _bs = (('不做了: ' if _bdrop else '验收通过: ') + re.sub(r'[^\u4e00-\u9fff\w ]', ' ', _bt)).strip()[:60]
                if _sum_problem(_bs):
                    _bs = '交代的这件事项商定不做了' if _bdrop else '验收通过: 你交代的这件事'
                out, _ = _row_apply(out, _bx, status='done', say=a.res, summary=_bs, need_sum=True, no_you=True)
                notes.append('同一张验收卡上的行 %s 一起收了' % _bx)
            if getattr(a, "_auto_accept", False):
                rows = dict.fromkeys([a.row, *_accept_batch_rows(s, a.ack)])
                out = _split_running_codex_rows(s, out, p, rows)
    except ValueError as e:
        checks.add("answer-edit", "%s\n  ⇒ 什么都没写。" % str(e).replace("<板>", __import__("shlex").quote(p)))
    return _answer_page, out, notes


def _answer_left_on_board(path, ack, original=None, planned=None):
    """写盘之后 touch 或别的进程可能再次改板；清回答记录之前核对卡与标记。"""
    try:
        with open(path, encoding="utf-8") as fh:
            src = fh.read()
    except (OSError, UnicodeError) as e:
        print("  ⛔ 已写，但复核板失败，保留回答记录(退出码 3):%s" % e)
        return True
    out = _strip_collected_card(src, ack)
    if out == src:
        return False
    if src == original and planned is not None:
        # 如果盖戳完整退回旧版，同时恢复收卡时原子写入的行状态。
        out = planned
    if _strip_collected_card(out, ack) != out:
        print("  ⛔ 已写，但卡或行标记仍在，保留回答记录(退出码 3)")
        return True
    try:
        _write_back(path, src, out, pending=False)
    except (OSError, SystemExit) as e:
        print("  ⛔ 卡或行标记仍在，保留回答记录(退出码 3)：%s" % e)
        return True
    print("  ✓ 收卡复核发现残留，已清掉卡和行标记：%s" % ack)
    return False


def _strip_collected_card(src, ack):
    head, end = _yours_zone_span(src)
    card = ""
    if head:
        body = src[head.end():end]
        matches = [c for c in _yours_cards(body) if _card_attr(c.group(0), "data-ack") == ack]
        if matches:
            card = matches[0].group(0)
            for c in reversed(matches):
                tail = c.end() + (body[c.end():c.end() + 1] == "\n")
                body = body[:c.start()] + body[tail:]
            header = re.sub(r'(<span class="n">)[^<]*(</span>)',
                            lambda m: "%s%d 件%s" % (m[1], len(_yours_cards(body)), m[2]), head.group(), count=1)
            src = src[:head.start()] + header + body + src[end:]
    return _clear_card_rows(src, card, ack, review_links=bool(card))[0]


def _collected_card_errors(src, page):
    head, end = _yours_zone_span(src)
    live = {_card_attr(c.group(0), "data-ack") for c in _yours_cards(src[head.end():end])} if head else set()
    live.update(f["you_card"] for f in (_yours_zone_rows(src) or {}).get("facts", []) if f["you_card"])
    if not live:
        return []
    collected = set()
    try:
        with open(_answers_consumed_file(), encoding="utf-8") as fh:
            for line in fh:
                try:
                    rec = json.loads(line)
                    if isinstance(rec, dict) and rec.get("page") == page and rec.get("id") in live:
                        collected.add(rec["id"])
                except (ValueError, TypeError):
                    continue
    except OSError:
        pass
    return ["卡已答 / 已收但卡或行标记还挂着：%s" % ack for ack in sorted(collected)]


def _answer_after_write(a, p, _answer_page, s, notes):
    for x in notes:
        print("  " + x)
    # 1008:他的回答原文在板上不再有落点(以前写进那一行的现状,现在那一句由作者写)⇒ 印出来,提醒留痕。--done 时它就是那一行的结论,不用印。
    if not a.done and not any("没链到「你交代的」里的行" in x for x in notes):
        print("  他的回答(板上不留这句,要留痕就写进卡号或账本):%s" % re.sub(r"\s+", " ", str(a.res)).strip())
    # 1006:他在板上点的那条回答(看板服务记的)到这里就消化完了 ⇒ 一起清掉。没有记录就跳过;清不掉只出一声,不影响上面的结果。
    _dr = _answers_drop(_answer_page, a.ack)
    if _dr is None:
        # 对话内答的卡也需要留下已收凭证，供 lint 查后来复活的旧卡。
        try:
            log = _answers_consumed_file()
            os.makedirs(os.path.dirname(log), exist_ok=True)
            with open(log, "a", encoding="utf-8") as fh:
                fh.write(json.dumps(dict(page=_answer_page, id=a.ack, dropped=datetime.datetime.now().isoformat()),
                                    ensure_ascii=False) + "\n")
        except OSError as e:
            print("  ⚠ 已收卡，收卡记录没能写入：%s" % e)
    if _dr is not None:
        # 1020:原文整条印出来 —— 收卡时他可能刚答过、你还没看(AI平台 v1.9 报的那次就是这样丢了一段补充)
        _dn = re.sub(r"\s*\n\s*", " ⏎ ", str(_dr.get("note") or "").strip())
        print("  ✓ 他在板上答的那条记录已清掉;原文:选了「%s」%s(答于 %s)"
              % (re.sub(r"\s+", " ", str(_dr.get("choice") or "")).strip() or "没选",
                 ";补充:" + _dn if _dn else "", _ans_when(_dr.get("ts"))))
        print("    ⇒ 核一眼你的 --res 是不是照这条办的;不是就改卡对应的行。原文另存在 %s" % _answers_consumed_file())
    # 1020:卡连着方案页的一道题 ⇒ 那一题的记录标成已消化(⛔ 不删:方案页上要照旧显示他的答案)
    _lm = re.search(r'<article\b[^>]*\bdata-ack="%s"[^>]*>' % re.escape(a.ack), s)
    _lq = re.search(r'\bdata-deep-q="([^"]+)"', _lm.group(0)) if _lm else None
    _lp = re.search(r'\bdata-deep-page="([^"]+)"', _lm.group(0)) if _lm else None
    if _lq and _lp:
        try:
            _d = _answers_raw(_lp.group(1))
            if _d and isinstance(_d.get(_lq.group(1)), dict):
                _d[_lq.group(1)]["copied"] = datetime.datetime.now().strftime("%Y-%m-%dT%H:%M:%S")
                _answers_save(_lp.group(1), _d)
                print("  方案页 %s 里同一题(%s)标成已消化" % (_lp.group(1), _lq.group(1)))
        except (OSError, ValueError) as e:
            print("  ⚠ 方案页那一题没标成已消化(%s: %s)—— 不影响结果;`answers --mark` 可补" % (type(e).__name__, e))


def _answer_clear_queue(a, p, src):
    # 1021:卡带卡号 #N、.queue.json 里 #N 还标着要他 ⇒ 盖戳前一并拿掉(否则机器卡接着挂)。
    _ca = re.search(r'<article\b[^>]*\bdata-ack="%s"[^>]*>.*?</article>' % re.escape(a.ack), src, re.S)
    _cn = re.search(r'<span class="chip id">#(\d+)</span>', _ca.group(0)) if _ca else None
    if _cn and not getattr(a, "keep_you", False):
        if _queue_drop_you(p, _cn.group(1)):
            print("  ✓ .queue.json 里 #%s 的「要你」一并拿掉(他已在这张卡上答过;还要他再定 ⇒ 加回 you,或下次用 --keep-you)" % _cn.group(1))


def _answer_finish_hints(a, p, notes):
    # 1007 F:这张卡没挂行(`ask --row` 挂的、按卡号找到行的都不算;--no-row 是作者明说不动行)⇒ 提示一句,印在最后免得被 touch 的输出淹掉
    if any("没链到「你交代的」里的行" in x for x in notes):
        for _l in _answer_rows_hint(p, open(p, encoding="utf-8").read()):
            print(_l)
    if not a.done:                                   # 1008 D:只提示,不改退出码
        for _l in _answer_later_hint(a.res, p):
            print(_l)
    if a.done:
        _dir_stale_tail(p)                           # 1021:大方向久没核、下面又做完一件 ⇒ 排在最后提醒(见 _dir_stale)


# ── 1021(负责人经 示例项目-CI/AI Review v6.9 转):线合并 / 改名 / 结束后,板怎么退场 ─────────
#   原来只有 `help retire` 一句「handoff 时顺手判」,没有命令 ⇒ 旧板撤成指针后永远留在 .claude/boards/、进索引和同侪条。
#   负责人原话大意:很多板对应的线已经不在了,这些板是不是该直接归档?
#   ⇒ `retire <板> --to <去向>`:板和它的 .queue.json / 留档 / .bak 挪进同目录 `_retired/`(⛔ 挪不删,能搬回来),
#     走板的扫描不进子目录 ⇒ 自动离开索引和同侪条;8777 上留一页「这块板已退场 → 去向」,他开着的面板不会变空白。
#   ⇒ `retire --scan`:列出本机每块板对应的会话还在不在、多久没动、还有没有没做完的 —— 只列不动,撤哪块由他定。

# ⭐ 1117 电商-基建 #a7c3:子线停下等人时标题按规矩改成「子线·X(等谁)」,要他进去亲手配合的叫「子线·X·要你进来」
#   (rules/common/session-lifecycle.md 命名规则),板名仍是「子线-X」⇒ 比标题前先去掉这两种尾巴。不去的后果:
#   改了名的子线被判成「子线会话不在」(主线板 lint 一直红),他在主线板上答的卡也叫不到它。
def _title_tail_cut(x):
    """去掉标题末尾的「(等…)」(全角 / 半角括号)和「·要你进来」。只动末尾;括号里不是「等」开头的不动。纯函数。"""
    x = re.sub(r"\s*[(\uff08]\s*等[^()\uff08\uff09]*[)\uff09]\s*$", "", str(x or ""))
    return re.sub(r"\s*[·・]\s*要你进来\s*$", "", x)


def _title_norm(x):
    """与 hooks/board-pane-check.js 的 boardByTitle 同一套:去掉末尾「(等…)」「·要你进来」、去掉「 vX.Y」及其后、去掉「-」和空格、小写。"""
    return re.sub(r"[-\s]+", "", re.sub(r"\s+v\d+(\.\d+)*.*$", "", _title_tail_cut(x), flags=re.I)).lower()


def _title_strip(x):
    """第二档:再去掉项目前缀(「示例项目-状态板」↔「状态板」)。"""
    return re.sub(r"[-\s]+", "", re.sub(r"^[^-\s]+-", "", re.sub(r"\s+v\d+(\.\d+)*.*$", "", _title_tail_cut(x), flags=re.I))).lower()


def _board_sessions(board_name, sessions):
    """这块板对得上的会话(先比全名,对不上再比去掉项目前缀的);sessions = [{title, archived, last}]。纯函数。"""
    b = board_name[:-5] if board_name.endswith(".html") else board_name
    hit = [x for x in sessions if _title_norm(x.get("title")) == _title_norm(b)]
    if not hit:
        hit = [x for x in sessions if _title_strip(x.get("title")) == _title_norm(b) or _title_norm(x.get("title")) == _title_strip(b)
               or (_title_strip(x.get("title")) == _title_strip(b) and _title_strip(b))]
    return hit


# ⭐ 1115 大扫除 C5:退场扫描 / 到点该追的「认不出主人」只认 Claude 会话 ⇒ Codex 桌面线程建的板(例:~/.claude/boards/Claude-申诉与订阅.html,
#   主人是 cwd=~ 的 Codex 线程)一直被当成没主。⇒ 认主人时加扫 ~/.codex/sessions/**/rollout-*.jsonl:
#   只读、只看最近 CODEX_OWNER_DAYS 天改过的、新的先看;转录里出现板文件名(原样或 JSON 转义)就算有主。BOARD_CODEX_SESSIONS 可改目录(自检指到空目录)。
# 依据: 任务书 sweep-1115/C-brief.md 第 5 条「只看最近 30 天」
CODEX_OWNER_DAYS = 30
# 依据: 11-15 实测本机 30 天内 rollout 4 个共 35MB;封顶防目录长大后一轮读几 GB(到点该追每 10 分钟可能跑一次)
CODEX_OWNER_MAX_FILES = 300


def _codex_sessions_root():
    return os.path.expanduser(os.environ.get("BOARD_CODEX_SESSIONS") or os.path.join("~", ".codex", "sessions"))


def _codex_board_owners(names, root=None, now=None, days=CODEX_OWNER_DAYS):
    """哪些板在 Codex 桌面线程的转录里出现过 ⇒ {板文件名: {sid, cwd, mtime, file}}(每块板取最近那份转录)。只读,读不到 ⇒ {}(⛔ 不抛)。"""
    names = [n for n in dict.fromkeys(names or []) if n]
    if not names:
        return {}
    root = root or _codex_sessions_root()
    now = time.time() if now is None else now
    cut = now - days * 86400
    files = []
    for f in glob.glob(os.path.join(glob.escape(root), "**", "rollout-*.jsonl"), recursive=True):
        try:
            mt = os.path.getmtime(f)
        except OSError:
            continue
        if mt >= cut:
            files.append((mt, f))
    files.sort(reverse=True)
    pat = {n: (n, json.dumps(n)[1:-1]) for n in names}
    out = {}
    for mt, f in files[:CODEX_OWNER_MAX_FILES]:
        left = [n for n in names if n not in out]
        if not left:
            break
        try:
            with open(f, encoding="utf-8", errors="replace") as fh:
                data = fh.read()
        except OSError:
            continue
        hit = [n for n in left if any(p in data for p in pat[n])]
        if not hit:
            continue
        meta = {}
        try:
            first = json.loads(data.split("\n", 1)[0])
            meta = first.get("payload") if isinstance(first, dict) and isinstance(first.get("payload"), dict) else {}
        except ValueError:
            pass
        for n in hit:
            out[n] = {"sid": str(meta.get("id") or meta.get("session_id") or ""), "cwd": str(meta.get("cwd") or ""), "mtime": mt, "file": f}
    return out


def _unowned_minus_codex(groups, cx):
    """到点该追「认不出主人」的组里,板全在 Codex 转录里认到主的拿出来。返回 (还是认不出的, 归 Codex 的)。纯函数。"""
    left, own = [], []
    for k, g in groups:
        names = {os.path.basename(bp) for bp, _f, _w in g["items"]}
        (own if names and all(n in cx for n in names) else left).append((k, g))
    return left, own


def _retire_classify(board, sessions, now, codex=None):
    """纯函数:一块板 → (结论, 说明)。board = {name, age_days, open_rows, cards};now = 时间戳(秒)。
    结论:live(有没归档、3 天内动过的会话)· stale(对得上的会话都归档了 / 很久没动)· nobody(一个会话都对不上 —— 可能是 Codex 线或改过名)。"""
    if (board.get("age_days") or 0) <= 3:
        return "live", "板 %d 天内有人写过" % max(1, board.get("age_days") or 0)
    hit = _board_sessions(board["name"], sessions)
    live = [x for x in hit if not x.get("archived") and now - (x.get("last") or 0) <= 3 * 86400]
    if live:
        return "live", "在用:%s" % "、".join(sorted({x["title"] for x in live})[:3])
    if codex:                                  # 1115 大扫除 C5:Claude 会话对不上 / 都归档了,Codex 线程最近 30 天的转录里提到这块板 ⇒ 算有主
        return "live", "Codex 线程在用(cwd %s,%d 天前的转录里提到这块板)" % (
            codex.get("cwd") or "没记", max(0, int((now - (codex.get("mtime") or now)) // 86400)))
    left = []
    if board.get("open_rows"):
        left.append("没做完 %d 行" % board["open_rows"])
    if board.get("cards"):
        left.append("「要你的」%d 张" % board["cards"])
    tail = (";还有" + "、".join(left) + " ⇒ 先搬去接手的板") if left else ";没有未完成的 ⇒ 可直接退场"
    if hit:
        newest = max(hit, key=lambda x: x.get("last") or 0)
        return "stale", "对得上的会话「%s」%s,板 %d 天没动%s" % (
            newest.get("title"), "已归档" if newest.get("archived") else "%d 天没动" % ((now - (newest.get("last") or 0)) // 86400),
            board.get("age_days") or 0, tail)
    return "nobody", "找不到对得上的会话(可能是 Codex 线或线改了名),板 %d 天没动%s" % (board.get("age_days") or 0, tail)


def _session_registry(root=None):
    """本机 Claude 会话注册表里每个会话的 {title, archived, last(秒)}。同一会话多份副本(切过账号)⇒ 取最新那份。读不到 ⇒ []。"""
    out = {}
    root = root or BP.claude_sessions_root()
    for f in glob.glob(os.path.join(glob.escape(root), "*", "*", "local_*.json")):
        try:
            d = json.load(open(f, encoding="utf-8"))
            mt = os.path.getmtime(f)
        except (OSError, ValueError):
            continue
        if not isinstance(d, dict):
            continue
        sid, last = d.get("sessionId") or f, (d.get("lastActivityAt") or 0) / 1000.0
        # ⭐ 1109:归档不改 lastActivityAt ⇒ 活动时间打平时只看活动时间会随机取到旧账号的冻结副本,改按文件修改时间再比一次
        key = (last, mt)
        if sid not in out or key > out[sid]["_key"]:
            out[sid] = {"title": d.get("title") or "", "archived": bool(d.get("isArchived")), "last": last, "_key": key}
    return list(out.values())


def _board_open_counts(src, name):
    try:
        y = _yours_zone_rows(src) or {}
        rows = len([f for f in y.get("facts", []) if f.get("ack") and f["open"]])
        cards = len(_yours_report(src, name)["cards"])
        return rows, cards
    except Exception:                     # 老方言的板读不出 ⇒ 当成「不知道」,不当成 0
        return None, None


# ⭐ 1109 负责人(经 AI Harness #d4e8):「我可能每次开一条线就新加个状态板,那最后我再多个什么几百个状态板……因为这种线都是临时的」
#   ⇒ 单开的板机器收尾:会话都归档了、板上没有没做完的 ⇒ `retire --oneoffs` 挪进 _retired/(可恢复,重新开工自动搬回)。
#   ⛔ 不靠归档钩子:他在侧边栏点归档、App 自动归档都不经过 archive_session。认不出会话 / 还有没做完的 ⇒ 不动,只列出来。
_ONEOFF_BOARD_RE = re.compile(r"^(?:单开|子线)-(.+?)(?:\.html)?$")
_ONEOFF_TITLE_RE = re.compile(r"^(?:单开#\S+\s+|子线[·・])(.+)$")


# ⭐ 1109 负责人(截图:子线回复「要你点一下板上那张」,右边是空的 New tab):「他让我去打开状态板,但我根本就不知道在哪里打开」。
#   子线把要他处理的卡挂到父线的板上,他在子线里看不到 ⇒ 要他做的事只能挂子线自己的板。普通的进展行可以写父线的板。
def _subline_board_problem(path, sess):
    """本会话是子线,却要把要他处理的事写到别的板 ⇒ 返回要报的话;否则 None。纯函数。"""
    m = _ONEOFF_TITLE_RE.match(str((sess or {}).get("title") or "").strip())
    if not m:
        return None
    want = m.group(1).strip()
    b = _ONEOFF_BOARD_RE.match(os.path.basename(path))
    if b and _title_norm(b.group(1)) == _title_norm(want):
        return None
    par = os.path.basename(path) if not b else "<派它的线的板>.html"      # 1110 子线投影:建板顺手声明父板,卡会投影到父板上
    return ("你是子线「%s」,要他处理的事不能挂在「%s」:他在子线里看不到那块板,会找不到在哪打开(负责人 11-09)。\n"
            "   先想一下真要问他吗:派它的线答得了的,去问派它的线,不用问他。\n"
            "   ⇒ 建自己的临时板并声明派它的线:`python3 ~/.claude/scripts/board.py new 子线-%s --parent %s`,把卡挂那里 ——"
            "卡和一句进度会投影到〈%s〉上,他在那块板上就能答,不用送进面板。"
            % (want, os.path.basename(path), want, par, par))


# ⭐ 1110 子线投影(负责人 11-10 17:40 批方案页 subline-on-main-plan-1110「行,照图做」;他 16:30 的话:只看主线的板、只和主线说话):
#   子线开板时声明派它的那条线的板(父板);父板页面现取子板「要你的」里的真卡和一句进度画上去 —— 投影,不是写入:
#   父板文件里不落子线任何内容;一块板仍只有一个主人,lint / 过期提醒 / 收尾钩子都不变。
#   声明落在子板 <div class="wrap" data-parent="父板.html" data-parent-row="父板上的行">(sync 只换文件头、body 原样留 ⇒ 不丢)。
#   名单(父板 → 子板)由 boards-index.py 写进 boards-web/_children.json(照 _peers.json 的路数);子板退场 / 声明清掉 ⇒ 条目跟着没。
#   否过什么、为什么:
#   ⛔ 子线把卡写进父板的文件 —— 整文件读改写没有按板的锁;叫醒按最近写入者选人(子线写了就叫到子线头上);子线归档后留下没主的卡。
#   ⛔ 让子线直接收父板上的卡 —— 同上,一块板两个主人。
#   ⛔ 新做跨线总览页 —— 他只看正在进的那条线的板;总览在一次点击之外。
#   ⛔ 现存子线板不动:没声明的照旧;没有子板声明指向它的板,页面和 rows / recheck 输出一个字都不变(自检「1110 子线投影」守着)。
_PARENT_DECL_RE = re.compile(r'<div\s+class="wrap"([^>]*)>')


def _decl_unesc(v):
    return v.replace("&quot;", '"').replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&")


def _parent_decl(src):
    """子板上的父板声明 → (父板文件名 | None, 父板上的行 | None)。纯函数;注释 / 脚本里的不算(先蒙掉再找)。"""
    m = _PARENT_DECL_RE.search(_mask_noncontent(src or ""))
    if not m:
        return None, None
    a = m.group(1)
    p = re.search(r'\sdata-parent="([^"]*)"', a)
    r = re.search(r'\sdata-parent-row="([^"]*)"', a)
    pv = _decl_unesc(p.group(1)).strip() if p else ""
    rv = _decl_unesc(r.group(1)).strip() if r else ""
    return (pv or None), ((rv or None) if pv else None)


def _set_parent_decl(src, parent, row):
    """在 wrap 上写 / 改 / 摘父板声明(parent=None ⇒ 两个属性都摘)。没有 wrap ⇒ ValueError。纯函数。"""
    m = _PARENT_DECL_RE.search(_mask_noncontent(src or ""))
    if not m:
        raise ValueError('这块板找不到 <div class="wrap">,没处落父板声明')
    tag = src[m.start():m.end()]
    tag = _attr_set(tag, "data-parent", parent or None)
    tag = _attr_set(tag, "data-parent-row", (row or None) if parent else None)
    return src[:m.start()] + tag + src[m.end():]


def _child_title(name):
    """子板文件名 → 人读的名字「子线·X」/「单开·X」;不是子线 / 单开板 ⇒ 原名。"""
    n = os.path.basename(str(name or ""))
    m = _ONEOFF_BOARD_RE.match(n)
    if not m:
        return n
    return "%s·%s" % ("子线" if n.startswith("子线-") else "单开", m.group(1))


def _child_parent_path(child_path, parent, boards):
    """父板文件名 → 父板路径:只认活板(all_boards 里有的,退场的不在);同名不止一块时取和子板同目录的,分不出 ⇒ None。"""
    cands = [q for q in boards if os.path.basename(q) == parent]
    if len(cands) > 1:
        cd = os.path.dirname(os.path.realpath(child_path))
        cands = [q for q in cands if os.path.dirname(os.path.realpath(q)) == cd]
    return cands[0] if len(cands) == 1 else None


def _parent_problem(child_path, parent, row=None, boards=None):
    """声明父板前的检查 → (要报的话 | None, 父板路径 | None)。父板必须是活板、不能是子线 / 单开板;给了行就得在父板上找得到。"""
    name = os.path.basename(str(child_path or ""))
    if not _ONEOFF_BOARD_RE.match(name):
        return ("只有子线 / 单开的板能声明父板(板名要是「子线-…」或「单开-…」),%s 不是 —— 常驻线的板自己就是主线的板。" % name), None
    par = os.path.basename(_strip_file_scheme(str(parent or "").strip()))
    if not par:
        return "没给父板(派它的那条线的板文件名,如 电商-基建.html)", None
    if not par.endswith(".html"):
        par += ".html"
    if par == name:
        return "父板不能是它自己", None
    if _ONEOFF_BOARD_RE.match(par):
        return ("父板 %s 本身是子线 / 单开的板 —— 父板要写派它的那条常驻线的板(他只看那块)。" % par), None
    boards = all_boards() if boards is None else list(boards)
    hit = _child_parent_path(child_path, par, boards)
    if not hit:
        n = sum(1 for q in boards if os.path.basename(q) == par)
        if n:
            return ("父板 %s 有 %d 块同名、分不出是哪块 —— 子板建在父板那个仓里就分得出。" % (par, n)), None
        return ("父板 %s 找不到:不在任何仓的 .claude/boards/ 里(退场了、拼错了,或还没建)。" % par), None
    if row:
        try:
            _row_span(open(hit, encoding="utf-8", errors="replace").read(), row)
        except (OSError, ValueError) as e:
            return ("父板 %s 上找不到行 %s(%s)—— `board.py rows %s` 看行编号。" % (par, row, e, hit)), None
    return None, hit


def _child_parent_of(p):
    """子板 → 它声明的父板文件名;不是子线 / 单开板、没声明、读不到 ⇒ None。"""
    if not _ONEOFF_BOARD_RE.match(os.path.basename(str(p or ""))):
        return None
    try:
        src = open(p, encoding="utf-8", errors="replace").read()
    except (OSError, TypeError, ValueError):
        return None
    par = _parent_decl(src)[0]
    return par if par and not _ONEOFF_BOARD_RE.match(par) else None


def _set_parent_file(p, parent, row):
    """原地改子板文件上的声明(保 inode,同 cmd_ask 的写法)。没变 ⇒ False。"""
    src = open(p, encoding="utf-8").read()
    new = _set_parent_decl(src, parent, row)
    if new == src:
        return False
    with open(p, "r+b") as f:
        b = new.encode("utf-8")
        f.write(b)
        f.truncate()
    return True


def _children_map(boards=None):
    """{父板 realpath: [子板 dict(path, name, title, row, src)]} —— 只收声明了父板、父板是活的常驻线板的子线 / 单开板。"""
    boards = all_boards() if boards is None else list(boards)
    out = {}
    for q in boards:
        n = os.path.basename(q)
        if not _ONEOFF_BOARD_RE.match(n):
            continue
        try:
            src = open(q, encoding="utf-8", errors="replace").read()
        except OSError:
            continue
        par, row = _parent_decl(src)
        if not par or _ONEOFF_BOARD_RE.match(par):
            continue
        pp = _child_parent_path(q, par, boards)
        if not pp:
            continue
        out.setdefault(os.path.realpath(pp), []).append(dict(path=q, name=n, title=_child_title(n), row=row, src=src))
    for v in out.values():
        v.sort(key=lambda x: x["name"])
    return out


def _children_of(path, boards=None, cmap=None):
    m = _children_map(boards) if cmap is None else cmap
    rp = os.path.realpath(path)
    if rp in m:
        return m[rp]
    for k, v in m.items():
        try:
            if os.path.samefile(k, path):
                return v
        except OSError:
            pass
    return []


def _child_stall_rows(child_src, now=None, facts=None):
    """子板未完成行的停着原因;只取文字或状态的上次变化,核查时间不算动。纯函数。"""
    now = now or datetime.datetime.now()
    facts = facts if facts is not None else (_yours_zone_rows(child_src, today=now.date()) or {}).get("facts", [])
    out = []
    for f in facts:
        if not f.get("open"):
            continue
        reasons = []
        if f.get("chat_new") is not None:
            reasons.append("群里有新回复要重判")
        at, _ = _row_moved_at(f)
        edited = bool(f.get("txt") and f.get("txt_now") and f["txt"] != f["txt_now"])
        if f.get("st") in ("doing", "blocked") and not edited and at is not None and (now - at).total_seconds() > DOING_STALE_HOURS * 3600:
            reasons.append("超过24小时没动")
        if f.get("eta") and f["eta"] < now.date():
            reasons.append("预计日已过")
        _sod = _stall_overdue(f, now.date())
        if _sod:                                          # ⭐ 1117 tail-2:等外部满 7 个工作日叫过「换一条路」、次日没处理 ⇒ 同一条路投到父板,
            reasons.append("等了 %d 个工作日没结果" % _sod)   #   与他首屏「卡着的」同一句(kit stallOverdue / projStall);两样都到只写这句(它更久)
        elif _chase_overdue(f, now.date()):               # 叫过子线、次日还没处理 ⇒ 投影到父板(与 kit projStall 同一句)
            reasons.append("等你动但没挂卡" if f.get("you") in ROW_YOU_MINE else "叫过没人追")
        if reasons:
            out.append((f, reasons))
    return out


def _child_session_status(name, sessions, n_open):
    if not n_open:
        return ""
    verdict = _oneoff_verdict(name, sessions, n_open, 0)
    if verdict and verdict[0] == "nobody":
        return "子线会话不在"
    if verdict and verdict[0] == "move":
        return "子线会话已归档"
    return ""


def _child_stall_info(k, sessions, now=None):
    facts = (_yours_zone_rows(k["src"], today=(now or datetime.datetime.now()).date()) or {}).get("facts", [])
    opens = [f for f in facts if f.get("open")]
    rows = _child_stall_rows(k["src"], now, facts)
    status = _child_session_status(k["name"], sessions, len(opens))
    if status:
        rows = [(f, [status] + reasons) for f, reasons in rows]
        seen = {id(f) for f, _ in rows}
        rows += [(f, [status]) for f in opens if id(f) not in seen]
    return rows, status


def _child_stall_summary(rows):
    counts = {}
    for _, reasons in rows:
        for reason in reasons:
            counts[reason] = counts.get(reason, 0) + 1
    if not counts:
        return ""
    reason = max(counts, key=counts.get)
    return "%s %d 件" % (reason, counts[reason])


def _child_stall_errors(path, boards=None, cmap=None, sessions=None, now=None):
    kids = _children_of(path, boards, cmap)
    if not kids:
        return []
    sessions = _session_registry() if sessions is None else sessions
    out = []
    for k in kids:
        rows, status = _child_stall_info(k, sessions, now)
        if not rows:
            continue
        detail = "、".join("%s(%s)" % (_row_label(f), "、".join(reasons)) for f, reasons in rows)
        action = "主线收回自己做或子板退场" if status else "叫醒子线(SendMessage 给子线会话)或主线收回自己做"
        out.append("%s 有 %d 件停着:%s ⇒ %s" % (k["title"], len(rows), detail, action))
    return out


def _children_web(paths, mapping):
    """给 boards-index 写 _children.json:{父板 web 名: [{file, title, row}]};mapping = 板路径 → web 名(撞名时带仓名前缀)。"""
    rmap = {os.path.realpath(k): v for k, v in (mapping or {}).items()}
    out = {}
    sessions = _session_registry()
    for pp, kids in _children_map(paths).items():
        pw = rmap.get(pp) or os.path.basename(pp)
        out[pw] = []
        for k in kids:
            ent = {"file": rmap.get(os.path.realpath(k["path"])) or k["name"], "title": k["title"], "row": k["row"] or ""}
            facts = (_yours_zone_rows(k["src"]) or {}).get("facts", [])
            status = _child_session_status(k["name"], sessions, sum(1 for f in facts if f.get("open")))
            if status:
                ent["session"] = status
            # 投影只遍历带 data-status 的行,用同一顺序标出刚改过但还没记账的行。
            tagged = [f for f in facts if f.get("st") is not None]
            edited = [i for i, f in enumerate(tagged) if f.get("txt") and f.get("txt_now") and f["txt"] != f["txt_now"]]
            if edited:
                ent["edited"] = edited
            out[pw].append(ent)
    return out


def _child_counts(src):
    """子板此刻:没做完的行(带编号的)几件、「要你的」里等他的真卡几张(机器卡、占位卡不算)。"""
    y = _yours_zone_rows(src) or {}
    n_open = sum(1 for f in y.get("facts", []) if f.get("open") and f.get("ack"))
    n_cards = sum(1 for c in _yours_report(src, "")["cards"]
                  if not c["machine"] and not re.match(r"(yours-empty|queue-generated)", c["id"]))
    return n_open, n_cards


def _children_lines(path, boards=None, prefix="", cmap=None):
    """接班读板(rows / recheck)末尾补的话:每块子板一行;没有子板 ⇒ [](输出逐字不变)。出错也是 [] —— 读板不能因为它坏。"""
    try:
        out = []
        kids = _children_of(path, boards, cmap)
        sessions = _session_registry() if kids else []
        for k in kids:
            n_open, n_cards = _child_counts(k["src"])
            rows, _ = _child_stall_info(k, sessions)
            tail = "，其中 %d 件停着(%s)" % (len(rows), _child_stall_summary(rows)) if rows else ""
            out.append("%s另有 %d 件在%s(子板 %s),卡 %d 张等他%s" % (prefix, n_open, k["title"], k["path"], n_cards, tail))
        return out
    except Exception:
        return []


def _pane_parent_msg(parent, last, now):
    """纯函数(1110 子线投影):带父板声明的子板挂了卡 —— 父板此刻有没有哪个面板开着(不要求是本会话的面板);开着 ⇒ None。"""
    t = last.get(parent) if isinstance(last, dict) else None
    try:
        if t is not None and now - float(t) < PANE_STALE_S:
            return None
    except (TypeError, ValueError):
        pass
    return "  👉 主线的板没开着,他暂时看不到这张卡。"


def _ask_link_line(path):
    """挂完卡印一句:回复里贴这个能点的链接。1110 子线投影:带父板声明的子板 ⇒ 链接指向父板上投影的那张卡(他只看父板)。"""
    import urllib.parse as _up
    par = _child_parent_of(path)
    if par:
        try:
            src = open(path, encoding="utf-8", errors="replace").read()
        except OSError:
            src = ""
        ids = [c["id"] for c in _yours_report(src, os.path.basename(path))["cards"]
               if not c["machine"] and not re.match(r"(yours-empty|queue-generated)", c["id"])]
        return ("  👉 这张卡投影在派你的那条线的板上(他只看那块板),回复里贴这个链接,他点了就开:%s/%s%s"
                % (BP.origin(), _up.quote(par), ("#proj-" + _up.quote(ids[0], safe="")) if ids else ""))
    return "  👉 回复里别只说「板上那张」,把链接贴给他,他点了就开:%s/%s" % (BP.origin(), _up.quote(os.path.basename(path)))


def _oneoff_sessions(name, sessions):
    """板名「单开-XX」对得上的单开会话(标题「单开#卡号 XX」)。不是单开板 ⇒ None。纯函数。"""
    m = _ONEOFF_BOARD_RE.match(name)
    if not m:
        return None
    want = _title_norm(m.group(1))
    out = []
    for x in sessions:
        t = _ONEOFF_TITLE_RE.match(str(x.get("title") or "").strip())
        if t and _title_norm(t.group(1)) == want:
            out.append(x)
    return out


def _oneoff_verdict(name, sessions, rows, cards):
    """纯函数:单开板 → (结论, 说明);不是单开板 ⇒ None。只有 retire 这一种结论会被机器收掉。
    结论:nobody 对不上会话 · live 还有没归档的会话 · unknown 板读不出 · move 还有没做完的 · retire 可以自动退场。"""
    hit = _oneoff_sessions(name, sessions)
    if hit is None:
        return None
    if not hit:
        return "nobody", "对不上子线会话(标题要是「子线·%s」),不动" % name[3:].replace(".html", "")
    if any(not x.get("archived") for x in hit):
        return "live", "会话还没归档,不动"
    if rows is None or cards is None:
        return "unknown", "会话已归档,但板读不出还有没有没做完的,不动"
    if rows or cards:
        return "move", "会话已归档,还有没做完 %d 行、「要你的」%d 张 ⇒ 派它的线先搬走" % (rows, cards)
    return "retire", "会话已归档,没有未完成的 ⇒ 可以自动退场"


def cmd_retire_oneoffs(dry=False, sessions=None, paths=None, unsure=None):
    """把能收的单开板收掉(`retire --oneoffs`,大扫除跑);--dry-run 只列。只收结论是 retire 的,其余只报告。"""
    sess = sessions if sessions is not None else _session_registry()
    if unsure is None and sessions is None:
        unsure = _registry_unsure()
    if unsure and not dry:                     # 1115 C10 同一类:没归档的那份读坏了就会只剩已归档的 ⇒ 误判可退;判不了这轮只列不退
        print("  ⚠ 会话清单此刻判不了(%s)⇒ 这轮只列不退场,下一轮再判" % unsure)
        dry = True
    done = 0
    seen = 0
    for p in (paths if paths is not None else all_boards()):
        name = os.path.basename(p)
        if "/worktrees/" in p or _derived_copy(name) or not _is_board_file(p):
            continue
        try:
            src = open(p, encoding="utf-8", errors="replace").read()
        except OSError:
            continue
        rows, cards = _board_open_counts(src, name)
        v = _oneoff_verdict(name, sess, rows, cards)
        if not v:
            continue
        seen += 1
        if v[0] != "retire":
            print("  · 不动 %s —— %s" % (name, v[1]))
            continue
        done += 1
        if dry:
            print("  · 会退场 %s —— %s" % (name, v[1]))
        else:
            cmd_retire(p, "单开会话已归档,事项都做完了(机器收尾)")
    print("单开的板 %d 块,%s %d 块。" % (seen, "可以退场" if dry else "这次退场", done))
    return 0


def cmd_retire_scan(sessions=None, paths=None, codex=None):
    now = time.time()
    sess = sessions if sessions is not None else _session_registry()
    print("本机 %d 个会话记录(Claude);Claude 对不上的再扫 Codex 线程最近 %d 天的转录。每块板:" % (len(sess), CODEX_OWNER_DAYS))
    groups = {"oneoff": [], "live": [], "stale": [], "nobody": []}
    skipped = 0
    later = []                                 # 1115 C5:Claude 会话认不出在用的,攒起来一次扫 Codex 转录再定
    for p in (paths if paths is not None else all_boards()):
        if "/worktrees/" in p:
            continue
        name = os.path.basename(p)
        if _derived_copy(name) or not _is_board_file(p):          # 留档页、方案 / 审核页不是板
            skipped += 1
            continue
        try:
            src = open(p, encoding="utf-8", errors="replace").read()
        except OSError:
            continue
        ge = _board_gen_epoch(p) or os.stat(p).st_mtime
        rows, cards = _board_open_counts(src, name)
        _ov = _oneoff_verdict(name, sess, rows, cards)
        if _ov:
            groups["oneoff"].append((name, _ov[1], p))
            continue
        b = {"name": name, "age_days": int((now - ge) // 86400), "open_rows": rows, "cards": cards}
        k, why = _retire_classify(b, sess, now)
        if k != "live":
            later.append((b, p))
            continue
        groups[k].append((name, why, p))
    cx = codex if codex is not None else (_codex_board_owners([b["name"] for b, _p in later]) if later else {})
    for b, p in later:
        k, why = _retire_classify(b, sess, now, codex=cx.get(b["name"]))
        groups[k].append((b["name"], why, p))
    if skipped:
        print("(跳过 %d 个不是板的页面:留档页、方案 / 审核页)" % skipped)
    for k, head in (("oneoff", "■ 单开的板(`retire --oneoffs` 自动收掉能收的)"), ("stale", "■ 线已经不在 / 很久没动(建议退场)"),
                    ("nobody", "■ 对不上会话(先确认是谁的)"), ("live", "■ 在用")):
        if groups[k]:
            print(head + "(%d)" % len(groups[k]))
            for name, why, p in groups[k]:
                print("  · %s —— %s" % (name, why) if k != "live" else "  · %s" % name)
    if groups["stale"] or groups["nobody"]:
        print("退场一块:`python3 ~/.claude/scripts/board.py retire <板文件> --to \"<去向:接手的板名,或一句为什么不再需要>\"`"
              "(⛔ 只撤自己线的板;别的线的板,先问那条线或问他)")
    return 0


def _retire_pointer_html(name, to, when):
    """8777 上原地留的一页:这块板已退场 → 去向。去向像板名(xxx.html)就给链接。"""
    t = _esc(to)
    link = ('<a href="./%s">%s</a>' % (_urlparse.quote(to), t)) if re.match(r"^[^/\s]+\.html$", str(to)) else t
    return ('<!doctype html><meta charset="utf-8"><title>%s(已退场)</title>'
            '<body style="font:16px/1.6 -apple-system,sans-serif;max-width:640px;margin:48px auto;padding:0 16px">'
            '<h1 style="font-size:20px">这块板 %s 已退场</h1><p>去向:%s</p><p style="color:#888">退场时间 %s。'
            '这条线以后重新开工,AI 跑第一条板命令时会自动把它搬回来。</p></body>\n'
            % (_esc(name), _esc(name), link, _esc(when)))


def _retired_forget_own(name, state_path=None):
    """retire 之后:收尾钩子 state.json 里 own 指着这块板的条目,own 清掉(下次写别的板时重新学)。返回清了几条。读写不了 ⇒ 0(不挡退场)。
    ⭐ 1113 FDE-总控报:退场后面板钩子每轮还报「客户甲-FDE.html N 分钟没被面板拉取」—— 钩子先信 state.json 学到的 own,而它没跟着清。
    钩子那一侧另有 own-board.js isRetiredBoard 兜底(这里清漏了、或别处先学回来也不追)。"""
    p = state_path or BP.state("board-stop-hook", "state.json")
    try:
        st = json.load(open(p, encoding="utf-8"))
    except (OSError, ValueError):
        return 0
    n = 0
    for k, v in (st.items() if isinstance(st, dict) else []):
        if isinstance(v, dict) and v.get("own") == name:
            v["own"] = None
            n += 1
    if n:
        tmp = p + ".retire.tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(st, fh, ensure_ascii=False)
        os.replace(tmp, p)
    return n


def _retired_board_path(path):
    directory, name = os.path.dirname(os.path.abspath(path)), os.path.basename(path)
    return os.path.join(directory, "_retired", name) if name.endswith(".html") else None


def _retired_restore(path):
    """板不在原处、而同目录 `_retired/` 里有它 ⇒ 搬回来(板 + .queue.json / 留档 / .bak),返回 True。
    ⭐ 1021 负责人:「我未来有一天再重新启用那个 session 的话……它会自己知道去把退场里面的拉回来吗?……不会的话就全留着」
      ⇒ 重新开工时 AI 跑的第一条板命令(head / touch / row / ask / new …)就把它搬回来,不用谁记得。"""
    bdir, name = os.path.dirname(os.path.abspath(path)), os.path.basename(path)
    rdir = os.path.join(bdir, "_retired")
    candidate = _retired_board_path(path)
    if os.path.exists(path) or not candidate or not os.path.isfile(candidate):
        return False
    stem = name[:-5]
    back = []
    for fn in (name, stem + DERIVED_SUFFIX, stem + "-留档.html", name + ".bak", stem + "-留档.html.bak"):
        s_, d_ = os.path.join(rdir, fn), os.path.join(bdir, fn)
        if os.path.exists(s_) and not os.path.exists(d_):
            os.rename(s_, d_)
            back.append(fn)
    try:
        with open(BP.state("retired-boards.jsonl"), "a", encoding="utf-8") as fh:
            fh.write(json.dumps({"board": os.path.join(bdir, name), "restored": datetime.datetime.now().strftime("%Y-%m-%d %H:%M")},
                                ensure_ascii=False) + "\n")
    except OSError:
        pass
    print("✓ 这块板之前退场了(在 _retired/ 里),这条线又开工了 ⇒ 已搬回原处:%s" % "、".join(back))
    return True


# ⭐ 1115 sw-gc(负责人 11-15 选「14 天没动、纯机器戳就删」):收尾钩子的 state.json 一个会话一条(<会话>::<目录>),从不清 ——
#   11-15 实测 1937 条,1830 条 14 天没动。只删「纯机器戳」(键都在 STATE_GC_KEYS 里)且最新的时间戳早于 N 天的;
#   有别的键(人写的 / 新加的)一律留着。写之前把原文件复制一份 state.json.bak-gc-<日期>(回滚 = 拷回去),写临时文件再 replace。
STATE_GC_KEYS = {"seen", "own", "miss", "lastNag", "lastDupNag", "since"}
STATE_GC_DAYS = 14   # 依据: 负责人 11-15 sw-gc「14 天没动」


def _state_gc_pick(d, now, days=STATE_GC_DAYS):
    """state.json 里该删的键(纯函数):值是 dict、键都在 STATE_GC_KEYS、里面所有时间戳(since / lastNag / lastDupNag / seen 的值)都早于 days 天。"""
    out = []
    for k, v in (d or {}).items():
        if not isinstance(v, dict) or not set(v) <= STATE_GC_KEYS:
            continue
        ts = [v.get(x) for x in ("since", "lastNag", "lastDupNag")] + list((v.get("seen") or {}).values() if isinstance(v.get("seen"), dict) else [])
        ts = [float(x) for x in ts if isinstance(x, (int, float)) and not isinstance(x, bool)]
        if ts and now - max(ts) >= days * 86400:
            out.append(k)
    return out


def cmd_gc(state=False, kit=False, days=STATE_GC_DAYS, dry=False, now=None, state_path=None, **kw):
    """`board.py gc --state [--days N] [--dry-run]` / `gc --kit [--dry-run]`。"""
    now = time.time() if now is None else now
    if not state and not kit:
        die("要说清理哪个:--state(收尾钩子的 state.json)或 --kit(没人引用的旧 kit)")
    if state:
        sp = state_path or BP.state("board-stop-hook", "state.json")
        try:
            d = json.load(open(sp, encoding="utf-8"))
        except (OSError, ValueError) as e:
            die("读不了 %s(%s)\n  ⇒ 什么都没动。" % (sp, e))
        if not isinstance(d, dict):
            die("%s 不是一个对象\n  ⇒ 什么都没动。" % sp)
        ks = _state_gc_pick(d, now, days)
        print("%s%s:%d 条,其中 %d 条是 %d 天没动的纯机器戳%s" % ("预演(--dry-run,什么都不动)· " if dry else "", sp, len(d), len(ks), days, "" if dry else ",删掉"))
        if ks and not dry:
            import shutil as _shg
            bak = "%s.bak-gc-%s" % (sp, time.strftime("%Y%m%d-%H%M%S", time.localtime(now)))
            _shg.copy2(sp, bak)
            for k in ks:
                d.pop(k, None)
            tmp = "%s.tmp%d" % (sp, os.getpid())
            with open(tmp, "w", encoding="utf-8") as fh:
                json.dump(d, fh, ensure_ascii=False)
            os.replace(tmp, sp)
            print("  原文件留了一份 %s(回滚:拷回去)" % bak)
        print("  留下 %d 条" % ((len(d) - len(ks)) if dry else len(d)))
    if kit:
        r = _kit_gc(now=now, dry=dry, **kw)
        print("%s_kit:留 %d 个,%s %d 个没人引用、放满 %d 天的旧文件%s" % ("预演(--dry-run,什么都不动)· " if dry else "", r["kept"], "会挪开" if dry else "挪开了",
                                                       len(r["moved"]), KIT_GC_DAYS, ";%s %d 批进废纸篓" % ("会把" if dry else "把", len(r["trashed"])) if r["trashed"] else ""))
    return 0


def cmd_retire(path, to, force=False, dry=False):
    """板退场。dry = 只印会动哪些文件(1115 sw-retire:真数据上先预演再跑),什么都不动。"""
    p = assert_canonical(path)
    name = os.path.basename(p)
    if not str(to or "").strip():
        die("要写去向:--to \"<接手的板名(xxx.html),或一句为什么不再需要>\" —— 他开着这块板时会看到它。")
    src = open(p, encoding="utf-8", errors="replace").read()
    rows, cards = _board_open_counts(src, name)
    if not force and (rows or cards):
        die("这块板还有没做完的 %s 行、「要你的」%s 张 —— 退场会把它们从他眼前拿走。\n"
            "   ⇒ 先搬到接手的板(`board.py rows %s` 看清单),或在原板标做完;确定不要了加 --force。\n   ⇒ 什么都没动。"
            % (rows, cards, p))
    bdir = os.path.dirname(p)
    rdir = os.path.join(bdir, "_retired")
    if dry:
        print("预演(--dry-run,什么都不动):%s 退场 → %s" % (name, to))
        for fn in (name, name[:-5] + DERIVED_SUFFIX, name[:-5] + "-留档.html", name + ".bak", name[:-5] + "-留档.html.bak"):
            if os.path.exists(os.path.join(bdir, fn)):
                print("  会挪进 %s" % os.path.join(rdir, fn))
        print("  会把 8777 上的 %s 换成退场页" % os.path.join(BP.web_root(), name))
        print("  会记一行到 %s" % BP.state("retired-boards.jsonl"))
        if rows or cards:
            print("  ⚠ 板上还有没做完的 %s 行、「要你的」%s 张 —— 带了 --force 才会真退,它们会从他眼前拿走" % (rows, cards))
        return 0
    os.makedirs(rdir, exist_ok=True)
    stem = name[:-5]
    when = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")
    inos = {}       # 1115:挪之前记下每份的 inode —— worktree 里同一 inode 的硬链(主板、派生、留档)都要去掉
    for fn in (name, stem + DERIVED_SUFFIX, stem + "-留档.html"):
        try:
            inos[fn] = os.stat(os.path.join(bdir, fn)).st_ino
        except OSError:
            pass
    moved = []
    for fn in (name, stem + DERIVED_SUFFIX, stem + "-留档.html", name + ".bak", stem + "-留档.html.bak"):
        src_f = os.path.join(bdir, fn)
        if not os.path.exists(src_f):
            continue
        dst = os.path.join(rdir, fn)
        if os.path.exists(dst):
            dst = os.path.join(rdir, "%s.%s" % (fn, time.strftime("%Y%m%d-%H%M%S")))
        os.rename(src_f, dst)
        moved.append(dst)
    # worktree 里同一份文件的硬链(同一个 inode)⇒ 去掉;别的副本留着并报出来(那里面可能有正本没有的东西)
    m = re.match(r"(.*)/\.claude/boards/[^/]+$", p)
    unlinked, kept = [], []
    if m:
        for fn in (name, stem + DERIVED_SUFFIX, stem + "-留档.html"):
            for o in glob.glob(os.path.join(glob.escape(m.group(1)), ".claude", "worktrees", "*", ".claude", "boards", glob.escape(fn))):
                try:
                    same = fn in inos and os.stat(o).st_ino == inos[fn]
                except OSError:
                    continue
                if same or (fn != name and moved and _same_bytes(o, os.path.join(rdir, fn)) if os.path.exists(os.path.join(rdir, fn)) else False):
                    os.unlink(o)
                    unlinked.append(o)
                else:
                    kept.append(o)
    # 8777 上那一份(硬链)换成「已退场 → 去向」的一页
    web = os.path.join(BP.web_root(), name)
    try:
        if os.path.lexists(web):
            os.unlink(web)
        os.makedirs(BP.web_root(), exist_ok=True)
        with open(web, "w", encoding="utf-8") as fh:
            fh.write(_retire_pointer_html(name, to, when))
    except OSError as e:
        print("  ⚠ 8777 上那一页没换成退场页(%s)—— 他开着的面板会停在旧板" % e)
    try:
        with open(BP.state("retired-boards.jsonl"), "a", encoding="utf-8") as fh:
            fh.write(json.dumps({"board": p, "to": to, "at": when, "moved": moved, "force": bool(force)}, ensure_ascii=False) + "\n")
    except OSError:
        pass
    _retired_forget_own(name)      # 1113:钩子学到的「本会话的板」指着它 ⇒ 当场清掉(FDE-总控报:退场后面板钩子还在追)
    print("✓ %s 已退场 → %s" % (name, to))
    for x in moved:
        print("  挪进 %s" % x)
    if unlinked:
        print("  去掉 worktree 里的 %d 个硬链(同一份文件)" % len(unlinked))
    for x in kept:
        print("  ⚠ 留着:%s —— 内容和正本不同,先看一眼再删" % x)
    print("  8777 上 %s 换成了退场页;索引和同侪条下次刷新时不再列它。这条线以后重新开工,跑第一条板命令(head / touch / new …)就自动搬回。"
          % name)
    return 0


# ── 1026(电商-投流线【要你做】:负责人 10-26 15:43 板上拍线改名「电商-投流达人」):板跟着线改名 ─────────
#   原来只有 retire,它要求板上没有没做完的 ⇒ 有在跑的行的线一改名,板只能停在旧名:侧栏按会话标题认不上、
#   `board.py path <新线名>` 找不到。手动 mv 会断硬链(worktree / 8777 各一份)、丢他的答案和已读、▶ 变死链。
#   ⇒ `rename <板> --to <新线名>`:同一个 inode 原地改名(行 / 卡 / 留档一样不丢),worktree 硬链跟着换名,
#     8777 旧网址留一页跳转,答案 / 已读 / 面板拉取 / 侧栏认板 / ▶ 按钮的记录按新名改。
#   ⛔ 方案页不改名:板上的入口、他答过的记录都按原名指着它,改了反而断。

def _rename_sides(o, n):
    """跟着板一起改名的文件(旧名, 新名):板、.queue.json、留档页、两份 .bak。"""
    return [(o + ".html", n + ".html"), (o + DERIVED_SUFFIX, n + DERIVED_SUFFIX), (o + "-留档.html", n + "-留档.html"),
            (o + ".html.bak", n + ".html.bak"), (o + "-留档.html.bak", n + "-留档.html.bak")]


def _rename_text(s, o, n):
    """板 / 留档页里指自己的地方:<title>、<h1>(「X 状态板」「X · 已留档」)、页脚和链接里的文件名。纯函数。
    ⛔ 正文里顺带提到旧线名的不动(「线改名电商-投流达人」前面不是 > / 引号 / 空白)、方案页名(「X-测品…」)不动。"""
    pat = r'(?<=[>/"\'\s])' + re.escape(o) + r'(?= 状态板| · 已留档|\.html|-留档\.html|' + re.escape(DERIVED_SUFFIX) + r')'
    return re.sub(pat, lambda m: n, s)


def _rename_json_state(fp, fmap):
    """状态文件里按页面名记的键和值:等于旧名、或以「/旧名」结尾的,换成新名。返回改了几处;读不到 ⇒ 0。
    这些文件不是硬链 ⇒ 写临时文件再 replace。"""
    try:
        raw = open(fp, encoding="utf-8").read()
        d = json.loads(raw)
    except (OSError, ValueError):
        return 0
    hit = [0]

    def fix(x):
        for o, n in fmap:
            if x == o or x.endswith("/" + o):
                hit[0] += 1
                return x[:len(x) - len(o)] + n
        return x

    def walk(x):
        if isinstance(x, dict):
            return {(fix(k) if isinstance(k, str) else k): walk(v) for k, v in x.items()}
        if isinstance(x, list):
            return [walk(v) for v in x]
        return fix(x) if isinstance(x, str) else x
    d2 = walk(d)
    if hit[0]:
        tmp = fp + ".rename-tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(d2, fh, ensure_ascii=False, indent=2 if "\n " in raw else None)
        os.replace(tmp, fp)
    return hit[0]


def _rename_pointer_html(old, new):
    """8777 旧网址上留的一页:立刻跳到新名;他开着旧网址的面板下一次自动刷新就过去了。⛔ 标题里别带「状态板」(那样会被当成板)。"""
    q = _urlparse.quote(new)
    return ('<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=./%s"><title>%s(已改名)</title>'
            '<body style="font:16px/1.6 -apple-system,sans-serif;max-width:640px;margin:48px auto;padding:0 16px">'
            '<h1 style="font-size:20px">这块板改名了:%s → <a href="./%s">%s</a></h1><p style="color:#888">正在跳过去;没跳就点新名字。</p>'
            '<script>location.replace("./%s")</script></body>\n' % (q, _esc(old), _esc(old), q, _esc(new), q))


def _renamed_to(path):
    """这个路径的板改过名 ⇒ 新路径;没有记录 ⇒ None。读 `renamed-boards.jsonl`,同一块改过几次取最后一次。"""
    def key(x):                      # 旧文件已经不在 ⇒ 只把目录解到真路径(/var ↔ /private/var、软链进来的仓)
        x = os.path.abspath(str(x or ""))
        return os.path.join(os.path.realpath(os.path.dirname(x)), os.path.basename(x))
    ap, hit = key(path), None
    try:
        for line in open(BP.state("renamed-boards.jsonl"), encoding="utf-8"):
            try:
                e = json.loads(line)
            except ValueError:
                continue
            if key(e.get("from")) == ap:
                hit = e.get("to")
    except OSError:
        return None
    return hit


def _hosts_table():
    try:
        return json.load(open(os.path.join(BP.web_root(), "_hosts.json"), encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def cmd_rename(path, to):
    p = assert_canonical(path)
    bdir, name = os.path.dirname(p), os.path.basename(p)
    o = name[:-5]
    n = re.sub(r"\.html$", "", str(to or "").strip()).replace(" 状态板", "").strip()
    if not n or "/" in n or n.startswith(("_", ".")) or n.endswith("-留档"):
        die("新名不对:--to 只写新线名(例:--to 电商-投流达人),不带路径、不以 _ / . 开头、不以「-留档」结尾。⇒ 什么都没动。")
    if n == o:
        die("新名和旧名一样(%s)。⇒ 什么都没动。" % o)
    if _derived_copy(name) or not _is_board_file(p):
        die("%s 不是一块状态板(留档页 / 方案页不单独改名,它们跟着板走或保持原名)。⇒ 什么都没动。" % name)
    sides = _rename_sides(o, n)
    web = BP.web_root()
    for _o, _n in sides:
        if os.path.lexists(os.path.join(bdir, _n)):
            die("新名已经有文件了:%s —— 先看一眼是谁的。⇒ 什么都没动。" % os.path.join(bdir, _n))
    if os.path.lexists(os.path.join(web, n + ".html")) and not os.path.samefile(os.path.join(web, n + ".html"), p):
        die("8777 上已经有一块 %s.html,而且不是这块板。⇒ 什么都没动。" % n)
    old_alias = [k for k, v in _hosts_table().items() if v == name]
    when = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")
    done, kept = [], []
    # ① 正本目录:同一个 inode 原地改名 ⇒ 硬链、行、卡、留档原样
    for _o, _n in sides:
        if os.path.exists(os.path.join(bdir, _o)):
            os.rename(os.path.join(bdir, _o), os.path.join(bdir, _n))
            done.append(_n)
    np_ = os.path.join(bdir, n + ".html")
    # ② 板和留档页里指自己的地方(原地写,保住硬链)
    for fn in (n + ".html", n + "-留档.html"):
        fp = os.path.join(bdir, fn)
        if not os.path.exists(fp):
            continue
        with open(fp, "r+", encoding="utf-8") as fh:
            t = fh.read()
            t2 = _rename_text(t, o, n)
            if t2 != t:
                fh.seek(0); fh.write(t2); fh.truncate()
    # ③ 同仓 worktree 里的那几份(多半是硬链):跟着换名;新名已有文件的不碰、报出来
    m = re.match(r"(.*)/\.claude/boards$", bdir)
    wts = glob.glob(os.path.join(glob.escape(m.group(1)), ".claude", "worktrees", "*", ".claude", "boards")) if m else []
    nwt = 0
    for wd in wts:
        for _o, _n in sides:
            a_, b_ = os.path.join(wd, _o), os.path.join(wd, _n)
            if not os.path.lexists(a_):
                continue
            if os.path.lexists(b_):
                kept.append(a_)
                continue
            os.rename(a_, b_)
            nwt += 1
    # ④ 8777:板的硬链换名,旧名换成跳转页
    try:
        os.makedirs(web, exist_ok=True)
        wo, wn = os.path.join(web, name), os.path.join(web, n + ".html")
        if os.path.lexists(wo) and not os.path.lexists(wn):
            os.rename(wo, wn)
        if not os.path.lexists(wn):
            os.link(np_, wn)
        if os.path.lexists(wo):
            os.unlink(wo)
        with open(wo, "w", encoding="utf-8") as fh:
            fh.write(_rename_pointer_html(name, n + ".html"))
    except OSError as e:
        print("  ⚠ 8777 上没换好(%s)—— 跑一次 `board.py touch %s` 会把硬链补上" % (e, np_))
    # ⑤ 按页面名记的状态:他的答案 / 已读、答案印过没有、面板最近一次拉取、侧栏认板(按会话 / 按目录 / 按线名)
    fmap = [(name, n + ".html")]
    moved_state = []
    for sub_, a_, b_ in (("answers", name + ".json", n + ".html.json"), ("acks", o + ".json", n + ".json")):
        sa = BP.state("board-server", sub_, _urlparse.quote(a_, safe=""))
        sb = BP.state("board-server", sub_, _urlparse.quote(b_, safe=""))
        if os.path.exists(sa) and not os.path.exists(sb):
            os.rename(sa, sb)
            moved_state.append(sub_)
            _rename_json_state(sb, fmap)
    nst = 0
    for fp in (BP.state("board-server", "answers-shown.json"), BP.state("board-server", "last-fetch.json"),
               BP.state("board-stop-hook", "state.json"), _launch_homes_path(), _launch_sids_path(), _launch_titles_path()):
        nst += _rename_json_state(fp, fmap)
    try:
        with open(BP.state("renamed-boards.jsonl"), "a", encoding="utf-8") as fh:
            fh.write(json.dumps({"from": p, "to": np_, "at": when, "moved": done, "worktree_links": nwt}, ensure_ascii=False) + "\n")
    except OSError:
        pass
    # ⑥ 总览、别名表刷新 ⇒ ▶ 按钮里还写着旧别名的 launch.json 换成新别名
    nl = 0
    try:
        refresh_index(wait=True)
        new_alias = [k for k, v in _hosts_table().items() if v == n + ".html"]
        if old_alias and new_alias and m:
            for lj in [os.path.join(m.group(1), ".claude", "launch.json")] + glob.glob(
                    os.path.join(glob.escape(m.group(1)), ".claude", "worktrees", "*", ".claude", "launch.json")):
                try:
                    t = open(lj, encoding="utf-8").read()
                except OSError:
                    continue
                t2 = t
                for oa in old_alias:
                    t2 = t2.replace("//%s.localhost" % oa, "//%s.localhost" % new_alias[0])
                t2 = t2.replace('"状态板 · %s"' % o, '"状态板 · %s"' % n)
                if t2 != t:
                    with open(lj, "w", encoding="utf-8") as fh:
                        fh.write(t2)
                    nl += 1
    except Exception as e:                  # 刷不了总览不影响改名本身;下一次 touch 会再刷
        print("  ⚠ 总览 / ▶ 按钮没刷成(%s)—— 跑一次 `board.py touch %s` 补上" % (e, np_))
    print("✓ %s → %s.html(%s)" % (name, n, when))
    print("  正本改名:%s" % "、".join(done))
    print("  worktree 里跟着换名 %d 个(硬链没断);8777 旧网址 %s 留了一页,打开就跳到新名" % (nwt, name))
    print("  他的答案 / 已读挪过去:%s;按页面名记的状态改了 %d 处;▶ 按钮换别名 %d 个 launch.json"
          % ("、".join(moved_state) or "没有要挪的", nst, nl))
    for x in kept:
        print("  ⚠ 留着旧名:%s —— 同一棵树里新名已经有文件,先看一眼再删" % x)
    print("  方案页保持原名(板上的入口和他答过的记录都按原名指着它)。")
    _print_board_pending_notes(np_)
    print("  ⇒ 下一步:`board.py touch %s`(刷板顶、同侪条);以后取路径用 `board.py path %s`。" % (np_, n))
    return 0


def _queue_drop_you(board_path, n):
    """他在一张带卡号 #n 的卡上答过了 ⇒ .queue.json 里 #n 的 you / you_why / you_parked 一起拿掉(原地写,保住硬链)。
    返回拿掉了几处;没有 .queue.json / 没有那张 / 没标 you ⇒ 0。⚠ 1021(CI/AI Review v6.9 报):
      他 10-20 22:50 在 #4767、#5438 的卡上答了,卡收掉了,而 .queue.json 里两张还标着 you: decide ⇒ 机器卡「卡在你身上」挂到第二天。"""
    qp = _queue_side_path(board_path)
    try:
        with open(qp, "r+", encoding="utf-8") as fh:
            d = json.load(fh)
            hit = [0]

            def walk(x):
                if isinstance(x, dict):
                    if str(x.get("n")) == str(n) and any(k in x for k in ("you", "you_why", "you_parked")):
                        for k in ("you", "you_why", "you_parked"):
                            x.pop(k, None)
                        hit[0] += 1
                    for v in list(x.values()):
                        walk(v)
                elif isinstance(x, list):
                    for v in x:
                        walk(v)
            walk(d)
            if hit[0]:
                fh.seek(0)
                fh.write(json.dumps(d, ensure_ascii=False, indent=2))
                fh.truncate()
            return hit[0]
    except (OSError, ValueError):
        return 0


# ──────────────── 1023 晚 电商-基建转(负责人 18:3x):外部群里对方的新回复被淹没,板上没出现
#   「我这个事情我要还要回复那个示例群成员,这事情怎么就直接被淹没掉了?也没放在状态板上……」
#   示例群 群 15:07 对方改了范围、18:14 ＠他追问;那条线下午没再读这个群,板上那一行停在旧结论,没有任何东西提醒它。
#   ⇒ 行上登记对方群(`row --ack <行> --chat oc_…`,写 data-chat);`board.py chat-watch --all`(本机 LaunchAgent 每 10 分钟跑)
#     去拉这些群里、这一行上次被 row 动过(data-chat-seen)之后**别人**发的话;有 ⇒ 行上记 data-chat-new / -who / -say / -n 并 touch:
#     板首屏「卡着的」最前面亮红、行尾一枚红标;lint 报错(那条线下次刷板就得重判);他每次发话时钩子提醒那条线(board-answers-inject)。
#     那条线 `row --ack <行> …` 重判过 ⇒ data-chat-seen 记成现在、红标当场拿掉。
#   ⛔ 只看登记了的群(不猜哪个群跟哪件事有关);⛔ 拉不到(没装 lark-cli / 没登录 / 断网)⇒ 说出来、这块板什么都不改,不当成「没有新消息」。
#   1104(负责人方案页拍「照这套改」):私聊 / 大群里聊别的事也把这一行顶红 ⇒ 登记时可带关键词(`row --chat oc_… --chat-kw "词1,词2"`,写 data-chat-kw),
#     只认内容里含任一关键词的消息;不带关键词照旧谁说话都算。⛔ 关键词只缩小「算不算新回复」,拉不到群照样报错、不当成没有新消息。
CHAT_RE = re.compile(r"^oc_[0-9A-Za-z]{8,64}$")
CHAT_ATTRS = ("data-chat-new", "data-chat-who", "data-chat-say", "data-chat-n")
CHAT_SAY_CUT = 80
CHAT_LOG = BP.state("chat-watch.log")


def _chat_ids(v):
    return [x for x in re.split(r"[,，\s]+", str(v or "").strip()) if x]


def _chat_kws(v):
    return [x for x in dict.fromkeys(re.split(r"[,，、]+", str(v or "").strip())) if x.strip()]


def _chat_arg_problem(v):
    ids = _chat_ids(v)
    if not ids:
        return "--chat 要给群的 chat_id(oc_ 开头);不再盯这个群写 --no-chat"
    bad = [x for x in ids if not CHAT_RE.match(x)]
    if bad:
        return ("--chat 只认飞书群的 chat_id(oc_ 开头),「%s」不是 —— 拿群名查:"
                "`lark-cli im +chat-search --as user --query \"<群名>\"`" % bad[0][:60])
    return None


def _row_chat_set(src, ack, chat=None, no_chat=False, now=None, kw=None):
    """`row` 成功之后:登记 / 拿掉对方群;这一行登记着群 ⇒ data-chat-seen 记成现在、红标(data-chat-new 等)拿掉。返回 (新文本, notes)。"""
    now = now or datetime.datetime.now()
    a, b, _z = _row_span(src, ack)
    tag = src[a:b]
    notes = []
    m = re.search(r'\bdata-chat\s*=\s*"([^"]*)"', tag)
    old = m.group(1) if m else None
    if no_chat:
        tag = _attr_set(_attr_set(_attr_set(tag, "data-chat", None), "data-chat-seen", None), "data-chat-kw", None)
        if old:
            notes.append("不再盯群 %s" % old)
        cur = None
    elif chat is not None:
        cur = ",".join(dict.fromkeys(_chat_ids(chat)))
        tag = _attr_set(tag, "data-chat", cur)
        if cur != old:
            notes.append("盯着群 %s(群里别人再说话,这一行亮红)" % cur)
    else:
        cur = old
    if kw is not None and not no_chat:
        if not cur:
            raise ValueError("--chat-kw 是给登记了群的行用的:这一行没盯群 ⇒ 同一条命令带上 --chat oc_…")
        _k = ",".join(_chat_kws(kw))
        tag = _attr_set(tag, "data-chat-kw", _esc(_k).replace('"', "&quot;") or None)
        notes.append(("只认含「%s」的消息" % "/".join(_chat_kws(kw))) if _k else "不再按关键词筛,群里谁说话都算")
    if cur:
        tag = _attr_set(tag, "data-chat-seen", now.strftime("%Y-%m-%dT%H:%M:%S"))
    had = bool(re.search(r'\bdata-chat-new\s*=', tag))
    for n in CHAT_ATTRS:
        tag = _attr_set(tag, n, None)
    if had and not no_chat:
        notes.append("群里的新回复记成你看过了(⚠ 没真读群就别这么收 —— 读:`lark-cli im +chat-messages-list --as user --chat-id %s`)" % (cur or old))
    return src[:a] + tag + src[b:], notes


def _lark_bin():
    import shutil
    return shutil.which("lark-cli")


def _lark_self_open_id(lark):
    try:
        # 未验证: dbba0506c 未记认证查询30秒的定值依据，下次群监测验收时测正常与异常查询耗时。
        r = subprocess.run([lark, "auth", "status"], capture_output=True, text=True, timeout=30, encoding="utf-8", errors="replace")
        d = json.loads(r.stdout)
        d = d.get("data", d)
        return ((d.get("identities") or {}).get("user") or {}).get("openId") or None
    except Exception:
        return None


def _lark_chat_messages(lark, chat, since):
    """群 chat 里 since(datetime)之后的消息,时间正序 → (列表, 出错原因)。只读。"""
    cmd = [lark, "im", "+chat-messages-list", "--as", "user", "--chat-id", chat,
           "--start-time", str(int(time.mktime(since.timetuple()))), "--order", "asc", "--page-size", "50"]
    try:
        # 未验证: dbba0506c 未记拉群消息60秒的定值依据，下次群监测验收时测慢网与分页耗时。
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=60, encoding="utf-8", errors="replace")
    except subprocess.TimeoutExpired:
        return None, "lark-cli 60 秒没回"
    except OSError as e:
        return None, "lark-cli 跑不起来:%s" % e
    try:
        d = json.loads(r.stdout or "")
    except Exception:
        return None, "lark-cli 的输出读不懂:%s" % re.sub(r"\s+", " ", (r.stderr or r.stdout or ""))[:160]
    if not d.get("ok"):
        return None, "lark-cli 报错:%s" % re.sub(r"\s+", " ", json.dumps(d.get("error") or d, ensure_ascii=False))[:200]
    return list((d.get("data") or {}).get("messages") or []), None


def _chat_parse_time(t):
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
        try:
            return datetime.datetime.strptime(str(t or "").strip(), fmt)
        except ValueError:
            pass
    return None


def _chat_new_for_row(msgs, seen, self_id, kws=None):
    """一行的「别人在 seen 之后说的话」:(条数, 最后一条) 或 (0, None)。
    ⚠ 飞书给的时间只到分钟 ⇒ 和 seen 同一分钟的也算新的(宁可多亮一次红,重判一次就收;漏掉才是这次的事故)。"""
    cut = seen.replace(second=0, microsecond=0)
    hit = []
    for m in msgs or []:
        snd = m.get("sender") or {}
        if m.get("deleted") or snd.get("sender_type") != "user" or (self_id and snd.get("id") == self_id):
            continue
        t = _chat_parse_time(m.get("create_time"))
        if kws and not any(k.lower() in str(m.get("content") or "").lower() for k in kws):
            continue
        if t is not None and t >= cut:
            hit.append((t, m))
    return (len(hit), hit[-1]) if hit else (0, None)


# ⭐ 1113(AI Harness #e4c8):11-11 12:00 子线-出单提速 那一行登记的群里,同事贴了 App Key / App Secret 明文,
#   chat-watch 原样写进了行上的 data-chat-say(板首屏和行尾都显示)并印进 state_dir/chat-watch.out。
#   ⇒ 摘录写板、印日志之前打码:① 「key / secret / token / 密钥 / 密码 / 口令…」后面跟着的值;② 看着像凭据的长串
#     (字母数字混合、20 位以上,或 sk- / ghp_ / xox 这类前缀)。只留前 3 位,让读的人还认得出是哪一把。
#   否过什么、为什么:⛔ 不整句不写(读的人要知道「对方贴了钥匙」这件事本身,才会去叫他换钥匙);
#     ⛔ 不按群 / 人跳过(谁都可能贴);⛔ 群号 oc_ / 用户 ou_ / 消息 om_ 这类飞书 id 不打(行上本来就写着,打了反而对不上;前面紧挨「_」的串不认,所以它们天然不中)。
def _redact_secrets(text):
    """摘录里的凭据打码 —— 调全机共用的 secret_redact.redact:键值形式的值、像凭据的长串 ⇒ 前 3 位 + •••;
    git 提交号(40/64 位小写十六进制)、飞书 img_/file_ key、链接里的段放过。纯函数。
    1113:原来这里自己一份正则,AI Harness 693d72d4 收窄豁免后两份会走样 ⇒ 只留共用那份。"""
    return _SR.redact(text)


def _chat_watch_board(p, lark, self_id, cache, now=None, dry=False):
    """一块板:返回 (要印的几行, 这块板改了没有)。拉不到某个群 ⇒ 这块板一个字不改,把原因说出来。"""
    now = now or datetime.datetime.now()
    src = open(p, encoding="utf-8").read()
    if 'data-chat="' not in src:
        return [], False
    y = _yours_zone_rows(src) or {}
    plan, out = [], []
    for f in y.get("facts", []):
        if not f.get("ack"):
            continue
        a0, a1, _z = _row_span(src, f["ack"])
        tag = src[a0:a1]
        g = lambda n: (re.search(r'\b%s\s*=\s*"([^"]*)"' % re.escape(n), tag) or [None, None])[1]
        chats = _chat_ids(g("data-chat"))
        if not chats or not f["open"]:
            continue
        seen = _chat_parse_time((g("data-chat-seen") or "").replace("T", " ")) or None
        if seen is None:                      # 手写的 data-chat、没经过 row:从现在起算(不追溯),写上 seen
            plan.append((f["ack"], {"data-chat-seen": now.strftime("%Y-%m-%dT%H:%M:%S")}))
            out.append("  · %s 第一次看到登记的群,从现在起算" % f["ack"])
            continue
        n, last = 0, None
        for c in chats:
            if c not in cache:
                cache[c] = _lark_chat_messages(lark, c, now - datetime.timedelta(days=3))
            msgs, err = cache[c]
            if err:
                return ["  ✗ %s 行 %s:群 %s 拉不到(%s)—— 这块板这一轮什么都没改" % (os.path.basename(p), f["ack"], c, err)], False
            k, l = _chat_new_for_row(msgs, seen, self_id, kws=_chat_kws(__import__("html").unescape(g("data-chat-kw") or "")))
            n += k
            if l and (last is None or l[0] >= last[0]):
                last = l
        if n:
            m = last[1]
            say = re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", str(m.get("content") or ""))).strip() or "(%s)" % (m.get("msg_type") or "消息")
            say = _redact_secrets(say)            # 1113 #e4c8:写进板、印进日志之前打码(见 _redact_secrets)
            snd = m.get("sender") or {}
            want = {"data-chat-new": last[0].strftime("%Y-%m-%dT%H:%M"), "data-chat-who": (snd.get("name") or "对方")[:20],
                    "data-chat-say": say[:CHAT_SAY_CUT] + ("…" if len(say) > CHAT_SAY_CUT else ""), "data-chat-n": str(n)}
            out.append("  ● %s 行 %s:群里 %s %s 说了新的(共 %d 条):「%s」" % (os.path.basename(p), f["ack"], want["data-chat-new"][11:],
                                                                    want["data-chat-who"], n, want["data-chat-say"]))
        else:
            want = {k: None for k in CHAT_ATTRS}
        if any((g(k) or None) != want.get(k) for k in CHAT_ATTRS):
            plan.append((f["ack"], want))
    if not plan or dry:
        return out, False
    new = src
    for ack, want in plan:
        a0, a1, _z = _row_span(new, ack)
        tag = new[a0:a1]
        for k, v in want.items():
            tag = _attr_set(tag, k, v)
        new = new[:a0] + tag + new[a1:]
    with open(p, encoding="utf-8") as fh:
        if fh.read() != src:
            return out + ["  ⚠ %s 刚被别人改过 —— 这一轮没记,下一轮再记" % os.path.basename(p)], False
    with open(p, "r+b") as fh:
        b = new.encode("utf-8"); fh.write(b); fh.truncate()
    _touch_child(p, "盯群")
    return out, True


def _chat_watch_clamshell_battery(ioreg_output, pmset_output):
    """与 msg-router power_state 同一条件，只读 ioreg 输出和 pmset 首行。"""
    return ('"AppleClamshellState" = Yes' in ioreg_output
            and "Battery Power" in pmset_output.partition("\n")[0])


def _chat_watch_power_output(argv):
    try:
        # 依据: 防止电源探测在后台任务中挂住，沿用同文件子进程探测的超时保护。
        result = subprocess.run(argv, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True, timeout=5)
        return result.stdout if result.returncode == 0 else ""
    except (OSError, subprocess.TimeoutExpired):
        return ""


def _chat_watch_log(message):
    try:
        os.makedirs(os.path.dirname(CHAT_LOG), exist_ok=True)
        with open(CHAT_LOG, "a", encoding="utf-8") as fh:
            fh.write("%s %s\n" % (datetime.datetime.now().strftime("%Y-%m-%dT%H:%M:%S"), message))
    except OSError:
        pass


def cmd_chat_watch(a):
    """⭐ 1023 晚:板上登记了对方群的没做完的行,群里别人说了新的 ⇒ 行上亮红(见本节开头)。--all 全机;--dry-run 只印不写。"""
    if _chat_watch_clamshell_battery(_chat_watch_power_output(["ioreg", "-r", "-k", "AppleClamshellState", "-d", "4"]),
                                     _chat_watch_power_output(["pmset", "-g", "batt"])):
        _chat_watch_log("skip clamshell_on_battery")
        print("盯群:合盖且用电池，这一轮跳过。")
        return 0
    paths = [x for x in all_boards() if _is_board_file(x)] if a.all else [os.path.abspath(x) for x in a.paths]
    if not paths:
        die("没给板文件。用法:board.py chat-watch <板> [--dry-run];全机:board.py chat-watch --all")
    paths = [x for x in paths if 'data-chat="' in open(x, encoding="utf-8", errors="replace").read()]
    if not paths:
        print("没有哪块板的行登记了对方群(`board.py row <板> --ack <行> --chat oc_…`)—— 没有要盯的。")
        return 0
    lark = _lark_bin()
    if not lark:
        print("✗ 本机没有 lark-cli —— 登记了群的 %d 块板这一轮都没看(⛔ 不是「没有新消息」)" % len(paths))
        return 1
    self_id = _lark_self_open_id(lark)
    if not self_id:
        print("  ⚠ 读不到当前飞书登录的是谁 —— 他自己在群里说的话也会算成「别人说了新的」")
    cache, lines, changed, bad = {}, [], 0, 0
    for p in paths:
        try:
            o, ch = _chat_watch_board(p, lark, self_id, cache, dry=a.dry_run)
        except ValueError as e:
            o, ch = ["  ✗ %s:%s" % (os.path.basename(p), e)], False
        lines += o
        changed += ch
        bad += sum(1 for x in o if x.lstrip().startswith("✗"))
    hot = sum(1 for x in lines if x.lstrip().startswith("●"))
    print("盯群:%d 块板 · %d 个群 · %d 行有新回复 · 改了 %d 块板%s" % (len(paths), len(cache), hot, changed, "(只看没写)" if a.dry_run else ""))
    for x in lines:
        print(x)
    if not a.dry_run:
        _chat_watch_log("boards=%d chats=%d hot=%d changed=%d failed=%d" % (len(paths), len(cache), hot, changed, bad))
    return 1 if bad else 0


