#   p50 88 · p75 139 · p90 170 · p95 173 · 最长 176(负责人看不懂的卡「前因后果一坨字」)
ASK_WHY_MAX = 170   # 依据: 现挂 30 张卡前因后果 p90 = 170 字
# 依据: 负责人 11-13 起点「看不懂」的卡里有「11 条建议一坨字」⇒ 「批了以后怎么做」最多 4 条、一条一句(首屏一行约 40 字)
ASK_HOW_MAX = 4
ASK_HOW_ITEM_MAX = 40   # 依据: 首屏一行约 40 字,一条一句
# 只有 AI 懂的词(1114,先只记不拦一周):英文代号(下划线 / 驼峰标识符、.py/.js/.html 文件名)或本机内部叫法
#   ⚠ 中文和英文之间没有 \b(两边都算 \w)⇒ 边界用「前后不是英文字母数字」;驼峰只认小写打头(iPhone 这类大家都懂的词放过)
_ASK_JARGON_RE = re.compile(r"(?<![A-Za-z0-9])(?:[A-Za-z][A-Za-z0-9]*_[A-Za-z0-9_]+|[a-z]+[A-Z][A-Za-z0-9]*|[A-Za-z0-9_.-]+\.(?:py|js|html))(?![A-Za-z0-9])"
                            r"|守护|巡检|终态|闸|钩子|子线|投影|盖戳|(?i:lint|selftest)")
_ASK_JARGON_OK = {"iPhone", "iPad", "iOS", "iCloud", "macOS", "eBay"}


_GOT_REWRITE_HOLE = "<改写这条结果>"   # 依据: 11-23 审查，结果切不开时按回答正文留占位。
_HOW_REWRITE_HOLE = "<改写这条做法>"   # 依据: 同上，做法切不开时按回答正文留占位。


def _last_prose_cut(text, width, punctuation):
    """返回限宽内最后一个标点的结束位置，网址里的标点不算。"""
    probe = re.sub(r"https?://\S+", lambda m: "\0" * len(m.group(0)), text)
    return max((m.end() for m in re.finditer(punctuation, probe) if m.end() <= width), default=0)


def _ask_how_items(how):
    return [part.strip() for part in str(how or "").split("|") if part.strip()]


def _split_ask_how(items):
    if all(len(item) <= ASK_HOW_ITEM_MAX for item in items):
        return None
    parts = []
    for item in items:
        split = ([item] if len(item) <= ASK_HOW_ITEM_MAX
                 else _split_at_sentence_end(item, ASK_HOW_ITEM_MAX, ASK_HOW_MAX))
        if not split:
            return None
        parts.extend(split)
    return parts if len(parts) <= ASK_HOW_MAX else None


def _ask_body_problem(why, how, report=None, *, shortened=None):
    """ask 的 --why 超 ASK_WHY_MAX 字 / --how 超 ASK_HOW_MAX 条或某条超 ASK_HOW_ITEM_MAX 字 ⇒ 一句说明;合规 ⇒ None。纯函数。"""
    w = re.sub(r"\s+", "", str(why or ""))
    if len(w) > ASK_WHY_MAX:
        problem = ('--why(前因后果)有 %d 字,超过 %d 字 —— 他看到的是一坨字。写不下就拆进 --how 一条一句,或做方案页(plan.py)挂 --deep'
                % (len(w), ASK_WHY_MAX))
        if report is None:
            return problem
        report('ask-why-length', problem)
    hw = _ask_how_items(how)
    if len(hw) > ASK_HOW_MAX:
        problem = '--how 有 %d 条,最多 %d 条 —— 他看不完(负责人 11-13 起点「看不懂」的卡里有「11 条建议一坨字」);多的做方案页挂 --deep' % (len(hw), ASK_HOW_MAX)
        if report is None:
            return problem
        report('ask-how-count', problem)
    for i, x in enumerate(hw, 1):
        if len(x) > ASK_HOW_ITEM_MAX:
            problem = '--how 第 %d 条有 %d 字,超过 %d 字 —— 一条一句,写不下拆成两条或做方案页' % (i, len(x), ASK_HOW_ITEM_MAX)
            if report is None:
                return problem
            if shortened is not None:
                end = _last_prose_cut(x, ASK_HOW_ITEM_MAX, r"[，,、。；;！!？?]+")
                shortened[i - 1] = x[:end]
                if end:
                    problem += "\n  ⇒ 可先截到标点处:「%s」(核对做法是否完整)" % x[:end]
            report('ask-how-length', problem)
    return None


def _ask_soft_hints(q, why, how, deep):
    """只提醒不拦的一条(1114 只 AI 懂的词;带 --deep 没写 --how 1115 起改成拒写,见 _ask_deep_how_problem):[(记号, 一行提示)]。纯函数。"""
    out = []
    hits = []
    for t in (q, why, how):
        for m in _ASK_JARGON_RE.finditer(str(t or "")):
            if m.group(0) not in hits and m.group(0) not in _ASK_JARGON_OK:
                hits.append(m.group(0))
    if hits:
        out.append(("ask-jargon", "  ⚠ 卡上有只有 AI 懂的词:%s —— 他看不懂;换成他会说的话(只提醒,不拦;先记一周看命中)" % "、".join(hits[:6])))
    return out


def _ask_deep_how_problem(deep, how):
    """⭐ 1115 sw-how(负责人 11-15 00:49 选「改成拦」):ask 带 --deep(要他批一个方案)却没写 --how(批了以后改成什么样)⇒ 拒写的话;否则 None。纯函数。
    起因:负责人 11-14 15:54 在 ask-4d24a8ae:「这张卡我没太搞懂到底要改成什么样的写法」(例子只在方案页里);原来只提醒(ask-deep-no-how),照样挂上去。"""
    if not str(deep or "").strip() or [x for x in str(how or "").split("|") if x.strip()]:
        return None
    return ('带了 --deep(要他批一个方案)却没写 --how:卡上看不出批了以后改成什么样(负责人 11-14 在 ask-4d24a8ae:「这张卡我没太搞懂到底要改成什么样的写法」)。\n'
            '   ⇒ 加 --how "改前是什么样 → 改后是什么样|第二步|批了你会看到什么"(≤%d 条、每条 ≤%d 字);改的是他看到的样子,再加 --img 放改前改后对比图' % (ASK_HOW_MAX, ASK_HOW_ITEM_MAX))


def _ask_rec_dup(rec, opts):
    """--rec 和第一个 --opt 的标题去空白后相同 ⇒ True(第一个选项本来就标「建议」,「我的建议」一块重复)。纯函数。"""
    if not opts:
        return False
    first = str(opts[0]).partition("|")[0]
    return bool(re.sub(r"\s+", "", str(rec or ""))) and re.sub(r"\s+", "", str(rec or "")) == re.sub(r"\s+", "", first)


# ⭐ 1116 周修(负责人 11-13 23:19 电商-基建 #e4f1:「做到哪里面是一大坨字……里面还有两句话是重复的」;11-16 周复查「看得懂吗」节):
#   kit 只在显示时去重(acceptDoingNode),作者照样写重复 ⇒ 挂卡那一刻拦:
#   验收卡每条 --got、普通卡 --why(前因后果)每一句,去掉标点空白后与 --q(去掉标点和句尾「通过吗 / 行吗 / 同意吗…」)
#   一方包含另一方(较短一方 ≥ CARD_DUP_MIN 字)或相似度 ≥ CARD_DUP_RATIO ⇒ 拒写。
#   否过什么:⛔ 不只看逐字相同 —— 实际的重复是「标题 = 结果 + 通过吗」;⛔ 不查 --rec / 选项(那是答案,本来就会和标题呼应)。
CARD_DUP_RATIO = 0.8   # 依据: 11-16 周复查任务书给的判据「去标点后包含或相似度 ≥0.8」
CARD_DUP_MIN = 6       # 依据: 不到 6 字的短语(「已上线」「换白底」)出现在标题里是常事,只算包含会误拦
_CARD_DUP_PUNCT_RE = re.compile(r"[\W_]+")
_CARD_DUP_TAIL_RE = re.compile(r"(?:(?:验收)?(?:通过|同意|可以|行|好|对|批准|确认)?吗|行不行|好不好|对不对|要不要)$")
_CARD_DUP_SENT_RE = re.compile(r"[。；;！？!?\n]+")


def _card_dup_norm(t, q=False):
    s = _CARD_DUP_PUNCT_RE.sub("", str(t or ""))
    return _CARD_DUP_TAIL_RE.sub("", s) if q else s


def _card_dup_same(a, q):
    """a(一条 --got / --why 的一句)和标题 q 是不是在说同一句。纯函数。"""
    import difflib as _dfl
    na, nq = _card_dup_norm(a), _card_dup_norm(q, q=True)
    if not na or not nq:
        return False
    short, long_ = (na, nq) if len(na) <= len(nq) else (nq, na)
    if len(short) >= CARD_DUP_MIN and short in long_:
        return True
    return len(short) >= CARD_DUP_MIN and _dfl.SequenceMatcher(None, na, nq).ratio() >= CARD_DUP_RATIO


def _card_dup_q_problem(q, gots=None, why=None, report=None):
    """--got 某条 / --why 某句和 --q 说的是同一句 ⇒ 拒写的话;否则 None。纯函数。"""
    for i, g in enumerate(gots or [], 1):
        if _card_dup_same(g, q):
            problem = ('第 %d 条 --got「%s」和标题 --q 说的是同一句 —— 做到哪写现在的结果,别重复标题'
                    '(负责人 11-13:「做到哪里面……还有两句话是重复的」)' % (i, re.sub(r"\s+", " ", str(g)).strip()[:40]))
            if report is None:
                return problem
            report('got-duplicate-title', problem)
    for i, s in enumerate([x.strip() for x in _CARD_DUP_SENT_RE.split(str(why or "")) if x.strip()], 1):
        if _card_dup_same(s, q):
            problem = ('--why 第 %d 句「%s」和标题 --q 说的是同一句 —— 做到哪写现在的结果,别重复标题;前因后果只写这件事从哪来,这句删掉'
                    '(负责人 11-13:「做到哪里面……还有两句话是重复的」)' % (i, s[:40]))
            if report is None:
                return problem
            report('why-duplicate-title', problem)
    return None


# ⭐ 1116 讲人话(负责人 11-16 11:18 在电商-基建卡 ask-5d701b19 点「不通过」:「这个我没太看懂你在说什么……你的验收卡就很大的问题,就是不讲人话。
#   你这边验收的很多事情,我根本就看不懂你到底干了什么……毕竟这验收卡老是不讲人话,看得很累。」
#   那张卡标题「出单来源改读主站渠道号接口:在香港读通了」,做到哪写「接口」「本地名单」「退出码 2」「未命名号」,没说他在哪个页面能看到什么变化)。
#   11-14 他批过「所有卡一种写法、写不清当场拒」(ask-4d24a8ae)⇒ 直接拒写,不走只记不拦。
#   查哪些:验收卡 --q / 每条 --got / --todo / --see(row --review 与 _review_add 两处),普通卡 ask 的 --q / --why。
#   判法:英文词按词边界(前后不是英文字母数字,不分大小写:Approve / printer 里的 pr 不算);中文按整词;
#     个别词带「正常业务说法」例外(充电接口 / 视频脚本 / 商品参数 / 开头钩子),先把例外抹掉再找。
#   否过什么:⛔ 不放「香港 / 主站 / 渠道 / 出单」这类地名、业务词(他天天说的话);
#     ⛔ 不再只提醒 —— 1114 起「只有 AI 懂的词」提醒(ask-jargon)挂了两天,11-16 那张卡照样满是内部词。
# 依据: 任务书 weekly-1116/F-brief.md 第 1 条起步词表 = 11-16 打回那张卡里的词 + 各线验收卡上常见的内部叫法
# 1117 晚 I:撤「接口」「API」—— 依据 11-17 投流线的回答卡引用他自己的原话被拦(他问的就是接口 / API;他自己说的词不算内部词)
PLAIN_WORDS = ("退出码", "exit", "脚本", "部署", "读回", "兜底", "字段", "PR", "commit", "提交号", "哈希",
               "hook", "钩子", "lint", "selftest", "自检", "变异", "正本", "sync", "子代理", "闸", "本地名单", "未命名号",
               "参数", "报错码", "json", "日志")
# 正常业务说法(电商卖手机配件、做带货视频,这些是他会说的话)⇒ 先抹掉再找
_PLAIN_OK_RE = re.compile(r"(?:充电|耳机|USB|Type-?C|数据线|网线|网口|音频|电源|硬件|Lightning|HDMI)\s*接口"
                          r"|(?:视频|拍摄|口播|直播|带货|分镜|短视频|广告|剧情)\s*脚本"
                          r"|(?:产品|商品|规格|技术|相机|拍摄|配置|尺寸)\s*参数"
                          r"|(?:开头|视频|前\s*[3三]\s*秒|黄金\s*[3三]\s*秒)\s*(?:钩子|hook)", re.I)
_PLAIN_RE = re.compile("|".join(("(?<![A-Za-z0-9])%s(?![A-Za-z0-9])" % re.escape(w)) if re.fullmatch(r"[A-Za-z]+", w) else re.escape(w)
                                for w in PLAIN_WORDS), re.I)
PLAIN_EXAMPLE = '别写「脚本跑通了」,写「出单看板的来源一栏现在显示主站的渠道名」'


def _plain_hits(t):
    """一段卡面文字里的内部词(按出现顺序、去重)。纯函数。"""
    s = _PLAIN_OK_RE.sub(lambda m: " " * len(m.group(0)), str(t or ""))
    out = []
    for m in _PLAIN_RE.finditer(s):
        if m.group(0) not in out:
            out.append(m.group(0))
    return out


def _plain_problem(fields, exempt=None, report=None):
    """fields = [(参数名, 文本 或 [文本…])] ⇒ 第一处有内部词的:拒写的话(报出命中的词 + 改写例子);都没有 ⇒ None。纯函数。
    exempt = 他自己的原话(回答卡的行标题,1117 晚 I):里面出现过的词不算内部词。"""
    for name, val in fields:
        vals = list(val) if isinstance(val, (list, tuple)) else [val]
        for i, v in enumerate(vals, 1):
            h = [x for x in _plain_hits(v) if not (exempt and x.lower() in str(exempt).lower())]
            if h:
                lab = name if len(vals) == 1 else "第 %d 条 %s" % (i, name)
                msg = ('%s 里有他看不懂的内部词:%s —— 卡上只写他在哪看到什么变化。\n'
                        '  例:%s;眼下看不出变化就写「看不出变化:<为什么,和你有什么关系>」\n'
                        '  (负责人 11-16:「验收卡老是不讲人话,看得很累」)' % (lab, "、".join("「%s」" % x for x in h[:6]), PLAIN_EXAMPLE))
                if report is None:
                    return msg
                original = str(v)
                at = original.lower().find(h[0].lower())
                snippet = _clause(original[max(0, at - 36):at + 80], 120)
                report("internal-words", msg + "\n  原文:「%s」" % snippet)
    return None


# ⭐ 1116 讲人话 ②:验收卡必须写「你在哪能看到什么变化」(--see),卡上标题下第一行「去哪看:…」。
#   ⛔ 不做「看不到变化就不许挂验收」:他 11-13 定过「派下去的每件事都要验收」⇒ 看不出变化写清为什么、和他有什么关系。
#   否过什么:⛔ 不拿 --check 顶 —— --check 只在有 --url 时上卡(入口按钮旁),11-16 那张卡没有入口,他照样不知道去哪看。
REVIEW_SEE_MAX = 50     # 依据: 任务书「≤50 字」,与标题 CARD_Q_MAX 同一口径(首屏一行)
REVIEW_SEE_WHY_MIN = 6  # 依据: 「看不出变化:」后面短于 6 字说不清为什么、和他有什么关系(「没有」「后台的」)
_SEE_NONE_RE = re.compile(r"^看不(?:出|到|见)(?:什么)?(?:变化|来)?\s*(?:[::]\s*(.*))?$")
# ⭐ 1117 J7 rt-nochange(负责人 11-16 20:48 在复盘页选「写着『看不出变化』的事并进每日小修清单,逐条可打回」;复盘:11-16 中午后新挂的验收卡约三成写着看不出变化,他点开也看不到东西)。
#   row --review 的 --see 以「看不出变化」开头 ⇒ 不单挂卡,自动走 --small 那条路(并进当天小修清单,他逐条可打回);作者不用加 --small。
#   带 --img / --url / --todo 照旧拒(有图 / 有页面 / 还要他做事 = 看得出变化或不是小修)。
#   标题或 --got 里有机制词(自动 / 定时 / 防再犯 / 每天 / 每周 / 守护)⇒ 先只记不拦:照进清单,board-hints.log 记 small-maybe-mech,11-23 看误判再定拦不拦
#   (复盘原话:「写着自动、定时、防再犯的不许进清单,先只记不拦一周看误判」;ai-dev-loop「加新的拦截先只记不拦跑一周」)。
SMALL_MECH_RE = re.compile(r"自动|定时|防再犯|每天|每周|守护")


def _see_no_change(see):
    """--see 是不是以「看不出变化」开头(同 _SEE_NONE_RE 那一族说法)。纯函数。"""
    return bool(_SEE_NONE_RE.match(re.sub(r"\s+", " ", str(see or "")).strip()))


def _small_mech_hit(title, gots):
    """小修的行标题 / --got 里有没有机制词 ⇒ 那个词或 None。纯函数。"""
    m = SMALL_MECH_RE.search(" ".join([str(title or "")] + [str(g or "") for g in (gots or [])]))
    return m.group(0) if m else None


def _review_see_text(text, markup=False):
    """把「去哪看」里的方案页网址显示为「打开方案页」；字数闸也按显示的字算。"""
    from html import escape
    parts = [text] if _proposal_answer_page(text) else re.split("(" + _PROPOSAL_URL_RE.pattern + ")", text)
    bits = []
    for part in parts:
        if _proposal_answer_page(part):
            label = "打开方案页"
            bits.append('<a class="autolink" href="%s">%s</a>' % (escape(part, quote=True), label) if markup else label)
        else:
            bits.append(_esc(part) if markup else part)
    return "".join(bits)


def _review_see_problem(see, report=None):
    """验收卡的 --see:必填、≤REVIEW_SEE_MAX 字;「看不出变化」要带「:为什么」;不写「见对话」;合规 ⇒ None。纯函数。"""
    t = re.sub(r"\s+", " ", str(see or "")).strip()
    if not t:
        problem = ('验收卡要写 --see「你在哪能看到什么变化」(≤%d 字),原样出在卡标题下第一行「去哪看:…」。\n'
                '  例:--see "出单看板 → 来源一栏,现在显示主站的渠道名"\n'
                '  眼下看不出变化 ⇒ --see "看不出变化:新单下周才进来,到时出单看板来源一栏会变"(⛔ 不因为看不出变化就不挂验收)\n'
                '  (负责人 11-16:「我根本就看不懂你到底干了什么」)' % REVIEW_SEE_MAX)
        if report is None:
            return problem
        report('see-missing', problem)
        return None
    t = _review_see_text(t)
    if len(t) > REVIEW_SEE_MAX:
        problem = '--see 有 %d 字,超过 %d 字 —— 只写哪个页面、哪一块、看到什么,怎么做的别写' % (len(t), REVIEW_SEE_MAX)
        if report is None:
            return problem
        report('see-length', problem)
    m = _SEE_NONE_RE.match(t)
    if m and len(re.sub(r"\W+", "", m.group(1) or "")) < REVIEW_SEE_WHY_MIN:
        problem = ('--see 写了看不出变化,还要接着写为什么、和你有什么关系(例:「看不出变化:新单下周才进来,到时出单看板来源一栏会变」)')
        if report is None:
            return problem
        report('see-no-change-reason', problem)
    if _SEE_ELSEWHERE_RE.search(t):
        problem = '--see 写了「%s」—— 他只看卡,把去哪看直接写进来' % _SEE_ELSEWHERE_RE.search(t).group(0)
        if report is None:
            return problem
        report('see-reference', problem)
    return None



# ⭐ 1117「怎么来的」(负责人 11-17 12:13 方案页「板这一侧改 5 处」第 2 条,整组批「都按建议做」):
#   验收卡上只写「看板好了」,他不知道这份数是从官方数据口取的、还是照着网页一格格读的、多久一次、拿什么真数对过 ——
#   照着网页读 / 人工抄的数,页面一改版就悄悄错。⇒ row --review 加 --src / --freq / --proved(--src page|manual 再加 --why-not-direct),
#   卡上固定一行「怎么来的:<来源> · 多久一次:… · 对过:…」,在「去哪看」下面。
#   必填:--q / --got 里有下面的词(或问「怎么实现」那组,见下);小修卡不要求;「不做了」卡(--drop)没有结果可说来源,也不要求。
#   1117 晚收窄(状态板线):⛔ 带 --url 本身不再触发 —— 给他挂「看一眼样例页」的验收卡被逼写数据来源,样例页不是数据;只按词判。
#   1117 晚 A(状态板线转负责人 14:25 截图:问「监控怎么实现的」,卡上只写「已上线并核过数,请验收」):问「怎么实现」那组词(REVIEW_HOW_ASK_RE)
#     卡标题和行标题都查,命中报「他问的是怎么实现的」;下面「不查行标题」只管监控类九个词。
#   否过什么:⛔ 不查行标题 —— 方案页写的是「标题 / --got」,卡标题(--q)才是他在卡上读到的那句;提问行省了 --q 时卡标题就是行标题,照查。
REVIEW_SRC_SHOW = {"official": "官方数据口", "backend": "后台导出", "page": "照着网页读", "manual": "人工"}   # 依据: 负责人 11-17 批的方案页原文四种叫法
REVIEW_HOW_WORDS_RE = re.compile(r"监控|跟踪|抓|同步|定时|每天|每周|看板|报表")   # 依据: 同上方案页原文词表(九个词一字不改)
REVIEW_HOW_ASK_RE = re.compile(r"怎么实现|如何实现|怎么做的|怎么做到|怎么来的|怎么抓|怎么拿|怎么算|从哪来|靠什么")   # 依据: 状态板线 11-17 转来的词表(十个,一字不改)
REVIEW_HOW_MAX = 30          # 依据: 未验证 —— 「多久一次」「拿哪个真数对过」各一句话;30 字约首屏半行,卡上一行放得下三段
REVIEW_WHY_DIRECT_MAX = 60   # 依据: 负责人 11-17 批的方案页原文「≤60 字」
REVIEW_HOW_EXAMPLE = '--src official --freq "每天 9 点一次" --proved "拿后台 11-16 的订单数对过,一致"'


def _review_how_needed(url, q, gots, titles=()):
    """这张验收卡要不要写「怎么来的」⇒ "ask"(卡标题或行标题问的是怎么实现的,1117 晚 A)/ True(标题 / 结果里有监控类词)/ False。纯函数。
    url 留着只为调用处不改:1117 晚起带入口本身不触发(样例页不是数据)。"""
    # 1117 晚:书名号里的是在引用别处的话(「投流线那张『监控怎么实现的』卡答非所问」说的是那张卡,不是他在问),去掉再判。
    #   否过:⛔ 只看行有没有标 --asked —— 普通验收行他也会问「怎么算的」(用例「--q 问怎么算 ⇒ 拒」)。
    _ask_txt = re.sub(r"「[^」]*」|『[^』]*』", "", " ".join([str(q or "")] + [str(t or "") for t in (titles or ())]))
    if REVIEW_HOW_ASK_RE.search(_ask_txt):
        return "ask"
    return bool(REVIEW_HOW_WORDS_RE.search(" ".join([str(q or "")] + [str(g or "") for g in (gots or [])])))


def _review_how_args(a):
    """row 的 --src / --freq / --proved / --why-not-direct ⇒ dict;四个都没给 ⇒ None。"""
    v = {k: getattr(a, n, None) for k, n in (("src", "how_src"), ("freq", "freq"), ("proved", "proved"), ("why", "why_not_direct"))}
    return v if any(x is not None for x in v.values()) else None


def _review_how_problem(how, needed=False, report=None):
    """「怎么来的」那几项:needed 而没给 / 给了不全 / 超长 / page·manual 没写为什么 ⇒ 拒写的话(带一条可照抄的写法);合规 ⇒ None。纯函数。"""
    if not how:
        if not needed:
            return None
        if needed == "ask":                               # 1117 晚 A
            problem = ('他问的是怎么实现的 —— 卡上要写清怎么来的(来源 / 多久一次 / 拿哪个真数对过),只写『已上线、核过数』等于没答。\n'
                    '  例:%s\n'
                    '  --src 四选一:official 官方数据口 · backend 后台导出 · page 照着网页读 · manual 人工;page / manual 还要 --why-not-direct "为什么不走官方的"'
                    % REVIEW_HOW_EXAMPLE)
            if report is None:
                return problem
            report('review-source-missing', problem)
            return None
        problem = ('这张验收卡要写「怎么来的」(标题 / 结果里有监控、跟踪、抓、同步、定时、每天、每周、看板、报表):'
                '他得知道这份数从哪来、多久一次、拿什么真数对过。\n'
                '  例:%s\n'
                '  --src 四选一:official 官方数据口 · backend 后台导出 · page 照着网页读 · manual 人工;page / manual 还要 --why-not-direct "为什么不走官方的"'
                % REVIEW_HOW_EXAMPLE)
        if report is None:
            return problem
        report('review-source-missing', problem)
        return None
    src = str(how.get("src") or "").strip()
    freq, proved, why = (re.sub(r"\s+", " ", str(how.get(k) or "")).strip() for k in ("freq", "proved", "why"))
    if src not in REVIEW_SRC_SHOW:
        problem = '--src 只认 official / backend / page / manual(官方数据口 / 后台导出 / 照着网页读 / 人工)\n  例:%s' % REVIEW_HOW_EXAMPLE
        if report is None:
            return problem
        report('review-source-value', problem)
    if not freq or not proved:
        problem = '「怎么来的」要写全:--freq「多久一次」和 --proved「拿哪个真数对过」都要\n  例:%s' % REVIEW_HOW_EXAMPLE
        if report is None:
            return problem
        report('review-source-details', problem)
    if len(freq) > REVIEW_HOW_MAX or len(proved) > REVIEW_HOW_MAX:
        problem = '--freq / --proved 每条 ≤%d 字(现在 %d / %d 字)—— 一句话:多久一次、拿哪个真数对过' % (REVIEW_HOW_MAX, len(freq), len(proved))
        if report is None:
            return problem
        report('review-source-length', problem)
    if src in ("page", "manual") and not why:
        problem = ('--src %s(%s)要再写 --why-not-direct「为什么不走官方的」(≤%d 字),卡上接在那行后面「没走官方路子因为:…」\n'
                '  例:--why-not-direct "官方数据口没有这一栏,后台也导不出"' % (src, REVIEW_SRC_SHOW[src], REVIEW_WHY_DIRECT_MAX))
        if report is None:
            return problem
        report('review-source-why', problem)
    if why and src not in ("page", "manual"):
        problem = '--why-not-direct 只配 --src page / manual(走官方数据口 / 后台导出不用解释)'
        if report is None:
            return problem
        report('review-source-why-mode', problem)
    if len(why) > REVIEW_WHY_DIRECT_MAX:
        problem = '--why-not-direct 有 %d 字,超过 %d 字 —— 一句话说清为什么不走官方的' % (len(why), REVIEW_WHY_DIRECT_MAX)
        if report is None:
            return problem
        report('review-source-why-length', problem)
    return None


# ⭐ 1116 讲人话 ④(电商-基建 #b6c2):盯着 / 卡着的行,现状第一句写「已了结 / 已上线 / 已做完……」,后面才是要等的那个日子
#   ⇒ 他读第一句以为做完了,其实这一行还挂着一件等日子的事。提醒拆成两行:做完的那件交验收,这一行只留那个日子的待办。
#   只提醒、不拦(lint warn)。否过什么:⛔ 不并进写行时的 done-first(那条只管 todo / doing / blocked,watch 在 1110 判过不报;
#     这里管的是「两件事挤一行」,改法不同)。⛔ 子句前面有「等 / 没 / 未 / 还」的不算(「等基建上线了再接」是在等)。
_WATCH_DONE_FIRST_RE = re.compile(r"^[^等没未还待]{0,10}?(已了结|了结了|已做完|做完了|已上线|上线了|已办完|已办好|已办妥|已办(?![理法])|已完成|已合并|已发布|已修好|已交付|已收尾|已全部(?:做完|上线|合并|完成))")


def _watch_done_first_hit(f):
    """这一行是不是「盯着 / 卡着、现状第一句却是完成语」:是 ⇒ 那第一句;不是 ⇒ None。纯函数(_watch_done_first_warns / _done_first_mark 共用)。"""
    if f.get("st") not in ("watch", "blocked"):
        return None
    first = re.split(r"[。;；,，!！?？\n]", str(f.get("why") or "").strip())[0].strip()
    return first if _WATCH_DONE_FIRST_RE.match(first) else None


# ⭐ 1116 板腐烂 7(电商-基建 #f2c6②):第一句完成语的提醒 839d3624 已加,可提醒只在 touch / lint 输出里,没人处理就一直挂着。
#   ⇒ touch 第一次看到这一行这样写时记 data-df-at=<那一刻>(已有的不盖);改好了(不再是完成语 / 不再盯着卡着)touch 拿掉。
#   连着挂满 DONE_FIRST_RED_H 小时 ⇒ kit 在他首屏「卡着的」标红(和「等了 N 天没人追」同一种红,kit doneFirstHours),lint 那句加一句「已挂满 N 小时」。
#   仍只提醒、不拦写。否过什么:⛔ 不按 data-txt-at 算(这条提醒 11-16 中午才上线,按改字时间算会把早就这样写的行当天全标红,不是「连续提醒满 24 小时」)。
# 依据: 任务书 #f2c6②「同一行连续提醒满 24 小时没处理 ⇒ 报到首屏」
DONE_FIRST_RED_H = 24


def _df_hours(f, now=None):
    """这一行 data-df-at 起到现在几个整小时;没记 / 读不懂 ⇒ None。"""
    try:
        t0 = datetime.datetime.strptime(str(f.get("df_at") or ""), "%Y-%m-%dT%H:%M")
    except ValueError:
        return None
    return int(((now or datetime.datetime.now()) - t0).total_seconds() // 3600)


def _watch_done_first_warns(src, today=None, now=None):
    """「你交代的」里盯着(watch)/ 卡着(blocked)的行,现状第一句(到第一个标点)是完成语 ⇒ [提醒];没有 ⇒ []。纯函数。"""
    y = _yours_zone_rows(src, today=today)
    out = []
    for f in (y["facts"] if y else []):
        first = _watch_done_first_hit(f)
        if first:
            h = _df_hours(f, now)
            out.append("「你交代的」%s 标着%s,现状第一句却是「%s」—— 拆成做完行 + 只剩那个日子的待办:做完的那件另开一行交验收(`row --review`),"
                       "这一行只留要等的那个日子(例:「11-20 看出单数」)。%s(只提醒,不拦)"
                       % (_row_label(f), "盯着" if f["st"] == "watch" else "卡着", _clause(first, 20),
                          ("这句已经连着提醒了 %d 小时没拆,他首屏「卡着的」已标红。" % h) if (h is not None and h >= DONE_FIRST_RED_H) else ""))
    return out


def _done_first_mark(src, now=None):
    """touch 那一步:第一句完成语的行记 data-df-at(已有的不盖),不再是的拿掉 ⇒ (新文本, 记了几行, 拿掉几行)。纯函数。没 data-ack 的行不管。"""
    now_s = (now or datetime.datetime.now()).strftime("%Y-%m-%dT%H:%M")
    y = _yours_zone_rows(src)
    n_set = n_clr = 0
    for f in (y["facts"] if y else []):
        if not f.get("ack"):
            continue
        hit = bool(_watch_done_first_hit(f))
        if hit == bool(f.get("df_at")):
            continue
        try:
            a, b, _z = _row_span(src, f["ack"])
        except ValueError:
            continue
        src = src[:a] + _attr_set(src[a:b], "data-df-at", now_s if hit else None) + src[b:]
        if hit:
            n_set += 1
        else:
            n_clr += 1
    return src, n_set, n_clr


# ⭐⭐ 1116 板腐烂三线反馈(负责人 11-16 下午让各线查自己板烂没烂;电商-基建 #f2c6、电商-选品 #e4a9、AI Harness #3f8a 报来机器没接住的几类)。
#   下面五条(任务书第 2–6 条)全是 lint 提醒(touch / head 都会顺手 lint),⛔ 不拦写:先只记不拦跑一周看命中再定(ai-dev-loop「加新的拦截先只记不拦」)。
#   否过什么:⛔ 编号对不上的回执不猜是哪一行(#e4a9 / #3f8a 都说过「猜错比不报更烦」);⛔ ntc 行按任务名去重不在这里(拉行脚本归电商-基建,它已修);
#     ⛔ 检查点里没上板的未做事项不在这里(handoff-yours-check.py 归 AI Harness)。
# 依据: 回执多在当天到;两周前的回执不再拿来比(避免很久以前的同号回执误报)
ROT_INBOX_DAYS = 14
# 依据: 信箱 jsonl 一行一封;一条线两周进信 < 500 封(11-16 实数:电商-基建 478 封是从开箱起的总数)
ROT_INBOX_TAIL = 1500
# 已撤机制词表(任务书第 5 条):[(在行里怎么写, 哪天撤的)]。新撤一个机制就往这里加一行。
# 依据: 负责人 11-15 撤掉验收卡分三档 / 标档(AI Harness #3f8a②;板上还有行在等它)
ROT_RETIRED = (("三档", "11-15"), ("标档", "11-15"), ("--tier", "11-15"))
ROT_SCHED_DIR = os.path.expanduser("~/.claude/scheduled-tasks")
_ROT_ASKID_RE = re.compile(r"(?<![0-9A-Za-z])(ask-[0-9a-f]{8})(?![0-9A-Za-z])")   # 依据: 卡号 = "ask-" + sha1 前 8 位(_ask_card_html)
_ROT_CODE_RE = re.compile(r"#([0-9a-fA-F]{4})(?![0-9A-Za-z])")
_ROT_RCODE_RE = re.compile(r"回执\s*#([0-9a-fA-F]{4})(?![0-9A-Za-z])")
_ROT_ACK_RE = re.compile(r"(?<![0-9A-Za-z-])(r\d{4}-[0-9a-z]+(?:-[0-9a-z]+)*)")
_ROT_WAITREPLY_RE = re.compile(r"等\s*([^\s,，。;；、:：()（）]{1,12}?)\s*(回复|回话|回信|确认|回(?![执来去滚本退收访顾头升落归应家国到]))")
_ROT_RETIRED_DONE_RE = re.compile(r"撤|废|停用|不再|取消|不用了")
_ROT_SCHED_TOKEN_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.-]{3,}")


def _rot_stamp(v):
    """行上「YYYY-MM-DDTHH:MM」⇒ epoch 秒;读不懂 ⇒ None。"""
    try:
        return time.mktime(time.strptime(str(v or "")[:16], "%Y-%m-%dT%H:%M"))
    except ValueError:
        return None


def _rot_row_seen(f):
    """这一行最近一次被人核过 / 改过的时刻(epoch 秒):改字 · --checked · 开始等 里最晚的;都没有退回 data-upd / data-fp0;再没有 ⇒ None。"""
    ts = [t for t in (_rot_stamp(f.get(k)) for k in ("txt_at", "chk_at", "wait_since")) if t is not None]
    if ts:
        return max(ts)
    for k in ("upd", "fp0"):
        t = _rot_stamp(f.get(k))
        if t is not None:
            return t
    return None


def _rot_line_of(title):
    """会话标题 / 发信人 ⇒ 线名(去掉末尾版本号;与 inbox.js lineOf 同一条)。"""
    return re.sub(r"\s*v\d+(\.\d+)*\s*$", "", str(title or "").strip(), flags=re.I).strip()


def _rot_inbox_dir():
    return os.environ.get("INBOX_DIR") or BP.state("inbox")


def _rot_inbox_file(line, inbox_dir=None):
    return os.path.join(inbox_dir or _rot_inbox_dir(), re.sub(r"[/\\:]", "_", line) + ".jsonl")


def _rot_board_lines(path, src, inbox_dir=None):
    """这块板归哪几条线(只留信箱文件在的):认主人(_accept_owner)· launch-titles 学到的「线名 → 板」· 板文件名 · <title>;
    都对不上再用叫醒那一套认法(_accept_owner_fallback)。⛔ 认不出就是 [],不猜。只读。"""
    fn = os.path.basename(path)
    stem = fn[:-len(".html")] if fn.endswith(".html") else fn
    tm = re.search(r"<title>(.*?)</title>", src, re.S)
    cands = []
    try:
        cands.append(_accept_owner(path, src))
    except Exception:          # noqa: BLE001 —— 认不出主人不挡 lint
        pass
    try:
        cands += [k for k, v in _launch_json_load(_launch_titles_path()).items() if v == fn]
    except Exception:          # noqa: BLE001
        pass
    cands += [stem, re.sub(r"\s*状态板\s*$", "", tm.group(1).strip()) if tm else ""]
    out = []
    for c in cands:
        c = _rot_line_of(c)
        if c and c not in out and os.path.isfile(_rot_inbox_file(c, inbox_dir)):
            out.append(c)
    if not out:
        try:
            _sd, live, state, writes = _wake_ctx()
            c = _rot_line_of(_accept_owner_fallback(fn, state, writes, live, _sd) or "")
            if c and os.path.isfile(_rot_inbox_file(c, inbox_dir)):
                out.append(c)
        except Exception:      # noqa: BLE001
            pass
    return out


def _rot_receipts(lines, inbox_dir=None, now=None):
    """这几条线信箱里近 ROT_INBOX_DAYS 天的回执 ⇒ [dict(at 秒, line 发信线, code 4 位编号或 None)]。读不到 ⇒ []。只读。"""
    now = now or time.time()
    out = []
    for ln in lines:
        try:
            raw = open(_rot_inbox_file(ln, inbox_dir), encoding="utf-8", errors="replace").read().splitlines()[-ROT_INBOX_TAIL:]
        except OSError:
            continue
        for x in raw:
            try:
                m = json.loads(x)
                at = float(m.get("at")) / 1000.0
            except (ValueError, TypeError, AttributeError):
                continue
            tag = str(m.get("tag") or "")
            if not tag.startswith("回执") or now - at > ROT_INBOX_DAYS * 86400:
                continue
            c = _ROT_RCODE_RE.search(tag) or _ROT_RCODE_RE.search(str(m.get("text") or ""))
            out.append(dict(at=at, line=_rot_line_of(m.get("from")), code=c.group(1).lower() if c else None))
    return out


def _rot_line_keys(line, universe):
    """一条线在行里可能怎么被叫:全名;「X-Y」的 Y(全机只有这一条线叫 Y 时才算,「总控」三条线都有 ⇒ 不算)。"""
    keys = {line}
    if "-" in line:
        tail = line.rsplit("-", 1)[1].strip()
        if len(tail) >= 2 and sum(1 for u in universe if u.rsplit("-", 1)[-1].strip() == tail) <= 1:
            keys.add(tail)
    return keys


def _rot_receipt_warns(facts, receipts, universe=(), consumed=None):
    """任务书第 2 条(电商-基建 #f2c6①、AI Harness #3f8a①):在等回执的行,回执到了板上不知道。纯函数。
    行的「在等 / 现状」里写着 #xxxx,信箱里有同号回执、晚于这一行上次核过 ⇒ 提醒;编号对不上不猜;
    只写了线名(没写编号)的,那条线在这一行上次核过之后发来过回执 ⇒ 弱一档提醒。"""
    out = []
    by_code = {}
    for r in receipts:
        if r["code"]:
            by_code.setdefault(r["code"], []).append(r)
    senders = sorted({r["line"] for r in receipts if r["line"]})
    univ = set(universe) | set(senders)
    for f in facts:
        if not f.get("open"):
            continue
        seen = _rot_row_seen(f)
        txt = "%s %s" % (f.get("wait_for") or "", f.get("why") or "")
        codes = [c.lower() for c in _ROT_CODE_RE.findall(txt)]
        hit = False
        for c in dict.fromkeys(codes):
            got = [r for r in by_code.get(c, []) if seen is None or r["at"] > seen]
            if got:
                r = max(got, key=lambda x: x["at"])
                out.append("「你交代的」%s:你等的回执 #%s 已到(%s %s),这一轮核了改行 —— 有结果就交验收或写现在到哪,还要等别的就改 --wait-for。(只提醒,不拦)"
                           % (_row_label(f), c, r["line"] or "未知线", time.strftime("%m-%d %H:%M", time.localtime(r["at"]))))
                hit = True
        # 1117:--wait-for 写的是别的板上的卡(ask-xxxxxxxx),他在那张卡上答了(进了 answers-consumed)⇒ 同一类提醒;同样只报这一行上次核过之后答的
        for aid in dict.fromkeys(_ROT_ASKID_RE.findall(str(f.get("wait_for") or ""))):
            got = [e["rec"] for e in (consumed or []) if isinstance(e, dict) and e.get("id") == aid and isinstance(e.get("rec"), dict)
                   and (seen is None or (_ans_ts_epoch(e["rec"].get("ts")) or 0) > seen)]
            if got:
                r = max(got, key=lambda x: _ans_ts_epoch(x.get("ts")) or 0)
                ch = re.sub(r"\s+", " ", str(r.get("choice") or "")).strip()
                said = ch or ("只写了补充:「%s」" % _clause(re.sub(r"\s+", " ", str(r.get("note") or "")).strip(), 40))
                out.append("「你交代的」%s:你等的卡 %s 他 %s 答了:%s —— 这一轮核了改行:有结果就交验收或写现在到哪,还要等别的就改 --wait-for。(只提醒,不拦)"
                           % (_row_label(f), aid, _ans_when(r.get("ts")), said))
                hit = True
        if hit or codes or not str(f.get("wait_for") or "").strip():
            continue
        wf = str(f.get("wait_for") or "")
        for ln in senders:
            if not any(k in wf for k in _rot_line_keys(ln, univ)):
                continue
            got = [r for r in receipts if r["line"] == ln and (seen is None or r["at"] > seen)]
            if got:
                r = max(got, key=lambda x: x["at"])
                out.append("「你交代的」%s:%s 在你等它之后发来过回执(%s),核一下是不是你等的那件;是就改行,不是就写清在等它哪一件(带 #编号)。(只提醒,不拦)"
                           % (_row_label(f), ln, time.strftime("%m-%d %H:%M", time.localtime(r["at"]))))
                break
    return out


_ROT_BOARD_TEXT = {}


def _rot_find_row(ack, boards=None):
    """全机找 data-ack=ack 的行 ⇒ (板文件名, 状态);找不到 ⇒ None。只读;板文本按 (路径, mtime) 缓存在这一进程里。"""
    pat = re.compile(r'<div\b[^>]*\bdata-ack="%s"[^>]*>' % re.escape(ack))
    for p in (all_boards() if boards is None else boards):
        try:
            k = (p, os.path.getmtime(p))
            t = _ROT_BOARD_TEXT.get(k)
            if t is None:
                t = _ROT_BOARD_TEXT[k] = open(p, encoding="utf-8", errors="replace").read()
        except OSError:
            continue
        for m in pat.finditer(t):
            st = re.search(r'\bdata-status="([^"]*)"', m.group(0))
            if st:
                return os.path.basename(p), st.group(1)
    return None


def _rot_waitdone_warns(facts, find=None):
    """任务书第 3 条(电商-选品 #e4a9②):--wait-for 里写了 rMMDD-xxxx,那一行在同板(或全机)已经做完 ⇒ 提醒。纯函数(find 注入全机查找)。"""
    own = {f.get("ack"): f for f in facts if f.get("ack")}
    out = []
    for f in facts:
        if not f.get("open"):
            continue
        for k in dict.fromkeys(_ROT_ACK_RE.findall(str(f.get("wait_for") or ""))):
            if k == f.get("ack"):
                continue
            if k in own:
                where, done = "这块板上", own[k].get("st") == "done"
            else:
                hit = (find or _rot_find_row)(k)
                if not hit:
                    continue
                where, done = hit[0], hit[1] == "done"
            if done:
                out.append("「你交代的」%s 写着在等 %s,可那一行(%s)已经做完了 —— 这一轮接着做,或者改写现在在等什么。(只提醒,不拦)"
                           % (_row_label(f), k, where))
    return out


def _rot_statewait_warns(facts):
    """任务书第 4 条(电商-选品 #e4a9③):标着在做 / 没开工、没写 --wait-for,现状却写「等 X 回 / 回复 / 确认」⇒ 提醒改成卡着 + --wait-for。纯函数。"""
    out = []
    for f in facts:
        if f.get("st") not in ("todo", "doing") or str(f.get("wait_for") or "").strip():
            continue
        why = str(f.get("why") or "")
        for m in _ROT_WAITREPLY_RE.finditer(why):
            if re.search(r"(不用|不必|无需|没在|不再|别|免得|不等)\s*$", why[max(0, m.start() - 4):m.start()]):
                continue
            if m.group(1) in ("你", "他", *BP.owner_names()):   # 等的是他:不是 --you wait,是挂卡让他点
                todo = "球在他那边就挂卡让他点(`ask`),这一行改成卡着在等他"
            else:
                todo = "球在别人那边就改成卡着、写明在等谁:`row <板> --ack %s --status blocked --you wait --wait-for \"%s\"`" % (f.get("ack") or "<行>", m.group(0))
            out.append("「你交代的」%s 标着%s,现状却写「%s」—— %s;已经回了就写现在到哪。(只提醒,不拦)"
                       % (_row_label(f), "在做" if f["st"] == "doing" else "没开工", m.group(0), todo))
            break
    return out


def _rot_retired_warns(facts, retired=None):
    """任务书第 5 条(AI Harness #3f8a②):没做完的行在等 / 现状点名已撤掉的机制 ⇒ 提醒。同一分句里已经写了撤 / 不再 的不报。纯函数。"""
    out = []
    for f in facts:
        if not f.get("open"):
            continue
        txt = "%s。%s" % (f.get("wait_for") or "", f.get("why") or "")
        for word, day in (ROT_RETIRED if retired is None else retired):
            hit = [c for c in re.split(r"[。;；!！?？\n]", txt) if word in c and not _ROT_RETIRED_DONE_RE.search(c)]
            if hit:
                out.append("「你交代的」%s 在等 / 写着「%s」—— 这件等的东西 %s 撤了,改等什么或收掉(不做了就 `row --drop`)。(只提醒,不拦)"
                           % (_row_label(f), word, day))
                break
    return out


def _rot_sched_warns(facts, sched_dir=None):
    """任务书第 6 条(AI Harness #3f8a③):--checked / --wait-for 写了「定时」—— 没写任务名 ⇒ 提醒带上;
    写了(~/.claude/scheduled-tasks/<名>/SKILL.md 在)⇒ 那个定时的提示里没有这一行的编号 ⇒ 提醒「它不会做」。只读那几个 SKILL.md。"""
    sd = sched_dir or ROT_SCHED_DIR
    out = []
    for f in facts:
        if not f.get("open"):
            continue
        for fld, val in (("--wait-for", f.get("wait_for")), ("--checked", f.get("chk"))):
            val = str(val or "")
            if "定时" not in val:
                continue
            names = [t for t in dict.fromkeys(_ROT_SCHED_TOKEN_RE.findall(val)) if os.path.isfile(os.path.join(sd, t, "SKILL.md"))]
            if not names and f.get("ack") and _rot_sched_has(sd, f["ack"]):
                break        # 没写名字,但有个定时的提示里写着这一行编号 ⇒ 它会做,不催
            if not names:
                out.append("「你交代的」%s 的 %s 写着「定时」却没写是哪个定时 —— 带上任务名(%s 下的目录名),机器才核得了它会不会做这件。(只提醒,不拦)"
                           % (_row_label(f), fld, sd.replace(os.path.expanduser("~"), "~")))
                break
            miss = []
            for n in names:
                try:
                    body = open(os.path.join(sd, n, "SKILL.md"), encoding="utf-8", errors="replace").read()
                except OSError:
                    continue
                if not f.get("ack") or f["ack"] not in body:
                    miss.append(n)
            if miss:
                out.append("「你交代的」%s 写着等定时「%s」处理,可那个定时的提示里没有这一行的编号 %s —— 它不会做这件:把编号和要做的写进那个定时的提示,或改等别的。(只提醒,不拦)"
                           % (_row_label(f), "、".join(miss), f.get("ack") or "(这一行没编号)"))
                break
    return out


def _rot_sched_has(sd, ack):
    """定时任务目录里有没有哪个 SKILL.md 写着这一行编号。只读。"""
    try:
        for n in os.listdir(sd):
            try:
                if ack in open(os.path.join(sd, n, "SKILL.md"), encoding="utf-8", errors="replace").read():
                    return True
            except OSError:
                continue
    except OSError:
        pass
    return False


def _rot1116_warns(path, src, now=None, inbox_dir=None, sched_dir=None, find=None, lines=None, consumed=None):
    """lint 那一步:任务书第 2–6 条的提醒合在一起。⛔ 只读(信箱、别的板、定时提示都只读)。"""
    y = _yours_zone_rows(src)
    facts = y["facts"] if y else []
    if not facts:
        return []
    out = []
    try:
        _ls = _rot_board_lines(path, src, inbox_dir) if lines is None else lines
        try:
            _univ = [f[:-len(".jsonl")] for f in os.listdir(inbox_dir or _rot_inbox_dir()) if f.endswith(".jsonl")]
        except OSError:
            _univ = []
        if consumed is None:                               # 1117:有行在等别的板上的卡才去读收过的回答(lint 每块板都跑,别白读)
            consumed = _answers_consumed_tail() if any(_ROT_ASKID_RE.search(str(f.get("wait_for") or "")) for f in facts) else []
        out += _rot_receipt_warns(facts, _rot_receipts(_ls, inbox_dir, now), _univ, consumed=consumed)
    except Exception as e:     # noqa: BLE001 —— 信箱读坏了不挡别的几条
        out.append("「等的回执到了」这条这一轮没有运行(不是通过了):%s: %s —— 报给状态板线" % (type(e).__name__, e))
    out += _rot_waitdone_warns(facts, find)
    out += _rot_statewait_warns(facts)
    out += _rot_retired_warns(facts)
    out += _rot_sched_warns(facts, sched_dir)
    return out


# ⭐ 1116 防样式漏定义(根治 .accept-small 那一类):13:35 上线的小修卡用了 kit.css 里没定义的 .accept-small,第一次挂卡各线板 lint 当场红
#   (电商-基建 #a5b9、AI Harness #5e21;83e3496b 补了 CSS)。根因:板上的「class 没样式」那道 lint 只看已经在板上的卡 ——
#   新卡类型上线时全机一张都没有,它没机会跑。⇒ 自检把每一类卡都实际生成一张(_class_zoo),收它们 HTML 里的 class,
#   连同 kit.js 运行时注入的(className= / classList.add / toggle / 字符串里的 class="…"),逐个核 kit.css 有定义;缺一个就红,报出是哪类卡的哪个 class。
#   ⚠ 新加一类卡 = 在 _class_zoo 里加一张,不然这条自检替它守不住。
def _css_defined_classes(css):
    """一份 CSS 里定义过的类名(选择器里出现的 .xxx;注释先剥)。纯函数。与 lint 孤儿类那条同一种取法。"""
    out = set()
    for m in re.finditer(r"([^{}]+)\{[^{}]*\}", strip_css_comments(css or "")):
        out |= set(re.findall(r"\.([A-Za-z][\w-]*)", m.group(1)))
    return out


def _html_classes(h):
    """一段 HTML 里用到的类名(<script> / <style> 先剥)。纯函数。"""
    h = re.sub(r"<(script|style)\b.*?</\1>", " ", h or "", flags=re.S | re.I)
    out = set()
    for m in re.finditer(r'class="([^"]*)"', h):
        out |= {c for c in m.group(1).split() if re.fullmatch(r"[A-Za-z][\w-]*", c)}
    return out


def _kit_js_classes(js):
    """kit.js 运行时往页面里放的类名:className = '…' / classList.add|toggle('…') / 拼 HTML 字符串里的 class="…"。
    引号后面紧跟 + 的是拼接前缀(如 'ts-' + k),不算(与 lint 同一条)。纯函数。"""
    out = set()
    for pat in (r"""className\s*=\s*['"]([^'"]+)['"](?!\s*\+)""", r"""classList\.(?:add|toggle)\(\s*['"]([^'"]+)['"](?!\s*\+)""",
                r"""class=\\?["']([^"'\\]+)\\?["'](?!\s*\+)"""):
        for m in re.finditer(pat, js or ""):
            out |= {c for c in m.group(1).split() if re.fullmatch(r"[A-Za-z][\w-]*", c)}
    return out


def _class_zoo():
    """每一类卡各生成一张 ⇒ [(哪类卡, HTML)]。纯函数(不读写任何文件;日子写死)。⚠ 新加一类卡就在这里加一张。
    ⚠ 1117 LH:自带区头(<div class="zone">)的类(排队区 / 主线卡)一律排在最后;跨类卡号不许重复 —— 两条都由 _class_zoo_problems 守(自检 1117 LH)。"""
