        ("带 --how 的卡", _ask_card_html(q, "就这样改", opts=["按建议", "先别"], how="第一步改名|第二步刷新|你会看到新名字")),
        ("带 --img 的卡", _ask_card_html(q, "就这样改", opts=["按建议", "先别"], imgs=[dict(url="/_card-img/a.png")])),
        ("方案页入口卡(--deep)", _ask_card_html(q, "就这样改", opts=["按建议", "先别"], deep="http://127.0.0.1:8777/proposals/x.html", deep_why="改前改后对比", deep_label="看完整方案")),
        ("要你动手卡(--steps)", _ask_card_html("请你在手机设置里打开通知开关", "照做", steps="起始界面|怎么做|等多久|结果怎么给我")),
        ("原文 / 复制卡(--text --copy)", _ask_card_html("这段话发给同事行不行", "就这样发", opts=["发", "不发"], texts=["第一段\n第二段"], copies=["命令|ls -la"])),
        ("普通验收卡(去哪看 + 多条结果)", rv(q=acc_q, gots=["来源一栏显示主站渠道名", "旧名不再出现"], see=see)),
        ("验收卡(外部入口 + 图)", rv(q=acc_q, gots=["来源一栏显示主站渠道名"], see=see, url="https://example.com/x", check="首页 → 订单页签 → 第一行", imgs=[dict(url="/_card-img/b.png")])),
        ("验收卡(方案页入口)", rv(q=acc_q, gots=["来源一栏显示主站渠道名"], see=see, url="http://127.0.0.1:8777/proposals/y.html", check="打开页 → 第二节 → 对比图", local=lambda u: None)),
        ("批量验收卡", rv(q="三件小事都改好了,你一起看一眼", gots=["甲好了", "乙好了", "丙好了"], more=["k2", "k3"], see=see)),
        ("还要你做的验收卡(--todo)", rv(q=acc_q, gots=["来源一栏显示主站渠道名"], see=see, todo=["去后台点一下保存"])),
        ("不做了卡(--drop)", rv(q="旧的测试页不做了,同意吗", drop="主站已经有同样的页,再做一份没人看", see=see)),
        ("提问行的回答卡(你问的 → 回答)", rv(q="为什么少了三单", gots=["少的三单是退款单,统计里本来就不算"], see="首屏这一行写着回答", asked=True)),
