    _auto_small = bool(_review and _drop is None and not _parts and not _asked and not getattr(a, 'small', False) and _see_no_change(getattr(a, 'see', None)))   # 1117 J7(见 SMALL_MECH_RE 上方)
    _batch_acks = [x.strip() for x in str(a.ack or "").split(",") if x.strip()]
    _small_batch = (_review and _drop is None and not _asked and _see_no_change(getattr(a, 'see', None))
                    and len(_batch_acks) == len(_gots or []) > 1)
    _small_mech = None
    if _auto_small:
        _asm = '--see 写的是「看不出变化」⇒ 这件会自动并进今天的小修清单(不单挂卡),'
