    if _review and str(_url or '').strip() and not str(_check or '').strip():
        checks.defer("写了 --check 后，再查文字是否够具体、有没有入口步骤")
        checks.add("review-check-missing", '给了 --url 就要给 --check「去哪看、看到什么算对」(出在入口按钮旁)\n  ⇒ 什么都没写。')
    if _review and str(_url or '').strip() and str(_check or '').strip() and _review_check_problem(_check):
        checks.add("review-check", '%s\n  ⇒ 什么都没写。' % _review_check_problem(_check))
    if _review and str(_url or '').strip() and str(_check or '').strip() and _review_steps_problem(_check):      # 1115 大扫除 D1
        checks.add("review-steps", '%s\n  ⇒ 什么都没写。' % _review_steps_problem(_check))
