    if _review and _asked and (_answer is not None or _parts) and (_gots or getattr(a, 'q', None) is not None):
        checks.add("answer-extra-fields", '回答卡用 --answer 或三格(可加 --table / --see):标题就是他问的那句(行标题),不用 --q / --got\n  ⇒ 什么都没写。')
