def _warn_dedup(board_path, warns, today=None):
    """touch 印的警告:同一块板、同一天,一字不差的只全文印第一次 → (要全文印的, 合并掉的条数)。
    ⭐ 1026 复查量:6 天里 touch / row 的输出 43% 是重复 20 次以上的固定行;例:排队区「理由提到负责人却没标 you」一条旧警告
      每改一行重印一遍,214 次 —— 不是这一轮改出来的,作者也没去修。⇒ 第一次照印(当天看得到),之后合成一句。
    ⛔ 报错(✗)不走这里,永远全印;「没有运行(不是通过了)」的照印(那是这一轮的状态,不是旧事);数字变了的(连续 N 轮)算新的。
    状态写在摘要同目录的 warns.json,只留当天。读写不了 ⇒ 全印(宁可多印)。"""
    sf = os.path.join(os.path.dirname(os.environ.get("BOARD_BRIEF_STATE") or BP.state("board-brief", "seen.json")), "warns.json")
    today = today or time.strftime("%Y-%m-%d")
    key = "%s|%s" % (os.path.abspath(board_path), today)
    try:
        seen = json.load(open(sf, encoding="utf-8"))
        if not isinstance(seen, dict):
            seen = {}
    except (OSError, ValueError):
        seen = {}
    have = set(seen.get(key) or [])
    out, rep_n = [], 0
    for w in warns:
        h = hashlib.md5(str(w).encode("utf-8")).hexdigest()[:12]
        if h in have and "没有运行(不是通过了)" not in str(w):
            rep_n += 1
            continue
        out.append(w)
        have.add(h)
    seen = {k: v for k, v in seen.items() if k.endswith("|" + today)}
    seen[key] = sorted(have)
    try:
        os.makedirs(os.path.dirname(sf), exist_ok=True)
        tmp = sf + ".tmp%d" % os.getpid()
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(seen, fh, ensure_ascii=False)
        os.replace(tmp, sf)
    except OSError:
        return list(warns), 0
    return out, rep_n


def _once_per_session(key):
    """这段教学话本会话第一次 ⇒ True(并记下);之后 ⇒ False。
    ⭐ 1028(负责人拍「token 效率重要,执行质量更重要」):row / answer 每次都附同样几句「这是什么意思、下一步怎么办」,
      一个会话里读一次就够。按 CLAUDE_CODE_SESSION_ID 记;拿不到会话号、或记录读写不了 ⇒ 照印(宁可多印)。
      ⚠ 只给「教怎么用」的话用;这一轮的状态、报错、警告一律照印。"""
    sid = os.environ.get("CLAUDE_CODE_SESSION_ID") or ""
    if not sid:
        return True
    sf = os.path.join(os.path.dirname(os.environ.get("BOARD_BRIEF_STATE") or BP.state("board-brief", "seen.json")), "once.json")
    try:
        seen = json.load(open(sf, encoding="utf-8"))
        if not isinstance(seen, dict):
            seen = {}
    except (OSError, ValueError):
        seen = {}
    k = "%s|%s" % (sid, key)
    if k in seen:
        return False
    now = time.time()
    seen = {a: b for a, b in seen.items() if isinstance(b, (int, float)) and now - b < 3 * 86400}   # 只留三天,文件不会越长越大
    seen[k] = now
    try:
        os.makedirs(os.path.dirname(sf), exist_ok=True)
        tmp = sf + ".tmp%d" % os.getpid()
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(seen, fh, ensure_ascii=False)
        os.replace(tmp, sf)
    except OSError:
        return True
    return True


def _brief(scenario):
    """把这一场景的摘要打出来。⛔ 一律在**判定行之前**调用。
    ⭐ 1020(Harness v2.5 全机审计,负责人拍「该改就改,本机效率优先」):row / answer / ask 各起一个子进程跑 touch,
      同一条命令把这段十几行的摘要打两遍;同一个目录一天里每次碰板也都打全文 ⇒ 一律:
      ① 子进程(父进程设了 BOARD_NO_BRIEF=1)不打;② 同一目录、同一场景,一天只打一次全文,之后只打第一行 + 一句「全文今天已打过」。"""
    lines = BRIEFS.get(scenario, [])
    if not lines or os.environ.get("BOARD_NO_BRIEF"):
        return
    sf = os.environ.get("BOARD_BRIEF_STATE") or BP.state("board-brief", "seen.json")
    key, today = "%s|%s" % (scenario, os.getcwd()), time.strftime("%Y-%m-%d")
    try:
        seen = json.load(open(sf, encoding="utf-8"))
        if not isinstance(seen, dict):
            seen = {}
    except (OSError, ValueError):
        seen = {}
    if seen.get(key) == today:
        # 1026(复查量:这一句本身 6 天被印了 610 次、约 7 万字,全是「不再重复」的重复)⇒ 当天第二次起一个字都不印
        return
    for line in lines:
        print(_port_text(line))
    seen = {k: v for k, v in seen.items() if v == today}      # 只留当天的,文件不会越长越大
    seen[key] = today
    try:
        os.makedirs(os.path.dirname(sf), exist_ok=True)
        with open(sf + ".tmp%d" % os.getpid(), "w", encoding="utf-8") as f:
            json.dump(seen, f, ensure_ascii=False)
        os.replace(sf + ".tmp%d" % os.getpid(), sf)
    except OSError:
        pass                     # 记不下来就下次再打全文,不影响主流程


def _lint_rule_hints(errors):
    """按报出来的错,挑出对应的规矩主题 —— 让人不必去猜「那到底该长什么样」。"""
    hit = []
    for topic_re, topic in LINT_TOPIC_HINTS:
        if topic in hit:
            continue
        if any(re.search(topic_re, e) for e in errors):
            hit.append(topic)
    if not hit:
        return
    print("  ↳ 这几条错背后的规矩(全文:board.py help <主题>):")
    for t in hit[:4]:
        title, body = RULES[t]
        first = next((l for l in body.split("\n")
                      if l.strip() and not l.startswith("#") and not l.startswith("→")), "")
        print("      · %-10s %s" % (t, title))
        if first:
            print("        %s" % first.strip()[:100])


def _help_of_subcommand(name):
    """name 是 board.py 的子命令 ⇒ 返回它的 --help 文本;不是 ⇒ None。只认小写字母、数字、连字符,别的不往下传。"""
    if not re.fullmatch(r"[a-z][a-z0-9-]*", name or ""):
        return None
    try:
        r = subprocess.run([sys.executable, os.path.abspath(__file__), name, "--help"], capture_output=True, text=True)
    except Exception:
        return None
    return r.stdout.strip() if r.returncode == 0 and r.stdout.strip() else None


def cmd_help(topic=None):
    """搬走的操作细节按主题可查。不带主题 = 列主题。

    ⭐ 这是「搬家」的兜底:场景触发只在**那一刻**打,而人可能在别的时刻想起来要查。
    """
    if not topic:
        print("状态板的操作细节(判据全文在 ~/.claude/reference/rules-ondemand/status-board.md;每轮注入的是 rules/common 那份摘要):")
        print("  用法:python3 ~/.claude/scripts/board.py help <主题>")
        print()
        rev = {}
        for sc, ts in SCENARIO_TOPICS.items():
            for t in ts:
                rev.setdefault(t, []).append(sc)
        for k, (title, _b) in RULES.items():
            print("  %-10s %-38s ← %s 时会自己打" % (k, title, " / ".join(rev.get(k, []))))
        print()
        print("  子命令的参数:`board.py <子命令> --help`(`help <子命令>` 也认);方案页工具:`plan.py --help`")
        print("  退出码 3：这次改动已写进板，随后自动 touch 没过；修好后单独 touch。")
        return 0
    if topic not in RULES:
        _moved = {"gates": "~/.claude/reference/board-gates.md(摘要)· reference/status-board-incidents-archive.md#gate-blind-spots(全文)"}
        if topic in _moved:
            die("「%s」0924 搬出了 help(没有命令会经过那一刻)→ %s" % (topic, _moved[topic]))
        # 1110 负责人(方案页 fable-audit-plan-1110 最后一题选「照做」):近 7 天 help 被调 124 次,其中 14 次是把子命令名当主题猜
        #   (answer 6 · plan 5 · rows 3),只得到一句「没有这个主题」再多跑一轮 ⇒ 认得出是子命令就直接印它的参数,plan 指到方案页工具。
        if topic == "plan":
            print("「plan」不是状态板的主题:方案页用另一个脚本。")
            print("  python3 ~/.claude/scripts/plan.py --help        # 命令一览(render / patch / lint)")
            print("  格式说明:~/.claude/scripts/plan-kit/README.md")
            return 0
        _sub = _help_of_subcommand(topic)
        if _sub:
            print("「%s」是子命令,不是 help 主题。它的参数(= `board.py %s --help`):" % (topic, topic))
            print(_sub)
            _rel = {"rows": "row", "answer": "ask", "answers": "ask", "touch": "freshness", "publish": "path"}.get(topic)
            if _rel:
                print("相关主题:`board.py help %s`" % _rel)
            return 0
        die("没有这个主题:%s —— 跑 `board.py help` 看全部主题;子命令的参数用 `board.py <子命令> --help`" % topic)
    title, body = RULES[topic]
    print("── %s(%s)" % (title, topic))
    print(_port_text(body))
    return 0


def _st_home_env(env, home):
    """selftest 把「家」换成临时目录。⭐ 1023:Windows 上 os.path.expanduser 认的是 USERPROFILE、不看 HOME ⇒ 只改 HOME 的话,
    子进程照样写进**真的**用户目录(总览页、~/.claude 下的东西)。⇒ Windows 上同时改 USERPROFILE 和 APPDATA(会话注册表跟着家走),
    并去掉 XDG_CONFIG_HOME(Linux 同理)。macOS 上只改 HOME —— 与从前逐字节一致。"""
    env["HOME"] = home
    if os.name == "nt":
        env["USERPROFILE"] = home
        env["APPDATA"] = os.path.join(home, "AppData", "Roaming")
    elif sys.platform != "darwin" and env is not os.environ:     # 只改子进程的那份;本进程的环境不永久改
        env.pop("XDG_CONFIG_HOME", None)
    return env


# 依据: kit.css 08-26「板头与分节词汇」那段是手写板的方言兼容层,没有脚本产出;11-15 实测 示例项目-记忆助手.html 在用其中的 emo
KIT_CSS_DIALECT = ("emo", "dead")


def _kit_css_unproduced(here=None):
    """kit.css 里定义了、却没有任何脚本产出的类(方言兼容类除外)—— 1115 大扫除删了一批,这道检查防它再攒。
    产出 = 类名在 kit.js / board.py(自检与本函数以外)/ plan.py / boards-server.py / board-kit 的 html / plan-kit 的 js 里出现过(去掉注释)。
    读不到的源跳过;kit.css 读不到 ⇒ ["(kit.css 读不到)"]。只读。"""
    import glob as _gl
    here = here or os.path.dirname(os.path.abspath(__file__))
    rd = lambda p: io.open(p, encoding="utf-8").read()
    try:
        css = re.sub(r'/\*.*?\*/', '', rd(os.path.join(here, "board-kit", "kit.css")), flags=re.S)
    except OSError:
        return ["(kit.css 读不到)"]
    cls = set()
    for sel in re.findall(r'([^{}]+)\{', css):
        if not sel.strip().startswith('@'):
            cls |= set(re.findall(r'\.(-?[A-Za-z_][\w-]*)', sel))
    js_strip = lambda t: "\n".join(re.sub(r'(^|\s)//.*$', '', l) for l in re.sub(r'/\*.*?\*/', '', t, flags=re.S).split("\n"))
    py_strip = lambda t: "\n".join(re.sub(r'^\s*#.*$', '', l) for l in t.split("\n"))
    srcs = []
    try:
        lines = rd(os.path.join(here, "board.py")).split("\n")
        keep, skip, past = [], False, False      # 跳过:本函数 + 自检(到自检后面第一个顶格 def 为止;自检里有顶格的 JS 字面串,不能按缩进判)
        for l in lines:
            if l.startswith("KIT_CSS_DIALECT"):
                skip = True
            elif l.startswith("def cmd_selftest"):
                skip, past = True, True
            elif skip and past and l.startswith("def "):
                skip = False
            if not skip:
                keep.append(l)
        srcs.append(py_strip("\n".join(keep)))
    except OSError:
        pass
    for rel, fn in (("board-kit/kit.js", js_strip), ("plan.py", py_strip), ("boards-server.py", py_strip),
                    ("board-kit/head.html", str), ("board-kit/markup.html", str)):
        try:
            srcs.append(fn(rd(os.path.join(here, rel))))
        except OSError:
            pass
    for p in sorted(_gl.glob(os.path.join(here, "plan-kit", "*.js"))):
        srcs.append(js_strip(rd(p)))
    allsrc = "\n".join(srcs)
    return sorted(c for c in cls if c not in KIT_CSS_DIALECT and not re.search(r'(?<![\w-])' + re.escape(c) + r'(?![\w-])', allsrc))


def _selftest_tmp_in_git(d):
    """1120:临时目录在某个 git 仓的工作树里 ⇒ 返回仓根,否则 None。
    ⭐ 由来(11-20):Codex 在暂存里跑自检时 TMPDIR 指到 ~/.claude/scratch(家目录就是 git 仓),
      自检的临时板被认成「正本的工作树副本」,退场 / 搬回用例把 zz-rt 写进了真板根 ~/.claude/boards 和 boards-web;
      之后真环境的自检两条退场用例一直红(撞上同名真板),同事那边的技能包也推不出去。"""
    try:
        r = subprocess.run(["git", "-C", d, "rev-parse", "--show-toplevel"], capture_output=True, text=True, timeout=10)
    except (OSError, subprocess.SubprocessError):
        return None
    top = (r.stdout or "").strip()
    return top if r.returncode == 0 and top else None


def _done_state_selftest():
    """1120 做完没有的牌子:在仓外临时板上真跑 cmd_row(内容照 11-20 电商-基建那张被打回、重挂的回答卡),kit 用 node 假 DOM 现画比两端。"""
    import contextlib
    import tempfile
    from pathlib import Path

    _h_unescape = __import__("html").unescape
    ap, _ = _board_parser()
    title = "渠道号当天出单做成实时：走投流全店计划的素材报表"
    answer = ("计划在投时，计划出单约等于店铺出单，付费单和自然单都算。"
              "AA 有两条计划，页面只读了一条；BB 的计划几乎没花钱。出单页正改成读取每家店所有在投计划。")
    table = ["店|店铺出单|计划记到|为什么", "某店乙 11-14~18|384 单|382 单|计划一直在投，对得上",
             "某店丙 11-14~18|223 单|220 单|两条计划，原来只读一条", "某店丁 11-14~18|56 单|1 单|计划几乎没花钱"]

    how = ["--src", "official", "--freq", "这次一次性核五天", "--proved", "三店逐单对上店铺分析数"]   # 照那张卡原样;不带表的回答卡要写怎么来的

    def fixture(asked, row_title=title):
        return ('<title>zz-donestate 状态板</title><div class="wrap">'
                '<div class="zone"><h2>要你的</h2><span class="n">0 件</span></div>'
                '<div class="zone"><h2>你交代的</h2><span class="n">1 件</span></div>'
                '<article class="card"><div class="body"><div class="checks">'
                '<div class="crow" data-status="doing" data-ack="r1120-37c7" data-eta="12-30" data-wait-for="平台审核"%s>'
                '<span class="mk"></span><span class="txt"><b>%s</b><span class="why">重查中</span></span>'
                '</div></div></div></article><div class="zone"><h2>排队中的活</h2></div></div>' % (' data-asked="1"' if asked else '', row_title)).encode()

    with tempfile.TemporaryDirectory(prefix="donestate-1120-") as tmp:
        board = Path(tmp) / "zz-donestate.html"

        def call(args, asked=True, row_title=title):
            before = fixture(asked, row_title)
            board.write_bytes(before)
            out, err = io.StringIO(), io.StringIO()
            ns = ap.parse_args(["row", str(board), "--ack", "r1120-37c7", "--review", *args, "--no-touch"])
            with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
                try:
                    rc = cmd_row(ns)
                except SystemExit as e:
                    rc = e.code
            after = board.read_text(encoding="utf-8")
            return rc, out.getvalue(), err.getvalue(), after, after.encode() == before

        def card(text):
            m = re.search(r'<article class="card"[^>]*data-accept="1".*?</article>', text, re.S)
            return m.group(0) if m else ""

        # 1123:固定卡片生成时间,整段 HTML 连同卡号逐字比较。
        from unittest.mock import patch
        import shlex

        def same_card(auto, direct):
            with patch.object(time, "localtime", return_value=time.localtime()):
                changed, clean = auto(), direct()
            auto_html, direct_html = card(changed[3]), card(clean[3])
            return (changed[0] == clean[0] == 0 and bool(auto_html)
                    and auto_html.encode() == direct_html.encode()), changed

        state = ["--state", "done"] + how
        response = "六笔退款都来自同一个客人。"
        extra = "退款规则没变"
        question_title = "上周退款为什么多了"
        match, changed = same_card(
            lambda: call(state + ["--answer", response], asked=False, row_title=question_title),
            lambda: call(state + ["--asked", "--answer", response], asked=False, row_title=question_title),
        )
        yield (match and 'data-asked="1"' in re.search(r'data-ack="r1120-37c7"[^>]*', changed[3]).group(0)
               and "已把这一行标成他问的" in changed[1]), "1123 补标提问行与显式 --asked 的卡 HTML 逐字一致", (changed[0], len(card(changed[3]).encode()) if changed[0] == 0 else changed[2])

        match, changed = same_card(
            lambda: call(state + ["--answer", response, "--q", str(board)]),
            lambda: call(state + ["--answer", response]),
        )
        yield (match and "回答卡不用 --q,已忽略" in changed[1]), \
            "1123 忽略多给的 --q 后卡 HTML 逐字一致", (changed[0], len(card(changed[3]).encode()) if changed[0] == 0 else changed[2])

        match, changed = same_card(
            lambda: call(state + ["--answer", response, "--got", extra, "--got", "订单数持平"]),
            lambda: call(state + ["--answer", response + extra + ";订单数持平"]),
        )
        yield (match and "回答卡不用 --got,已并进回答" in changed[1]), \
            "1123 并进多给的 --got 后卡 HTML 逐字一致", (changed[0], len(card(changed[3]).encode()) if changed[0] == 0 else changed[2])

        match, changed = same_card(
            lambda: call(state + ["--q", "重复标题", "--got", "六笔退款都来自同一个客人", "--got", extra,
                                  "--table", table[0], "--table", table[1]]),
            lambda: call(state + ["--answer", "六笔退款都来自同一个客人;" + extra,
                                  "--table", table[0], "--table", table[1]]),
        )
        yield (match and "已把 --got 并进回答" in changed[1]), \
            "1123 只给多条 --got 的带表卡与直接写 --answer 的 HTML 逐字一致", (changed[0], len(card(changed[3]).encode()) if changed[0] == 0 else changed[2])

        full_answer = "甲" * ANSWER_MAX
        match, changed = same_card(
            lambda: call(state + ["--answer", full_answer, "--got", extra]),
            lambda: call(state + ["--answer", full_answer]),
        )
        yield (match and "已忽略(回答已满)" in changed[1]), \
            "1123 正好 100 字的回答原样保留并说明忽略 --got", (changed[0], len(card(changed[3]).encode()) if changed[0] == 0 else changed[2])

        def fixed_values(result):
            cmd = next((line for line in result[2].splitlines() if line.startswith("python3 ")), "")
            return shlex.split(cmd)[4:] if cmd else []

        missing = call(["--answer", response, "--got", extra, "--q", question_title] + how,
                       asked=False, row_title=question_title)
        fixed = fixed_values(missing)
        yield (missing[0] == 2 and missing[4] and "回答卡要先说做完没有" in missing[2]
               and all(x in fixed for x in ("--asked", "--answer", response + extra, "--state", DONE_STATE_HOLE))
               and "--q" not in fixed and "--got" not in fixed), \
            "1123 自动整理成功也照旧拒漏 --state，整条命令留状态占位", (missing[0], fixed)

        invalid = call(state + ["--got", "已上线", "--got", "交给子代理检查", "--got", "甲" * ANSWER_MAX])
        fixed = fixed_values(invalid)
        fix_rc = call([response if x == "<改写答案正文>" else x for x in fixed])[0] if fixed else None
        yield (invalid[0] == 2 and invalid[4] and all(x in invalid[2] for x in
               ("超过 %d 字" % ANSWER_MAX, "回答卡要写答案本身", "内部词")) and fix_rc == 0
               and "--got" not in fixed and "--answer" in fixed and "<改写答案正文>" in fixed), \
            "1123 转成回答后一次报长度、首句和内部词，填好正文的整条命令可重跑", (invalid[0], invalid[2], fix_rc)

        overflow = call(state + ["--answer", response, "--got", "甲" * ANSWER_MAX])
        yield (overflow[0] == 2 and overflow[4] and "超过 %d 字" % ANSWER_MAX in overflow[2]
               and "<改写答案正文>" in fixed_values(overflow)), \
            "1123 追加 --got 后超长照旧拒，命令留正文占位", (overflow[0], overflow[2])

        def badge(text):
            m = re.search(r'<span class="done-state ds-(\w+)">(.*?)</span><h2 class="q">', card(text))
            return (m.group(1), _h_unescape(m.group(2))) if m else None

        review = ["--q", "渠道号出单页改好了，请你点通过", "--got", "出单页读每家店所有在投计划", "--see", "出单页 → 渠道号一栏显示当天单数",
                  "--src", "official", "--freq", "每小时一次", "--proved", "三店逐单对上店铺分析数"]
        done = call(review, asked=False)
        left = call(review + ["--left", "某店丁 店"], asked=False)
        yield (done[0] == 0 and badge(done[3]) == ("done", "做完了") and left[0] == 0
               and badge(left[3]) == ("partial", "没做完 · 还差 某店丁 店") and 'data-left="某店丁 店"' in card(left[3])), \
            "① 验收卡不给 --left 牌子「做完了」,给了「没做完 · 还差 …」", (done[0], badge(done[3]), left[0], badge(left[3]), [l for l in (done[2] + left[2]).splitlines() if l.startswith("✗")][:3])

        def listed(result, *words):
            rc, _out, err, _after, same = result
            return (rc == 2 and same and err.count("✗ 这次有 ") == 1 and "✗ 这次有 %d 处要改:" % len(words) in err
                    and all(w in err for w in words)
                    and sum(line[:1] in _NUM_MARKS for line in err.splitlines() if line) == len(words))

        miss = call(["--q", title, "--answer", answer, "--table", table[0], "--table", table[1]])
        fixed = next((l for l in miss[2].splitlines() if l.startswith("python3 ")), "")
        yield (listed(miss, "回答卡要先说做完没有") and "--state '<填 done|partial|na>'" in fixed and "--q" not in fixed.split("--answer")[0]), \
            "② 回答卡多给 --q 仍拒漏 --state,改好命令留占位", (miss[0], [l[:60] for l in miss[2].splitlines() if l[:1] in "✗" + _NUM_MARKS], fixed[-90:])
        part = call(["--q", title, "--answer", answer, "--state", "partial"] + how)
        fixed2 = next((l for l in part[2].splitlines() if l.startswith("python3 ")), "")
        yield (listed(part, "--state partial 要带 --left") and "--left '<还差什么>'" in fixed2), \
            "③ --state partial 不带 --left:同一张清单里报,命令留占位", (part[0], [l[:60] for l in part[2].splitlines() if l[:1] in "✗" + _NUM_MARKS], fixed2[-90:])
        na = call(["--answer", answer, "--table", table[0], "--table", table[1], "--state", "na"])
        okd = call(["--answer", answer, "--table", table[0], "--table", table[1], "--state", "done"])
        yield (na[0] == 0 and card(na[3]) and badge(na[3]) is None and "data-done-state" not in na[3]
               and okd[0] == 0 and badge(okd[3]) == ("done", "做完了")), \
            "④ --state na 不出牌子(对照 done 出「做完了」)", (na[0], badge(na[3]), okd[0], badge(okd[3]), [l for l in na[2].splitlines() if l.startswith("✗")][:3])
        multi = call(["--answer", answer, "--state", "partial", "--left", "出单页读全部计划"] + how)
        tabled = call(["--answer", answer, "--table", table[0], "--table", table[1], "--state", "partial", "--left", "出单页读全部计划"])
        shop = _multi_objects("三家店：某店甲、某店乙、主站，都改成从新表读价")
        quiet = [_multi_objects(x) for x in ("11-14/11-18 两天没花钱", "AI 和 API 都通了", "只有 某店乙 一家")]
        yield (multi[0] == 0 and "逐个列成小表更清楚:--table" in multi[1] and badge(multi[3]) == ("partial", "没做完 · 还差 出单页读全部计划")
               and tabled[0] == 0 and "逐个列成小表" not in tabled[1] and shop == ["某店甲", "某店乙", "主站"] and quiet == [[], [], []]), \
            "⑤ partial 讲到几个对象只提示列小表、照常挂上;带了表不提示;日期 / 常见缩写 / 一家不算", (multi[0], [l for l in multi[1].splitlines() if "小表" in l], tabled[0], shop, quiet)

        # ⑥ kit 现画:只给卡上两个属性,kit doneStateMark 画出的字和位置 == board.py 生成的那枚
        kj = ""
        try:
            kj = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "board-kit", "kit.js"), encoding="utf-8").read()
        except OSError:
            pass
        fns = [re.search(r'\n  function %s\(.*?\n  \}\n' % n, kj, re.S) for n in ("doneStateLabel", "doneStateMark")]
        gen = [(done[3], "done", None), (left[3], "partial", "某店丁 店"), (okd[3], "done", None), (multi[3], "partial", "出单页读全部计划"), (na[3], "na", None)]
        cases = []
        for text, st, lf in gen:
            hd = card(text).split(">", 1)[0]
            attr = lambda k: (lambda m: _h_unescape(m.group(1)) if m else None)(re.search(r'\b%s="([^"]*)"' % k, hd))
            cases.append({"st": attr("data-done-state"), "left": attr("data-left"), "py": (badge(text) or (None, ""))[1], "lab": _done_state_label(st, lf)})
        js = ("var document={createElement:function(t){return {tag:t,className:'',textContent:'',parentNode:null}}};\n"
              + "".join(m.group(0) for m in fns if m) +
              "\nvar CASES=%s;\nconsole.log(JSON.stringify(CASES.map(function(c){"
              "var kids=[{name:'chips'},{name:'h2'}];var top={insertBefore:function(n,ref){n.parentNode=top;kids.splice(kids.indexOf(ref),0,n);}};"
              "kids.forEach(function(k){k.parentNode=top});var qel=kids[1];"
              "var cd={getAttribute:function(k){return k==='data-done-state'?c.st:k==='data-left'?c.left:null},querySelector:function(){return null}};"
              "var lab=doneStateMark(cd,qel);var at=kids.indexOf(qel);var prev=at>0?kids[at-1]:null;"
              "return [lab, prev&&prev.textContent===lab&&lab?prev.className:'', doneStateLabel(c.st,c.left)];})));" % json.dumps(cases, ensure_ascii=False))
        r = subprocess.run(["node", "-e", js], capture_output=True, text=True, timeout=30)  # 依据: 现有首屏 node 自检的超时
        try:
            got = json.loads(r.stdout.strip())
        except ValueError:
            got = None
        want = [[c["py"], ("done-state ds-" + c["st"]) if c["py"] else "", c["py"]] for c in cases]
        yield (all(fns) and got == want and [c["lab"] for c in cases] == [c["py"] for c in cases]
               and [c["py"] for c in cases] == ["做完了", "没做完 · 还差 某店丁 店", "做完了", "没做完 · 还差 出单页读全部计划", ""]), \
            "⑥ kit 只凭卡上属性现画,字和位置(标题正上方)与 board.py 生成的逐条一致", ("kit=%s 预期=%s %s" % (got, want, r.stderr[-200:]))


def _reject_selftest():
    """在仓外临时板上真跑三个写板入口，重跑 stderr 给出的原样命令。"""
    import contextlib
    import shlex
    import tempfile
    from pathlib import Path

    ap, _ = _board_parser()
    handlers = {"row": cmd_row, "ask": cmd_ask, "answer": cmd_answer}
    base = ('<title>zz-rejectall 状态板</title><div class="wrap">'
            '<div class="zone"><h2>要你的</h2><span class="n">0 件</span></div>'
            '<div class="zone"><h2>你交代的</h2><span class="n">1 件</span></div>'
            '<article class="card"><div class="body"><div class="checks">'
            '<div class="crow" data-status="doing" data-ack="r1120-1752" data-eta="12-30" data-wait-for="平台审核">'
            '<span class="mk"></span><span class="txt"><b>上周退款为什么多了</b><span class="why">在对账</span></span>'
            '</div></div></div></article><div class="zone"><h2>排队中的活</h2></div></div>').encode()

    with tempfile.TemporaryDirectory(prefix="write-reject-1120-") as tmp:
        board = Path(tmp) / "有空格 ' 的板.html"

        def call(command, args, fixture=base):
            board.write_bytes(fixture)
            stdout, stderr = io.StringIO(), io.StringIO()
            ns = ap.parse_args([command, str(board), *args, "--no-touch"])
            with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
                try:
                    rc = handlers[command](ns)
                except SystemExit as e:
                    rc = e.code
            return rc, stderr.getvalue(), board.read_bytes() == fixture

        def matches(result, *errors):
            rc, err, same = result
            return (rc == 2 and same and f"✗ 这次有 {len(errors)} 处要改:" in err
                    and all(word in err for word in errors)
                    and sum(line[:1] in _NUM_MARKS for line in err.splitlines() if line) == len(errors))

        whole = ["--ack", "r1120-1752", "--review"]
        disputed = call("row", whole + ["--q", "上周退款为什么多了", "--state", "done", "--answer", "同一个客人分六次退，是子代理核的。",
                        "--table", "时段|退款", "--table", "上周|六单", "--see", "看不出变化:这是调查结论",
                        "--src", "backend", "--freq", "一次实测", "--proved", "对了原始订单"])
        yield matches(disputed, "子代理"), "① 回答卡整理字段后仍拒内部词，板不变", disputed[1].splitlines()[:3]
        small = call("row", whole + ["--q", "来源名称已经统一，请你点通过", "--got", "原有页面的来源名称已经全部统一" * 4,
                     "--got", "原订单保留原样", "--see", "看不出变化:" + "这次只整理旧名称，页面会继续显示原来的内容" * 4,
                     "--src", "backend"])
        yield matches(small, "超过 40 字", "小修清单一件一行", "超过 50 字", "不带「怎么来的」"), "② 小修卡一次报四处，板不变", small[1].splitlines()[:3]

        def rerun(result, marker):
            rc, err, same = result
            command = next((l for l in err.splitlines() if l.startswith("python3 ") and str(board.name) in l.replace("'\"'\"'", "'")), "")
            if not command:
                return False, "没有给出完整命令"
            parts = shlex.split(command)
            if parts[3] != str(board):
                return False, "路径引号对不上"
            command = command.replace("'<填 done|partial|na>'", "done")
            rerun = subprocess.run(["/bin/sh", "-c", command], capture_output=True, text=True)
            return rc == 2 and same and rerun.returncode == 0 and marker in board.read_text(), f"重跑退出码 {rerun.returncode}"

        repaired = call("row", whole + ["--q", "上周退款为什么多了", "--answer", "商家名称是 'North Star'，同一个客人分六次退。",
                       "--see", "退款详情 → 显示同一位顾客"])
        answer_ok, answer_detail = rerun(repaired, "North Star")
        repaired_small = call("row", whole + ["--got", "新单保留原名称", "--got", "旧单已归档", "--src", "backend",
                             "--see", "看不出变化:页面上的原名称照旧"])
        small_ok, small_detail = rerun(repaired_small, "新单保留原名称；旧单已归档")
        rename = call("row", whole + ["--asked", "--state", "na", "--q", "金额差异来自同一笔订单的六次退款。",
                      "--see", "退款详情 → 显示同一位顾客"])
        rename_ok, rename_detail = rerun(rename, "金额差异来自同一笔订单")
        yield all((answer_ok, small_ok, rename_ok)), "③ 三条完整命令填好状态占位即写入", (answer_detail, small_detail, rename_detail)

        ask = call("ask", ["--q", "这 3 件", "--rec", "先核订单", "--do", "--steps", "起始界面:订单页", "--steps", "怎么做:点开",
                           "--deep-q", "d1", "--how", "先查三单", "--img", "nope.txt"])
        msg = ask[1]
        yield (matches(ask, "--steps 给了 2 次", "--deep-q 要配 --deep", "只写了件数或指代", "--img 只收")
               and msg.count("改完上面再查:") == 1 and msg.index("改完上面再查:") > msg.index("④")
               and "方案页题号与两边选项" in msg and "--steps 里缺了" not in msg), "④ 问卡独立项一起报，依赖项只在末尾", msg.splitlines()[:3]

        log = str(Path(tmp) / "hints.log")
        past = {"event": "board-write", "command": "row", "outcome": "rejected", "ts": 0, "checks": ["past"]}
        Path(log).write_text(json.dumps(past) + '\n{"keys":["old-hint"]}\n{坏行\n')
        _board_write_event(str(board), "ask", [], log_path=log)
        _board_write_event(str(board), "row", ["b", "a", "c", "d", "e", "f"], log_path=log)
        _board_write_event(str(board), "answer", ["b", "a"], log_path=log)
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            cmd_reject_stats(datetime.date.today(), log_path=log)
        stats = buf.getvalue()
        yield ("2 / 3（66.67%）" in stats and "平均每次拒写 4.00 处" in stats
               and stats.splitlines()[3:] == ["  a 2 次", "  b 2 次", "  c 1 次", "  d 1 次", "  e 1 次"]), "⑤ 临时日志分母、均值和前五准确", stats.splitlines()[1:3]

        # 1122:从拒写入口读回真实日志格式，再用一条旧记录核对 --detail 输出。
        from unittest.mock import patch
        long_reason = "同一条拒写原因" * 10
