        refusals = [call("row", [*drop_args, "--q", q]) for q, _ in bad_drop_q]
        yield all(r[0] == 2 and r[2] and marker in r[1]
                  for r, (_, marker) in zip(refusals, bad_drop_q)), \
              "1123 不做卡的 --q 仍检查正文", [(r[0], r[1].splitlines()[:3]) for r in refusals]

        delivery = base.replace("上周退款为什么多了".encode(), "主图换白底(11-17 交代)".encode())
        wrong_answer = call("row", whole + ["--q", "主图换成白底了,通过吗?", "--answer", "五张都换了。", "--state", "done"], delivery)
        yield (matches(wrong_answer, "普通交付验收改用 --got；如果是他问的,先 row --ack <行> --asked")
               and "改好的整条命令" not in wrong_answer[1]), \
              "1123 普通交付行 --answer 拒写并提示两种改法", wrong_answer[1].splitlines()

        for suffix in ("好了吗", "是不是合适", "能不能通过", "用了多少", "用哪张", "是否合适？", "是否合适?"):
            q_fixture = delivery.replace("主图换白底(11-17 交代)".encode(), ("主图白底" + suffix + "(11-17 交代)").encode())
            answered, answered_board = write("row", whole + ["--answer", "五张都换了。", "--state", "done"], q_fixture)
            yield answered.returncode == 0 and 'data-asked="1"' in answered_board, \
                  "1123 问句行标题可补标：" + suffix, answered.stderr.splitlines()[:3]


        how_args = ["--q", "配送地址是否统一用新入口？", "--rec", "建议改"]
