    def _c_say_wait():
        op, dn = {"open": True, "you": "wait", "ack": "k9"}, {"open": False, "you": "wait", "ack": "k9"}
        w = (_say_wait_words("还差你定一件;你点头我就试"), _say_wait_words("他说「等你定」,其实不用等你;不再等你回"),
             _say_wait_words("等负责人拍,等你"), _say_wait_words("在做,10-14 出"))
        g = (_say_wait_problem("尾货口径等你定", op, False, None, path="/x/b.html"),          # 报
             _say_wait_problem("尾货口径等你定", op, True, None),                             # 有卡 ⇒ 不报
             _say_wait_problem("尾货口径等你定", dict(op, you="decide"), False, None),        # 行上已标着要他 ⇒ 不报
             _say_wait_problem("你 10-07 说先搁着,等你重新提", op, False, "wait"),            # 这次明说 --you wait ⇒ 不报
             _say_wait_problem("尾货口径等你定", dn, False, None),                             # 做完的行 ⇒ 不报
             _say_wait_problem("在做,10-14 出", op, False, None),                              # 没这类说法 ⇒ 不报
             _say_wait_problem("他说「等你定」", op, False, None))                             # 引号里 ⇒ 不报
        return (w == (["还差你", "你点头"], [], ["等负责人", "等你"], []) and bool(g[0]) and "等你" in g[0] and "ask /x/b.html --row k9" in g[0]
                and "--you wait" in g[0] and all(x is None for x in g[1:])), (w, [bool(x) for x in g])

    def _c_decide_card():
        nolink = _P5.replace('<a href="#row-k1">原行</a>', '原行')
        a = _decide_no_card_error("/x/b.html", _P5, today=_T5)                       # 有卡链到 k1 ⇒ 不报
        b = _decide_no_card_error("/x/b.html", nolink, today=_T5) or ""               # 卡不链了 ⇒ 报 k1;k4(do)不报
        c = _decide_no_card_error("/x/b.html", nolink.replace('data-status="blocked" data-you="decide" data-ack="k1"',
                                                              'data-status="done" data-ack="k1"'), today=_T5)      # 做完了 ⇒ 不报
        d = _decide_no_card_error("/x/b.html", nolink.replace('data-you="decide" data-ack="k1"', 'data-you="do" data-ack="k1"'), today=_T5)  # 改成动手 ⇒ 不报
        return (a is None and "1 行标着要他拍板" in b and "拍运费" in b and "挂卡号的" not in b and "ask /x/b.html --row k1" in b
                and c is None and d is None), (bool(a), b[:120], bool(c), bool(d))

    def _c_after_set():
        o, n = _row_apply(_P5, "k2", after="k1")
        o2, n2 = _row_apply(_P5, "k2", after="k1", say="等运费拍完再做", status="todo", eta="10-09")
        f2 = _f5(o2, "k2")
        return (_tag5(o, "k2") == '<div class="crow" data-status="doing" data-ack="k2" data-eta="10-02" data-after="k1">'
                and o.replace(' data-after="k1"', "") == _P5 and any("排在 k1 后面" in x for x in n)
                and f2.get("after") == "k1" and f2.get("st") == "todo" and f2.get("why") == "等运费拍完再做" and f2.get("eta_raw") == "10-09"
                and _only5(_P5, o2, "k2") and _f5(_P5, "k2").get("after") is None), (_tag5(o, "k2"), n)

    def _c_after_bad():
        ch1 = _row_apply(_P5, "k2", after="k1")[0]             # k2 → k1
        ch2 = _row_apply(ch1, "k4", after="k2")[0]             # k4 → k2 → k1(链本身合法)
        g = [_err5(lambda: _row_apply(_P5, "k2", after="nope")),            # 指向不存在
             _err5(lambda: _row_apply(_P5, "k2", after="k2")),              # 指向自己
             _err5(lambda: _row_apply(ch1, "k1", after="k2")),              # 直接成环
             _err5(lambda: _row_apply(ch2, "k1", after="k4")),              # 间接成环
             _err5(lambda: _row_apply(_P5, "k3", after="k1")),              # 这一行已做完
             _err5(lambda: _row_apply(_P5, "k2", after="k1", status="done", say="好了")),   # 这次标成做完
             _err5(lambda: _row_apply(_P5, "k2", after="k3")),              # 前面那行已做完
             _err5(lambda: _row_apply(_P5, "k2", after="k1", no_after=True)),
             _err5(lambda: _row_apply(_P5, "k2", after=" "))]
        return (all(g) and "找不到" in g[0] and "自己" in g[1] and "成环" in g[2] and "成环" in g[3] and "做完" in g[4] and "做完" in g[5]
                and "已经做完了" in g[6] and "只能给一个" in g[7] and 'data-after="k2"' in _tag5(ch2, "k4")), [x[:14] for x in g]

    def _c_after_no():
        with_a = _row_apply(_P5, "k2", after="k1")[0]
        o, n = _row_apply(with_a, "k2", no_after=True)
        noeta = _row_apply(_PNE, "k2", after="k1")[0]          # 没预计日 + 排在后面:写得进去
        e = _err5(lambda: _row_apply(noeta, "k2", no_after=True))               # 拿掉之后没有预计日 ⇒ 拒
        o2, _n2 = _row_apply(noeta, "k2", no_after=True, eta="10-12", status="doing")
        d, nd = _row_apply(with_a, "k2", status="done", say="做完了")          # 标做完 ⇒ data-after 一并拿掉
        return (o == _P5 and any("不再排在 k1 后面" in x for x in n) and "预计哪天" in e and "data-after" not in _tag5(o2, "k2")
                and 'data-eta="10-12"' in _tag5(o2, "k2") and "data-after" not in _tag5(d, "k2") and any("不再排在" in x for x in nd)), (n, e[:30])

    def _c_after_eta():
        a_ = _PNE.replace(' data-ack="k2"', ' data-ack="k2" data-after="k1"')
        bad = _PNE.replace(' data-ack="k2"', ' data-ack="k2" data-after="k1" data-eta="下周"')
        y_a, y_n = _yours_zone_rows(a_, today=_T5), _yours_zone_rows(_PNE, today=_T5)
        return (_f5(a_, "k2").get("missing") == [] and _f5(_PNE, "k2").get("missing") == ["预计哪天"]
                and not any("(k2)" in lb for lb, _m in y_a["open_missing"]) and any("(k2)" in lb for lb, _m in y_n["open_missing"])
                and _f5(bad, "k2").get("missing") == ["预计哪天要写成 MM-DD(现在是「下周」)"]
                and _raises5(lambda: _row_apply(_PNE, "k2", say="x")) and not _raises5(lambda: _row_apply(_PNE, "k2", say="x", after="k1"))), \
            (_f5(a_, "k2").get("missing"), _f5(_PNE, "k2").get("missing"))

    def _c_after_lint():
        e = _after_done_error("/x/b.html", _PA3, today=_T5) or ""
        gone = _after_done_error("/x/b.html", _PA3.replace('data-after="k3"', 'data-after="moved"'), today=_T5) or ""
        open_x = _after_done_error("/x/b.html", _PA3.replace('data-after="k3"', 'data-after="k1"'), today=_T5)        # 前面那件没做完
        you_d = _after_done_error("/x/b.html", _P5.replace(' data-ack="k1" data-eta', ' data-ack="k1" data-after="k3" data-eta'), today=_T5)   # 这一行标着要他拍
        you_do = _after_done_error("/x/b.html", _P5.replace(' data-ack="k4" data-eta', ' data-ack="k4" data-after="k3" data-eta'), today=_T5)  # 要他动手
        asked = _after_done_error("/x/b.html", _PA3.replace('<h2 class="q">没链行的?</h2>',
                                  '<h2 class="q">现在开始吗?</h2><div class="checks"><div class="crow"><span class="mk">·</span><span class="txt"><a href="#row-k2">那一行</a></span></div></div>'), today=_T5)
        y_done = _after_done_error("/x/b.html", _P5.replace(' data-ack="k3"', ' data-ack="k3" data-after="k1"'), today=_T5)   # 带着它的那一行自己做完了
        mach = _after_done_error("/x/b.html", _PA3.replace('<h2 class="q">机器</h2>', '<h2 class="q">机器</h2><a href="#row-k2">x</a>'), today=_T5) or ""   # 机器卡里的链接不算挂了卡
        return (all(x in e for x in ("1 行", "这一件还标着排在它后面", "在做的(k2)", "做完的(k3)", "已经做完",
                                     "board.py row /x/b.html --ack k2 --status doing --no-after --say", "--eta MM-DD",
                                     "board.py ask /x/b.html --q", "--row k2"))
                and "已经不在板上" in gone and 'data-ack="moved"' in gone and "(k2)" in gone
                and open_x is None and you_d is None and you_do is None and asked is None and y_done is None
                and "(k2)" in mach and _after_done_error("/x", _P5, today=_T5) is None), \
            (e[:60], bool(gone), open_x, you_d, you_do, asked, y_done, bool(mach))

    def _c_after_fp():
        a_, b_, z_ = _row_span(_P5, "k2")
        tag, body = _P5[a_:b_], _P5[b_:z_]
        base = _row_fp(tag, body)
        w1 = _row_fp(tag[:-1] + ' data-after="k1">', body)
        w2 = _row_fp(tag[:-1] + ' data-after="k4">', body)
        s1, _i1 = _rows_track_apply(_P5, _now5)                 # 第一次记:只存指纹
        s2, i2 = _rows_track_apply(_row_apply(s1, "k2", after="k1")[0], _now5)   # 加 after ⇒ 这一行算动过
        s3, i3 = _rows_track_apply(s2, _now5)                   # 再跑一次 ⇒ 一个字不动
        card = '<article class="card" data-ack="c1"><div class="crow" data-status="todo" data-ack="r1"%s><span class="txt">甲</span></div></article>'
        return ("data-after" in _ROW_FP_ATTRS and base == "5a53f86258" and len({base, w1, w2}) == 3
                and i2["changed"] == ["k2"] and s3 == s2 and i3["changed"] == []
                and _content_fingerprint(card % "") != _content_fingerprint(card % ' data-after="k9"')
                and _card_body_sig(card % "") != _card_body_sig(card % ' data-after="k9"')), (base, i2["changed"], s3 == s2)

    def _c_ans_need_why():
        g = [_err5(lambda: _answer_apply(_P5, "ask-aaaa1111", "先不关", today=_T5)),                 # 卡里有 #row- 链接
             _err5(lambda: _answer_apply(_P5, "ask-bbbb2222", "点了", today=_T5)),                   # 按卡号找到行
             _err5(lambda: _answer_apply(_P5, "ask-cccc3333", "好", row="k2", today=_T5)),           # --row 给的
             _err5(lambda: _answer_apply(_P5, "ask-aaaa1111", "先不关", why="  ", today=_T5))]       # --why 是空白
        return (all(all(w in x for w in ("由你写一句", "--why", "--done", "--no-row", "这一行现在写的是")) for x in g)
                and "查清了 建议先不关" in g[0] and "拍运费(k1)" in g[0] and "(k4)" in g[1] and "写到 一半" in g[2]), [x[:24] for x in g]

    def _c_row_strict_you():
        # 1009:行上标着要他,改现状 / 状态时必须当场说还要不要他(只在命令行那条路:strict_you=True)
        e1 = _err5(lambda: _row_apply(_P5, "k4", say="你答了两件,另一件先不管", status="watch", eta="10-14", strict_you=True))
        e2 = _err5(lambda: _row_apply(_P5, "k4", say="换一句现状", strict_you=True))
        o3, _ = _row_apply(_P5, "k4", say="他答过了", status="doing", eta="10-14", no_you=True, strict_you=True)
        o4, _ = _row_apply(_P5, "k4", say="还在等他点", you="do", strict_you=True)                 # 原样再给一遍 = 确认
