    def _pj_cap(fn):
        """跑一个命令函数,收下它的 stdout + stderr;die ⇒ ("exit", 码)。"""
        import contextlib as _cl
        o = io.StringIO()
        with _cl.redirect_stdout(o), _cl.redirect_stderr(o):
            try:
                rc = fn()
            except SystemExit as x:
                rc = ("exit", x.code)
        return rc, o.getvalue()

    def _pj_env(d, roots):
        """临时 BOARD_CONFIG(板根 / web 根 / 状态目录都在临时目录);回原值的函数。⛔ 不写 state_dir。"""
        keep = (BP._CACHE, os.environ.get("BOARD_CONFIG"), os.environ.get("BOARD_NO_BRIEF"), os.environ.get("CLAUDECODE"))
        cf = os.path.join(d, "pj-cfg.json")
        json.dump({"board_roots": roots, "web_root": os.path.join(d, "web"), "state_dir": os.path.join(d, "st")}, open(cf, "w"))
        os.environ["BOARD_CONFIG"] = cf
        os.environ["BOARD_NO_BRIEF"] = "1"
        os.environ.pop("CLAUDECODE", None)
        BP._CACHE = None

        def back():
            BP._CACHE = keep[0]
            for k, v in zip(("BOARD_CONFIG", "BOARD_NO_BRIEF", "CLAUDECODE"), keep[1:]):
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
        return back

