                io.open(os.path.join(web, "子线-采购实付核账.html"), "w", encoding="utf-8").write(_set_parent_decl(_P5, "电商-基建.html", "k2"))
                io.open(os.path.join(web, "子线-无声明.html"), "w", encoding="utf-8").write(_P5)
