            o4, l4 = run({"x.html": now - 5}, {mk: {"board": "x.html", "t": now - 5}}, A)  # 两边都活
            o5, l5 = run({"x.html": now - 5}, {mk: {"board": "x.html", "t": now - 200}}, A)  # 新判法的记录过期
            o6, l6 = run({}, {}, ["--board", "x.html"])                                    # 没有会话 id ⇒ 没标记
