    def _chat_watch_battery_test():
        from unittest.mock import patch as mock
        from contextlib import redirect_stdout
        from tempfile import TemporaryDirectory

        closed, opened = '"AppleClamshellState" = Yes', '"AppleClamshellState" = No'
        battery, ac = "Now drawing from 'Battery Power'\n", "Now drawing from 'AC Power'\n"
        tests = [(closed, battery, True), (closed, ac + battery, False), (opened, battery, False)]
        got = [_chat_watch_clamshell_battery(lid, power) for lid, power, _ in tests]
        want = [expected for _, _, expected in tests]
        with TemporaryDirectory(prefix="chat-watch-power-") as temp:
            log = os.path.join(temp, "chat-watch.log")
            args = __import__("argparse").Namespace(all=True, paths=[], dry_run=False)
            with mock(__name__ + ".CHAT_LOG", log), mock(__name__ + "._chat_watch_power_output", side_effect=[closed, battery]) as read:
                with mock(__name__ + ".all_boards", return_value=[]) as boards, redirect_stdout(io.StringIO()) as out:
                    try:
                        rc = cmd_chat_watch(args)
                    except SystemExit as e:
                        rc = e.code
            calls = [call.args[0] for call in read.call_args_list]
            lines = io.open(log, encoding="utf-8").read().splitlines() if os.path.exists(log) else []
        checks = [got == want, rc == 0, not boards.called, "这一轮跳过" in out.getvalue(),
                  calls == [["ioreg", "-r", "-k", "AppleClamshellState", "-d", "4"], ["pmset", "-g", "batt"]],
                  len(lines) == 1 and lines[0].endswith(" skip clamshell_on_battery")]
        return all(checks), "电源判定=%s 预期=%s 整轮跳过=%s" % (got, want, checks[1:])

