    def _c8_skill_env(**kw):
        """临时改环境变量的小工具:进来设、出去还原。"""
        import contextlib as _cx

        @_cx.contextmanager
        def cm():
            old = {k: os.environ.get(k) for k in kw}
            try:
                for k, v in kw.items():
                    if v is None:
                        os.environ.pop(k, None)
                    else:
                        os.environ[k] = v
                yield
            finally:
                for k, v in old.items():
                    if v is None:
                        os.environ.pop(k, None)
                    else:
                        os.environ[k] = v
        return cm()

