    def _l10_ans_cmd(src, rec, **kw):
        """在临时目录里造一块板真跑 cmd_answer → (返回码 / "exit", 印的全部, 写回后的板, 记日志收到的参数)。⛔ 不写 state_dir:答案读写 / 日志都换成桩。"""
        import tempfile as _tfa, contextlib as _cla
        d = _tfa.mkdtemp(prefix="zz-land-ans-")
        logged = []
        stubs = {"_hint_log": lambda path, ack, keys, log_path=None, checked=False, st=None: (logged.append(dict(ack=ack, keys=list(keys), st=st)), True)[1],
                 "assert_canonical": lambda path: path, "_answers_raw": lambda *a_, **k_: {kw.get("ack", "ask-aaaa1111"): rec} if rec else {}, "_answers_drop": lambda *a_, **k_: (dict(rec) if rec else None),
                 "_answers_consumed_file": lambda *a_, **k_: os.path.join(d, "consumed.jsonl"), "_dir_stale_tail": lambda *a_, **k_: None,
                 "_queue_drop_you": lambda *a_, **k_: False, "_answer_unseen": lambda *a_, **k_: None, "_answers_save": lambda *a_, **k_: None}
        real = {k: globals()[k] for k in stubs}
        try:
            bp = os.path.join(d, "zz-land1110.html")
            io.open(bp, "w", encoding="utf-8").write('<title>zz-land 状态板</title><div class="wrap">' + src + '</div>')
            ns = dict(path=bp, ack="ask-aaaa1111", res="他答了", row=None, done=False, why=None, why_add=False, why_replace=False, no_row=False, sum=None,
                      followup=None, no_followup=None, keep_you=False, force=True, no_touch=True)
            ns.update(kw)
            globals().update(stubs)
            buf = io.StringIO()
            with _cla.redirect_stdout(buf), _cla.redirect_stderr(buf):
                try:
                    rc = cmd_answer(argparse.Namespace(**ns))
                except SystemExit:
                    rc = "exit"
            after = io.open(bp, encoding="utf-8").read()
        finally:
            globals().update(real)
            shutil.rmtree(d, ignore_errors=True)
        return rc, buf.getvalue(), after, logged

