    def _l19_f(a):
        tag = '<div class="crow" data-ack="k"' + "".join(' %s="%s"' % kv for kv in a.items()) + '>'
        return _row_facts(tag, _L19_BODY, today=_L19T)

    def _l19_node(js_tail):
        import subprocess as _sp
        kj = _kit_js
        fns = [re.search(r'\n  function %s\(.*?\n  \}\n' % n, kj, re.S) for n in ("mdDate", "stampMs", "chaseOverdue")]
        if not all(fns):
            return None, "函数没有抽出来"
        js = ("var DAY_MS=864e5, BALL_HIS={decide:1,'do':1,nudge:1,stuck:1};\nfunction today0(){var d=new Date(Date.now());d.setHours(0,0,0,0);return d.getTime()}\n"
              + "".join(m.group(0) for m in fns) + _kit_j_block(kj) + "\nDate.now=function(){return new Date(2026,10,20,10).getTime()};\n" + js_tail)
        r = _sp.run(['node', '-e', js], capture_output=True, text=True, timeout=30)  # 依据: 现有首屏 node 自检的超时
        try:
            return json.loads(r.stdout.strip()), ""
        except ValueError:
            return None, "node: " + r.stderr[-300:]

    def _l19_matrix():
        # ② ③ ④:board.py `_late_row` / `_chase_overdue` 与 kit `lateRow` / `chaseOverdue` 逐条同答,且答对
        py = [[bool(_late_row(_l19_f(a), _L19T)), _chase_overdue(_l19_f(a), _L19T)] for _d, a, _l, _o in _L19_CASES]
        js, err = _l19_node("var CASES=%s;\nfunction ROW(a){return {getAttribute:k=>Object.prototype.hasOwnProperty.call(a,k)?a[k]:null}}\n"
                            "console.log(JSON.stringify(CASES.map(a=>[lateRow(ROW(a)), chaseOverdue(ROW(a))])));" % json.dumps([a for _d, a, _l, _o in _L19_CASES]))
        want = [[l, o] for _d, _a, l, o in _L19_CASES]
        bad = [(_L19_CASES[i][0], py[i], (js or [None] * len(py))[i], want[i]) for i in range(len(py)) if py[i] != want[i] or not js or js[i] != want[i]]
        return (not bad and not err), ("对不上:%s %s" % (bad, err)) if (bad or err) else "%d 条两边同答" % len(py)

    def _l19_chase_due():
        # ② 到点该追给 late:说明以「过了预计 」开头;叫醒消息三个出口,没有「去问他」;等外部的原样
        f1 = _l19_f(_L19_CASES[4][1]); f2 = _l19_f(_L19_CASES[13][1]); f3 = _l19_f({"data-status": "watch", "data-eta": "11-10"})
        d1, d2, d3 = _chase_due(f1, _L19T), _chase_due(f2, _L19T), _chase_due(f3, _L19T)
        fe = _l19_f({"data-status": "blocked", "data-you": "wait", "data-wait-for": "同事甲回", "data-eta": "11-30", "data-wait-since": "2026-11-12T10:00"})
        de = _chase_due(fe, _L19T)
        f1["title"] = "过期的那件"
        tx = _chase_text("电商-基建", [("/x/电商-基建.html", f1, d1[1])], "ab12") if d1 else ""
        tm = _chase_text("电商-基建", [("/x/电商-基建.html", f1, d1[1]), ("/x/电商-基建.html", fe, de[1])], "ab12") if (d1 and de) else ""
        g = [bool(d1) and d1[0] == "late" and d1[1].startswith(LATE_WHY_HEAD) and "10 天" in d1[1], d2 is None, d3 is None,
             bool(de) and de[0] == "ext",
             "--review" in tx and "--wait-for" in tx and "--why" in tx and "问我" not in tx and "过了预计还没做完" in tx and "等外部 / 等日子的到点了" not in tx
             and "过了预计 N 天" in tx and "--checked 不算处理" in tx and "等了 N 天没人追" not in tx,
             "1 件在等外部 / 等日子的到点了" in tm and "1 件过了预计还没做完" in tm and "等了 N 天没人追" in tm and "--chase" in tm]
        return all(g), "got=%s" % g

    def _you_idle_board(extra="", card=""):
        return _w10_bd([("blocked", "k", ' data-you="do" data-eta="11-30"' + extra,
                         "物流索赔", "这段现状留在原行", '<span class="act">点开核对</span>')], card)

