    def _you_idle_due_test():
        at = datetime.datetime(2026, 11, 19, 10)
        stamp = ' data-you-since="2026-11-18T10:00"'
        link = '<article class="card" data-ack="ask-1"><a href="#row-k">原行</a></article>'
        machine = ROWYOU_BEGIN + link.replace("ask-1", "rows-on-you") + ROWYOU_END
        base = _you_idle_board(stamp)
        tracked, _ = _rows_track_apply(base, at.timetuple())
        cases = [
            ("满 24 小时", base, at, "you-idle"),
            ("少一分钟", base, at - datetime.timedelta(minutes=1), None),
            ("已有手写卡", _you_idle_board(stamp, link), at, None),
            ("机器卡自身链接", _you_idle_board(stamp, machine), at, "you-idle"),
            ("已改动", _you_idle_board(stamp + ' data-upd="2026-11-19T09:59"'), at, None),
            ("改现状未 touch", tracked.replace("这段现状留在原行", "新的现状"), at, None),
            ("刚收卡", _you_idle_board(stamp + ' data-card-at="2026-11-19T09:59"'), at, None),
            ("已收行", base.replace('data-status="blocked"', 'data-status="done"'), at, None),
            ("旧行可追溯", _you_idle_board(' data-fp0="2026-11-18T10:00"'), at, "you-idle"),
            ("旧行无记录", _you_idle_board(), at, None),
        ]
        bad = []
        for name, source, now, expected in cases:
            result = _chase_due(_you_idle_fact(source), now.date(), now)
            got = result[0] if result else None
            if got != expected:
                bad.append((name, got, expected))
        return not bad, str(bad) if bad else "10 条边界及对照符合预期"

    def _you_idle_round_test():
        marked_at = datetime.datetime(2026, 11, 18, 10)
        wake_at = datetime.datetime(2026, 11, 19, 11)
        source = _you_idle_board().replace('data-you="do"', 'data-you="wait" data-wait-for="物流商"')
        marked, _ = _row_apply(source, "k", you="do", now_dt=marked_at)
        marked, _ = _rows_track_apply(marked, marked_at.timetuple())
        called = _chase_mark(marked, ["k"], wake_at.date().isoformat())
        updated, _ = _row_apply(called, "k", act="核对两笔赔款", now_dt=wake_at)
        cleared, _ = _row_apply(called, "k", you="wait", wait_for="物流商", now_dt=wake_at)
        manually_updated, _ = _rows_track_apply(called.replace("这段现状留在原行", "补了进展"), wake_at.timetuple())
        checks = [_you_idle_fact(marked)["you_since"] == "2026-11-18T10:00",
                  _you_idle_fact(updated)["you_since"] == "2026-11-18T10:00",
                  _you_idle_fact(cleared)["you_since"] is None,
                  _you_idle_fact(updated)["chase_due"] is None,
                  _you_idle_fact(manually_updated)["chase_due"] is None,
                  _chase_due(_you_idle_fact(updated), wake_at.date(), wake_at) is None,
                  _chase_overdue(_you_idle_fact(cleared), _L19T) is None,
                  any("挂了 2 天没人挂卡" in line for line in _stuck_red_lines(called, today=_L19T, now=wake_at))]
        return all(checks), "计时及清记号=%s" % checks

