             r2 == 'exit' and a2 == full, r3 == 'exit' and a3 == full, r4 == 'exit' and a4 == full, r5 == 'exit' and a5 == '<title>zz-wait 状态板</title><div class="wrap">' + res + '</div>',
             r6 != 'exit' and all(st(a6, k) == 'done' for k in ('k', 'k2', 'k3')) and 'data-accept="1"' not in a6 and '一起收了' in o6,
