    def _sweepA7_1115():
        # ⭐ 1115 大扫除 A7:board-freshness-check.js 原来没日志(hook-hits.py 判不了命中)⇒ 拦收工那一刻往 state_dir/board-freshness-check.log 记一行;不拦不记(真跑钩子,HOME 指临时目录)
        import subprocess as _sp, tempfile as _tf
        _hd = os.path.dirname(os.path.abspath(__file__))
        hk = next((c for c in (os.path.join(_hd, "hooks", "board-freshness-check.js"),
                               os.path.join(os.path.dirname(_hd), "hooks", "board-freshness-check.js")) if os.path.isfile(c)), None)
        node = shutil.which("node")
        if not hk or not node or not shutil.which("git"):
            return False, "找不到钩子 / node / git(hk=%s node=%s)" % (hk, node)
        d = os.path.realpath(_tf.mkdtemp(prefix="zz-freshA7-"))
        try:
            home, repo = os.path.join(d, "home"), os.path.join(d, "repo")
            sdir = os.path.join(home, _SELFTEST_HOOK_STATE_DIR, "board-stop-hook")
            os.makedirs(sdir); os.makedirs(os.path.join(repo, ".claude", "boards"))
            _sp.run(["git", "init", "-q", repo], check=True, capture_output=True, timeout=30)   # 依据: git init 本机 <0.1 秒,30 秒同其它子进程用例
            bp = os.path.join(repo, ".claude", "boards", "zz-保鲜.html")
            io.open(bp, "w", encoding="utf-8").write("<p>x</p>")
            now = int(time.time())
            lp = os.path.join(home, _SELFTEST_HOOK_STATE_DIR, "board-freshness-check.log")
            iso = datetime.datetime.fromtimestamp(now, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")

            def go(miss, mt):
                os.utime(bp, (mt, mt))
                json.dump({"S1A7::%s" % os.path.realpath(repo): {"seen": {"zz-保鲜.html": mt}, "own": "zz-保鲜.html", "miss": miss, "lastNag": 0, "lastDupNag": 0, "since": now - 7200}},
                          open(os.path.join(sdir, "state.json"), "w"))
                io.open(os.path.join(sdir, "writes.jsonl"), "w", encoding="utf-8").write(json.dumps({"cwd": repo, "board": "zz-保鲜.html", "ts": now - 60, "sid": "S1A7"}) + "\n")
                tp = os.path.join(d, "t.jsonl")
                io.open(tp, "w", encoding="utf-8").write(json.dumps({"type": "assistant", "timestamp": iso, "message": {"content": [{"type": "text", "text": "已合并"}]}}, ensure_ascii=False) + "\n")
                env = dict(os.environ, HOME=home)
                env.pop("HOOK_SELFTEST", None)
                # 依据: 自检里跑一次 node 钩子,本机实测不到 1 秒;30 秒只防卡死
                r = _sp.run([node, hk], input=json.dumps({"session_id": "S1A7", "cwd": repo, "transcript_path": tp}), capture_output=True, text=True, timeout=30, env=env)
                return r.stdout, (io.open(lp, encoding="utf-8").read().splitlines() if os.path.exists(lp) else [])
            o1, L1 = go(2, now - 3600)          # 第 3 轮、板 60 分钟没动、转录里有新事实 ⇒ 拦 + 记一行
            o2, L2 = go(0, now)                 # 板刚动过 ⇒ 不拦、不记
            g = ['"decision":"block"' in o1.replace(" ", ""),
                 len(L1) == 1 and " speak " in L1[0] and "board=zz-保鲜.html" in L1[0] and "sid=S1A7" in L1[0] and re.match(r"\d{4}-\d\d-\d\dT\d\d:\d\d", L1[0]) is not None,
                 o2.strip() == "" and L2 == L1]
            return all(g), "got=%s out=%r log=%r" % (g, o1[:120], L1[:2])
        finally:
            shutil.rmtree(d, ignore_errors=True)

