    def _rot1116_classes():
        # 1:每一类卡都实际生成一张 + kit.js 运行时注入的,class 逐个核 kit.css 有定义;缺一个就红并报哪类卡的哪个 class
        css, kj = _kit.get("kit.css", ""), _kit_js
        zoo = _class_zoo()
        empty = [n for n, h in zoo if len(_html_classes(h)) < 5]
        miss, n_cls, per = _class_orphans(zoo, css, kj)
        g = {"每一类都真生成出来了(每张 ≥5 个 class)": not empty, "kit 运行时注入的收到了(≥100 个)": per.get("kit 运行时注入(含首屏「要你做的 · 待验收」那块)", 0) >= 100,
             "缺定义 0 个": not miss, "小修卡在里面且用了 .accept-small": any(n == "小修清单卡" and "accept-small" in _html_classes(h) for n, h in zoo),
             "首屏「待验收」的类在 kit 注入里": "fsx-tag-accept" in _kit_js_classes(kj)}
        # 反向:真缺一个时报得出哪类卡、哪个 class
        m2, _n2, _p2 = _class_orphans([("zz 假卡", '<div class="accept-small zz-nope"></div>')], css.replace(".accept-small{", ".zz-gone{"), "")
        g["缺了能报出哪类卡哪个 class"] = ("zz 假卡", "accept-small") in m2 and ("zz 假卡", "zz-nope") in m2
        bad = [k for k, v in g.items() if not v]
        return not bad, "%d 类卡 + kit 运行时注入,核了 %d 个不同的 class;缺定义:%s;坏了:%s;空卡:%s" % (
            len(zoo), n_cls, ["%s 的 .%s" % x for x in miss] or "无", bad, empty)

    def _lh1117_zoo():
        # 1117 LH:卡型样例排法 —— 自带区头的类在最后、跨类卡号不重复;反向:挪到中间 / 重复号都报得出来
        zoo = _class_zoo()
        probs = _class_zoo_problems(zoo)
        names = [n for n, _ in zoo]
        g = {"现在的样例没问题": not probs, "排队区 / 主线卡在最后两位": names[-2:] == ["排队区", "主线卡"],
             "去催卡 / 卡在你身上的都在排队区前面": names.index("去催卡") < names.index("排队区") and names.index("卡在你身上的") < names.index("排队区")}
        _q = [x for x in zoo if x[0] == "排队区"]
        _mid = [x for x in zoo if x[0] not in ("排队区", "主线卡")]
        _ni = [n for n, _ in _mid].index("去催卡")
        _bad = _mid[:_ni] + _q + _mid[_ni:] + [x for x in zoo if x[0] == "主线卡"]
        _p1 = _class_zoo_problems(_bad)
        g["反向:排队区挪到去催卡前面报得出被吞的两类"] = any("「去催卡」排在自带区头的「排队区」后面" in x for x in _p1) and any("「卡在你身上的」" in x for x in _p1)
        _p2 = _class_zoo_problems([("甲", '<a href="https://github.com/o/r/issues/12">#12</a>'), ("乙", '<a href="https://github.com/o/r/issues/12">#12</a>'),
                                   ("丙", '<a href="https://github.com/o/r/issues/123">#123</a>')])
        g["反向:跨类重复卡号报得出(#12 ≠ #123)"] = _p2 == ["卡号 #12 在「甲」「乙」里重复用了 —— 每类卡用自己的号"]
        bad = [k for k, v in g.items() if not v]
        return not bad, "问题:%s;坏了:%s;反向 1:%s" % (probs or "无", bad, _p1[:2])

