    def _j17_ask(src, **kw):
        """在临时目录里造一块板真跑 cmd_ask → (返回码 / "exit", 印的全部, 写回后的板)。⛔ 不写 state_dir。"""
        import tempfile as _tfa, contextlib as _cla
        d = _tfa.mkdtemp(prefix="zz-ask1117-")
        stubs = {"_hint_log": lambda *a_, **k_: True, "_ask_how_log": lambda *a_, **k_: None, "assert_canonical": lambda path: path,
                 "_subline_board_problem": lambda *a_, **k_: None}
        real = {k: globals()[k] for k in stubs}
        try:
            bp = os.path.join(d, "zz-ask1117.html")
            io.open(bp, "w", encoding="utf-8").write('<title>zz-ask 状态板</title><div class="wrap">' + src + '</div>')
            ns = dict(path=bp, q="请你在手机设置里打开通知开关", rec="照做", cost=None, opt=[], card=None, no_touch=True, why=None, steps=None,
                      deep=None, deep_why=None, deep_label=None, row=None, do=False, text=None, copy=None, how=None, img=None)
            ns.update(kw)
            globals().update(stubs)
            buf = io.StringIO()
            with _cla.redirect_stdout(buf), _cla.redirect_stderr(buf):
                try:
                    rc = cmd_ask(argparse.Namespace(**ns))
                except SystemExit:
                    rc = "exit"
            after = io.open(bp, encoding="utf-8").read()
        finally:
            globals().update(real)
            shutil.rmtree(d, ignore_errors=True)
        return rc, buf.getvalue(), after

