    def _ask1117_wake():
        # 1117 二轮:回答卡点「没答到点上」⇒ 叫醒那条线写「他说没答到点上」+ 他的补充、选了照按钮字,不写验收没通过;看过了又补字 ⇒ 写看过了;普通验收卡照旧(cmd_wake_lines 真跑,假时间)
        import tempfile as _tfw
        g, sent = {}, []
        d = _tfw.mkdtemp(prefix="zz-asked-wake-"); work = os.path.join(d, "work"); back = _pj_env(d, [work])
        saved = {k: globals()[k] for k in ("_wake_send", "_wake_live_sessions", "_wake_pick_sid", "_touch_child", "_accept_notify", "_accept_owner")}
        try:
            bd = os.path.join(work, "r", ".claude", "boards"); web = os.path.join(d, "web")
            os.makedirs(bd); os.makedirs(web); name = "测试-回答卡.html"; path = os.path.join(bd, name)
            open(path, "w", encoding="utf-8").write(""); os.link(path, os.path.join(web, name))
            globals()["_wake_live_sessions"] = lambda _: {"S": ("socket", "token", "idle")}
            globals()["_wake_pick_sid"] = lambda *a_: "S"
            globals()["_touch_child"] = lambda *a_, **k_: 0
            globals()["_wake_send"] = lambda sock, tok, msg, timeout=3.0: (sent.append(msg) or "")
            globals()["_accept_owner"] = lambda *a_: "测试-回答卡"
            globals()["_accept_notify"] = lambda line, msg: ""
            adir = BP.state("board-server", "answers"); os.makedirs(adir, exist_ok=True)
            T = time.time() - 40   # 依据: 与 1114 验收合一叫醒那条同一套假时间(点完 100 秒 > 一分半宽限)
            iso = datetime.datetime.fromtimestamp(T).astimezone().isoformat(timespec="seconds")

            def wrun(asked, choice, note):
                del sent[:]
                src, _ = _review_add(_P5, "k2", "", "", q="为什么少了三单" if asked else "在做的做好了,通过吗?", gots=["少的三单是退款单"], asked=asked)
                ack = re.search(r'data-ack="(ask-[0-9a-f]{8})"[^>]*data-accept="1"', src).group(1)
                open(path, "w", encoding="utf-8").write(src)
                for f in ("woken.json", "answers-shown.json"):
                    fp = BP.state("board-server", f)
                    if os.path.exists(fp):
                        os.remove(fp)
                af = _answers_file(name, adir)
                json.dump({ack: {"choice": choice, "note": note, "ts": iso, "sub": iso}}, open(af, "w"), ensure_ascii=False)
                os.utime(af, (T, T))
                _pj_cap(lambda: cmd_wake_lines(sess_dir=os.path.join(d, "sess"), now=T + 100))
                return list(sent)
            w1 = wrun(True, "不通过", "还想知道是哪三单")
            w2 = wrun(True, "不通过", "")
            w3 = wrun(True, "通过", "顺手把口径写进表头")
            w4 = wrun(False, "不通过", "差首屏")
            g["没答到点上:写他说没答到点上 + 补充"] = len(w1) == 1 and "他说没答到点上:还想知道是哪三单" in w1[0] and "选了:没答到点上" in w1[0] and "验收" not in w1[0] and "选了:不通过" not in w1[0]
            g["没答到点上没写补充:照样不写验收"] = len(w2) == 1 and "他说没答到点上(没写还想知道什么" in w2[0] and "验收" not in w2[0]
            g["看过了又补字:写看过了"] = len(w3) == 1 and "他看过了回答,补了一句:顺手把口径写进表头" in w3[0] and "选了:看过了" in w3[0] and "验收" not in w3[0]
            g["普通验收卡照旧"] = len(w4) == 1 and "验收没通过" in w4[0] and "选了:不通过" in w4[0] and "没答到点上" not in w4[0]
        finally:
            globals().update(saved); back(); shutil.rmtree(d, ignore_errors=True)
        bad = [k for k, v in g.items() if not v]
        return not bad, "坏了:%s 发出:%s" % (bad, [x[-300:] for x in (locals().get("w1") or [])][:1])

