        r2, o2, a2, _ = _w10_cmd(bd, review=True, q='测试事项做好了,通过吗?', got=['首屏能看到结果'])
        g["row --review 重复 ⇒ 拒写板不动"] = r1 == "exit" and a1 == full and "别重复标题" in o1
        g["row --review 不重复 ⇒ 照挂"] = r2 != "exit" and 'data-accept="1"' in a2
        try:
            _review_add(full, 'k', '', '', q='测试事项首屏能看到结果,通过吗?', gots=['测试事项首屏能看到结果'])
            g["_review_add 自己也拦"] = False
        except ValueError as e:
            g["_review_add 自己也拦"] = "别重复标题" in str(e)
        d, media, P, back = _c13_env()
        try:
            rc3, o3, a3, f3 = _c13_ask(d, bd, why='首页新配图要不要换上。上周拍了新图。')
            rc4, o4, a4, f4 = _c13_ask(d, bd, why='上周拍了新图,转化页还在用旧图。')
            g["ask --why 重复 ⇒ 拒写板不动"] = rc3 == "exit" and a3 == f3 and "别重复标题" in o3
            g["ask --why 不重复 ⇒ 照挂"] = rc4 != "exit" and a4 != f4
        finally:
            back()
        bad = [k for k, v in g.items() if not v]
        return not bad, "坏了:%s o1=%s o3=%s" % (bad, o1[-160:], o3[-160:])

