        g['css'] = all(('.%s{' % k) in css for k in ('accept-got', 'accept-got-i', 'accept-got-t', 'accept-got-a', 'accept-got-v', 'accept-entry', 'accept-check'))
        # node 真跑 acceptFmt2Order:图先被通用那步挪到问题正下方,新格式再排成 问题 → 交代→现在 → 入口 → 图
        fa = kj.index('  function acceptFmt2Order('); fb = kj.index('\n  }\n', fa) + 4
        js = ("function N(c){this.c=c;this.parentNode=null}\n"
              "var P={kids:[],insertBefore:function(n,ref){var k=this.kids;if(ref===n)ref=k[k.indexOf(n)+1]||null;var i=k.indexOf(n);if(i>=0)k.splice(i,1);var j=ref?k.indexOf(ref):-1;if(j<0)k.push(n);else k.splice(j,0,n);n.parentNode=this}};\n"
              "['q','cimgs','accept-got','accept-entry','checks'].forEach(function(c){var n=new N(c);n.parentNode=P;P.kids.push(n)});\n"
              "P.kids.forEach(function(n,i){Object.defineProperty(n,'nextSibling',{get:function(){var k=P.kids;return k[k.indexOf(n)+1]||null}})});\n"
              "var cd={querySelector:function(s){return P.kids.filter(function(n){return '.'+n.c===s})[0]||null}};\n"
              + kj[fa:fb] + "\nacceptFmt2Order(cd, P.kids[0]);console.log(JSON.stringify(P.kids.map(function(n){return n.c})));")
        try:
            rr = _sp.run(['node', '-e', js], capture_output=True, text=True, timeout=30)   # 依据: 与现有 node 自检相同的防挂死时限
            g['kit顺序'] = json.loads(rr.stdout.strip()) == ['q', 'accept-got', 'accept-entry', 'cimgs', 'checks']
        except Exception as e:
            g['kit顺序'] = False
        bad_k = [k for k, v in g.items() if not v]
        return not bad_k, "红:%s" % bad_k

