    # ──────────────── 1113 卡上放图 / review 入口 / 按组批量定(本轮三件)
    def _c13_png(width, height, color, raw, *, depth=8, interlace=0, palette=b"", transparency=b""):
        def chunk(tag, data):
            return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data))

        header = struct.pack(">IIBBBBB", width, height, depth, color, 0, 0, interlace)
        extra = (chunk(b"PLTE", palette) if palette else b"") + (chunk(b"tRNS", transparency) if transparency else b"")
        compressed = zlib.compress(raw)
        return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", header) + extra
                + chunk(b"IDAT", compressed[:5]) + chunk(b"IDAT", compressed[5:]) + chunk(b"IEND", b""))

    # 依据: 11-23 加空白闸后，原单像素用例需换成两个明显不同的像素。
    _C13_PNG = _c13_png(2, 1, 2, b"\0\0\0\0\xff\xff\xff")
    _C13_JPG = b"\xff\xd8\xff\xe0" + b"\x00" * 24
    _C13_GOOD = '打开验收页 → 第一节的配图是新换的那张'   # 1115 D1:给了 --url 的 --check 要分步

    def _c13_styled(cls):
        css = _kit.get('kit.css', '')
        return bool(re.search(r'\.%s(?![\w-])' % re.escape(cls), css))

    def _c13_env():
        """临时目录 + 卡图落点(BOARD_ANSWER_MEDIA)指过去;⛔ 不写真的 state_dir。返回 (目录, 落点, 各种图的路径, 还原函数)。"""
        import tempfile as _tf13
        d = _tf13.mkdtemp(prefix="zz-cards1113-")
        media = os.path.join(d, "media")
        old = os.environ.get("BOARD_ANSWER_MEDIA")
        os.environ["BOARD_ANSWER_MEDIA"] = media
        P = {}
        for k, name, blob in (("png", "a.png", _C13_PNG), ("jpeg", "b.JPEG", _C13_JPG), ("txt", "c.txt", b"hello"), ("fake", "d.png", b"not an image"),
                              ("bmp", "e.bmp", _C13_PNG), ("png2", "f.png", _C13_PNG + b"\x00")):
            P[k] = os.path.join(d, name)
            open(P[k], "wb").write(blob)
        P["missing"] = os.path.join(d, "nope.png")

        def back():
            if old is None:
                os.environ.pop("BOARD_ANSWER_MEDIA", None)
            else:
                os.environ["BOARD_ANSWER_MEDIA"] = old
            shutil.rmtree(d, ignore_errors=True)
        return d, media, P, back

    def _c13_call(fn, ns):
        """真跑 cmd_ask / cmd_row(板在临时目录里)⇒ (返回码 / "exit", 印的全部)。写日志、盖戳、子线检查一律换成空的。"""
        if fn is cmd_row and ns.get("review") and "see" not in ns:   # 1116 讲人话:--see 必填,老用例不测它 ⇒ 补一句缺省
            ns = dict(ns, see="首屏「测试事项」那一行写着新结果")
        import contextlib as _cl13
        stubs = {"_hint_log": lambda *a_, **k_: True, "assert_canonical": lambda path: path,
                 "_once_per_session": lambda *a_, **k_: False, "_dir_stale_tail": lambda *a_, **k_: None,
                 "_subline_board_problem": lambda *a_, **k_: None, "_scheduled_tasks": lambda *a_, **k_: [],
                 "_ask_how_log": lambda *a_, **k_: None, "_touch_child": lambda *a_, **k_: 0}
        real = {k: globals()[k] for k in stubs}
        buf = io.StringIO()
        try:
            globals().update(stubs)
            with _cl13.redirect_stdout(buf), _cl13.redirect_stderr(buf):
                try:
                    rc = fn(argparse.Namespace(**ns))
                except SystemExit:
                    rc = "exit"
        finally:
            globals().update(real)
        return rc, buf.getvalue()

    def _c13_ask(d, src, **kw):
        bp = os.path.join(d, "zz-ask1113.html")
        full = '<title>zz-ask 状态板</title><div class="wrap">' + src + '</div>'
